window.KURALS = [
  {"n":1,"ta":["அகர முதல எழுத்தெல்லாம் ஆதி","பகவன் முதற்றே உலகு"],"tr":["Akara Muthala Ezhuthellaam Aathi","Bagavan Mutharre Ulagu"],"en":["A, as its first of letters, every speech maintains;","The \"Primal Deity\" is first through all the world’s domains"],"s":"As the letter ‘A’ comes first in every language, the Divine comes first in the world. Begin from what is highest.","ch":1,"sec":1,"th":"wisdom"},
  {"n":2,"ta":["கற்றதனால் ஆய பயனென்கொல் வாலறிவன்","நற்றாள் தொழாஅர் எனின்"],"tr":["Katrathanaal Aaya Payanenkol Vaalarivan","Natraal Thozhaaar Enin"],"en":["No fruit have men of all their studied lore,","Save they the ‘Purely Wise One’s’ feet adore"],"s":"What is the use of all your learning if you never bow to true wisdom?","ch":1,"sec":1,"th":"wisdom"},
  {"n":3,"ta":["மலர்மிசை ஏகினான் மாணடி சேர்ந்தார்","நிலமிசை நீடுவாழ் வார்"],"tr":["Malarmisai Ekinaan Maanati Serndhaar","Nilamisai Neetuvaazh Vaar"],"en":["His feet, 'Who o'er the full-blown flower hath past, ' who gain","In bliss long time shall dwell above this earthly plain"],"s":"They who are united to the glorious feet of Him who passes swiftly over the flower of the mind, shall flourish long above all worlds","ch":1,"sec":1,"th":"wisdom"},
  {"n":4,"ta":["வேண்டுதல் வேண்டாமை இலான் அடி சேர்ந்தார்க்கு","யாண்டும் இடும்பை இல"],"tr":["Ventuthal Ventaamai Ilaanadi Serndhaarkku","Yaantum Itumpai Il"],"en":["His foot, ‘Whom want affects not, irks not grief,’ who gain","Shall not, through every time, of any woes complain"],"s":"Those who reach the One who wants nothing and fears nothing will never face trouble anywhere.","ch":1,"sec":1,"th":"wisdom"},
  {"n":5,"ta":["இருள்சேர் இருவினையும் சேரா இறைவன்","பொருள்சேர் புகழ்புரிந்தார் மாட்டு"],"tr":["Irulser Iruvinaiyum Seraa Iraivan","Porulser Pukazhpurindhaar Maattu"],"en":["The men, who on the 'King's' true praised delight to dwell,","Affects not them the fruit of deeds done ill or well"],"s":"The two-fold deeds that spring from darkness shall not adhere to those who delight in the true praise of God","ch":1,"sec":1,"th":"wisdom"},
  {"n":6,"ta":["பொறிவாயில் ஐந்தவித்தான் பொய்தீர் ஒழுக்க","நெறிநின்றார் நீடுவாழ் வார்"],"tr":["Porivaayil Aindhaviththaan Poidheer Ozhukka","Nerinindraar Neetuvaazh Vaar"],"en":["Long live they blest, who 've stood in path from falsehood freed;","His, 'Who quenched lusts that from the sense-gates five proceed'"],"s":"Those shall long proposer who abide in the faultless way of Him who has destroyed the five desires of the senses","ch":1,"sec":1,"th":"wisdom"},
  {"n":7,"ta":["தனக்குவமை இல்லாதான் தாள்சேர்ந்தார்க்கு அல்லால்","மனக்கவலை மாற்றல் அரிது"],"tr":["Thannakkuvamai Illaathaan Thaalserndhaarkku Allaal","Manakkavalai Maatral Arithu"],"en":["Unless His foot, ‘to Whom none can compare,’ men gain,","‘Tis hard for mind to find relief from anxious pain"],"s":"Worry will not leave the mind until it finds a greater, steadier thing to hold on to.","ch":1,"sec":1,"th":"wisdom"},
  {"n":8,"ta":["அறவாழி அந்தணன் தாள்சேர்ந்தார்க் கல்லால்","பிறவாழி நீந்தல் அரிது"],"tr":["Aravaazhi Andhanan Thaalserndhaark Kallaal","Piravaazhi Neendhal Aridhu"],"en":["Unless His feet 'the Sea of Good, the Fair and Bountiful, ' men gain,","'Tis hard the further bank of being's changeful sea to attain"],"s":"None can swim the sea of vice, but those who are united to the feet of that gracious Being who is a sea of virtue","ch":1,"sec":1,"th":"wisdom"},
  {"n":9,"ta":["கோளில் பொறியின் குணமிலவே எண்குணத்தான்","தாளை வணங்காத் தலை"],"tr":["Kolil Poriyin Kunamilave Enkunaththaan","Thaalai Vanangaath Thalai"],"en":["Before His foot, 'the Eight-fold Excellence, ' with unbent head,","Who stands, like palsied sense, is to all living functions dead"],"s":"The head that worships not the feet of Him who is possessed of eight attributes, is as useless as a sense without the power of sensation","ch":1,"sec":1,"th":"wisdom"},
  {"n":10,"ta":["பிறவிப் பெருங் கடல் நீந்துவர் நீந்தார்","இறைவன் அடி சேராதார்"],"tr":["Piravipperungadal Neendhuvar Neendhaar","Iraivan Adiseraathaar"],"en":["They swim the sea of births, the ‘Monarch’s’ foot who gain;","None others reach the shore of being’s mighty main"],"s":"Only those who hold on to the highest will cross the great ocean of life. The rest will not reach the other shore.","ch":1,"sec":1,"th":"wisdom"},
  {"n":11,"ta":["வான்நின்று உலகம் வழங்கி வருதலால்","தான்அமிழ்தம் என்று உணரற்பாற்று"],"tr":["Vaannindru Ulagam Vazhangi Varudhalaal","Thaanamizhtham Endru Unaralpaatru"],"en":["The world its course maintains through life that rain unfailing gives;","Thus rain is known the true ambrosial food of all that lives"],"s":"Rain keeps every living thing alive. It is the world’s own food — treasure it.","ch":2,"sec":1,"th":"gratitude"},
  {"n":12,"ta":["துப்பார்க்குத் துப்பாய துப்பாக்கித் துப்பார்க்குத்","துப்பாய தூஉம் மழை"],"tr":["Thuppaarkkuth Thuppaaya Thuppaakkith Thuppaarkkuth","Thuppaaya Thooum Mazhai"],"en":["The rain makes pleasant food for eaters rise;","As food itself, thirst-quenching draught supplies"],"s":"Rain produces good food, and is itself food","ch":2,"sec":1,"th":"gratitude"},
  {"n":13,"ta":["விண்இன்று பொய்ப்பின் விரிநீர் வியனுலகத்து","உள்நின்று உடற்றும் பசி"],"tr":["Vinindru Poippin Virineer Viyanulakaththu","Ulnindru Utatrum Pasi"],"en":["If clouds, that promised rain, deceive, and in the sky remain,","Famine, sore torment, stalks o'er earth's vast ocean-girdled plain"],"s":"If the cloud, withholding rain, deceive  (our hopes) hunger will long distress the sea-girt spacious world","ch":2,"sec":1,"th":"gratitude"},
  {"n":14,"ta":["ஏரின் உழாஅர் உழவர் புயல்என்னும்","வாரி வளங்குன்றிக் கால்"],"tr":["Erin Uzhaaar Uzhavar Puyalennum","Vaari Valangundrik Kaal"],"en":["If clouds their wealth of waters fail on earth to pour,","The ploughers plough with oxen's sturdy team no more"],"s":"If the abundance of wealth imparting rain diminish, the labour of the plough must cease","ch":2,"sec":1,"th":"gratitude"},
  {"n":15,"ta":["கெடுப்பதூஉம் கெட்டார்க்குச் சார்வாய்மற் றாங்கே","எடுப்பதூஉம் எல்லாம் மழை"],"tr":["Ketuppadhooum Kettaarkkuch Chaarvaaimar Raange","Etuppadhooum Ellaam Mazhai"],"en":["'Tis rain works all: it ruin spreads, then timely aid supplies;","As, in the happy days before, it bids the ruined rise"],"s":"Rain by its absence ruins men; and by its existence restores them to fortune","ch":2,"sec":1,"th":"gratitude"},
  {"n":16,"ta":["விசும்பின் துளிவீழின் அல்லால்மற் றாங்கே","பசும்புல் தலைகாண்பு அரிது"],"tr":["Visumpin Thuliveezhin Allaalmar Raange","Pasumpul Thalaikaanpu Aridhu"],"en":["If from the clouds no drops of rain are shed","'Tis rare to see green herb lift up its head"],"s":"If no drop falls from the clouds, not even the green blade of grass will be seen","ch":2,"sec":1,"th":"gratitude"},
  {"n":17,"ta":["நெடுங்கடலும் தன்நீர்மை குன்றும் தடிந்தெழிலி","தான்நல்கா தாகி விடின்"],"tr":["Netungatalum Thanneermai Kundrum Thatindhezhili","Thaannalkaa Thaaki Vitin"],"en":["If clouds restrain their gifts and grant no rain,","The treasures fail in ocean's wide domain"],"s":"Even the wealth of the wide sea will be diminished, if the cloud that has drawn  (its waters) up gives them not back again  (in rain)","ch":2,"sec":1,"th":"gratitude"},
  {"n":18,"ta":["சிறப்பொடு பூசனை செல்லாது வானம்","வறக்குமேல் வானோர்க்கும் ஈண்டு"],"tr":["Sirappotu Poosanai Sellaadhu Vaanam","Varakkumel Vaanorkkum Eentu"],"en":["If heaven grow dry, with feast and offering never more,","Will men on earth the heavenly ones adore"],"s":"If the heaven dry up, neither yearly festivals, nor daily worship will be offered in this world, to the celestials","ch":2,"sec":1,"th":"gratitude"},
  {"n":19,"ta":["தானம் தவம்இரண்டும் தங்கா வியன்உலகம்","வானம் வழங்கா தெனின்"],"tr":["Thaanam Thavamirantum Thangaa Viyanulakam","Vaanam Vazhangaa Thenin"],"en":["If heaven its watery treasures ceases to dispense,","Through the wide world cease gifts, and deeds of 'penitence'"],"s":"If rain fall not, penance and alms-deeds will not dwell within this spacious world","ch":2,"sec":1,"th":"gratitude"},
  {"n":20,"ta":["நீர்இன்று அமையாது உலகெனின் யார்யார்க்கும்","வான்இன்று அமையாது ஒழுக்கு"],"tr":["Neerindru Amaiyaadhu Ulagenin Yaaryaarkkum","Vaanindru Amaiyaadhu Ozhukku"],"en":["When water fails, functions of nature cease, you say;","Thus when rain fails, no men can walk in ‘duty’s ordered way’"],"s":"Without water, nothing in nature works. Without rain, people cannot even live good and orderly lives.","ch":2,"sec":1,"th":"gratitude"},
  {"n":21,"ta":["ஒழுக்கத்து நீத்தார் பெருமை விழுப்பத்து","வேண்டும் பனுவல் துணிவு"],"tr":["Ozhukkaththu Neeththaar Perumai Vizhuppaththu","Ventum Panuval Thunivu"],"en":["The settled rule of every code requires, as highest good,","Their greatness who, renouncing all, true to their rule have stood"],"s":"The end and aim of all treatise is to extol beyond all other excellence, the greatness of those who, while abiding in the rule of conduct peculiar to their state, have abandoned all desire","ch":3,"sec":1,"th":"wisdom"},
  {"n":22,"ta":["துறந்தார் பெருமை துணைக்கூறின் வையத்து","இறந்தாரை எண்ணிக்கொண் டற்று"],"tr":["Thurandhaar Perumai Thunaikkoorin Vaiyaththu","Irandhaarai Ennikkon Tatru"],"en":["As counting those that from the earth have passed away,","'Tis vain attempt the might of holy men to say"],"s":"To describe the measure of the greatness of those who have forsaken the two-fold desires, is like counting the dead","ch":3,"sec":1,"th":"wisdom"},
  {"n":23,"ta":["இருமை வகைதெரிந்து ஈண்டுஅறம் பூண்டார்","பெருமை பிறங்கிற்று உலகு"],"tr":["Irumai Vakaidherindhu Eentuaram Poontaar","Perumai Pirangitru Ulaku"],"en":["Their greatness earth transcends, who, way of both worlds weighed,","In this world take their stand, in virtue's robe arrayed"],"s":"The greatness of those who have discovered the properties of both states of being, and renounced the world, shines forth on earth  (beyond all others)","ch":3,"sec":1,"th":"wisdom"},
  {"n":24,"ta":["உரனென்னும் தோட்டியான் ஓரைந்தும் காப்பான்","வரனென்னும் வைப்பிற்கோர் வித்து"],"tr":["Uranennum Thottiyaan Oraindhum Kaappaan","Varanennum Vaippirkor Viththu"],"en":["He, who with firmness, curb the five restrains,","Is seed for soil of yonder happy plains"],"s":"He who guides his five senses by the hook of wisdom will be a seed in the world of heaven","ch":3,"sec":1,"th":"wisdom"},
  {"n":25,"ta":["ஐந்தவித்தான் ஆற்றல் அகல்விசும்பு ளார்கோமான்","இந்திரனே சாலுங் கரி"],"tr":["Aindhaviththaan Aatral Akalvisumpu Laarkomaan","Indhirane Saalung Kari"],"en":["Their might who have destroyed 'the five', shall soothly tell","Indra, the lord of those in heaven's wide realms that dwell"],"s":"Indra, the king of the inhabitants of the spacious heaven, is himself, a sufficient proof of the strength of him who has subdued his five senses","ch":3,"sec":1,"th":"wisdom"},
  {"n":26,"ta":["செயற்கரிய செய்வார் பெரியர் சிறியர்","செயற்கரிய செய்கலா தார்"],"tr":["Seyarkariya Seyvaar Periyar Siriyar","Seyarkariya Seykalaa Thaar"],"en":["Things hard in the doing will great men do;","Things hard in the doing the mean eschew"],"s":"The great will do those things which is difficult to be done; but the mean cannot do them","ch":3,"sec":1,"th":"wisdom"},
  {"n":27,"ta":["சுவைஒளி ஊறுஓசை நாற்றமென ஐந்தின்","வகைதெரிவான் கட்டே உலகு"],"tr":["Suvaioli Ooruosai Naatramendru Aindhin","Vakaidherivaan Katte Ulaku"],"en":["Taste, light, touch, sound, and smell: who knows the way","Of all the five,  the world submissive owns his sway"],"s":"The world is within the knowledge of him who knows the properties of taste, sight, touch, hearing and smell","ch":3,"sec":1,"th":"wisdom"},
  {"n":28,"ta":["நிறைமொழி மாந்தர் பெருமை நிலத்து","மறைமொழி காட்டி விடும்"],"tr":["Niraimozhi Maandhar Perumai Nilaththu","Maraimozhi Kaatti Vitum"],"en":["The might of men whose word is never vain,","The 'secret word' shall to the earth proclaim"],"s":"The hidden words of the men whose words are full of effect, will shew their greatness to the world","ch":3,"sec":1,"th":"wisdom"},
  {"n":29,"ta":["குணமென்னும் குன்றேறி நின்றார் வெகுளி","கணமேயும் காத்தல் அரிது"],"tr":["Kunamennum Kundreri Nindraar Vekuli","Kanameyum Kaaththal Aridhu"],"en":["The wrath 'tis hard e'en for an instant to endure,","Of those who virtue's hill have scaled, and stand secure"],"s":"The anger of those who have ascended the mountain of goodness, though it continue but for a moment, cannot be resisted","ch":3,"sec":1,"th":"wisdom"},
  {"n":30,"ta":["அந்தணர் என்போர் அறவோர்மற் றெவ்வுயிர்க்கும்","செந்தண்மை பூண்டொழுக லான்"],"tr":["Andhanar Enpor Aravormar Revvuyir","Kkum Sendhanmai Poontozhuka Laan"],"en":["Towards all that breathe, with seemly graciousness adorned they live;","And thus to virtue's sons the name of 'Anthanar' men give"],"s":"The virtuous are truly called Anthanar; because in their conduct towards all creatures they are clothed in kindness","ch":3,"sec":1,"th":"wisdom"},
  {"n":31,"ta":["சிறப்புஈனும் செல்வமும் ஈனும் அறத்தினூஉங்கு","ஆக்கம் எவனோ உயிர்க்கு"],"tr":["Sirappu Eenum Selvamum Eenum","Araththinooungu Aakkam Evano Uyirkku"],"en":["It yields distinction, yields prosperity; what gain","Greater than virtue can a living man obtain"],"s":"Virtue will confer heaven and wealth; what greater source of happiness can man possess?","ch":4,"sec":1,"th":"effort"},
  {"n":32,"ta":["அறத்தினூஉங்கு ஆக்கமும் இல்லை அதனை","மறத்தலின் ஊங்கில்லை கேடு"],"tr":["Araththinooungu Aakkamum Illai Adhanai","Maraththalin Oongillai Ketu"],"en":["No greater gain than virtue aught can cause;","No greater loss than life oblivious of her laws"],"s":"There can be no greater source of good than  (the practice of) virtue; there can be no greater source of evil than the forgetfulness of it","ch":4,"sec":1,"th":"effort"},
  {"n":33,"ta":["ஒல்லும் வகையான் அறவினை ஓவாதே","செல்லும் வாய் எல்லாஞ் செயல்"],"tr":["Ollum Vakaiyaan Aravinai Ovaadhe","Sellum Vaai Ellaanj Cheyal"],"en":["To finish virtue’s work with ceaseless effort strive,","What way thou may’st, where’er thou see’st the work may thrive"],"s":"Do good in every way you can, at every chance you get. Never stop trying.","ch":4,"sec":1,"th":"effort"},
  {"n":34,"ta":["மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன்","ஆகுல நீர பிற"],"tr":["Manaththukkan Maasilan Aadhal Anaiththu","Aran Aakula Neera Pira"],"en":["Spotless be thou in mind! This only merits virtue's name;","All else, mere pomp of idle sound, no real worth can claim"],"s":"Let him who does virtuous deeds be of spotless mind; to that extent is virtue; all else is vain show","ch":4,"sec":1,"th":"effort"},
  {"n":35,"ta":["அழுக்காறு அவாவெகுளி இன்னாச்சொல் நான்கும்","இழுக்கா இயன்றது அறம்"],"tr":["Azhukkaaru Avaavekuli Innaachchol Naankum","Izhukkaa Iyandradhu Aram"],"en":["'Tis virtue when, his footsteps sliding not through envy, wrath,","Lust, evil speech-these four, man onwards moves in ordered path"],"s":"That conduct is virtue which is free from these four things, viz, malice, desire, anger and bitter speech","ch":4,"sec":1,"th":"effort"},
  {"n":36,"ta":["அன்றறிவாம் என்னாது அறஞ்செய்க மற்றது","பொன்றுங்கால் பொன்றாத் துணை"],"tr":["Andrarivaam Ennaadhu Aranjeyka Matradhu","Pondrungaal Pondraath Thunai"],"en":["Do deeds of virtue now Say not, 'To-morrow we'll be wise';","Thus, when thou diest, shalt thou find a help that never dies"],"s":"Defer not virtue to another day; receive her now; and at the dying hour she will be your undying friend","ch":4,"sec":1,"th":"effort"},
  {"n":37,"ta":["அறத்தாறு இதுவென வேண்டா சிவிகை","பொறுத்தானோடு ஊர்ந்தான் இடை"],"tr":["Araththaaru Ithuvena Ventaa Sivikai","Poruththaanotu Oorndhaan Itai"],"en":["Needs not in words to dwell on virtue's fruits: compare","The man in litter borne with them that toiling bear"],"s":"The fruit of virtue need not be described in books; it may be inferred from seeing the bearer of a palanquin and the rider therein","ch":4,"sec":1,"th":"effort"},
  {"n":38,"ta":["வீழ்நாள் படாஅமை நன்றாற்றின் அஃதொருவன்","வாழ்நாள் வழியடைக்கும் கல்"],"tr":["Veezhnaal Pataaamai Nandraatrin Aqdhoruvan","Vaazhnaal Vazhiyataikkum Kal"],"en":["If no day passing idly, good to do each day you toil,","A stone it will be to block the way of future days of moil"],"s":"If one allows no day to pass without some good being done, his conduct will be a stone to block up the passage to other births","ch":4,"sec":1,"th":"effort"},
  {"n":39,"ta":["அறத்தான் வருவதே இன்பம் மற்றெல்லாம்","புறத்த புகழும் இல"],"tr":["Araththaan Varuvadhe Inpam Mar","Rellaam Puraththa Pukazhum Ila"],"en":["What from virtue floweth, yieldeth dear delight;","All else extern, is void of glory's light"],"s":"Only that pleasure which flows from domestic virtue is pleasure; all else is not pleasure, and it is without praise","ch":4,"sec":1,"th":"effort"},
  {"n":40,"ta":["செயற்பால தோரும் அறனே ஒருவற்கு","உயற்பால தோரும் பழி"],"tr":["Seyarpaala Thorum Arane Oruvarku","Uyarpaala Thorum Pazhi"],"en":["'Virtue' sums the things that should be done;","'Vice' sums the things that man should shun"],"s":"That is virtue which each ought to do, and that is vice which each should shun","ch":4,"sec":1,"th":"effort"},
  {"n":41,"ta":["இல்வாழ்வான் என்பான் இயல்புடைய மூவர்க்கும்","நல்லாற்றின் நின்ற துணை"],"tr":["Ilvaazhvaan Enpaan Iyalputaiya Moovarkkum","Nallaatrin Nindra Thunai"],"en":["The men of household virtue, firm in way of good, sustain","The other orders three that rule professed maintain"],"s":"He will be called a  (true) householder, who is a firm support to the virtuous of the three orders in","ch":5,"sec":1,"th":"family"},
  {"n":42,"ta":["துறந்தார்க்கும் துவ்வாதவர்க்கும் இறந்தார்க்கும்","இல்வாழ்வான் என்பான் துணை"],"tr":["Thurandhaarkkum Thuvvaa Dhavarkkum Irandhaarkkum","Ilvaazhvaan Enpaan Thunai"],"en":["To anchorites, to indigent, to those who've passed away,","The man for household virtue famed is needful held and stay"],"s":"He will be said to flourish in domestic virtue who aids the forsaken, the poor, and the dead","ch":5,"sec":1,"th":"family"},
  {"n":43,"ta":["தென்புலத்தார் தெய்வம் விருந்தொக்கல் தானென்றாங்கு","ஐம்புலத்தாறு ஓம்பல் தலை"],"tr":["Thenpulaththaar Theyvam Virundhokkal Thaanendraangu","Aimpulaththaaru Ompal Thalai"],"en":["The manes, God, guests kindred, self, in due degree,","These five to cherish well is chiefest charity"],"s":"The chief  (duty of the householder) is to preserve the five-fold rule  (of conduct) towards the manes, the Gods, his guests, his relations and himself","ch":5,"sec":1,"th":"family"},
  {"n":44,"ta":["பழியஞ்சிப் பாத்தூண் உடைத்தாயின் வாழ்க்கை","வழியெஞ்சல் எஞ்ஞான்றும் இல்"],"tr":["Pazhiyanjip Paaththoon Utaiththaayin Vaazhkkai","Vazhiyenjal Egngnaandrum Il"],"en":["Who shares his meal with other, while all guilt he shuns,","His virtuous line unbroken though the ages runs"],"s":"His descendants shall never fail who, living in the domestic state, fears vice  (in the acquisition of property) and shares his food  (with others)","ch":5,"sec":1,"th":"family"},
  {"n":45,"ta":["அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை","பண்பும் பயனும் அது"],"tr":["Anpum Aranum Utaiththaayin Ilvaazhkkai","Panpum Payanum Adhu"],"en":["If love and virtue in the household reign,","This is of life the perfect grace and gain"],"s":"If the married life possess love and virtue, these will be both its duty and reward","ch":5,"sec":1,"th":"family"},
  {"n":46,"ta":["அறத்தாற்றின் இல்வாழ்க்கை ஆற்றின் புறத்தாற்றில்","போஒய்ப் பெறுவ தெவன்?"],"tr":["Araththaatrin Ilvaazhkkai Aatrin Puraththaatril","Pooip Peruva Thevan?"],"en":["If man in active household life a virtuous soul retain,","What fruit from other modes of virtue can he gain"],"s":"What will he who lives virtuously in the domestic state gain by going into the other,  (ascetic) state?","ch":5,"sec":1,"th":"family"},
  {"n":47,"ta":["இயல்பினான் இல்வாழ்க்கை வாழ்பவன் என்பான்","முயல்வாருள் எல்லாம் தலை"],"tr":["Iyalpinaan Ilvaazhkkai Vaazhpavan Enpaan","Muyalvaarul Ellaam Thalai"],"en":["In nature's way who spends his calm domestic days,","'Mid all that strive for virtue's crown hath foremost place"],"s":"Among all those who labour  (for future happiness) he is greatest who lives well in the household state","ch":5,"sec":1,"th":"family"},
  {"n":48,"ta":["ஆற்றின் ஒழுக்கி அறனிழுக்கா இல்வாழ்க்கை","நோற்பாரின் நோன்மை உடைத்து"],"tr":["Aatrin Ozhukki Aranizhukkaa Ilvaazhkkai","Norpaarin Nonmai Utaiththu"],"en":["Others it sets upon their way, itself from virtue ne'er declines;","Than stern ascetics' pains such life domestic brighter shines"],"s":"The householder who, not swerving from virtue, helps the ascetic in his way, endures more than those who endure penance","ch":5,"sec":1,"th":"family"},
  {"n":49,"ta":["அறனெனப் பட்டதே இல்வாழ்க்கை அஃதும்","பிறன்பழிப்ப தில்லாயின் நன்று"],"tr":["Aran Enap Pattadhe Ilvaazhkkai","Aqdhum Piranpazhippa Thillaayin Nandru"],"en":["The life domestic rightly bears true virtue's name;","That other too, if blameless found, due praise may claim"],"s":"The marriage state is truly called virtue The other state is also good, if others do not reproach it","ch":5,"sec":1,"th":"family"},
  {"n":50,"ta":["வையத்துள் வாழ்வாங்கு வாழ்பவன் வான்உறையும்","தெய்வத்துள் வைக்கப் படும்"],"tr":["Vaiyaththul Vaazhvaangu Vaazhpavan Vaanu�ryum","Theyvaththul Vaikkap Patum"],"en":["Who shares domestic life, by household virtues graced,","Shall, mid the Gods, in heaven who dwell, be placed"],"s":"He who on earth has lived in the conjugal state as he should live, will be placed among the Gods who dwell in heaven","ch":5,"sec":1,"th":"family"},
  {"n":51,"ta":["மனைக்தக்க மாண்புடையள் ஆகித்தற் கொண்டான்","வளத்தக்காள் வாழ்க்கைத் துணை"],"tr":["Manaikdhakka Maanputaiyal Aakiththar Kontaan","Valaththakkaal Vaazhkkaith Thunai"],"en":["As doth the house beseem, she shows her wifely dignity;","As doth her husband's wealth befit, she spends: help - meet is she"],"s":"She who has the excellence of home virtues, and can expend within the means of her husband, is a help in the domestic state","ch":6,"sec":1,"th":"family"},
  {"n":52,"ta":["மனைமாட்சி இல்லாள்கண் இல்லாயின் வாழ்க்கை","எனைமாட்சித் தாயினும் இல்"],"tr":["Manaimaatchi Illaalkan Illaayin Vaazhkkai","Enaimaatchith Thaayinum Il"],"en":["If household excellence be wanting in the wife,","Howe'er with splendour lived, all worthless is the life"],"s":"If the wife be devoid of domestic excellence, whatever  (other) greatness be possessed, the conjugal state, is nothing","ch":6,"sec":1,"th":"family"},
  {"n":53,"ta":["இல்லதென் இல்லவள் மாண்பானால் உள்ளதென்","இல்லவள் மாணாக் கடை?"],"tr":["Illadhen Illaval Maanpaanaal Ulladhen","Illaval Maanaak Katai?"],"en":["There is no lack within the house, where wife in worth excels,","There is no luck within the house, where wife dishonoured dwells"],"s":"If his wife be eminent  (in virtue), what does  (that man) not possess? If she be without excellence, what does  (he) possess?","ch":6,"sec":1,"th":"family"},
  {"n":54,"ta":["பெண்ணின் பெருந்தக்க யாவுள கற்பென்னும்","திண்மைஉண் டாகப் பெறின்"],"tr":["Pennin Perundhakka Yaavula Karpennum","Thinmaiun Taakap Perin"],"en":["If woman might of chastity retain,","What choicer treasure doth the world contain"],"s":"What is more excellent than a wife, if she possess the stability of chastity?","ch":6,"sec":1,"th":"family"},
  {"n":55,"ta":["தெய்வம் தொழாஅள் கொழுநன் தொழுதெழுவாள்","பெய்யெனப் பெய்யும் மழை"],"tr":["Theyvam Thozhaaal Kozhunan Thozhudhezhuvaal","Peyyenap Peyyum Mazhai"],"en":["No God adoring, low she bends before her lord;","Then rising, serves: the rain falls instant at her word"],"s":"If she, who does not worship God, but who rising worships her husband, say, \"let it rain,\" it will rain","ch":6,"sec":1,"th":"family"},
  {"n":56,"ta":["தற்காத்துத் தற்கொண்டாற் பேணித் தகைசான்ற","சொற்காத்துச் சோர்விலாள் பெண்"],"tr":["Tharkaaththuth Tharkontaar Penith Thakaisaandra","Sorkaaththuch Chorvilaal Pen"],"en":["Who guards herself, for husband's comfort cares, her household's fame,","In perfect wise with sleepless soul preserves, -give her a woman's name"],"s":"She is a wife who unweariedly guards herself, takes care of her husband, and preserves an unsullied fame","ch":6,"sec":1,"th":"family"},
  {"n":57,"ta":["சிறைகாக்கும் காப்பெவன் செய்யும் மகளிர்","நிறைகாக்கும் காப்பே தலை"],"tr":["Siraikaakkum Kaappevan Seyyum Makalir","Niraikaakkum Kaappe Thalai"],"en":["Of what avail is watch and ward?","Honour's woman's safest guard"],"s":"What avails the guard of a prison? The chief guard of a woman is her chastity","ch":6,"sec":1,"th":"family"},
  {"n":58,"ta":["பெற்றாற் பெறின்பெறுவர் பெண்டிர் பெருஞ்சிறப்புப்","புத்தேளிர் வாழும் உலகு"],"tr":["Petraar Perinperuvar Pentir Perunjirappup","Puththelir Vaazhum Ulaku"],"en":["If wife be wholly true to him who gained her as his bride,","Great glory gains she in the world where gods bliss abide"],"s":"If women shew reverence to their husbands, they will obtain great excellence in the world where the gods flourish","ch":6,"sec":1,"th":"family"},
  {"n":59,"ta":["புகழ்புரிந்த இல்லிலோர்க்கு இல்லை இகழ்வார்முன்","ஏறுபோல் பீடு நடை"],"tr":["Pukazhpurindha Illilorkku Illai Ikazhvaarmun","Erupol Peetu Natai"],"en":["Who have not spouses that in virtue's praise delight,","They lion-like can never walk in scorner's sight"],"s":"The man whose wife seeks not the praise  (of chastity) cannot walk with lion-like stately step, before those who revile them","ch":6,"sec":1,"th":"family"},
  {"n":60,"ta":["மங்கலம் என்ப மனைமாட்சி மற்று அதன்","நன்கலம் நன்மக்கட் பேறு"],"tr":["Mangalam Enpa Manaimaatchi Matru","Adhan Nankalam Nanmakkat Peru"],"en":["The house's 'blessing', men pronounce the house-wife excellent;","The gain of blessed children is its goodly ornament"],"s":"The excellence of a wife is the good of her husband; and good children are the jewels of that goodness","ch":6,"sec":1,"th":"family"},
  {"n":61,"ta":["பெறுமவற்றுள் யாமறிவது இல்லை அறிவறிந்த","மக்கட்பேறு அல்ல பிற"],"tr":["Perumavatrul Yaamarivadhu Illai Arivarindha","Makkatperu Alla Pira"],"en":["Of all that men acquire, we know not any greater gain,","Than that which by the birth of learned children men obtain"],"s":"Among all the benefits that may be acquired, we know no greater benefit than the acquisition of intelligent children","ch":7,"sec":1,"th":"family"},
  {"n":62,"ta":["எழுபிறப்பும் தீயவை தீண்டா பழிபிறங்காப்","பண்புடை மக்கட் பெறின்"],"tr":["Ezhupirappum Theeyavai Theentaa Pazhipirangaap","Panputai Makkat Perin"],"en":["Who children gain, that none reproach, of virtuous worth,","No evils touch them, through the sev'n-fold maze of birth"],"s":"The evils of the seven births shall not touch those who abtain children of a good disposition, free from vice","ch":7,"sec":1,"th":"family"},
  {"n":63,"ta":["தம்பொருள் என்பதம் மக்கள் அவர்பொருள்","தம்தம் வினையான் வரும்"],"tr":["Thamporul Enpadham Makkal Avarporul","Thamdham Vinaiyaan Varum"],"en":["'Man's children are his fortune, ' say the wise;","From each one's deeds his varied fortunes rise"],"s":"Men will call their sons their wealth, because it flows to them through the deeds which they  (sons) perform on their behalf","ch":7,"sec":1,"th":"family"},
  {"n":64,"ta":["அமிழ்தினும் ஆற்ற இனிதேதம் மக்கள்","சிறுகை அளாவிய கூழ்"],"tr":["Amizhdhinum Aatra Inidhedham Makkal","Sirukai Alaaviya Koozh"],"en":["Than God's ambrosia sweeter far the food before men laid,","In which the little hands of children of their own have play'd"],"s":"The rice in which the little hand of their children has dabbled will be far sweeter  (to the parent) than ambrosia","ch":7,"sec":1,"th":"family"},
  {"n":65,"ta":["மக்கள்மெய் தீண்டல் உடற்கின்பம் மற்றுஅவர்","சொற்கேட்டல் இன்பம் செவிக்கு"],"tr":["Makkalmey Theental Utarkinpam Matru","Avar Sorkettal Inpam Sevikku"],"en":["To patent sweet the touch of children dear;","Their voice is sweetest music to his ear"],"s":"The touch of children gives pleasure to the body, and the hearing of their words, pleasure to the ear","ch":7,"sec":1,"th":"family"},
  {"n":66,"ta":["குழல்இனிது யாழ்இனிது என்பதம் மக்கள்","மழலைச்சொல் கேளா தவர்"],"tr":["Kuzhal Inidhu Yaazhinidhu Enpadham","Makkal Mazhalaichchol Kelaa Thavar"],"en":["'The pipe is sweet, ' 'the lute is sweet, ' by them't will be averred,","Who music of their infants' lisping lips have never heard"],"s":"\"The pipe is sweet, the lute is sweet,\" say those who have not heard the prattle of their own children","ch":7,"sec":1,"th":"family"},
  {"n":67,"ta":["தந்தை மகற்காற்றும் நன்றி அவையத்து","முந்தி இருப்பச் செயல்"],"tr":["Thandhai Makarkaatrum Nandri Avaiyaththu","Mundhi Iruppach Cheyal"],"en":["Sire greatest boon on son confers, who makes him meet,","In councils of the wise to fill the highest seat"],"s":"The benefit which a father should confer on his son is to give him precedence in the assembly of the learned","ch":7,"sec":1,"th":"family"},
  {"n":68,"ta":["தம்மின்தம் மக்கள் அறிவுடைமை மாநிலத்து","மன்னுயிர்க் கெல்லாம் இனிது"],"tr":["Thammindham Makkal Arivutaimai Maanilaththu","Mannuyirk Kellaam Inidhu"],"en":["Their children's wisdom greater than their own confessed,","Through the wide world is sweet to every human breast"],"s":"That their children should possess knowledge is more pleasing to all men of this great earth than to themselves","ch":7,"sec":1,"th":"family"},
  {"n":69,"ta":["ஈன்ற பொழுதின் பெரிதுவக்கும் தன்மகனைச்","சான்றோன் எனக்கேட்ட தாய்"],"tr":["Eendra Pozhudhin Peridhuvakkum Thanmakanaich","Chaandron Enakketta Thaai"],"en":["When mother hears him named 'fulfill'd of wisdom's lore,","'Far greater joy she feels, than when her son she bore"],"s":"The mother who hears her son called \"a wise man\" will rejoice more than she did at his birth","ch":7,"sec":1,"th":"family"},
  {"n":70,"ta":["மகன்தந்தைக்கு ஆற்றும் உதவி இவன்தந்தை","என்நோற்றான் கொல் எனும் சொல்"],"tr":["Makandhandhaikku Aatrum Udhavi Ivandhandhai","Ennotraan Kol Enum Sol"],"en":["To sire, what best requital can by grateful child be done?","To make men say, 'What merit gained the father such a son? '"],"s":"(So to act) that it may be said \"by what great penance did his father beget him,\" is the benefit which a son should render to his father","ch":7,"sec":1,"th":"family"},
  {"n":71,"ta":["அன்பிற்கும் உண்டோ அடைக்குந்தாழ் ஆர்வலர்","புன்கணீர் பூசல் தரும்"],"tr":["Anpirkum Unto Ataikkundhaazh Aarvalar","Punkaneer Poosal Tharum"],"en":["And is there bar that can even love restrain?","The tiny tear shall make the lover's secret plain"],"s":"Is there any fastening that can shut in love? Tears of the affectionate will publish the love that is within","ch":8,"sec":1,"th":"compassion"},
  {"n":72,"ta":["அன்பிலார் எல்லாம் தமக்குரியர் அன்புடையார்","என்பும் உரியர் பிறர்க்கு"],"tr":["Anpilaar Ellaam Thamakkuriyar Anputaiyaar","Enpum Uriyar Pirarkku"],"en":["The loveless to themselves belong alone;","The loving men are others' to the very bone"],"s":"Those who are destitute of love appropriate all they have to themselves; but those who possess love consider even their bones to belong to others","ch":8,"sec":1,"th":"compassion"},
  {"n":73,"ta":["அன்போடு இயைந்த வழக்கென்ப ஆருயிர்க்கு","என்போடு இயைந்த தொடர்பு"],"tr":["Anpotu Iyaindha Vazhakkenpa Aaruyirkku","Enpotu Iyaindha Thotarpu"],"en":["Of precious soul with body's flesh and bone,","The union yields one fruit, the life of love alone"],"s":"They say that the union of soul and body in man is the fruit of the union of love and virtue  (in a former birth)","ch":8,"sec":1,"th":"compassion"},
  {"n":74,"ta":["அன்புஈனும் ஆர்வம் உடைமை அதுஈனும்","நண்பு என்னும் நாடாச் சிறப்பு"],"tr":["Anpu Eenum Aarvam Utaimai","Adhueenum Nanpu Ennum Naataach"],"en":["From love fond yearning springs for union sweet of minds;","And that the bond of rare excelling friendship binds"],"s":"Love begets desire: and that  (desire) begets the immeasureable excellence of friendship","ch":8,"sec":1,"th":"compassion"},
  {"n":75,"ta":["அன்புற்று அமர்ந்த வழக்கென்ப வையகத்து","இன்புற்றார் எய்தும் சிறப்பு"],"tr":["Anputru Amarndha Vazhakkenpa Vaiyakaththu","Inputraar Eydhum Sirappu"],"en":["Sweetness on earth and rarest bliss above,","These are the fruits of tranquil life of love"],"s":"These are the fruits of tranquil life of love","ch":8,"sec":1,"th":"compassion"},
  {"n":76,"ta":["அறத்திற்கே அன்புசார் பென்ப அறியார்","மறத்திற்கும் அஃதே துணை"],"tr":["Araththirke Anpusaar Penpa Ariyaar","Maraththirkum Aqdhe Thunai"],"en":["The unwise deem love virtue only can sustain,","It also helps the man who evil would restrain"],"s":"The ignorant say that love is an ally to virtue only, but it is also a help to get out of vice","ch":8,"sec":1,"th":"compassion"},
  {"n":77,"ta":["என்பி லதனை வெயில்போலக் காயுமே","அன்பி லதனை அறம்"],"tr":["Enpi Ladhanai Veyilpolak Kaayume","Anpi Ladhanai Aram"],"en":["As sun's fierce ray dries up the boneless things,","So loveless beings virtue's power to nothing brings"],"s":"Virtue will burn up the soul which is without love, even as the sun burns up the creature which is without bone, ie worms","ch":8,"sec":1,"th":"compassion"},
  {"n":78,"ta":["அன்பகத் தில்லா உயிர்வாழ்க்கை வன்பாற்கண்","வற்றல் மரந்தளிர்த் தற்று"],"tr":["Anpakath Thillaa Uyirvaazhkkai Vanpaarkan","Vatral Marandhalirth Thatru"],"en":["The loveless soul, the very joys of life may know,","When flowers, in barren soil, on sapless trees, shall blow"],"s":"The domestic state of that man whose mind is without love is like the flourishing of a withered tree upon the parched desert","ch":8,"sec":1,"th":"compassion"},
  {"n":79,"ta":["புறத்துறுப் பெல்லாம் எவன்செய்யும் யாக்கை","அகத்துறுப்பு அன்பி லவர்க்கு"],"tr":["Puraththurup Pellaam Evanseyyum Yaakkai","Akaththuruppu Anpi Lavarkku"],"en":["Though every outward part complete, the body's fitly framed;","What good, when soul within, of love devoid, lies halt and maimed"],"s":"Of what avail are all the external members  (of the body) to those who are destitute of love, the internal member","ch":8,"sec":1,"th":"compassion"},
  {"n":80,"ta":["அன்பின் வழியது உயிர்நிலை அஃதிலார்க்கு","என்புதோல் போர்த்த உடம்பு"],"tr":["Anpin Vazhiyadhu Uyirnilai Aqdhilaarkku","Enpudhol Porththa Utampu"],"en":["Bodies of loveless men are bony framework clad with skin;","Then is the body seat of life, when love resides within"],"s":"That body alone which is inspired with love contains a living soul: if void of it,  (the body) is bone overlaid with skin","ch":8,"sec":1,"th":"compassion"},
  {"n":81,"ta":["இருந்தோம்பி இல்வாழ்வ தெல்லாம் விருந்தோம்பி","வேளாண்மை செய்தற் பொருட்டு"],"tr":["Irundhompi Ilvaazhva Thellaam Virundhompi","Velaanmai Seydhar Poruttu"],"en":["All household cares and course of daily life have this in view","Guests to receive with courtesy, and kindly acts to do"],"s":"The whole design of living in the domestic state and laying up  (property) is  (to be able) to exercise the benevolence of hospitality","ch":9,"sec":1,"th":"compassion"},
  {"n":82,"ta":["விருந்து புறத்ததாத் தானுண்டல் சாவா","மருந்தெனினும் வேண் டற்பாற் றன்று"],"tr":["Virundhu Puraththadhaath Thaanuntal Saavaa","Marundheninum Ventarpaar Randru"],"en":["Though food of immortality should crown the board,","Feasting alone, the guests without unfed, is thing abhorred"],"s":"It is not fit that one should wish his guests to be outside  (his house) even though he were eating the food of immortality","ch":9,"sec":1,"th":"compassion"},
  {"n":83,"ta":["வருவிருந்து வைகலும் ஓம்புவான் வாழ்க்கை","பருவந்து பாழ்படுதல் இன்று"],"tr":["Varuvirundhu Vaikalum Ompuvaan Vaazhkkai","Paruvandhu Paazhpatudhal Indru"],"en":["Each day he tends the coming guest with kindly care;","Painless, unfailing plenty shall his household share"],"s":"The domestic life of the man that daily entertains the guests who come to him shall not be laid waste by poverty","ch":9,"sec":1,"th":"compassion"},
  {"n":84,"ta":["அகனமர்ந்து செய்யாள் உறையும் முகனமர்ந்து","நல்விருந்து ஓம்புவான் இல்"],"tr":["Akanamarndhu Seyyaal Uraiyum Mukanamarndhu","Nalvirundhu Ompuvaan Il"],"en":["With smiling face he entertains each virtuous guest,","'Fortune' with gladsome mind shall in his dwelling rest"],"s":"Lakshmi with joyous mind shall dwell in the house of that man who, with cheerful countenance, entertains the good as guests","ch":9,"sec":1,"th":"compassion"},
  {"n":85,"ta":["வித்தும் இடல்வேண்டும் கொல்லோ விருந்தோம்பி","மிச்சில் மிசைவான் புலம்"],"tr":["Viththum Italventum Kollo Virundhompi","Michchil Misaivaan Pulam"],"en":["Who first regales his guest, and then himself supplies,","O'er all his fields, unsown, shall plenteous harvests rise"],"s":"Is it necessary to sow the field of the man who, having feasted his guests, eats what may remain?","ch":9,"sec":1,"th":"compassion"},
  {"n":86,"ta":["செல்விருந்து ஓம்பி வருவிருந்து பார்த்திருப்பான்","நல்வருந்து வானத் தவர்க்கு"],"tr":["Selvirundhu Ompi Varuvirundhu Paarththiruppaan","Nalvarundhu Vaanath Thavarkku"],"en":["The guest arrived he tends, the coming guest expects to see;","To those in heavenly homes that dwell a welcome guest is he"],"s":"He who, having entertained the guests that have come, looks out for others who may yet come, will be a welcome guest to the inhabitants of heaven","ch":9,"sec":1,"th":"compassion"},
  {"n":87,"ta":["இனைத்துணைத் தென்பதொன் றில்லை விருந்தின்","துணைத்துணை வேள்விப் பயன்"],"tr":["Inaiththunaith Thenpadhon Rillai Virundhin","Thunaiththunai Velvip Payan"],"en":["To reckon up the fruit of kindly deeds were all in vain;","Their worth is as the worth of guests you entertain"],"s":"The advantages of benevolence cannot be measured; the measure  (of the virtue) of the guests  (entertained) is the only measure","ch":9,"sec":1,"th":"compassion"},
  {"n":88,"ta":["பரிந்தோம்பிப் பற்றற்றேம் என்பர் விருந்தோம்பி","வேள்வி தலைப்படா தார்"],"tr":["Parindhompip Patratrem Enpar Virundhompi","Velvi Thalaippataa Thaar"],"en":["With pain they guard their stores, yet 'All forlorn are we,","' they'll cry, Who cherish not their guests, nor kindly help supply"],"s":"Those who have taken no part in the benevolence of hospitality shall  (at length lament) saying, \"we have laboured and laid up wealth and are now without support.\"","ch":9,"sec":1,"th":"compassion"},
  {"n":89,"ta":["உடைமையுள் இன்மை விருந்தோம்பல் ஓம்பா","மடமை மடவார்கண் உண்டு"],"tr":["Utaimaiyul Inmai Virundhompal Ompaa","Matamai Matavaarkan Untu"],"en":["To turn from guests is penury, though worldly goods abound;","'Tis senseless folly, only with the senseless found"],"s":"That stupidity which excercises no hospitality is poverty in the midst of wealth It is the property of the stupid","ch":9,"sec":1,"th":"compassion"},
  {"n":90,"ta":["மோப்பக் குழையும் அனிச்சம் முகந்திரிந்து","நோக்கக் குநழ்யும் விருந்து"],"tr":["Moppak Kuzhaiyum Anichcham Mukandhirindhu","Nokkak Kuzhaiyum Virundhu"],"en":["The flower of 'Anicha' withers away, If you do but its fragrance inhale;","If the face of the host cold welcome convey, The guest's heart within him will fail"],"s":"As the Anicham flower fades in smelling, so fades the guest when the face is turned away","ch":9,"sec":1,"th":"compassion"},
  {"n":91,"ta":["இன்சொலால் ஈரம் அளைஇப் படிறுஇலவாம்","செம்பொருள் கண்டார்வாய்ச் சொல்"],"tr":["Insolaal Eeram Alaiip Patiruilavaam","Semporul Kantaarvaaich Chol"],"en":["Pleasant words are words with all pervading love that burn;","Words from his guileless mouth who can the very truth discern"],"s":"Sweet words are those which imbued with love and free from deceit flow from the mouth of the virtuous","ch":10,"sec":1,"th":"compassion"},
  {"n":92,"ta":["அகன்அமர்ந்து ஈதலின் நன்றே முகனமர்ந்து","இன்சொலன் ஆகப் பெறின்"],"tr":["Akanamarndhu Eedhalin Nandre Mukanamarndhu","Insolan Aakap Perin"],"en":["A pleasant word with beaming smile's preferred,","Even to gifts with liberal heart conferred"],"s":"Sweet speech, with a cheerful countenance is better than a gift made with a joyous mind","ch":10,"sec":1,"th":"compassion"},
  {"n":93,"ta":["முகத்தான் அமர்ந்து இனிதுநோக்கி அகத்தானாம்","இன்சொ லினதே அறம்"],"tr":["Mukaththaan Amarndhuinidhu Nokki Akaththaanaam","Inso Linadhe Aram"],"en":["With brightly beaming smile, and kindly light of loving eye,","And heart sincere, to utter pleasant words is charity"],"s":"Sweet speech, flowing from the heart  (uttered) with a cheerful countenance and a sweet look, is true virtue","ch":10,"sec":1,"th":"compassion"},
  {"n":94,"ta":["துன்புறூஉம் துவ்வாமை இல்லாகும் யார்மாட்டும்","இன்புறூஉம் இன்சொ லவர்க்கு"],"tr":["Thunpurooum Thuvvaamai Illaakum Yaarmaattum","Inpurooum Inso Lavarkku"],"en":["The men of pleasant speech that gladness breathe around,","Through indigence shall never sorrow's prey be found"],"s":"Sorrow-increasing poverty shall not come upon those who use towards all, pleasure-increasing sweetness of speech","ch":10,"sec":1,"th":"compassion"},
  {"n":95,"ta":["பணிவுடையன் இன்சொலன் ஆதல் ஒருவற்கு","அணியல்ல மற்றுப் பிற"],"tr":["Panivutaiyan Insolan Aadhal Oruvarku","Aniyalla Matrup Pira"],"en":["Humility with pleasant speech to man on earth,","Is choice adornment; all besides is nothing worth"],"s":"Humility and sweetness of speech are the ornaments of man; all others are not  (ornaments)","ch":10,"sec":1,"th":"compassion"},
  {"n":96,"ta":["அல்லவை தேய அறம்பெருகும் நல்லவை","நாடி இனிய சொலின்"],"tr":["Allavai Theya Aramperukum Nallavai","Naati Iniya Solin"],"en":["Who seeks out good, words from his lips of sweetness flow;","In him the power of vice declines, and virtues grow"],"s":"If a man, while seeking to speak usefully, speaks also sweetly, his sins will diminish and his virtue increase","ch":10,"sec":1,"th":"compassion"},
  {"n":97,"ta":["நயன்ஈன்று நன்றி பயக்கும் பயன்ஈன்று","பண்பின் தலைப்பிரியாச் சொல்"],"tr":["Nayan Eendru Nandri Payakkum","Payaneendru Panpin Thalaippiriyaach Chol"],"en":["The words of sterling sense, to rule of right that strict adhere,","To virtuous action prompting, blessings yield in every sphere"],"s":"That speech which, while imparting benefits ceases not to please, will yield righteousness  (for this world) and merit  (for the next world)","ch":10,"sec":1,"th":"compassion"},
  {"n":98,"ta":["சிறுமையுவு நீங்கிய இன்சொல் மறுமையும்","இம்மையும் இன்பம் தரும்"],"tr":["Sirumaiyul Neengiya Insol Marumaiyum","Immaiyum Inpam Tharum"],"en":["Sweet kindly words, from meanness free, delight of heart,","In world to come and in this world impart"],"s":"Sweet speech, free from harm to others, will give pleasure both in this world and in the next","ch":10,"sec":1,"th":"compassion"},
  {"n":99,"ta":["இன்சொல் இனிதீன்றல் காண்பான் எவன்கொலோ","வன்சொல் வழங்கு வது?"],"tr":["Insol Inidheendral Kaanpaan Evankolo","Vansol Vazhangu Vadhu?"],"en":["Who sees the pleasure kindly speech affords,","Why makes he use of harsh, repellant words"],"s":"Why does he use harsh words, who sees the pleasure which sweet speech yields?","ch":10,"sec":1,"th":"compassion"},
  {"n":100,"ta":["இனிய உளவாக இன்னாத கூறல்","கனிஇருப்பக் காய்கவர்ந் தற்று"],"tr":["Iniya Ulavaaka Innaadha Kooral","Kaniiruppak Kaaikavarn Thatru"],"en":["When pleasant words are easy, bitter words to use,","Is, leaving sweet ripe fruit, the sour unripe to choose"],"s":"To say disagreeable things when agreeable are at hand is like eating unripe fruit when there is ripe","ch":10,"sec":1,"th":"compassion"},
  {"n":101,"ta":["செய்யாமல் செய்த உதவிக்கு வையகமும்","வானகமும் ஆற்றல் அரிது"],"tr":["Seyyaamal Seydha Udhavikku Vaiyakamum","Vaanakamum Aatral Aridhu"],"en":["Assistance given by those who ne'er received our aid,","Is debt by gift of heaven and earth but poorly paid"],"s":"(The gift of) heaven and earth is not an equivalent for a benefit which is conferred where none had been received","ch":11,"sec":1,"th":"gratitude"},
  {"n":102,"ta":["காலத்தி னாற்செய்த நன்றி சிறிதெனினும்","ஞாலத்தின் மாணப் பெரிது"],"tr":["Kaalaththi Naarseydha Nandri Siridheninum","Gnaalaththin Maanap Peridhu"],"en":["A timely benefit, -though thing of little worth,","The gift itself, -in excellence transcends the earth"],"s":"A favour conferred in the time of need, though it be small  (in itself), is  (in value) much larger than the world","ch":11,"sec":1,"th":"gratitude"},
  {"n":103,"ta":["பயன்தூக்கார் செய்த உதவி நயன்தூக்கின்","நன்மை கடலின் பெரிது"],"tr":["Payandhookkaar Seydha Udhavi Nayandhookkin","Nanmai Katalin Peridhu"],"en":["Kindness shown by those who weigh not what the return may be:","When you ponder right its merit, 'Tis vaster than the sea"],"s":"If we weigh the excellence of a benefit which is conferred without weighing the return, it is larger than the sea","ch":11,"sec":1,"th":"gratitude"},
  {"n":104,"ta":["தினைத்துணை நன்றி செயினும் பனைத்துணையாக்","கொள்வர் பயன்தெரி வார்"],"tr":["Thinaiththunai Nandri Seyinum Panaiththunaiyaak","Kolvar Payandheri Vaar"],"en":["Each benefit to those of actions' fruit who rightly deem,","Though small as millet-seed, as palm-tree vast will seem"],"s":"Though the benefit conferred be as small as a millet seed, those who know its advantage will consider it as large as a palmyra fruit","ch":11,"sec":1,"th":"gratitude"},
  {"n":105,"ta":["உதவி வரைத்தன்று உதவி உதவி","செயப்பட்டார் சால்பின் வரைத்து"],"tr":["Udhavi Varaiththandru Udhavi Udhavi","Seyappattaar Saalpin Varaiththu"],"en":["The kindly aid's extent is of its worth no measure true;","Its worth is as the worth of him to whom the act you do"],"s":"The benefit itself is not the measure of the benefit; the worth of those who have received it is its measure","ch":11,"sec":1,"th":"gratitude"},
  {"n":106,"ta":["மறவற்க மாசற்றார் கேண்மை துறவற்க","துன்பத்துள் துப்பாயார் நட்பு"],"tr":["Maravarka Maasatraar Kenmai Thuravarka","Thunpaththul Thuppaayaar Natpu"],"en":["Kindness of men of stainless soul remember evermore","Forsake thou never friends who were thy stay in sorrow sore"],"s":"Forsake not the friendship of those who have been your staff in adversity Forget not be benevolence of the blameless","ch":11,"sec":1,"th":"gratitude"},
  {"n":107,"ta":["எழுமை எழுபிறப்பும் உள்ளுவர் தங்கண்","விழுமந் துடைத்தவர் நட்பு"],"tr":["Ezhumai Ezhupirappum Ulluvar Thangan","Vizhuman Thutaiththavar Natpu"],"en":["Through all seven worlds, in seven-fold birth, Remains in mem'ry of the wise","Friendship of those who wiped on earth, The tears of sorrow from their eyes"],"s":"(The wise) will remember throughout their seven-fold births the love of those who have wiped away their affliction","ch":11,"sec":1,"th":"gratitude"},
  {"n":108,"ta":["நன்றி மறப்பது நன்றன்று நன்றல்லது","அன்றே மறப்பது நன்று"],"tr":["Nandri Marappadhu Nandrandru Nandralladhu","Andre Marappadhu Nandru"],"en":["‘Tis never good to let the thought of good things done thee pass away;","Of things not good, ‘tis good to rid thy memory that very day"],"s":"Never forget a kindness done to you. Forget any harm on the very same day.","ch":11,"sec":1,"th":"gratitude"},
  {"n":109,"ta":["கொன்றன்ன இன்னா செயினும் அவர்செய்த","ஒன்றுநன்று உள்ளக் கெடும்"],"tr":["Kondranna Innaa Seyinum Avarseydha","Ondrunandru Ullak Ketum"],"en":["Effaced straightway is deadliest injury,","By thought of one kind act in days gone by"],"s":"Though one inflict an injury great as murder, it will perish before the thought of one benefit  (formerly) conferred","ch":11,"sec":1,"th":"gratitude"},
  {"n":110,"ta":["எந்நன்றி கொன்றார்க்கும் உய்வுண்டாம் உய்வில்லை","செய்ந்நன்றி கொன்ற மகற்கு"],"tr":["Ennandri Kondraarkkum Uyvuntaam Uyvillai","Seynnandri Kondra Makarku"],"en":["Who every good have killed, may yet destruction flee;","Who 'benefit' has killed, that man shall ne'er 'scape free"],"s":"He who has killed every virtue may yet escape; there is no escape for him who has killed a benefit","ch":11,"sec":1,"th":"gratitude"},
  {"n":111,"ta":["தகுதி எனவொன்று நன்றே பகுதியால்","பாற்பட்டு ஒழுகப் பெறின்"],"tr":["Thakudhi Enavondru Nandre Pakudhiyaal","Paarpattu Ozhukap Perin"],"en":["If justice, failing not, its quality maintain,","Giving to each his due, -'tis man's one highest gain"],"s":"That equity which consists in acting with equal regard to each of  (the three) divisions of men [enemies, strangers and friends] is a pre-eminent virtue","ch":12,"sec":1,"th":"calm"},
  {"n":112,"ta":["செப்பம் உடையவன் ஆக்கஞ் சிதைவின்றி","எச்சத்திற் கேமாப்பு உடைத்து"],"tr":["Seppam Utaiyavan Aakkanj Chidhaivindri","Echchaththir Kemaappu Utaiththu"],"en":["The just man's wealth unwasting shall endure,","And to his race a lasting joy ensure"],"s":"The wealth of the man of rectitude will not perish, but will bring happiness also to his posterity","ch":12,"sec":1,"th":"calm"},
  {"n":113,"ta":["நன்றே தரினும் நடுவிகந்தாம் ஆக்கத்தை","அன்றே யொழிய விடல்"],"tr":["Nandre Tharinum Natuvikandhaam Aakkaththai","Andre Yozhiya Vital"],"en":["Though only good it seem to give, yet gain","By wrong acquired, not e'en one day retain"],"s":"Forsake in the very moment  (of acquisition) that gain which, though it should bring advantage, is without equity","ch":12,"sec":1,"th":"calm"},
  {"n":114,"ta":["தக்கார் தகவிலர் என்பது அவரவர்","எச்சத்தாற் காணப்ப படும்"],"tr":["Thakkaar Thakavilar Enpadhu Avaravar","Echchaththaar Kaanap Patum"],"en":["Who just or unjust lived shall soon appear:","By each one's offspring shall the truth be clear"],"s":"The worthy and unworthy may be known by the existence or otherwise of good offsprings","ch":12,"sec":1,"th":"calm"},
  {"n":115,"ta":["கேடும் பெருக்கமும் இல்லல்ல நெஞ்சத்துக்","கோடாமை சான்றோர்க் கணி"],"tr":["Ketum Perukkamum Illalla Nenjaththuk","Kotaamai Saandrork Kani"],"en":["The gain and loss in life are not mere accident;","Just mind inflexible is sages' ornament"],"s":"Loss and gain come not without cause; it is the ornament of the wise to preserve evenness of mind  (under both)","ch":12,"sec":1,"th":"calm"},
  {"n":116,"ta":["கெடுவல்யான் என்பது அறிகதன் நெஞ்சம்","நடுவொரீஇ அல்ல செயின்"],"tr":["Ketuvalyaan Enpadhu Arikadhan Nenjam","Natuvoreei Alla Seyin"],"en":["If, right deserting, heart to evil turn,","Let man impending ruin's sign discern"],"s":"Let him whose mind departing from equity commits sin well consider thus within himself, \"I shall perish.\"","ch":12,"sec":1,"th":"calm"},
  {"n":117,"ta":["கெடுவாக வையாது உலகம் நடுவாக","நன்றிக்கண் தங்கியான் தாழ்வு"],"tr":["Ketuvaaka Vaiyaadhu Ulakam Natuvaaka","Nandrikkan Thangiyaan Thaazhvu"],"en":["The man who justly lives, tenacious of the right,","In low estate is never low to wise man's sight"],"s":"The great will not regard as poverty the low estate of that man who dwells in the virtue of equity","ch":12,"sec":1,"th":"calm"},
  {"n":118,"ta":["சமன்செய்து சீர்தூக்குங் கோல்போல் அமைந்தொருபால்","கோடாமை சான்றோர்க் கணி"],"tr":["Samanseydhu Seerdhookkung Kolpol Amaindhorupaal","Kotaamai Saandrork Kani"],"en":["To stand, like balance-rod that level hangs and rightly weighs,","With calm unbiassed equity of soul, is sages' praise"],"s":"To incline to neither side, but to rest impartial as the even-fixed scale is the ornament of the wise","ch":12,"sec":1,"th":"calm"},
  {"n":119,"ta":["சொற்கோட்டம் இல்லது செப்பம் ஒருதலையா","உட்கோட்டம் இன்மை பெறின்"],"tr":["Sorkottam Illadhu Seppam Orudhalaiyaa","Utkottam Inmai Perin"],"en":["Inflexibility in word is righteousness,","If men inflexibility of soul possess"],"s":"Freedom from obliquity of speech is rectitude, if there be  (corresponding) freedom from bias of mind","ch":12,"sec":1,"th":"calm"},
  {"n":120,"ta":["வாணிகம் செய்வார்க்கு வாணிகம் பேணிப்","பிறவும் தமபோல் செயின்"],"tr":["Vaanikam Seyvaarkku Vaanikam Penip","Piravum Thamapol Seyin"],"en":["As thriving trader is the trader known,","Who guards another's interests as his own"],"s":"The true merchandize of merchants is to guard and do by the things of others as they do by their own","ch":12,"sec":1,"th":"calm"},
  {"n":121,"ta":["அடக்கம் அமரருள் உய்க்கும் அடங்காமை","ஆரிருள் உய்த்து விடும்"],"tr":["Atakkam Amararul Uykkum Atangaamai","Aarirul Uyththu Vitum"],"en":["Control of self does man conduct to bliss th' immortals share;","Indulgence leads to deepest night, and leaves him there"],"s":"Self-control will place  (a man) among the Gods; the want of it will drive  (him) into the thickest darkness  (of hell)","ch":13,"sec":1,"th":"calm"},
  {"n":122,"ta":["காக்க பொருளா அடக்கத்தை ஆக்கம்","அதனினூஉங் கில்லை உயிர்க்கு"],"tr":["Kaakka Porulaa Atakkaththai Aakkam","Adhaninooung Killai Uyirkku"],"en":["Guard thou as wealth the power of self-control;","Than this no greater gain to living soul"],"s":"Let self-control be guarded as a treasure; there is no greater source of good for man than that","ch":13,"sec":1,"th":"calm"},
  {"n":123,"ta":["செறிவறிந்து சீர்மை பயக்கும் அறிவறிந்து","ஆற்றின் அடங்கப் பெறின்"],"tr":["Serivarindhu Seermai Payakkum Arivarindhu","Aatrin Atangap Perin"],"en":["If versed in wisdom's lore by virtue's law you self restrain","Your self-repression known will yield you glory's gain"],"s":"Knowing that self-control is knowledge, if a man should control himself, in the prescribed course, such self-control will bring him distinction among the wise","ch":13,"sec":1,"th":"calm"},
  {"n":124,"ta":["நிலையின் திரியாது அடங்கியான் தோற்றம்","மலையினும் மாணப் பெரிது"],"tr":["Nilaiyin Thiriyaadhu Atangiyaan Thotram","Malaiyinum Maanap Peridhu"],"en":["In his station, all unswerving, if man self subdue,","Greater he than mountain proudly rising to the view"],"s":"More lofty than a mountain will be the greatness of that man who without swerving from his domestic state, controls himself","ch":13,"sec":1,"th":"calm"},
  {"n":125,"ta":["எல்லார்க்கும் நன்றாம் பணிதல் அவருள்ளும்","செல்வர்க்கே செல்வம் தகைத்து"],"tr":["Ellaarkkum Nandraam Panidhal Avarullum","Selvarkke Selvam Thakaiththu"],"en":["To all humility is goodly grace; but chief to them","With fortune blessed, -'tis fortune's diadem"],"s":"Humility is good in all; but especially in the rich it is  (the excellence of) higher riches","ch":13,"sec":1,"th":"calm"},
  {"n":126,"ta":["ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின்","எழுமையும் ஏமாப் புடைத்து"],"tr":["Orumaiyul Aamaipol Aindhatakkal Aatrin","Ezhumaiyum Emaap Putaiththu"],"en":["Like tortoise, who the five restrains","In one, through seven world bliss obtains"],"s":"Should one throughout a single birth, like a tortoise keep in his five senses, the fruit of it will prove a safe-guard to him throughout the seven-fold births.","ch":13,"sec":1,"th":"calm"},
  {"n":127,"ta":["யாகாவா ராயினும் நாகாக்க காவாக்கால்","சோகாப்பர் சொல்லிழுக்குப் பட்டு"],"tr":["Yaakaavaa Raayinum Naakaakka Kaavaakkaal","Sokaappar Sollizhukkup Pattu"],"en":["Whate'er they fail to guard, o'er lips men guard should keep;","If not, through fault of tongue, they bitter tears shall weep"],"s":"Whatever besides you leave unguarded, guard your tongue; otherwise errors of speech and the consequent misery will ensue","ch":13,"sec":1,"th":"calm"},
  {"n":128,"ta":["ஒன்றானுந் தீச்சொல் பொருட்பயன் உண்டாயின்","நன்றாகா தாகி விடும்"],"tr":["Ondraanun Theechchol Porutpayan Untaayin","Nandraakaa Thaaki Vitum"],"en":["Though some small gain of good it seem to bring,","The evil word is parent still of evil thing"],"s":"If a man's speech be productive of a single evil, all the good by him will be turned into evil","ch":13,"sec":1,"th":"calm"},
  {"n":129,"ta":["தீயினாற் சுட்டபுண் உள்ளாறும் ஆறாதே","நாவினாற் சுட்ட வடு"],"tr":["Theeyinaar Suttapun Ullaarum Aaraadhe","Naavinaar Sutta Vatu"],"en":["In flesh by fire inflamed, nature may thoroughly heal the sore;","In soul by tongue inflamed, the ulcer healeth never more"],"s":"The wound which has been burnt in by fire may heal, but a wound burnt in by the tongue will never heal","ch":13,"sec":1,"th":"calm"},
  {"n":130,"ta":["கதங்காத்துக் கற்றடங்கல் ஆற்றுவான் செவ்வி","அறம்பார்க்கும் ஆற்றின் நுழைந்து"],"tr":["Kadhangaaththuk Katratangal Aatruvaan Sevvi","Arampaarkkum Aatrin Nuzhaindhu"],"en":["Who learns restraint, and guards his soul from wrath,","Virtue, a timely aid, attends his path"],"s":"Virtue, seeking for an opportunity, will come into the path of that man who, possessed of learning and self-control, guards himself against anger","ch":13,"sec":1,"th":"calm"},
  {"n":131,"ta":["ஒழுக்கம் விழுப்பந் தரலான் ஒழுக்கம்","உயிரினும் ஓம்பப் படும்"],"tr":["Ozhukkam Vizhuppan Tharalaan Ozhukkam","Uyirinum Ompap Patum"],"en":["'Decorum' gives especial excellence; with greater care","'Decorum' should men guard than life, which all men share"],"s":"Propriety of conduct leads to eminence, it should therefore be preserved more carefully than life","ch":14,"sec":1,"th":"calm"},
  {"n":132,"ta":["பரிந்தோம்பிக் காக்க ஒழுக்கம் தெரிந்தோம்பித்","தேரினும் அஃதே துணை"],"tr":["Parindhompik Kaakka Ozhukkam Therindhompith","Therinum Aqdhe Thunai"],"en":["Searching, duly watching, learning, 'decorum' still we find;","Man's only aid; toiling, guard thou this with watchful mind"],"s":"Let propriety of conduct be laboriously preserved and guarded; though one know and practise and excel in many virtues, that will be an eminent aid","ch":14,"sec":1,"th":"calm"},
  {"n":133,"ta":["ஒழுக்கம் உடைமை குடிமை இழுக்கம்","இழிந்த பிறப்பாய் விடும்"],"tr":["Ozhukkam Utaimai Kutimai Izhukkam","Izhindha Pirappaai Vitum"],"en":["'Decorum's' true nobility on earth;","'Indecorum's' issue is ignoble birth"],"s":"Propriety of conduct is true greatness of birth, and impropriety will sink into a mean birth","ch":14,"sec":1,"th":"calm"},
  {"n":134,"ta":["மறப்பினும் ஓத்துக் கொளலாகும் பார்ப்பான்","பிறப்பொழுக்கங் குன்றக் கெடும்"],"tr":["Marappinum Oththuk Kolalaakum Paarppaan","Pirappozhukkang Kundrak Ketum"],"en":["Though he forget, the Brahman may regain his Vedic lore;","Failing in 'decorum due, ' birthright's gone for evermore"],"s":"A Brahman though he should forget the Vedas may recover it by reading; but, if he fail in propriety of conduct even his high birth will be destroyed","ch":14,"sec":1,"th":"calm"},
  {"n":135,"ta":["அழுக்கா றுடையான்கண் ஆக்கம்போன்று இல்லை","ஒழுக்க மிலான்கண் உயர்வு"],"tr":["Azhukkaa Rutaiyaankan Aakkampondru Illai","Ozhukka Milaankan Uyarvu"],"en":["The envious soul in life no rich increase of blessing gains,","So man of 'due decorum' void no dignity obtains"],"s":"Just as the envious man will be without wealth, so will the man of destitute of propriety of conduct be without greatness","ch":14,"sec":1,"th":"calm"},
  {"n":136,"ta":["ஒழுக்கத்தின் ஒல்கார் உரவோர் இழுக்கத்தின்","ஏதம் படுபாக் கறிந்து"],"tr":["Ozhukkaththin Olkaar Uravor Izhukkaththin","Edham Patupaak Karindhu"],"en":["The strong of soul no jot abate of 'strict decorum's' laws,","Knowing that 'due decorum's' breach foulest disgrace will cause"],"s":"Those firm in mind will not slacken in their observance of the proprieties of life, knowing, as they do, the misery that flows from the transgression from them","ch":14,"sec":1,"th":"calm"},
  {"n":137,"ta":["ஒழுக்கத்தின் எய்துவர் மேன்மை இழுக்கத்தின்","எய்துவர் எய்தாப் பழி"],"tr":["Ozhukkaththin Eydhuvar Menmai Izhukkaththin","Eydhuvar Eydhaap Pazhi"],"en":["'Tis source of dignity when 'true decorum' is preserved;","Who break 'decorum's' rules endure e'en censures undeserved"],"s":"From propriety of conduct men obtain greatness; from impropriety comes insufferable disgrace","ch":14,"sec":1,"th":"calm"},
  {"n":138,"ta":["நன்றிக்கு வித்தாகும் நல்லொழுக்கம் தீயொழுக்கம்","என்றும் இடும்பை தரும்"],"tr":["Nandrikku Viththaakum Nallozhukkam Theeyozhukkam","Endrum Itumpai Tharum"],"en":["'Decorum true' observed a seed of good will be;","'Decorum's breach' will sorrow yield eternally"],"s":"Propriety of conduct is the seed of virtue; impropriety will ever cause sorrow","ch":14,"sec":1,"th":"calm"},
  {"n":139,"ta":["ஒழுக்க முடையவர்க்கு ஒல்லாவே தீய","வழுக்கியும் வாயாற் சொலல்"],"tr":["Ozhukka Mutaiyavarkku Ollaave Theeya","Vazhukkiyum Vaayaar Solal"],"en":["It cannot be that they who 'strict decorum's' law fulfil,","E'en in forgetful mood, should utter words of ill"],"s":"Those who study propriety of conduct will not speak evil, even forgetfully","ch":14,"sec":1,"th":"calm"},
  {"n":140,"ta":["உலகத்தோடு ஒட்ட ஒழுகல் பலகற்றும்","கல்லார் அறிவிலா தார்"],"tr":["Ulakaththotu Otta Ozhukal Palakatrum","Kallaar Arivilaa Thaar"],"en":["Who know not with the world in harmony to dwell,","May many things have learned, but nothing well"],"s":"Those who know not how to act agreeably to the world, though they have learnt many things, are still ignorant","ch":14,"sec":1,"th":"calm"},
  {"n":141,"ta":["பிறன்பொருளாள் பெட்டொழுகும் பேதைமை ஞாலத்து","அறம்பொருள் கண்டார்கண் இல்"],"tr":["Piranporulaal Pettozhukum Pedhaimai Gnaalaththu","Aramporul Kantaarkan Il"],"en":["Who laws of virtue and possession's rights have known,","Indulge no foolish love of her by right another's own"],"s":"The folly of desiring her who is the property of another will not be found in those who know  (the attributes of) virtue and  (the rights of) property","ch":15,"sec":1,"th":"calm"},
  {"n":142,"ta":["அறன்கடை நின்றாருள் எல்லாம் பிறன்கடை","நின்றாரின் பேதையார் இல்"],"tr":["Arankatai Nindraarul Ellaam Pirankatai","Nindraarin Pedhaiyaar Il"],"en":["No fools, of all that stand from virtue's pale shut out,","Like those who longing lurk their neighbour's gate without"],"s":"Among all those who stand on the outside of virtue, there are no greater fools than those who stand outside their neighbour's door","ch":15,"sec":1,"th":"calm"},
  {"n":143,"ta":["விளிந்தாரின் வேறல்லர் மன்ற தெளிந்தாரில்","தீமை புரிந்து ஒழுகு வார்"],"tr":["Vilindhaarin Verallar Mandra Thelindhaaril","Theemai Purindhu Ozhuku Vaar"],"en":["They're numbered with the dead, e'en while they live, -how otherwise?","With wife of sure confiding friend who evil things devise"],"s":"Certainly they are no better than dead men who desire evil towards the wife of those who","ch":15,"sec":1,"th":"calm"},
  {"n":144,"ta":["எனைத்துணையர் ஆயினும் என்னாம் தினைத்துணையும்","தேரான் பிறனில் புகல்"],"tr":["Enaiththunaiyar Aayinum Ennaam Thinaiththunaiyum","Theraan Piranil Pukal"],"en":["How great soe'er they be, what gain have they of life,","Who, not a whit reflecting, seek a neighbour's wife"],"s":"However great one may be, what does it avail if, without at all considering his guilt, he goes unto the wife of another?","ch":15,"sec":1,"th":"calm"},
  {"n":145,"ta":["எளிதென இல்லிறப்பான் எய்துமெஞ் ஞான்றும்","விளியாது நிற்கும் பழி"],"tr":["Elidhena Illirappaan Eydhumenj Gnaandrum","Viliyaadhu Nirkum Pazhi"],"en":["'Mere triflel' saying thus, invades the home, so he ensures","A gain of guilt that deathless aye endures"],"s":"He who thinks lightly of going into the wife of another acquires guilt that will abide with him imperishably and for ever","ch":15,"sec":1,"th":"calm"},
  {"n":146,"ta":["பகைபாவம் அச்சம் பழியென நான்கும்","இகவாவாம் இல்லிறப்பான் கண்"],"tr":["Pakaipaavam Achcham Pazhiyena Naankum","Ikavaavaam Illirappaan Kan"],"en":["Who home ivades, from him pass nevermore,","Hatred and sin, fear, foul disgrace; these four"],"s":"Hatred, sin, fear, disgrace; these four will never leave him who goes in to his neighbour's wife","ch":15,"sec":1,"th":"calm"},
  {"n":147,"ta":["அறனியலான் இல்வாழ்வான் என்பான் பிறனியலாள்","பெண்மை நயவா தவன்"],"tr":["Araniyalaan Ilvaazhvaan Enpaan Piraniyalaal","Penmai Nayavaa Thavan"],"en":["Who sees the wife, another's own, with no desiring eye","In sure domestic bliss he dwelleth ever virtuously"],"s":"He who desires not the womanhood of her who should walk according to the will of another will be praised as a virtuous house-holder","ch":15,"sec":1,"th":"calm"},
  {"n":148,"ta":["பிறன்மனை நோக்காத பேராண்மை சான்றோர்க்கு","அறனொன்றோ ஆன்ற வொழுக்கு"],"tr":["Piranmanai Nokkaadha Peraanmai Saandrorkku","Aranondro Aandra Vozhukku"],"en":["Manly excellence, that looks not on another's wife,","Is not virtue merely, 'tis full 'propriety' of life"],"s":"That noble manliness which looks not at the wife of another is the virtue and dignity of the great","ch":15,"sec":1,"th":"calm"},
  {"n":149,"ta":["நலக்குரியார் யாரெனின் நாமநீர் வைப்பின்","பிறர்க்குரியாள் தோள்தோயா தார்"],"tr":["Nalakkuriyaar Yaarenin Naamaneer Vaippin","Pirarkkuriyaal Tholdhoyaa Thaar"],"en":["Who 're good indeed, on earth begirt by ocean's gruesome tide?","The men who touch not her that is another's bride"],"s":"Is it asked, \"who are those who shall obtain good in this world surrounded by the terror-producing sea?\" Those who touch not the shoulder of her who belongs to another","ch":15,"sec":1,"th":"calm"},
  {"n":150,"ta":["அறன்வரையான் அல்ல செயினும் பிறன்வரையாள்","பெண்மை நயவாமை நன்று"],"tr":["Aranvaraiyaan Alla Seyinum Piranvaraiyaal","Penmai Nayavaamai Nandru"],"en":["Though virtue's bounds he pass, and evil deeds hath wrought;","At least, 'tis good if neighbour's wife he covet not"],"s":"Though a man perform no virtuous deeds and commit  (every) vice, it will be well if he desire not the womanhood of her who is within the limit  (of the house) of another","ch":15,"sec":1,"th":"calm"},
  {"n":151,"ta":["அகழ்வாரைத் தாங்கும் நிலம்போலத் தம்மை","இகழ்வார்ப் பொறுத்தல் தலை"],"tr":["Akazhvaaraith Thaangum Nilampolath Thammai","Ikazhvaarp Poruththal Thalai"],"en":["As earth bears up the men who delve into her breast,","To bear with scornful men of virtues is the best"],"s":"The earth holds up even the people who dig it. In the same way, bear with those who insult you. That is the greatest virtue.","ch":16,"sec":1,"th":"patience"},
  {"n":152,"ta":["பொறுத்தல் இறப்பினை என்றும் அதனை","மறத்தல் அதனினும் நன்று"],"tr":["Poruththal Irappinai Endrum Adhanai","Maraththal Adhaninum Nandru"],"en":["Forgiving trespasses is good always;","Forgetting them hath even higher praise"],"s":"Forgiving someone is always good. Forgetting the hurt is even better.","ch":16,"sec":1,"th":"patience"},
  {"n":153,"ta":["இன்மையுள் இன்மை விருந்தொரால் வன்மையுள்","வன்மை மடவார்ப் பொறை"],"tr":["Inmaiyul Inmai Virundhoraal Vanmaiyul","Vanmai Matavaarp Porai"],"en":["The sorest poverty is bidding guest unfed depart;","The mightiest might to bear with men of foolish heart"],"s":"To neglect hospitality is poverty of poverty To bear with the ignorant is might of might","ch":16,"sec":1,"th":"patience"},
  {"n":154,"ta":["நிறையுடைமை நீங்காமை வேண்டின் பொற்யுடைமை","போற்றி யொழுகப் படும்"],"tr":["Niraiyutaimai Neengaamai Ventin Poraiyutaimai","Potri Yozhukap Patum"],"en":["Seek'st thou honour never tarnished to retain;","So must thou patience, guarding evermore, maintain"],"s":"If you desire that greatness should never leave, you preserve in your conduct the exercise of patience","ch":16,"sec":1,"th":"patience"},
  {"n":155,"ta":["ஒறுத்தாரை ஒன்றாக வையாரே வைப்பர்","பொறுத்தாரைப் பொன்போற் பொதிந்து"],"tr":["Orththaarai Ondraakai VaaiyaaRe Vaippar","Poruththaaraip Ponpol Pothindhu"],"en":["Who wreak their wrath as worthless are despised;","Who patiently forbear as gold are prized"],"s":"People who lash out in anger are thrown away like trash. Patient people are kept safe like gold.","ch":16,"sec":1,"th":"patience"},
  {"n":156,"ta":["ஒறுத்தார்க்கு ஒருநாளை இன்பம் பொறுத்தார்க்குப்","பொன்றுந் துணையும் புகழ்"],"tr":["Oruththaarkku Orunaalai Inpam Poruththaarkkup","Pondrun Thunaiyum Pukazh"],"en":["Who wreak their wrath have pleasure for a day;","Who bear have praise till earth shall pass away"],"s":"The pleasure of the resentful continues for a day The praise of the patient will continue until  (the final destruction of) the world","ch":16,"sec":1,"th":"patience"},
  {"n":157,"ta":["திறனல்ல திறப்பிறர் செய்யினும் நோன்து","அறனல் செய்யாமை நன்று"],"tr":["Thiranalla Thirappirar Seyyinum Noanthu","Aranala Seyyaamai Nandru"],"en":["Though others work thee ill, thus shalt thou blessing reap;","Grieve for their sin, thyself from vicious action keep"],"s":"Even if others do you wrong, do not do wrong back. Feel sorry for their mistake, and stay good.","ch":16,"sec":1,"th":"patience"},
  {"n":158,"ta":["மிகுதியான் மிக்கவை செய்தாரைத் தாந்தம்","தகுதியான் வென்று விடல்"],"tr":["Mikudhiyaan Mikkavai Seydhaaraith Thaandham","Thakudhiyaan Vendru Vital"],"en":["With overweening pride when men with injuries assail,","By thine own righteous dealing shalt thou mightily prevail"],"s":"Let a man by patience overcome those who through pride commit excesses","ch":16,"sec":1,"th":"patience"},
  {"n":159,"ta":["துறந்தாரின் தூய்மை உடையர் இறந்தார்வாய்","இன்னாச்சொல் நோற்கிற் பவர்"],"tr":["Thurandhaarin Thooimai Utaiyar Irandhaarvaai","Innaachchol Norkir Pavar"],"en":["They who transgressors' evil words endure","With patience, are as stern ascetics pure"],"s":"Those who bear with the uncourteous speech of the insolent are as pure as the ascetics","ch":16,"sec":1,"th":"patience"},
  {"n":160,"ta":["உண்ணாது நோற்பார் பெரியர் பிறர்சொல்லும்","இன்னாச்சொல் நோற்பாரின் பின்"],"tr":["Unnaadhu Norpaar Periyar Pirarsollum","Innaachchol Norpaarin Pin"],"en":["Though 'great' we deem the men that fast and suffer pain,","Who others' bitter words endure, the foremost place obtain"],"s":"Those who endure abstinence from food are great, next to those who endure the uncourteous speech of others","ch":16,"sec":1,"th":"patience"},
  {"n":161,"ta":["ஒழுக்காறாக் கொள்க ஒருவன்தன் நெஞ்சத்து","அழுக்காறு இலாத இயல்பு"],"tr":["Ozhukkaaraak Kolka Oruvandhan Nenjaththu","Azhukkaaru Ilaadha Iyalpu"],"en":["As 'strict decorum's' laws, that all men bind,","Let each regard unenvying grace of mind"],"s":"Let a man esteem that disposition which is free from envy in the same manner as propriety of conduct","ch":17,"sec":1,"th":"calm"},
  {"n":162,"ta":["விழுப்பேற்றின் அஃதொப்பது இல்லையார் மாட்டும்","அழுக்காற்றின் அன்மை பெறின்"],"tr":["Vizhuppetrin Aqdhoppadhu Illaiyaar Maattum","Azhukkaatrin Anmai Perin"],"en":["If man can learn to envy none on earth,","'Tis richest gift, -beyond compare its worth"],"s":"Amongst all attainable excellences there is none equal to that of being free from envy towords others","ch":17,"sec":1,"th":"calm"},
  {"n":163,"ta":["அறன்ஆக்கம் வேண்டாதான் என்பான் பிறனாக்கம்","பேணாது அழுக்கறுப் பான்"],"tr":["Aranaakkam Ventaadhaan Enpaan Piranaakkam","Penaadhu Azhukkarup Paan"],"en":["Nor wealth nor virtue does that man desire 'tis plain,","Whom others' wealth delights not, feeling envious pain"],"s":"Of him who instead of rejoicing in the wealth of others, envies it, it will be said \"he neither desires virtue not wealth.\"","ch":17,"sec":1,"th":"calm"},
  {"n":164,"ta":["அழுக்காற்றின் அல்லவை செய்யார் இழுக்காற்றின்","ஏதம் படுபாக்கு அறிந்து"],"tr":["Azhukkaatrin Allavai Seyyaar Izhukkaatrin","Edham Patupaakku Arindhu"],"en":["The wise through envy break not virtue's laws,","Knowing ill-deeds of foul disgrace the cause"],"s":"(The wise) knowing the misery that comes from transgression will not through envy commit unrighteous deeds","ch":17,"sec":1,"th":"calm"},
  {"n":165,"ta":["அழுக்காறு உடையார்க்கு அதுசாலும் ஒன்னார்","வழுக்காயும் கேடீன் பது"],"tr":["Azhukkaaru Utaiyaarkku Adhusaalum Onnaar","Vazhukka�yum Keteen Padhu"],"en":["Envy they have within! Enough to seat their fate!","Though foemen fail, envy can ruin consummate"],"s":"To those who cherish envy that is enough Though free from enemies that  (envy) will bring destruction","ch":17,"sec":1,"th":"calm"},
  {"n":166,"ta":["கொடுப்பது அழுக்கறுப்பான் சுற்றம் உடுப்பதூஉம்","உண்பதூஉம் இன்றிக் கெடும்"],"tr":["Kotuppadhu Azhukkaruppaan Sutram Utuppadhooum","Unpadhooum Indrik Ketum"],"en":["Who scans good gifts to others given with envious eye,","His kin, with none to clothe or feed them, surely die"],"s":"He who is envious at a gift  (made to another) will with his relations utterly perish destitute of food and rainment","ch":17,"sec":1,"th":"calm"},
  {"n":167,"ta":["அவ்வித்து அழுக்காறு உடையானைச் செய்யவள்","தவ்வையைக் காட்டி விடும்"],"tr":["Avviththu Azhukkaaru Utaiyaanaich Cheyyaval","Thavvaiyaik Kaatti Vitum"],"en":["From envious man good fortune's goddess turns away,","Grudging him good, and points him out misfortune's prey"],"s":"Lakshmi envying  (the prosperity) of the envious man will depart and introduce him to her sister","ch":17,"sec":1,"th":"calm"},
  {"n":168,"ta":["அழுக்காறு எனஒரு பாவி திருச்செற்றுத்","தீயுழி உய்த்து விடும்"],"tr":["Azhukkaaru Enaoru Paavi Thiruchchetruth","Theeyuzhi Uyththu Vitum"],"en":["Envy, embodied ill, incomparable bane,","Good fortune slays, and soul consigns to fiery pain"],"s":"Envy will destroy  (a man's) wealth  (in his world) and drive him into the pit of fire  (in the world to come.)","ch":17,"sec":1,"th":"calm"},
  {"n":169,"ta":["அவ்விய நெஞ்சத்தான் ஆக்கமும் செவ்வியான்","கேடும் நினைக்கப் படும்"],"tr":["Avviya Nenjaththaan Aakkamum Sevviyaan","Ketum Ninaikkap Patum"],"en":["To men of envious heart, when comes increase of joy,","Or loss to blameless men, the 'why' will thoughtful hearts employ"],"s":"The wealth of a man of envious mind and the poverty of the righteous will be pondered","ch":17,"sec":1,"th":"calm"},
  {"n":170,"ta":["அழுக்கற்று அகன்றாரும் இல்லை அஃதுஇல்லார்","பெருக்கத்தில் தீர்ந்தாரும் இல்"],"tr":["Azhukkatru Akandraarum Illai Aqdhuillaar","Perukkaththil Theerndhaarum Il"],"en":["No envious men to large and full felicity attain;","No men from envy free have failed a sure increase to gain"],"s":"Never have the envious become great; never have those who are free from envy been without greatness","ch":17,"sec":1,"th":"calm"},
  {"n":171,"ta":["நடுவின்றி நன்பொருள் வெஃகின் குடிபொன்றிக்","குற்றமும் ஆங்கே தரும்"],"tr":["Natuvindri Nanporul Veqkin Kutipondrik","Kutramum Aange Tharum"],"en":["With soul unjust to covet others' well-earned store,","Brings ruin to the home, to evil opes the door"],"s":"If a man departing from equity covet the property  (of others), at that very time will his family be destroyed and guilt be incurred","ch":18,"sec":1,"th":"calm"},
  {"n":172,"ta":["படுபயன் வெஃகிப் பழிப்படுவ செய்யார்","நடுவன்மை நாணு பவர்"],"tr":["Patupayan Veqkip Pazhippatuva Seyyaar","Natuvanmai Naanu Pavar"],"en":["Through lust of gain, no deeds that retribution bring,","Do they, who shrink with shame from every unjust thing"],"s":"Those who blush at the want of equity will not commit disgraceful acts through desire of the profit that may be gained","ch":18,"sec":1,"th":"calm"},
  {"n":173,"ta":["சிற்றின்பம் வெஃகி அறனல்ல செய்யாரே","மற்றின்பம் வேண்டு பவர்"],"tr":["Sitrinpam Veqki Aranalla Seyyaare","Matrinpam Ventu Pavar"],"en":["No deeds of ill, misled by base desire,","Do they, whose souls to other joys aspire"],"s":"Those who desire the higher pleasures  (of heaven) will not act unjustly through desire of the trifling joy.  (in this life.)","ch":18,"sec":1,"th":"calm"},
  {"n":174,"ta":["இலமென்று வெஃகுதல் செய்யார் புலம்வென்ற","புன்மையில் காட்சி யவர்"],"tr":["Ilamendru Veqkudhal Seyyaar Pulamvendra","Punmaiyil Kaatchi Yavar"],"en":["Men who have conquered sense, with sight from sordid vision freed,","Desire not other's goods, e'en in the hour of sorest need"],"s":"The wise who have conquered their senses and are free from crime, will not covet  (the things of others), with the thought \"we are destitute.\"","ch":18,"sec":1,"th":"calm"},
  {"n":175,"ta":["அஃகி அகன்ற அறிவென்னாம் யார்மாட்டும்","வெஃகி வெறிய செயின்"],"tr":["Aqki Akandra Arivennaam Yaarmaattum","Veqki Veriya Seyin"],"en":["What gain, though lore refined of amplest reach he learn,","His acts towards all mankind if covetous desire to folly turn"],"s":"What is the advantage of extensive and accurate knowledge if a man through covetousness act senselessly towards all?","ch":18,"sec":1,"th":"calm"},
  {"n":176,"ta":["அருள்வெஃகி ஆற்றின்கண் நின்றான் பொருள்வெஃகிப்","பொல்லாத சூழக் கெடும்"],"tr":["Arulveqki Aatrinkan Nindraan Porulveqkip","Pollaadha Soozhak Ketum"],"en":["Though, grace desiring, he in virtue's way stand strong,","He's lost who wealth desires, and ponders deeds of wrong"],"s":"If he, who through desire of the virtue of kindness abides in the domestic state ie, the path in which it may be obtained, covet  (the property of others) and think of evil methods  (to obtain it), he will perish","ch":18,"sec":1,"th":"calm"},
  {"n":177,"ta":["வேண்டற்க வெஃகியாம் ஆக்கம் விளைவயின்","மாண்டற் கரிதாம் பயன்"],"tr":["Ventarka Veqkiyaam Aakkam Vilaivayin","Maantar Karidhaam Payan"],"en":["Seek not increase by greed of gain acquired;","That fruit matured yields never good desired"],"s":"Desire not the gain of covetousness In the enjoyment of its fruits there is no glory","ch":18,"sec":1,"th":"calm"},
  {"n":178,"ta":["அஃகாமை செல்வத்திற்கு யாதெனின் வெஃகாமை","வேண்டும் பிறன்கைப் பொருள்"],"tr":["Aqkaamai Selvaththirku Yaadhenin Veqkaamai","Ventum Pirankaip Porul"],"en":["What saves prosperity from swift decline?","Absence of lust to make another's cherished riches thine"],"s":"If it is weighed, \"what is the indestructibility of wealth,\" it is freedom from covetousness","ch":18,"sec":1,"th":"calm"},
  {"n":179,"ta":["அறனறிந்து வெஃகா அறிவுடையார்ச் சேரும்","திறன்அறிந் தாங்கே திரு"],"tr":["Aranarindhu Veqkaa Arivutaiyaarch Cherum","Thiranarin Thaange Thiru"],"en":["Good fortune draws anigh in helpful time of need,","To him who, schooled in virtue, guards his soul from greed"],"s":"Lakshmi, knowing the manner  (in which she may approach) will immediately come to those wise men who, knowing that it is virtue, covet not the property of others","ch":18,"sec":1,"th":"calm"},
  {"n":180,"ta":["இறலீனும் எண்ணாது வெஃகின் விறல்ஈனும்","வேண்டாமை என்னுஞ் செருக்கு"],"tr":["Iraleenum Ennaadhu Veqkin Viraleenum","Ventaamai Ennunj Cherukku"],"en":["From thoughtless lust of other's goods springs fatal ill,","Greatness of soul that covets not shall triumph still"],"s":"To covet  (the wealth of another) regardless of consequences will bring destruction That greatness  (of mind) which covets not will give victory","ch":18,"sec":1,"th":"calm"},
  {"n":181,"ta":["அறங்கூறான் அல்ல செயினும் ஒருவன்","புறங்கூறான் என்றல் இனிது"],"tr":["Arangooraan Alla Seyinum Oruvan","Purangooraan Endral Inidhu"],"en":["Though virtuous words his lips speak not, and all his deeds are ill","If neighbour he defame not, there's good within him still"],"s":"Though one do not even speak of virtue and live in sin, it will be well if it be said of him \"he does not backbite.\"","ch":19,"sec":1,"th":"truth"},
  {"n":182,"ta":["அறனழீஇ அல்லவை செய்தலின் தீதே","புறனழீஇப் பொய்த்து நகை"],"tr":["Aranazheei Allavai Seydhalin Theedhe","Puranazheeip Poiththu Nakai"],"en":["Than he who virtue scorns, and evil deeds performs, more vile,","Is he that slanders friend, then meets him with false smile"],"s":"To smile deceitfully  (in another's presence) after having reviled him to his destruction  (behind his back) is a greater evil than the commission of  (every other) sin and the destruction of  (every) virtue","ch":19,"sec":1,"th":"truth"},
  {"n":183,"ta":["புறங்கூறிப் பொய்த்துயிர் வாழ்தலின் சாதல்","அறங்கூற்றும் ஆக்கத் தரும்"],"tr":["Purangoorip Poiththuyir Vaazhdhalin Saadhal","Arangootrum Aakkath Tharum"],"en":["'Tis greater gain of virtuous good for man to die,","Than live to slander absent friend, and falsely praise when nigh"],"s":"Death rather than life will confer upon the deceitful backbiter the profit which  (the treatises on) virtue point out","ch":19,"sec":1,"th":"truth"},
  {"n":184,"ta":["கண்ணின்று கண்ணறச் சொல்லினும் சொல்லற்க","முன்னின்று பின்நோக்காச் சொல்"],"tr":["Kannindru Kannarach Chollinum Sollarka","Munnindru Pinnokkaach Chol"],"en":["In presence though unkindly words you speak, say not","In absence words whose ill result exceeds your thought"],"s":"Though you speak without kindness before another's face speak not in his absence words which regard not the evil subsequently resulting from it","ch":19,"sec":1,"th":"truth"},
  {"n":185,"ta":["அறஞ்சொல்லும் நெஞ்சத்தான் அன்மை புறஞ்சொல்லும்","புன்மையாற் காணப் படும்"],"tr":["Aranjollum Nenjaththaan Anmai Puranjollum","Punmaiyaar Kaanap Patum"],"en":["The slanderous meanness that an absent friend defames,","'This man in words owns virtue, not in heart, ' proclaims"],"s":"The emptiness of that man's mind who  (merely) praises virtue will be seen from the meanness of reviling another behind his back","ch":19,"sec":1,"th":"truth"},
  {"n":186,"ta":["பிறன்பழி கூறுவான் தன்பழி யுள்ளும்","திறன்தெரிந்து கூறப் படும்"],"tr":["Piranpazhi Kooruvaan Thanpazhi Yullum","Thirandherindhu Koorap Patum"],"en":["Who on his neighbours' sins delights to dwell,","The story of his sins, culled out with care, the world will tell"],"s":"The character of the faults of that man who publishes abroad the faults of others will be sought out and published","ch":19,"sec":1,"th":"truth"},
  {"n":187,"ta":["பகச்சொல்லிக் கேளிர்ப் பிரிப்பர் நகச்சொல்லி","நட்பாடல் தேற்றா தவர்"],"tr":["Pakachchollik Kelirp Pirippar Nakachcholli","Natpaatal Thetraa Thavar"],"en":["With friendly art who know not pleasant words to say,","Speak words that sever hearts, and drive choice friends away"],"s":"Those who know not to live in friendship with amusing conversation will by back-biting estrange even their relatives","ch":19,"sec":1,"th":"truth"},
  {"n":188,"ta":["துன்னியார் குற்றமும் தூற்றும் மரபினார்","என்னைகொல் ஏதிலார் மாட்டு"],"tr":["Thunniyaar Kutramum Thootrum Marapinaar","Ennaikol Edhilaar Maattu"],"en":["Whose nature bids them faults of closest friends proclaim","What mercy will they show to other men's good name"],"s":"What will those not do to strangers whose nature leads them to publish abroad the faults of their intimate friends?","ch":19,"sec":1,"th":"truth"},
  {"n":189,"ta":["அறன்நோக்கி ஆற்றுங்கொல் வையம் புறன்நோக்கிப்","புன்சொல் உரைப்பான் பொறை"],"tr":["Arannokki Aatrungol Vaiyam Purannokkip","Punsol Uraippaan Porai"],"en":["'Tis charity, I ween, that makes the earth sustain their load","Who, neighbours' absence watching, tales or slander tell abroad"],"s":"The world through charity supports the weight of those who reproach others observing their absence","ch":19,"sec":1,"th":"truth"},
  {"n":190,"ta":["ஏதிலார் குற்றம்போல் தங்குற்றங் காண்கிற்பின்","தீதுண்டோ மன்னும் உயிர்க்கு"],"tr":["Edhilaar Kutrampol Thangutrang Kaankirpin","Theedhunto Mannum Uyirkku"],"en":["If each his own, as neighbours' faults would scan,","Could any evil hap to living man"],"s":"If they observed their own faults as they observe the faults of others, would any evil happen to men?","ch":19,"sec":1,"th":"truth"},
  {"n":191,"ta":["பல்லார் முனியப் பயனில சொல்லுவான்","எல்லாரும் எள்ளப் படும்"],"tr":["Pallaar Muniyap Payanila Solluvaan","Ellaarum Ellap Patum"],"en":["Words without sense, while chafe the wise,","Who babbles, him will all despise"],"s":"He who to the disgust of many speaks useless things will be despised by all","ch":20,"sec":1,"th":"truth"},
  {"n":192,"ta":["பயனில பல்லார்முன் சொல்லல் நயனில","நட்டார்கண் செய்தலிற் றீது"],"tr":["Payanila Pallaarmun Sollal Nayanila","Nattaarkan Seydhalir Reedhu"],"en":["Words without sense, where many wise men hear, to pour","Than deeds to friends ungracious done offendeth more"],"s":"To speak useless things in the presence of many is a greater evil than to do unkind things towards friends","ch":20,"sec":1,"th":"truth"},
  {"n":193,"ta":["நயனிலன் என்பது சொல்லும் பயனில","பாரித் துரைக்கும் உரை"],"tr":["Nayanilan Enpadhu Sollum Payanila","Paarith Thuraikkum Urai"],"en":["Diffusive speech of useless words proclaims","A man who never righteous wisdom gains"],"s":"That conversation in which a man utters forth useless things will say of him \"he is without virtue.\"","ch":20,"sec":1,"th":"truth"},
  {"n":194,"ta":["நயன்சாரா நன்மையின் நீக்கும் பயன்சாராப்","பண்பில்சொல் பல்லா ரகத்து"],"tr":["Nayansaaraa Nanmaiyin Neekkum Payansaaraap","Panpilsol Pallaa Rakaththu"],"en":["Unmeaning, worthless words, said to the multitude,","To none delight afford, and sever men from good"],"s":"The words devoid of profit or pleasure which a man speaks will, being inconsistent with virtue,","ch":20,"sec":1,"th":"truth"},
  {"n":195,"ta":["சீர்மை சிறப்பொடு நீங்கும் பயனில","நீர்மை யுடையார் சொலின்"],"tr":["Seermai Sirappotu Neengum Payanila","Neermai Yutaiyaar Solin"],"en":["Gone are both fame and boasted excellence,","When men of worth speak of words devoid of sense"],"s":"If the good speak vain words their eminence and excellence will leave them","ch":20,"sec":1,"th":"truth"},
  {"n":196,"ta":["பயனில்சொல் பாராட்டு வானை மகன்எனல்","மக்கட் பதடி யெனல்"],"tr":["Payanil Sol Paaraattu Vaanai","Makanenal Makkat Padhati Yenal"],"en":["Who makes display of idle words' inanity,","Call him not man, -chaff of humanity"],"s":"Call not him a man who parades forth his empty words Call him the chaff of men","ch":20,"sec":1,"th":"truth"},
  {"n":197,"ta":["நயனில சொல்லினுஞ் சொல்லுக சான்றோர்","பயனில சொல்லாமை நன்று"],"tr":["Nayanila Sollinunj Cholluka Saandror","Payanila Sollaamai Nandru"],"en":["Let those who list speak things that no delight afford,","'Tis good for men of worth to speak no idle word"],"s":"Let the wise if they will, speak things without excellence; it will be well for them not to speak useless things","ch":20,"sec":1,"th":"truth"},
  {"n":198,"ta":["அரும்பயன் ஆயும் அறிவினார் சொல்லார்","பெரும்பயன் இல்லாத சொல்"],"tr":["Arumpayan Aayum Arivinaar Sollaar","Perumpayan Illaadha Sol"],"en":["The wise who weigh the worth of every utterance,","Speak none but words of deep significance"],"s":"The wise who seek after rare pleasures will not speak words that have not much weight in them","ch":20,"sec":1,"th":"truth"},
  {"n":199,"ta":["பொருள்தீர்ந்த பொச்சாந்துஞ் சொல்லார் மருள்தீர்ந்த","மாசறு காட்சி யவர்"],"tr":["Poruldheerndha Pochchaandhunj Chollaar Maruldheerndha","Maasaru Kaatchi Yavar"],"en":["The men of vision pure, from wildering folly free,","Not e'en in thoughtless hour, speak words of vanity"],"s":"Those wise men who are without faults and are freed from ignorance will not even forgetfully speak things that profit not","ch":20,"sec":1,"th":"truth"},
  {"n":200,"ta":["சொல்லுக சொல்லிற் பயனுடைய சொல்லற்க","சொல்லிற் பயனிலாச் சொல்"],"tr":["Solluka Sollir Payanutaiya Sollarka","Sollir Payanilaach Chol"],"en":["If speak you will, speak words that fruit afford,","If speak you will, speak never fruitless word"],"s":"Speak what is useful, and speak not useless words","ch":20,"sec":1,"th":"truth"},
  {"n":201,"ta":["தீவினையார் அஞ்சார் விழுமியார் அஞ்சுவர்","தீவினை என்னும் செருக்கு"],"tr":["Theevinaiyaar Anjaar Vizhumiyaar Anjuvar","Theevinai Ennum Serukku"],"en":["With sinful act men cease to feel the dread of ill within,","The excellent will dread the wanton pride of cherished sin"],"s":"Those who have experience of evil deeds will not fear, but the excellent will fear the pride of sin","ch":21,"sec":1,"th":"truth"},
  {"n":202,"ta":["தீயவை தீய பயத்தலால் தீயவை","தீயினும் அஞ்சப் படும்"],"tr":["Theeyavai Theeya Payaththalaal Theeyavai","Theeyinum Anjap Patum"],"en":["Since evils new from evils ever grow,","Evil than fire works out more dreaded woe"],"s":"Because evil produces evil, therefore should evil be feared more than fire","ch":21,"sec":1,"th":"truth"},
  {"n":203,"ta":["அறிவினுள் எல்லாந் தலையென்ப தீய","செறுவார்க்கும் செய்யா விடல்"],"tr":["Arivinul Ellaan Thalaiyenpa Theeya","Seruvaarkkum Seyyaa Vital"],"en":["Even to those that hate make no return of ill;","So shalt thou wisdom's highest law, 'tis said, fulfil"],"s":"So shalt thou wisdom's highest law, 'tis said, fulfil","ch":21,"sec":1,"th":"truth"},
  {"n":204,"ta":["மறந்தும் பிறன்கேடு சூழற்க சூழின்","அறஞ்சூழம் சூழ்ந்தவன் கேடு"],"tr":["Marandhum Piranketu Soozharka Soozhin","Aranjoozham Soozhndhavan Ketu"],"en":["Though good thy soul forget, plot not thy neighbour's fall,","Thy plans shall 'virtue's Power' by ruin to thyself forestall"],"s":"Even though forgetfulness meditate not the ruin of another Virtue will meditate the ruin of him who thus meditates","ch":21,"sec":1,"th":"truth"},
  {"n":205,"ta":["இலன்என்று தீயவை செய்யற்க செய்யின்","இலனாகும் மற்றும் பெயர்த்து"],"tr":["Ilan Endru Theeyavai Seyyarka","Seyyin Ilanaakum Matrum Peyarththu"],"en":["Make not thy poverty a plea for ill;","Thy evil deeds will make thee poorer still"],"s":"Commit not evil, saying, \"I am poor\": if you do, you will become poorer still","ch":21,"sec":1,"th":"truth"},
  {"n":206,"ta":["தீப்பால தான்பிறர்கண் செய்யற்க நோய்ப்பால","தன்னை அடல்வேண்டா தான்"],"tr":["Theeppaala Thaanpirarkan Seyyarka Noippaala","Thannai Atalventaa Thaan"],"en":["What ranks as evil spare to do, if thou would'st shun","Affliction sore through ill to thee by others done"],"s":"Let him not do evil to others who desires not that sorrows should pursue him","ch":21,"sec":1,"th":"truth"},
  {"n":207,"ta":["எனைப்பகை யுற்றாரும் உய்வர் வினைப்பகை","வீயாது பின்சென்று அடும்"],"tr":["Enaippakai Yutraarum Uyvar Vinaippakai","Veeyaadhu Pinsendru Atum"],"en":["From every enmity incurred there is to 'scape, a way;","The wrath of evil deeds will dog men's steps, and slay"],"s":"However great be the enmity men have incurred they may still live The enmity of sin will incessantly pursue and kill","ch":21,"sec":1,"th":"truth"},
  {"n":208,"ta":["தீயவை செய்தார் கெடுதல் நிழல்தன்னை","வீயாது அஇஉறைந் தற்று"],"tr":["Theeyavai Seydhaar Ketudhal Nizhaldhannai","Veeyaadhu Atiurain Thatru"],"en":["Man's shadow dogs his steps where'er he wends;","Destruction thus on sinful deeds attends"],"s":"Destruction will dwell at the heels of those who commit evil even as their shadow that leaves them not","ch":21,"sec":1,"th":"truth"},
  {"n":209,"ta":["தன்னைத்தான் காதல னாயின் எனைத்தொன்றும்","துன்னற்க தீவினைப் பால்"],"tr":["Thannaiththaan Kaadhala Naayin Enaiththondrum","Thunnarka Theevinaip Paal"],"en":["Beware, if to thyself thyself is dear,","Lest thou to aught that ranks as ill draw near"],"s":"If a man love himself, let him not commit any sin however small","ch":21,"sec":1,"th":"truth"},
  {"n":210,"ta":["அருங்கேடன் என்பது அறிக மருங்கோடித்","தீவினை செய்யான் எனின்"],"tr":["Arungetan Enpadhu Arika Marungotith","Theevinai Seyyaan Enin"],"en":["The man, to devious way of sin that never turned aside,","From ruin rests secure, whatever ills betide"],"s":"Know ye that he is freed from destruction who commits no evil, going to neither side of the right path","ch":21,"sec":1,"th":"truth"},
  {"n":211,"ta":["கைம்மாறு வேண்டா கடப்பாடு மாரிமாட்டு","என் ஆற்றுங் கொல்லோ உலகு"],"tr":["Kaimmaaru Ventaa Katappaatu Maarimaattu","En Aatrung Kollo Ulaku"],"en":["Duty demands no recompense; to clouds of heaven,","By men on earth, what answering gift is given"],"s":"Benevolence seeks not a return. What does the world give back to the clouds?","ch":22,"sec":1,"th":"compassion"},
  {"n":212,"ta":["தாளாற்றித் தந்த பொருளெல்லாம் தக்கார்க்கு","வேளாண்மை செய்தற் பொருட்டு"],"tr":["Thaalaatrith Thandha Porulellaam Thakkaarkku","Velaanmai Seydhar Poruttu"],"en":["The worthy say, when wealth rewards their toil-spent hours,","For uses of beneficence alone 'tis ours"],"s":"All the wealth acquired with perseverance by the worthy is for the exercise of benevolence","ch":22,"sec":1,"th":"compassion"},
  {"n":213,"ta":["புத்தே ளுலகத்தும் ஈண்டும் பெறலரிதே","ஒப்புரவின் நல்ல பிற"],"tr":["Puththe Lulakaththum Eentum Peralaridhe","Oppuravin Nalla Pira"],"en":["To 'due beneficence' no equal good we know,","Amid the happy gods, or in this world below"],"s":"It is difficult to obtain another good equal to benevolence either in this world or in that of the gods","ch":22,"sec":1,"th":"compassion"},
  {"n":214,"ta":["ஒத்த தறவோன் உயிர்வாழ்வான் மற்றையான்","செத்தாருள் வைக்கப் படும்"],"tr":["Oththa Tharavon Uyirvaazhvaan Matraiyaan","Seththaarul Vaikkap Patum"],"en":["Who knows what's human life's befitting grace,","He lives; the rest 'mongst dead men have their place"],"s":"He truly lives who knows  (and discharges) the proper duties  (of benevolence) He who knows them not will be reckoned among the dead","ch":22,"sec":1,"th":"compassion"},
  {"n":215,"ta":["ஊருணி நீர்நிறைந் தற்றே உலகவாம்","பேரறி வாளன் திரு"],"tr":["Ooruni Neernirain Thatre Ulakavaam","Perari Vaalan Thiru"],"en":["The wealth of men who love the 'fitting way, ' the truly wise,","Is as when water fills the lake that village needs supplies"],"s":"The wealth of that man of eminent knowledge who desires to exercise the benevolence approved of by the world, is like the full waters of a city-tank","ch":22,"sec":1,"th":"compassion"},
  {"n":216,"ta":["பயன்மரம் உள்ளூர்ப் பழுத்தற்றால் செல்வம்","நயனுடை யான்கண் படின்"],"tr":["Payanmaram Ulloorp Pazhuththatraal Selvam","Nayanutai Yaankan Patin"],"en":["A tree that fruits in th' hamlet's central mart,","Is wealth that falls to men of liberal heart"],"s":"The wealth of a man  (possessed of the virtue) of benevolence is like the ripening of a fruitful tree in the midst of a town","ch":22,"sec":1,"th":"compassion"},
  {"n":217,"ta":["மருந்தாகித் தப்பா மரத்தற்றால் செல்வம்","பெருந்தகை யான்கண் படின்"],"tr":["Marundhaakith Thappaa Maraththatraal Selvam","Perundhakai Yaankan Patin"],"en":["Unfailing tree that healing balm distils from every part,","Is ample wealth that falls to him of large and noble heart"],"s":"If wealth be in the possession of a man who has the great excellence  (of benevolence), it is like a tree which as a medicine is an infallible cure for disease","ch":22,"sec":1,"th":"compassion"},
  {"n":218,"ta":["இடனில் பருவத்தும் ஒப்புரவிற்கு ஒல்கார்","கடனறி காட்சி யவர்"],"tr":["Itanil Paruvaththum Oppuravirku Olkaar","Katanari Kaatchi Yavar"],"en":["E'en when resources fall, they weary not of 'kindness due,","'-They to whom Duty's self appears in vision true"],"s":"The wise who know what is duty will not scant their benevolence even when they are without wealth","ch":22,"sec":1,"th":"compassion"},
  {"n":219,"ta":["நயனுடையான் நல்கூர்ந்தா னாதல் செயும்நீர","செய்யாது அமைகலா வாறு"],"tr":["Nayanutaiyaan Nalkoorndhaa Naadhal Seyumneera","Seyyaadhu Amaikalaa Vaaru"],"en":["The kindly-hearted man is poor in this alone,","When power of doing deeds of goodness he finds none"],"s":"The poverty of a benevolent man, is nothing but his inability to exercise the same","ch":22,"sec":1,"th":"compassion"},
  {"n":220,"ta":["ஒப்புரவி னால்வரும் கேடெனின் அஃதொருவன்","விற்றுக்கோள் தக்க துடைத்து"],"tr":["Oppuravi Naalvarum Ketenin Aqdhoruvan","Vitrukkol Thakka Thutaiththu"],"en":["Though by 'beneficence, ' the loss of all should come,","'Twere meet man sold himself, and bought it with the sum"],"s":"If it be said that loss will result from benevolence, such loss is worth being procured even by the sale of one's self","ch":22,"sec":1,"th":"compassion"},
  {"n":221,"ta":["வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம்","குறியெதிர்ப்பை நீர துடைத்து"],"tr":["Variyaarkkondru Eevadhe Eekaimar Rellaam","Kuriyedhirppai Neera Thutaiththu"],"en":["Call that a gift to needy men thou dost dispense,","All else is void of good, seeking for recompense"],"s":"To give to the destitute is true charity All other gifts have the nature of  (what is done for) a measured return","ch":23,"sec":1,"th":"compassion"},
  {"n":222,"ta":["நல்லாறு எனினும் கொளல்தீது மேலுலகம்","இல்லெனினும் ஈதலே நன்று"],"tr":["Nallaaru Eninum Kolaldheedhu Melulakam","Illeninum Eedhale Nandru"],"en":["Though men declare it heavenward path, yet to receive is ill;","Though upper heaven were not, to give is virtue still"],"s":"To beg is evil, even though it were said that it is a good path  (to heaven) To give is good, even though it were said that those who do so cannot obtain heaven","ch":23,"sec":1,"th":"compassion"},
  {"n":223,"ta":["இலனென்னும் எவ்வம் உரையாமை ஈதல்","குலனுடையான் கண்ணே யுள"],"tr":["Ilanennum Evvam Uraiyaamai Eedhal","Kulanutaiyaan Kanne Yula"],"en":["'I've nought' is ne'er the high-born man's reply;","He gives to those who raise themselves that cry"],"s":"(Even in a low state) not to adopt the mean expedient of saying \"I have nothing,\" but to give, is the characteristic of the mad of noble birth","ch":23,"sec":1,"th":"compassion"},
  {"n":224,"ta":["இன்னாது இரக்கப் படுதல் இரந்தவர்","இன்முகங் காணும் அளவு"],"tr":["Innaadhu Irakkap Patudhal Irandhavar","Inmukang Kaanum Alavu"],"en":["The suppliants' cry for aid yields scant delight,","Until you see his face with grateful gladness bright"],"s":"To see men begging from us in disagreeable, until we see their pleasant countenance","ch":23,"sec":1,"th":"compassion"},
  {"n":225,"ta":["ஆற்றுவார் ஆற்றல் பசிஆற்றல் அப்பசியை","மாற்றுவார் ஆற்றலின் பின்"],"tr":["Aatruvaar Aatral Pasiaatral Appasiyai","Maatruvaar Aatralin Pin"],"en":["'Mid devotees they're great who hunger's pangs sustain,","Who hunger's pangs relieve a higher merit gain"],"s":"The power of those who perform penance is the power of enduring hunger It is inferior to the power of those who remove the hunger  (of others)","ch":23,"sec":1,"th":"compassion"},
  {"n":226,"ta":["அற்றார் அழிபசி தீர்த்தல் அஃதொருவன்","பெற்றான் பொருள்வைப் புழி"],"tr":["Atraar Azhipasi Theerththal Aqdhoruvan","Petraan Porulvaip Puzhi"],"en":["Let man relieve the wasting hunger men endure;","For treasure gained thus finds he treasure-house secure"],"s":"The removal of the killing hunger of the poor is the place for one to lay up his wealth","ch":23,"sec":1,"th":"compassion"},
  {"n":227,"ta":["பாத்தூண் மரீஇ யவனைப் பசியென்னும்","தீப்பிணி தீண்டல் அரிது"],"tr":["Paaththoon Mareei Yavanaip Pasiyennum","Theeppini Theental Aridhu"],"en":["Whose soul delights with hungry men to share his meal,","The hand of hunger's sickness sore shall never feel"],"s":"The fiery disease of hunger shall never touch him who habitually distributes his food to others","ch":23,"sec":1,"th":"compassion"},
  {"n":228,"ta":["ஈத்துவக்கும் இன்பம் அறியார்கொல் தாமுடைமை","வைத்திழக்கும் வன்க ணவர்"],"tr":["Eeththuvakkum Inpam Ariyaarkol Thaamutaimai","Vaiththizhakkum Vanka Navar"],"en":["Delight of glad'ning human hearts with gifts do they not know.","Men of unpitying eye, who hoard their wealth and lose it so"],"s":"Do the hard-eyed who lay up and lose their possessions not know the happiness which springs from the pleasure of giving?","ch":23,"sec":1,"th":"compassion"},
  {"n":229,"ta":["இரத்தலின் இன்னாது மன்ற நிரப்பிய","தாமே தமியர் உணல்"],"tr":["Iraththalin Innaadhu Mandra Nirappiya","Thaame Thamiyar Unal"],"en":["They keep their garners full, for self alone the board they spread;","'Tis greater pain, be sure, than begging daily bread"],"s":"Solitary and unshared eating for the sake of filling up one's own riches is certainly much more","ch":23,"sec":1,"th":"compassion"},
  {"n":230,"ta":["சாதலின் இன்னாத தில்லை இனிததூஉம்","ஈதல் இயையாக் கடை"],"tr":["Saadhalin Innaadha Thillai Inidhadhooum","Eedhal Iyaiyaak Katai"],"en":["'Tis bitter pain to die, 'Tis worse to live.","For him who nothing finds to give"],"s":"Nothing is more unpleasant than death: yet even that is pleasant where charity cannot be exercised","ch":23,"sec":1,"th":"compassion"},
  {"n":231,"ta":["ஈதல் இசைபட வாழ்தல் அதுவல்லது","ஊதியம் இல்லை உயிர்க்கு"],"tr":["Eedhal Isaipata Vaazhdhal Adhuvalladhu","Oodhiyam Illai Uyirkku"],"en":["See that thy life the praise of generous gifts obtain;","Save this for living man exists no real gain"],"s":"Give to the poor and live with praise There is no greater profit to man than that","ch":24,"sec":1,"th":"wisdom"},
  {"n":232,"ta":["உரைப்பார் உரைப்பவை எல்லாம் இரப்பார்க்கொன்று","ஈவார்மேல் நிற்கும் புகழ்"],"tr":["Uraippaar Uraippavai Ellaam Irappaarkkondru","Eevaarmel Nirkum Pukazh"],"en":["The speech of all that speak agrees to crown","The men that give to those that ask, with fair renown"],"s":"Whatsoever is spoken in the world will abide as praise upon that man who gives alms to the poor","ch":24,"sec":1,"th":"wisdom"},
  {"n":233,"ta":["ஒன்றா உலகத்து உயர்ந்த புகழல்லால்","பொன்றாது நிற்பதொன் றில்"],"tr":["Ondraa Ulakaththu Uyarndha Pukazhallaal","Pondraadhu Nirpadhon Ril"],"en":["Save praise alone that soars on high,","Nought lives on earth that shall not die"],"s":"There is nothing that stands forth in the world imperishable, except fame, exalted in solitary greatness","ch":24,"sec":1,"th":"wisdom"},
  {"n":234,"ta":["நிலவரை நீள்புகழ் ஆற்றின் புலவரைப்","போற்றாது புத்தேள் உலகு"],"tr":["Nilavarai Neelpukazh Aatrin Pulavaraip","Potraadhu Puththel Ulaku"],"en":["If men do virtuous deeds by world-wide ample glory crowned,","The heavens will cease to laud the sage for other gifts renowned"],"s":"If one has acquired extensive fame within the limits of this earth, the world of the Gods will no longer praise those sages who have attained that world","ch":24,"sec":1,"th":"wisdom"},
  {"n":235,"ta":["நத்தம்போல் கேடும் உளதாகும் சாக்காடும்","வித்தகர்க் கல்லால் அரிது"],"tr":["Naththampol Ketum Uladhaakum Saakkaatum","Viththakark Kallaal Aridhu"],"en":["Loss that is gain, and death of life's true bliss fulfilled,","Are fruits which only wisdom rare can yield"],"s":"Prosperity to the body of fame, resulting in poverty to the body of flesh and the stability to the former arising from the death of the latter, are achievable only by the wise","ch":24,"sec":1,"th":"wisdom"},
  {"n":236,"ta":["தோன்றின் புகழொடு தோன்றுக அஃதிலார்","தோன்றலின் தோன்றாமை நன்று"],"tr":["Thondrin Pukazhotu Thondruka Aqdhilaar","Thondralin Thondraamai Nandru"],"en":["If man you walk the stage, appear adorned with glory's grace;","Save glorious you can shine, 'twere better hide your face"],"s":"If you are born  (in this world), be born with qualities conductive to fame From those who are destitute of them it will be better not to be born","ch":24,"sec":1,"th":"wisdom"},
  {"n":237,"ta":["புகழ்பட வாழாதார் தந்நோவார் தம்மை","இகழ்வாரை நோவது எவன்?"],"tr":["Pukazhpata Vaazhaadhaar Thannovaar Thammai","Ikazhvaarai Novadhu Evan?"],"en":["If you your days will spend devoid of goodly fame,","When men despise, why blame them? You've yourself to blame"],"s":"Why do those who cannot live with praise, grieve those who despise them, instead of grieving themselves for their own inability","ch":24,"sec":1,"th":"wisdom"},
  {"n":238,"ta":["வசையென்ப வையத்தார்க் கெல்லாம் இசையென்னும்","எச்சம் பெறாஅ விடின்"],"tr":["Vasaiyenpa Vaiyaththaark Kellaam Isaiyennum","Echcham Peraaa Vitin"],"en":["Fame is virtue's child, they say; if, then,","You childless live, you live the scorn of men"],"s":"Not to beget fame will be esteemed a disgrace by the wise in this world","ch":24,"sec":1,"th":"wisdom"},
  {"n":239,"ta":["வசையிலா வண்பயன் குன்றும் இசையிலா","யாக்கை பொறுத்த நிலம்"],"tr":["Vasaiyilaa Vanpayan Kundrum Isaiyilaa","Yaakkai Poruththa Nilam"],"en":["The blameless fruits of fields' increase will dwindle down,","If earth the burthen bear of men without renown"],"s":"The ground which supports a body without fame will diminish in its rich produce","ch":24,"sec":1,"th":"wisdom"},
  {"n":240,"ta":["வசையொழிய வாழ்வாரே வாழ்வார் இசையொழிய","வாழ்வாரே வாழா தவர்"],"tr":["Vasaiyozhiya Vaazhvaare Vaazhvaar Isaiyozhiya","Vaazhvaare Vaazhaa Thavar"],"en":["Who live without reproach, them living men we deem;","Who live without renown, live not, though living men they seem"],"s":"Those live who live without disgrace Those who live without fame live not","ch":24,"sec":1,"th":"wisdom"},
  {"n":241,"ta":["அருட்செல்வம் செல்வத்துள் செல்வம் பொருட்செல்வம்","பூரியார் கண்ணும் உள"],"tr":["Arutchelvam Selvaththul Selvam Porutchelvam","Pooriyaar Kannum Ula"],"en":["Wealth 'mid wealth is wealth 'kindliness';","Wealth of goods the vilest too possess"],"s":"The wealth of kindness is wealth of wealth, in as much as the wealth of property is possessed by the basest of men","ch":25,"sec":1,"th":"compassion"},
  {"n":242,"ta":["நல்லாற்றாள் நாடி அருளாள்க பல்லாற்றால்","தேரினும் அஃதே துணை"],"tr":["Nallaatraal Naati Arulaalka Pallaatraal","Therinum Aqdhe Thunai"],"en":["The law of 'grace' fulfil, by methods good due trial made,","Though many systems you explore, this is your only aid"],"s":"(Stand) in the good path, consider, and be kind. Even considering according to the conflicting tenets of the different sects, kindness will be your best aid,  (in the acquisition of heavenly bliss.)","ch":25,"sec":1,"th":"compassion"},
  {"n":243,"ta":["அருள்சேர்ந்த நெஞ்சினார்க் கில்லை இருள்சேர்ந்த","இன்னா உலகம் புகல்"],"tr":["Arulserndha Nenjinaark Killai Irulserndha","Innaa Ulakam Pukal"],"en":["They in whose breast a 'gracious kindliness' resides,","See not the gruesome world, where darkness drear abides"],"s":"They will never enter the world of darkness and wretchedness whose minds are the abode of kindness","ch":25,"sec":1,"th":"compassion"},
  {"n":244,"ta":["மன்னுயிர் ஓம்பி அருளாள்வார்க்கு இல்லென்ப","தன்னுயிர் அஞ்சும் வினை"],"tr":["Mannuyir Ompi Arulaalvaarkku Illenpa","Thannuyir Anjum Vinai"],"en":["Who for undying souls of men provides with gracious zeal,","In his own soul the dreaded guilt of sin shall never feel"],"s":"(The wise) say that the evils, which his soul would dread, will never come upon the man who exercises kindness and protects the life  (of other creatures)","ch":25,"sec":1,"th":"compassion"},
  {"n":245,"ta":["அல்லல் அருளாள்வார்க்கு இல்லை வளிவழங்கும்","மல்லன்மா ஞாலங் கரி"],"tr":["Allal Arulaalvaarkku Illai Valivazhangum","Mallanmaa Gnaalang Kari"],"en":["The teeming earth's vast realm, round which the wild winds blow,","Is witness, men of 'grace' no woeful want shall know"],"s":"This great rich earth over which the wind blows, is a witness that sorrow never comes upon the kindhearted","ch":25,"sec":1,"th":"compassion"},
  {"n":246,"ta":["பொருள்நீங்கிப் பொச்சாந்தார் என்பர் அருள்நீங்கி","அல்லவை செய்தொழுகு வார்"],"tr":["Porulneengip Pochchaandhaar Enpar Arulneengi","Allavai Seydhozhuku Vaar"],"en":["Gain of true wealth oblivious they eschew,","Who 'grace' forsake, and graceless actions do"],"s":"(The wise) say that those who neglect kindness and practise cruelties, neglected virtue  (in their former birth), and forgot  (the sorrows which they must suffer.)","ch":25,"sec":1,"th":"compassion"},
  {"n":247,"ta":["அருளில்லார்க்கு அவ்வுலகம் இல்லை பொருளில்லார்க்கு","இவ்வுலகம் இல்லாகி யாங்கு"],"tr":["Arulillaarkku Avvulakam Illai Porulillaarkku","Ivvulakam Illaaki Yaangu"],"en":["As to impoverished men this present world is not;","The 'graceless' in you world have neither part nor lot"],"s":"As this world is not for those who are without wealth, so that world is not for those who are without kindness","ch":25,"sec":1,"th":"compassion"},
  {"n":248,"ta":["பொருளற்றார் பூப்பர் ஒருகால் அருளற்றார்","அற்றார்மற் றாதல் அரிது"],"tr":["Porulatraar Pooppar Orukaal Arulatraar","Atraarmar Raadhal Aridhu"],"en":["Who lose the flower of wealth, when seasons change, again may bloom;","Who lose 'benevolence', lose all; nothing can change their doom"],"s":"Those who are without wealth may, at some future time, become prosperous; those who are destitute of kindness are utterly destitute; for them there is no change","ch":25,"sec":1,"th":"compassion"},
  {"n":249,"ta":["தெருளாதான் மெய்ப்பொருள் கண்டற்றால் தேரின்","அருளாதான் செய்யும் அறம்"],"tr":["Therulaadhaan Meypporul Kantatraal Therin","Arulaadhaan Seyyum Aram"],"en":["When souls unwise true wisdom's mystic vision see,","The 'graceless' man may work true works of charity"],"s":"If you consider, the virtue of him who is without kindness is like the perception of the true being by him who is without wisdom","ch":25,"sec":1,"th":"compassion"},
  {"n":250,"ta":["வலியார்முன் தன்னை நினைக்கதான் தன்னின்","மெலியார்மேல் செல்லு மிடத்து"],"tr":["Valiyaarmun Thannai Ninaikka Thaan","Thannin Meliyaarmel Sellu Mitaththu"],"en":["When weaker men you front with threat'ning brow,","Think how you felt in presence of some stronger foe"],"s":"When a man is about to rush upon those who are weaker than himself, let him remember how he has stood  (trembling) before those who are stronger than himself","ch":25,"sec":1,"th":"compassion"},
  {"n":251,"ta":["தன்னூன் பெருக்கற்குத் தான்பிறிது ஊனுண்பான்","எங்ஙனம் ஆளும் அருள்?"],"tr":["Thannoon Perukkarkuth Thaanpiridhu Oonunpaan","Engnganam Aalum Arul?"],"en":["How can the wont of 'kindly grace' to him be known,","Who other creatures' flesh consumes to feed his own"],"s":"How can he be possessed of kindness, who to increase his own flesh, eats the flesh of other creatures","ch":26,"sec":1,"th":"compassion"},
  {"n":252,"ta":["பொருளாட்சி போற்றாதார்க்கு இல்லை அருளாட்சி","ஆங்கில்லை ஊன்தின் பவர்க்கு"],"tr":["Porulaatchi Potraadhaarkku Illai Arulaatchi","Aangillai Oondhin Pavarkku"],"en":["No use of wealth have they who guard not their estate;","No use of grace have they with flesh who hunger sate"],"s":"As those possess no property who do not take care of it, so those possess no kindness who feed on flesh","ch":26,"sec":1,"th":"compassion"},
  {"n":253,"ta":["படைகொண்டார் நெஞ்சம்போல் நன்னூக்காது ஒன்றன்","உடல்சுவை உண்டார் மனம்"],"tr":["Pataikontaar Nenjampol Nannookkaadhu Ondran","Utalsuvai Untaar Manam"],"en":["Like heart of them that murderous weapons bear, his mind,","Who eats of savoury meat, no joy in good can find"],"s":"Like the  (murderous) mind of him who carries a weapon  (in his hand), the mind of him who feasts with pleasure on the body of another  (creature), has no regard for goodness","ch":26,"sec":1,"th":"compassion"},
  {"n":254,"ta":["அருளல்ல தியாதெனிற் கொல்லாமை கோறல்","பொருளல்லது அவ்வூன் தினல்"],"tr":["Arulalladhu Yaadhenin Kollaamai Koral","Porulalladhu Avvoon Thinal"],"en":["'What's grace, or lack of grace'? 'To kill' is this, that 'not to kill';","To eat dead flesh can never worthy end fulfil"],"s":"If it be asked what is kindness and what its opposite, the answer would be preservation and destruction of life; and therefore it is not right to feed on the flesh  (obtained by taking away life)","ch":26,"sec":1,"th":"compassion"},
  {"n":255,"ta":["உண்ணாமை உள்ளது உயிர்நிலை ஊனுண்ண","அண்ணாத்தல் செய்யாது அளறு"],"tr":["Unnaamai Ulladhu Uyirnilai Oonunna","Annaaththal Seyyaadhu Alaru"],"en":["If flesh you eat not, life's abodes unharmed remain;","Who eats, hell swallows him, and renders not again"],"s":"Not to eat flesh contributes to the continuance of life; therefore if a man eat flesh, hell will not open its mouth  (to let him escape out, after he has once fallen in)","ch":26,"sec":1,"th":"compassion"},
  {"n":256,"ta":["தினற்பொருட்டால் கொல்லாது உலகெனின் யாரும்","விலைப்பொருட்டால் ஊன்றருவா ரில்"],"tr":["Thinarporuttaal Kollaadhu Ulakenin Yaarum","Vilaipporuttaal Oondraruvaa Ril"],"en":["'We eat the slain, ' you say, by us no living creatures die;","Who'd kill and sell, I pray, if none came there the flesh to buy"],"s":"If the world does not destroy life for the purpose of eating, then no one would sell flesh for the sake of money","ch":26,"sec":1,"th":"compassion"},
  {"n":257,"ta":["உண்ணாமை வேண்டும் புலாஅல் பிறிதொன்றன்","புண்ணது உணர்வார்ப் பெறின்"],"tr":["Unnaamai Ventum Pulaaal Piridhondran","Punnadhu Unarvaarp Perin"],"en":["With other beings' ulcerous wounds their hunger they appease;","If this they felt, desire to eat must surely cease"],"s":"If men should come to know that flesh is nothing but the unclean ulcer of a body, let them abstain from eating it","ch":26,"sec":1,"th":"compassion"},
  {"n":258,"ta":["செயிரின் தலைப்பிரிந்த காட்சியார் உண்ணார்","உயிரின் தலைப்பிரிந்த ஊன்"],"tr":["Seyirin Thalaippirindha Kaatchiyaar Unnaar","Uyirin Thalaippirindha Oon"],"en":["Whose souls the vision pure and passionless perceive,","Eat not the bodies men of life bereave"],"s":"The wise, who have freed themselves from mental delusion, will not eat the flesh which has been severed from an animal","ch":26,"sec":1,"th":"compassion"},
  {"n":259,"ta":["அவிசொரிந் தாயிரம் வேட்டலின் ஒன்றன்","உயிர்செகுத் துண்ணாமை நன்று"],"tr":["Avisorin Thaayiram Vettalin Ondran","Uyirsekuth Thunnaamai Nandru"],"en":["Than thousand rich oblations, with libations rare,","Better the flesh of slaughtered beings not to share"],"s":"Not to kill and eat  (the flesh of) an animal, is better than the pouring forth of ghee etc, in a thousand sacrifices","ch":26,"sec":1,"th":"compassion"},
  {"n":260,"ta":["கொல்லான் புலாலை மறுத்தானைக் கைகூப்பி","எல்லா உயிருந் தொழும்"],"tr":["Kollaan Pulaalai Maruththaanaik Kaikooppi","Ellaa Uyirun Thozhum"],"en":["Who slays nought,  flesh rejects- his feet before","All living things with clasped hands adore"],"s":"All creatures will join their hands together, and worship him who has never taken away life, nor eaten flesh","ch":26,"sec":1,"th":"compassion"},
  {"n":261,"ta":["உற்றநோய் நோன்றல் உயிர்க்குறுகண் செய்யாமை","அற்றே தவத்திற் குரு"],"tr":["Utranoi Nondral Uyirkkurukan Seyyaamai","Atre Thavaththir Kuru"],"en":["To bear due penitential pains, while no offence","He causes others, is the type of 'penitence'"],"s":"The nature of religious discipline consists, in the endurance  (by the ascetic) of the sufferings which it brings on himself, and in abstaining from giving pain to others","ch":27,"sec":1,"th":"effort"},
  {"n":262,"ta":["தவமும் தவமுடையார்க்கு ஆகும் அதனை","அஃதிலார் மேற்கொள் வது"],"tr":["Thavamum Thavamutaiyaarkku Aakum Adhanai","Aqdhilaar Merkol Vadhu"],"en":["To 'penitents' sincere avails their 'penitence';","Where that is not, 'tis but a vain pretence"],"s":"Austerities can only be borne, and their benefits enjoyed, by those who have practised them  (in a former birth); it will be useless for those who have not done so, to attempt to practise them  (now)","ch":27,"sec":1,"th":"effort"},
  {"n":263,"ta":["துறந்தார்க்குத் துப்புரவு வேண்டி மறந்தார்கொல்","மற்றை யவர்கள் தவம்"],"tr":["Thurandhaarkkuth Thuppuravu Venti Marandhaarkol","Matrai Yavarkal Thavam"],"en":["Have other men forgotten 'penitence' who strive","To earn for penitents the things by which they live"],"s":"It is to provide food etc, for the ascetics who have abandoned  (the desire of earthly possessions) that other persons have forgotten  (to practise) austerity?","ch":27,"sec":1,"th":"effort"},
  {"n":264,"ta":["ஒன்னார்த் தெறலும் உவந்தாரை ஆக்கலும்","எண்ணின் தவத்தான் வரும்"],"tr":["Onnaarth Theralum Uvandhaarai Aakkalum","Ennin Thavaththaan Varum"],"en":["Destruction to his foes, to friends increase of joy","The 'penitent' can cause, if this his thoughts employ"],"s":"If  (the ascetic) desire the destruction of his enemies, or the aggrandizement of his friends, it will be effected by  (the power of) his austerities","ch":27,"sec":1,"th":"effort"},
  {"n":265,"ta":["வேண்டிய வேண்டியாங் கெய்தலால் செய்தவம்","ஈண்டு முயலப் படும்"],"tr":["Ventiya Ventiyaang Keydhalaal Seydhavam","Eentu Muyalap Patum"],"en":["That what they wish may, as they wish, be won,","By men on earth are works of painful 'penance' done"],"s":"Religious dislipline is practised in this world, because it secures the attainment of whatever one may wish to enjoy  (in the world to come)","ch":27,"sec":1,"th":"effort"},
  {"n":266,"ta":["தவஞ்செய்வார் தங்கருமஞ் செய்வார்மற் றல்லார்","அவஞ்செய்வார் ஆசையுட் பட்டு"],"tr":["Thavanj Cheyvaar Thangarumanj Cheyvaarmar","Rallaar Avanjeyvaar Aasaiyut Pattu"],"en":["Who works of 'penance' do, their end attain,","Others in passion's net enshared, toil but in vain"],"s":"Those discharge their duty who perform austerities; all others accomplish their own destruction, through the entanglement of the desire  (of riches and sensual pleasure)","ch":27,"sec":1,"th":"effort"},
  {"n":267,"ta":["சுடச்சுடரும் பொன்போல் ஒளிவிடும் துன்பஞ்","சுடச்சுட நோற்கிற் பவர்க்கு"],"tr":["Sutachchutarum Ponpol Olivitum Thunpanjjch","Utachchuta Norkir Pavarkku"],"en":["The hotter glows the fining fire, the gold the brighter shines;","The pain of penitence, like fire, the soul of man refines"],"s":"Just as gold is purified as heated in the fire, will those shine, who have endured the burning of pain  (in frequent austerities)","ch":27,"sec":1,"th":"effort"},
  {"n":268,"ta":["தன்னுயிர் தான்அறப் பெற்றானை ஏனைய","மன்னுயி ரெல்லாந் தொழும்"],"tr":["Thannuyir Thaanarap Petraanai Enaiya","Mannuyi Rellaan Thozhum"],"en":["Who gains himself in utter self-control,","Him worships every other living soul"],"s":"All other creatures will worship him who has attained the control of his own soul","ch":27,"sec":1,"th":"effort"},
  {"n":269,"ta":["கூற்றம் குதித்தலும் கைகூடும் நோற்றலின்","ஆற்றல் தலைப்பட் டவர்க்குல்"],"tr":["Kootram Kudhiththalum Kaikootum Notralin","Aatral Thalaippat Tavarkkul"],"en":["E'en over death the victory he may gain,","If power by penance won his soul obtain"],"s":"Those who have attained the power which religious discipline confers, will be able also to pass the limit of Yama,  (the God of death)","ch":27,"sec":1,"th":"effort"},
  {"n":270,"ta":["இலர்பல ராகிய காரணம் நோற்பார்","சிலர்பலர் நோலா தவர்"],"tr":["Ilarpala Raakiya Kaaranam Norpaar","Silarpalar Nolaa Thavar"],"en":["The many all things lack! The cause is plain,","The 'penitents' are few The many shun such pain"],"s":"Because there are few who practise austerity and many who do not, there are many destitute and few rich in this world","ch":27,"sec":1,"th":"effort"},
  {"n":271,"ta":["வஞ்ச மனத்தான் படிற்றொழுக்கம் பூதங்கள்","ஐந்தும் அகத்தே நகும்"],"tr":["Vanja Manaththaan Patitrozhukkam Poodhangal","Aindhum Akaththe Nakum"],"en":["Who with deceitful mind in false way walks of covert sin,","The five-fold elements his frame compose, decide within"],"s":"The five elements  (of his body) will laugh within him at the feigned conduct of the deceitful minded man","ch":28,"sec":1,"th":"truth"},
  {"n":272,"ta":["வானுயர் தோற்றம் எவன்செய்யும் தன்னெஞ்சம்","தான்அறி குற்றப் படின்"],"tr":["Vaanuyar Thotram Evanseyyum Thannenjam","Thaanari Kutrap Patin"],"en":["What gain, though virtue's semblance high as heaven his fame exalt,","If heart dies down through sense of self-detected fault"],"s":"What avails an appearance  (of sanctity) high as heaven, if his mind suffers  (the indulgence) of conscious sin","ch":28,"sec":1,"th":"truth"},
  {"n":273,"ta":["வலியில் நிலைமையான் வல்லுருவம் பெற்றம்","புலியின்தோல் போர்த்துமேய்ந் தற்று"],"tr":["Valiyil Nilaimaiyaan Valluruvam Petram","Puliyindhol Porththumeyn Thatru"],"en":["As if a steer should graze wrapped round with tiger's skin,","Is show of virtuous might when weakness lurks within"],"s":"The assumed appearance of power, by a man who has no power  (to restrain his senses and perform austerity), is like a cow feeding on grass covered with a tiger's skin","ch":28,"sec":1,"th":"truth"},
  {"n":274,"ta":["தவமறைந்து அல்லவை செய்தல் புதல்மறைந்து","வேட்டுவன் புள்சிமிழ்த் தற்று"],"tr":["Thavamaraindhu Allavai Seydhal Pudhalmaraindhu","Vettuvan Pulsimizhth Thatru"],"en":["'Tis as a fowler, silly birds to snare, in thicket lurks","When, clad in stern ascetic garb, one secret evil works"],"s":"He who hides himself under the mask of an ascetic and commits sins, like a sportsman who conceals himself in the thicket to catch birds","ch":28,"sec":1,"th":"truth"},
  {"n":275,"ta":["பற்றற்றேம் என்பார் படிற்றொழுக்கம் எற்றெற்றென்று","ஏதம் பலவுந் தரும்"],"tr":["Patratrem Enpaar Patitrozhukkam Etretrendru","Edham Palavun Tharum"],"en":["'Our souls are free, ' who say, yet practise evil secretly,","'What folly have we wrought! ' by many shames o'er-whelmed, shall cry"],"s":"The false conduct of those who say they have renounced all desire will one day bring them sorrows that will make them cry out, \"Oh! what have we done, what have we done.\"","ch":28,"sec":1,"th":"truth"},
  {"n":276,"ta":["நெஞ்சின் துறவார் துறந்தார்போல் வஞ்சித்து","வாழ்வாரின் வன்கணார் இல்"],"tr":["Nenjin Thuravaar Thurandhaarpol Vanjiththu","Vaazhvaarin Vankanaar Il"],"en":["In mind renouncing nought, in speech renouncing every tie,","Who guileful live,  no men are found than these of 'harder eye'"],"s":"Amongst living men there are none so hard-hearted as those who without to saking  (desire) in their heart, falsely take the appearance of those who have forsaken  (it)","ch":28,"sec":1,"th":"truth"},
  {"n":277,"ta":["புறங்குன்றி கண்டனைய ரேனும் அகங்குன்றி","முக்கிற் கரியார் உடைத்து"],"tr":["Purangundri Kantanaiya Renum Akangundri","Mukkir Kariyaar Utaiththu"],"en":["Outward, they shine as 'kunri' berry's scarlet bright;","Inward, like tip of 'kunri' bead, as black as night"],"s":"(The world) contains persons whose outside appears  (as fair) as the  (red) berry of the Abrus, but whose inside is as black as the nose of that berry","ch":28,"sec":1,"th":"truth"},
  {"n":278,"ta":["மனத்தது மாசாக மாண்டார் நீராடி","மறைந்தொழுகு மாந்தர் பலர்"],"tr":["Manaththadhu Maasaaka Maantaar Neeraati","Maraindhozhuku Maandhar Palar"],"en":["Many wash in hollowed waters, living lives of hidden shame;","Foul in heart, yet high upraised of men in virtuous fame"],"s":"There are many men of masked conduct, who perform their ablutions, and  (make a show) of","ch":28,"sec":1,"th":"truth"},
  {"n":279,"ta":["கணைகொடிது யாழ்கோடு செவ்விதுஆங் கன்ன","வினைபடு பாலால் கொளல்"],"tr":["Kanaikotidhu Yaazhkotu Sevvidhuaang Kanna","Vinaipatu Paalaal Kolal"],"en":["Cruel is the arrow straight, the crooked lute is sweet,","Judge by their deeds the many forms of men you meet"],"s":"As, in its use, the arrow is crooked, and the curved lute is straight, so by their deeds,  (and not by their appearance) let  (the uprightness or crookedness of) men be estimated","ch":28,"sec":1,"th":"truth"},
  {"n":280,"ta":["மழித்தலும் நீட்டலும் வேண்டா உலகம்","பழித்தது ஒழித்து விடின்"],"tr":["Mazhiththalum Neettalum Ventaa Ulakam","Pazhiththadhu Ozhiththu Vitin"],"en":["What's the worth of shaven head or tresses long,","If you shun what all the world condemns as wrong"],"s":"There is no need of a shaven crown, nor of tangled hair, if a man abstain from those deeds which the wise have condemned","ch":28,"sec":1,"th":"truth"},
  {"n":281,"ta":["எள்ளாமை வேண்டுவான் என்பான் எனைத்தொன்றும்","கள்ளாமை காக்கதன் நெஞ்சு"],"tr":["Ellaamai Ventuvaan Enpaan Enaiththondrum","Kallaamai Kaakkadhan Nenju"],"en":["Who seeks heaven's joys, from impious levity secure,","Let him from every fraud preserve his spirit pure"],"s":"Let him, who desires not to be despised, keep his mind from  (the desire of) defrauding another of the smallest thing","ch":29,"sec":1,"th":"truth"},
  {"n":282,"ta":["உள்ளத்தால் உள்ளலும் தீதே பிறன்பொருளைக்","கள்ளத்தால் கள்வேம் எனல்"],"tr":["Ullaththaal Ullalum Theedhe Piranporulaik","Kallaththaal Kalvem Enal"],"en":["'Tis sin if in the mind man but thought conceive;","'By fraud I will my neighbour of his wealth bereave. '"],"s":"Even the thought  (of sin) is sin; think not then of crafiily stealing the property of another","ch":29,"sec":1,"th":"truth"},
  {"n":283,"ta":["களவினால் ஆகிய ஆக்கம் அளவிறந்து","ஆவது போலக் கெடும்"],"tr":["Kalavinaal Aakiya Aakkam Alavirandhu","Aavadhu Polak Ketum"],"en":["The gain that comes by fraud, although it seems to grow","With limitless increase, to ruin swift shall go"],"s":"The property, which is acquired by fraud, will entirely perish, even while it seems to increase","ch":29,"sec":1,"th":"truth"},
  {"n":284,"ta":["களவின்கண் கன்றிய காதல் விளைவின்கண்","வீயா விழுமம் தரும்"],"tr":["Kalavinkan Kandriya Kaadhal Vilaivinkan","Veeyaa Vizhumam Tharum"],"en":["The lust inveterate of fraudful gain,","Yields as its fruit undying pain"],"s":"The eager desire of defrauding others will, when it brings forth its fruit, produce undying sorrow","ch":29,"sec":1,"th":"truth"},
  {"n":285,"ta":["அருள்கருதி அன்புடைய ராதல் பொருள்கருதிப்","பொச்சாப்புப் பார்ப்பார்கண் இல்"],"tr":["Arulkarudhi Anputaiya Raadhal Porulkarudhip","Pochchaappup Paarppaarkan Il"],"en":["'Grace' is not in their thoughts, nor know they kind affection's power,","Who neighbour's goods desire, and watch for his unguarded hour"],"s":"The study of kindness and the exercise of benevolence is not with those who watch for another's forgetfulness, though desire of his property","ch":29,"sec":1,"th":"truth"},
  {"n":286,"ta":["அளவின்கண் நின்றொழுகல் ஆற்றார் களவின்கண்","கன்றிய காத லவர்"],"tr":["Alavinkan Nindrozhukal Aatraar Kalavinkan","Kandriya Kaadha Lavar"],"en":["They cannot walk restrained in wisdom's measured bound,","In whom inveterate lust of fraudful gain is found"],"s":"They cannot walk steadfastly, according to rule, who eagerly desire to defraud others","ch":29,"sec":1,"th":"truth"},
  {"n":287,"ta":["களவென்னும் காரறி வாண்மை அளவென்னும்","ஆற்றல் புரிந்தார்கண்ட இல்"],"tr":["Kalavennum Kaarari Vaanmai Alavennum","Aatral Purindhaarkanta Il"],"en":["Practice of fraud's dark cunning arts they shun,","Who long for power by 'measured wisdom' won"],"s":"That black-knowledge which is called fraud, is not in those who desire that greatness which is called rectitude","ch":29,"sec":1,"th":"truth"},
  {"n":288,"ta":["அளவறிந்தார் நெஞ்சத் தறம்போல நிற்கும்","களவறிந்தார் நெஞ்சில் கரவு"],"tr":["Alavarindhaar Nenjath Tharampola Nirkum","Kalavarindhaar Nenjil Karavu"],"en":["As virtue dwells in heart that 'measured wisdom' gains;","Deceit in hearts of fraudful men established reigns"],"s":"Deceit dwells in the mind of those who are conversant with fraud, even as virtue in the minds of those who are conversant with rectitude","ch":29,"sec":1,"th":"truth"},
  {"n":289,"ta":["அளவல்ல செய்தாங்கே வீவர் களவல்ல","மற்றைய தேற்றா தவர்"],"tr":["Alavalla Seydhaange Veevar Kalavalla","Matraiya Thetraa Thavar"],"en":["Who have no lore save that which fraudful arts supply,","Acts of unmeasured vice committing straightway die"],"s":"Those, who are acquainted with nothing but fraud, will perish in the very commission of transgression","ch":29,"sec":1,"th":"truth"},
  {"n":290,"ta":["கள்வார்க்குத் தள்ளும் உயிர்நிலை கள்வார்க்குத்","தள்ளாது புத்தே ளுளகு"],"tr":["Kalvaarkkuth Thallum Uyirnilai Kalvaarkkuth","Thallaadhu Puththe Lulaku"],"en":["The fraudful forfeit life and being here below;","Who fraud eschew the bliss of heavenly beings know"],"s":"Even their body will fail the fraudulent; but even the world of the gods will not fail those who are free from fraud","ch":29,"sec":1,"th":"truth"},
  {"n":291,"ta":["வாய்மை எனப்படுவது யாதெனின் யாதொன்றும்","தீமை இல்லாத சொல்"],"tr":["Vaaimai Enappaduvadhu Yaadhenin Yaadhondrum","Theemai Illaadha Sol"],"en":["You ask, in lips of men what ‘truth’ may be;","‘Tis speech from every taint of evil free"],"s":"What is truth? It is words with no harm in them at all.","ch":30,"sec":1,"th":"truth"},
  {"n":292,"ta":["பொய்மையும் வாய்மை யிடத்த புரைதீர்ந்த","நன்மை பயக்கும் எனின்"],"tr":["Poimaiyum Vaaimai Yitaththa Puraidheerndha","Nanmai Payakkum Enin"],"en":["Falsehood may take the place of truthful word,","If blessing, free from fault, it can afford"],"s":"Even falsehood has the nature of truth, if it confer a benefit that is free from fault","ch":30,"sec":1,"th":"truth"},
  {"n":293,"ta":["தனெஞ்சறிவது பொய்யற்க பொய்த்தபின்","தனெஞ்சே தன்னைச் சுடும்"],"tr":["Thunenjarivadhu Poyyarke Poythapin","Thunenje Thannai Sutum"],"en":["Speak not a word which false thy own heart knows","Self-kindled fire within the false one’s spirit glows"],"s":"Never say what you know in your heart is false. A lie burns the liar first.","ch":30,"sec":1,"th":"truth"},
  {"n":294,"ta":["உள்ளத்தாற் பொய்யா தொழுகின் உலகத்தார்","உள்ளத்து ளெல்லாம் உளன்"],"tr":["Ullaththaar Poiyaa Thozhukin Ulakaththaar","Ullaththu Lellaam Ulan"],"en":["True to his inmost soul who lives,  enshrined","He lives in souls of all mankind"],"s":"He who, in his conduct, preserves a mind free from deceit, will dwell in the minds of all men","ch":30,"sec":1,"th":"truth"},
  {"n":295,"ta":["மனத்தொடு வாய்மை மொழியின் தவத்தொடு","தானஞ்செய் வாரின் தலை"],"tr":["Manaththotu Vaaimai Mozhiyin Thavaththotu","Thaananjey Vaarin Thalai"],"en":["Greater is he who speaks the truth with full consenting mind","Than men whose lives have penitence and charity combined"],"s":"He, who speaks truth with all his heart, is superior to those who make gifts and practise austerities","ch":30,"sec":1,"th":"truth"},
  {"n":296,"ta":["பொய்யாமை அன்ன புகழில்லை எய்யாமை","எல்லா அறமுந் தரும்"],"tr":["Poiyaamai Anna Pukazhillai Eyyaamai","Ellaa Aramun Tharum"],"en":["No praise like that of words from falsehood free;","This every virtue yields spontaneously"],"s":"There is no praise like the praise of never uttering a falsehood: without causing any suffering, it will lead to every virtue","ch":30,"sec":1,"th":"truth"},
  {"n":297,"ta":["பொய்யாமை பொய்யாமை ஆற்றின் அறம்பிற","செய்யாமை செய்யாமை நன்று"],"tr":["Poyyaamai Poyyaamai Aatrin Arampira","Seyyaamai Seyyaamai Nandru"],"en":["If all your life be utter truth, the truth alone,","‘Tis well, though other virtuous acts be left undone"],"s":"If you live by truth alone, that is enough. Even if you do nothing else good, truth is enough.","ch":30,"sec":1,"th":"truth"},
  {"n":298,"ta":["புறள்தூய்மை நீரான் அமையும் அகந்தூய்மை","வாய்மையால் காணப் படும்"],"tr":["Puraldhooimai Neeraan Amaiyum Akandhooimai","Vaaimaiyaal Kaanap Patum"],"en":["Outward purity the water will bestow;","Inward purity from truth alone will flow"],"s":"Purity of body is produced by water and purity of mind by truthfulness","ch":30,"sec":1,"th":"truth"},
  {"n":299,"ta":["எல்லா விளக்கும் விளக்கல்ல சான்றோர்க்குப்","பொய்யா விளக்கே விளக்கு"],"tr":["Ellaa Vilakkum Vilakkalla Saandrorkkup","Poiyaa Vilakke Vilakku"],"en":["Every lamp is not a lamp in wise men's sight;","That's the lamp with truth's pure radiance bright"],"s":"All lamps of nature are not lamps; the lamp of truth is the lamp of the wise","ch":30,"sec":1,"th":"truth"},
  {"n":300,"ta":["யாமெய்யாக் கண்டவற்றுள் இல்லை எனைத்தொன்றும்","வாய்மையின் நல்ல பிற"],"tr":["Yaameyyaak Kantavatrul Illai Enaiththondrum","Vaaimaiyin Nalla Pira"],"en":["Of all good things we've scanned with studious care,","There's nought that can with truthfulness compare"],"s":"Amidst all that we have seen  (described) as real  (excellence), there is nothing so good as truthfulness","ch":30,"sec":1,"th":"truth"},
  {"n":301,"ta":["செல்லிடத்துக் காப்பான் சினங்காப்பான் அல்லிடத்துக்","காக்கின்என் காவாக்கால் என்?"],"tr":["Sellitaththuk Kaappaan Sinangaappaan Allitaththuk","Kaakkinen Kaavaakkaal En?"],"en":["Where thou hast power thy angry will to work, thy wrath restrain;","Where power is none, what matter if thou check or give it rein"],"s":"He restrains his anger who restrains it when it can injure; when it cannot injure, what does it matter whether he restrain it, or not?","ch":31,"sec":1,"th":"anger"},
  {"n":302,"ta":["செல்லா இடத்துச் சினந்தீது செல்லிடத்தும்","இல்அதனின் தீய பிற"],"tr":["Sellaa Itaththuch Chinandheedhu Sellitaththum","Iladhanin Theeya Pira"],"en":["Where power is none to wreak thy wrath, wrath importent is ill;","Where thou hast power thy will to work, 'tis greater, evil still"],"s":"Anger is bad, even when it cannot injure; when it can injure; there is no greater evil","ch":31,"sec":1,"th":"anger"},
  {"n":303,"ta":["மறத்தல் வெகுளியை யார்மாட்டும் தீய","பிறத்தல் அதனான் வரும்"],"tr":["Maraththal Vekuliyai Yaarmaattum Theeya","Piraththal Adhanaan Varum"],"en":["If any rouse thy wrath, the trespass straight forget;","For wrath an endless train of evils will beget"],"s":"Forget anger towards every one, as fountains of evil spring from it","ch":31,"sec":1,"th":"anger"},
  {"n":304,"ta":["நகையும் உவகையும் கொல்லும் சினத்தின்","பகையும் உளவோ பிற"],"tr":["Nakaiyum Uvakaiyum Kollum Sinaththin","Pakaiyum Ulavo Pira"],"en":["Wrath robs the face of smiles, the heart of joy,","What other foe to man works such annoy"],"s":"What other foe to man works such annoy?","ch":31,"sec":1,"th":"anger"},
  {"n":305,"ta":["தன்னைத்தான் காக்கின் சினங்காக்க காவாக்கால்","தன்னையே கொல்லுஞ் சினம்"],"tr":["Thannaiththaan Kaakkin Sinangaakka Kaavaakkaal","Thannaiye Kollunj Sinam"],"en":["If thou would’st guard thyself, guard against wrath alway;","‘Gainst wrath who guards not, him his wrath shall slay"],"s":"If you want to protect yourself, guard against anger. Anger will kill the one who does not control it.","ch":31,"sec":1,"th":"anger"},
  {"n":306,"ta":["சினமென்னும் சேர்ந்தாரைக் கொல்லி இனமென்னும்","ஏமப் புணையைச் சுடும்"],"tr":["Sinamennum Serndhaaraik Kolli Inamennum","Emap Punaiyaich Chutum"],"en":["Wrath, the fire that slayeth whose draweth near,","Will burn the helpful 'raft' of kindred dear"],"s":"The fire of anger will burn up even the pleasant raft of friendship","ch":31,"sec":1,"th":"anger"},
  {"n":307,"ta":["சினத்தைப் பொருளென்று கொண்டவன் கேடு","நிலத்தறைந்தான் கைபிழையா தற்று"],"tr":["Sinaththaip Porulendru Kontavan Ketu","Nilaththaraindhaan Kaipizhaiyaa Thatru"],"en":["The hand that smites the earth unfailing feels the sting;","So perish they who nurse their wrath as noble thing"],"s":"Destruction will come upon him who ragards anger as a good thing, as surely as the hand of him who strikes the ground will not fail","ch":31,"sec":1,"th":"anger"},
  {"n":308,"ta":["இணர்எரி தோய்வன்ன இன்னா செயினும்","புணரின் வெகுளாமை நன்று"],"tr":["Inareri Thoivanna Innaa Seyinum","Punarin Vekulaamai Nandru"],"en":["Though men should work thee woe, like touch of tongues of fire","'Tis well if thou canst save thy soul from burning ire"],"s":"Though one commit things against you as painful  (to bear) as if a bundle of fire had been thrust upon you, it will be well, to refrain, if possible, from anger","ch":31,"sec":1,"th":"anger"},
  {"n":309,"ta":["உள்ளிய தெல்லாம் உடனெய்தும் உள்ளத்தால்","உள்ளான் வெகுளி எனின்"],"tr":["Ulliya Thellaam Utaneydhum Ullaththaal","Ullaan Vekuli Enin"],"en":["If man his soul preserve from wrathful fires,","He gains with that whate'er his soul desires"],"s":"If a man never indulges anger in his heart, he will at once obtain whatever he has thought of","ch":31,"sec":1,"th":"anger"},
  {"n":310,"ta":["இறந்தார் இறந்தார் அனையர் சினத்தைத்","துறந்தார் துறந்தார் துணை"],"tr":["Irandhaar Irandhaar Anaiyar Sinaththaith","Thurandhaar Thurandhaar Thunai"],"en":["Men of surpassing wrath are like the men who've passed away;","Who wrath renounce, equals of all-renouncing sages they"],"s":"Those, who give way to excessive anger, are no better than dead men; but those, who are freed from it, are equal to those who are freed  (from death)","ch":31,"sec":1,"th":"anger"},
  {"n":311,"ta":["சிறப்பீனும் செல்வம் பெறினும் பிறர்க்குஇன்னா","செய்யாமை மாசற்றார் கோள்"],"tr":["Sirappeenum Selvam Perinum Pirarkku","Innaa Seyyaamai Maasatraar Kol"],"en":["Though ill to neighbour wrought should glorious pride of wealth secure,","No ill to do is fixed decree of men in spirit pure"],"s":"It is the determination of the spotless not to cause sorrow to others, although they could  (by so causing) obtain the wealth which confers greatness","ch":32,"sec":1,"th":"compassion"},
  {"n":312,"ta":["கறுத்துஇன்னா செய்தவக் கண்ணும் மறுத்தின்னா","செய்யாமை மாசற்றார் கோள்"],"tr":["Karuththuinnaa Seydhavak Kannum Maruththinnaa","Seyyaamai Maasatraar Kol"],"en":["Though malice work its worst, planning no ill return, to endure,","And work no ill, is fixed decree of men in spirit pure"],"s":"It is the determination of the spotless not to do evil, even in return, to those who have cherished enmity and done them evil","ch":32,"sec":1,"th":"compassion"},
  {"n":313,"ta":["செய்யாமல் செற்றார்க்கும் இன்னாத செய்தபின்","உய்யா விழுமந் தரும்"],"tr":["Seyyaamal Setraarkkum Innaadha Seydhapin","Uyyaa Vizhumam Tharum"],"en":["Though unprovoked thy soul malicious foes should sting,","Retaliation wrought inevitable woes will bring"],"s":"Even if enemies hurt you for no reason, hurting them back will bring you ruin.","ch":32,"sec":1,"th":"compassion"},
  {"n":314,"ta":["இன்னா செய்தாரை ஒறுத்தல் அவர்நாண","நன்னயஞ் செய்து விடல்"],"tr":["Innaasey Thaarai Othuthal Avarnaana","Nannayanj Seydhu Vidal"],"en":["To punish wrong, with kindly benefits the doers ply;","Thus shame their souls; but pass the ill unheeded by"],"s":"The best way to punish someone who hurts you: do them a kindness so good that they feel ashamed. Then let the harm go.","ch":32,"sec":1,"th":"compassion"},
  {"n":315,"ta":["அறிவினான் ஆகுவ துண்டோ பிறிதின்நோய்","தந்நோய்போல் போற்றாக் கடை"],"tr":["Arivinaan Aakuva Thunto Piridhinnoi","Thannoipol Potraak Katai"],"en":["From wisdom's vaunted lore what doth the learner gain,","If as his own he guard not others' souls from pain"],"s":"What benefit has he derived from his knowledge, who does not endeavour to keep off pain from another as much as from himself?","ch":32,"sec":1,"th":"compassion"},
  {"n":316,"ta":["இன்னா எனத்தான் உணர்ந்தவை துன்னாமை","வேண்டும் பிறன்கண செயல்"],"tr":["Innaa Enaththaan Unarndhavai Thunnaamai","Ventum Pirankan Seyal"],"en":["What his own soul has felt as bitter pain,","From making others feel should man abstain"],"s":"If you know in your own heart what hurts, do not do it to anyone else. That is the whole rule.","ch":32,"sec":1,"th":"compassion"},
  {"n":317,"ta":["எனைத்தானும் எஞ்ஞான்றும் யார்க்கும் மனத்தானாம்","மாணாசெய் யாமை தலை"],"tr":["Enaiththaanum Egngnaandrum Yaarkkum Manaththaanaam","Maanaasey Yaamai Thalai"],"en":["To work no wilful woe, in any wise, through all the days,","To any living soul, is virtue's highest praise"],"s":"It is the chief of all virtues not knowingly to do any person evil, even in the lowest degree, and at any time","ch":32,"sec":1,"th":"compassion"},
  {"n":318,"ta":["தன்னுயிர்ககு ஏன்னாமை தானறிவான் என்கொலோ","மன்னுயிர்க்கு இன்னா செயல்"],"tr":["Thannuyirkaku Ennaamai Thaanarivaan Enkolo","Mannuyirkku Innaa Seyal"],"en":["Whose soul has felt the bitter smart of wrong, how can","He wrongs inflict on ever-living soul of man"],"s":"Why does a man inflict upon other creatures those sufferings, which he has found by experience are sufferings to himself?","ch":32,"sec":1,"th":"compassion"},
  {"n":319,"ta":["பிறர்க்கின்னா முற்பகல் செய்யின் தமக்குஇன்னா","பிற்பகல் தாமே வரும்"],"tr":["Pirarkkinnaa Murpakal Seyyin Thamakku","Innaa Pirpakal Thaame Varum"],"en":["If, ere the noontide, you to others evil do,","Before the eventide will evil visit you"],"s":"If a man inflict sorrow upon others in the morning, it will come upon him unsought in the very evening","ch":32,"sec":1,"th":"compassion"},
  {"n":320,"ta":["நோயெல்லாம் நோய்செய்தார் மேலவாம் நோய்செய்யார்","நோயின்மை வேண்டு பவர்"],"tr":["Noyellaam Noiseydhaar Melavaam Noiseyyaar","Noyinmai Ventu Pavar"],"en":["O'er every evil-doer evil broodeth still;","He evil shuns who freedom seeks from ill"],"s":"Sorrow will come upon those who cause pain to others; therfore those, who desire to be free from sorrow, give no pain to others","ch":32,"sec":1,"th":"compassion"},
  {"n":321,"ta":["அறவினை யாதெனின் கொல்லாமை கோறல்","பிறவினை எல்லாந் தரும்"],"tr":["Aravinai Yaadhenin Kollaamai Koral","Piravinai Ellaan Tharum"],"en":["What is the work of virtue? 'Not to kill';","For 'killing' leads to every work of ill"],"s":"Never to destroy life is the sum of all virtuous conduct The destruction of life leads to every evil","ch":33,"sec":1,"th":"compassion"},
  {"n":322,"ta":["பகுத்துண்டு பல்லுயிர் ஓம்புதல் நூலோர்","தொகுத்தவற்றுள் எல்லாந் தலை"],"tr":["Pakuththuntu Palluyir Ompudhal Noolor","Thokuththavatrul Ellaan Thalai"],"en":["Let those that need partake your meal; guard every-thing that lives;","This the chief and sum of lore that hoarded wisdom gives"],"s":"The chief of all  (the virtues) which authors have summed up, is the partaking of food that has been shared with others, and the preservation of the mainfold life of other creatures","ch":33,"sec":1,"th":"compassion"},
  {"n":323,"ta":["ஒன்றாக நல்லது கொல்லாமை மற்றதன்","பின்சாரப் பொய்யாமை நன்று"],"tr":["Ondraaka Nalladhu Kollaamai Matradhan","Pinsaarap Poiyaamai Nandru"],"en":["Alone, first of goods things, is 'not to slay';","The second is, no untrue word to say"],"s":"Not to destroy life is an incomparably  (great) good next to it in goodness ranks freedom from falsehood","ch":33,"sec":1,"th":"compassion"},
  {"n":324,"ta":["நல்லாறு எனப்படுவது யாதெனின் யாதொன்றும்","கொல்லாமை சூழும் நெறி"],"tr":["Nallaaru Enappatuvadhu Yaadhenin Yaadhondrum","Kollaamai Soozhum Neri"],"en":["You ask, What is the good and perfect way?","'Tis path of him who studies nought to slay"],"s":"Good path is that which considers how it may avoid killing any creature","ch":33,"sec":1,"th":"compassion"},
  {"n":325,"ta":["நிலைஅஞ்சி நீத்தாருள் எல்லாம் கொலைஅஞ்சிக்","கொல்லாமை சூழ்வான் தலை"],"tr":["Nilaianji Neeththaarul Ellaam Kolaianjik","Kollaamai Soozhvaan Thalai"],"en":["Of those who 'being' dread, and all renounce, the chief are they,","Who dreading crime of slaughter, study nought to slay"],"s":"Of all those who, fearing the permanence of earthly births, have abandoned desire, he is the chief who, fearing  (the guilt of) murder, considers how he may avoid the destruction of life","ch":33,"sec":1,"th":"compassion"},
  {"n":326,"ta":["கொல்லாமை மேற்கொண் டொழுகுவான் வாழ்நாள்மேல்","செல்லாது உயிருண்ணுங் கூற்று"],"tr":["Kollaamai Merkon Tozhukuvaan Vaazhnaalmel","Sellaadhu Uyirunnung Kootru"],"en":["Ev'n death that life devours, their happy days shall spare,","Who law, 'Thou shall not kill', uphold with reverent care"],"s":"Yama, the destroyer of life, will not attack the life of him, who acts under the determination of never destroying life","ch":33,"sec":1,"th":"compassion"},
  {"n":327,"ta":["தன்னுயிர் நீப்பினும் செய்யற்க தான்பிறிது","இன்னுயிர் நீக்கும் வினை"],"tr":["Thannuyir Neeppinum Seyyarka Thaanpiridhu","Innuyir Neekkum Vinai"],"en":["Though thine own life for that spared life the price must pay,","Take not from aught that lives gift of sweet life away"],"s":"Let no one do that which would destroy the life of another, although he should by so doing, lose his own life","ch":33,"sec":1,"th":"compassion"},
  {"n":328,"ta":["நன்றாகும் ஆக்கம் பெரிதெனினும் சான்றோர்க்குக்","கொன்றாகும் ஆக்கங் கடை"],"tr":["Nandraakum Aakkam Peridheninum Saandrorkkuk","Kondraakum Aakkang Katai"],"en":["Though great the gain of good should seem, the wise","Will any gain by staughter won despise"],"s":"The advantage which might flow from destroying life in sacrifice, is dishonourable to the wise  (who renounced the world), even although it should be said to be productive of great good","ch":33,"sec":1,"th":"compassion"},
  {"n":329,"ta":["கொலைவினைய ராகிய மாக்கள் புலைவினையர்","புன்மை தெரிவா ரகத்து"],"tr":["Kolaivinaiya Raakiya Maakkal Pulaivinaiyar","Punmai Therivaa Rakaththu"],"en":["Whose trade is 'killing', always vile they show,","To minds of them who what is vileness know"],"s":"To minds of them who what is vileness know","ch":33,"sec":1,"th":"compassion"},
  {"n":330,"ta":["உயிருடம்பின் நீக்கியா ரென்ப செயிருடம்பின்","செல்லாத்தீ வாழ்க்கை யவர்"],"tr":["Uyir Utampin Neekkiyaar Enpa","Seyir Utampin Sellaaththee Vaazhkkai"],"en":["Who lead a loathed life in bodies sorely pained,","Are men, the wise declare, by guilt of slaughter stained"],"s":"(The wise) will say that men of diseased bodies, who live in degradation and in poverty, are those who separated the life from the body of animals  (in a former birth)","ch":33,"sec":1,"th":"compassion"},
  {"n":331,"ta":["நில்லாத வற்றை நிலையின என்றுணரும்","புல்லறிவாண்மை கடை"],"tr":["Nillaadha Vatrai Nilaiyina Endrunarum","Pullari Vaanmai Katai"],"en":["Lowest and meanest lore, that bids men trust secure,","In things that pass away, as things that shall endure"],"s":"The worst kind of foolishness: trusting things that pass as if they will last forever.","ch":34,"sec":1,"th":"impermanence"},
  {"n":332,"ta":["கூத்தாட்டு அவைக்குழாத் தற்றே பெருஞ்செல்வம்","போக்கும் அதுவிளிந் தற்று"],"tr":["Kooththaattu Avaik Kuzhaath Thatre","Perunjelvam Pokkum Adhuvilin Thatru"],"en":["As crowds round dancers fill the hall, is wealth's increase;","Its loss, as throngs dispersing, when the dances cease"],"s":"The acquisition of wealth is like the gathering together of an assembly for a theatre; its expenditure is like the breaking up of that assembly","ch":34,"sec":1,"th":"impermanence"},
  {"n":333,"ta":["அற்கா இயல்பிற்றுச் செல்வம் அதுபெற்றால்","அற்குப ஆங்கே செயல்"],"tr":["Arkaa Iyalpitruch Chelvam Adhupetraal","Arkupa Aange Seyal"],"en":["Unenduring is all wealth; if you wealth enjoy,","Enduring works in working wealth straightway employ"],"s":"Wealth is perishable; let those who obtain it immediately practise those  (virtues) which are imperishable","ch":34,"sec":1,"th":"impermanence"},
  {"n":334,"ta":["நாளென ஒன்றுபோற் காட்டி உயிர்ஈரும்","வாளது உணர்வார்ப் பெறின்"],"tr":["Naalena Ondrupol Kaatti Uyir Eerum","Vaaladhu Unarvaarp Perin"],"en":["As ‘day’ it vaunts itself; well understood, ‘tis knife,","That daily cuts away a portion from thy life"],"s":"It calls itself ‘day,’ but it is really a knife. Every day it quietly cuts a piece of your life away.","ch":34,"sec":1,"th":"impermanence"},
  {"n":335,"ta":["நாச்செற்று விக்குள்மேல் வாராமுன் நல்வினை","மேற்சென்று செய்யப் படும்"],"tr":["Naachchetru Vikkulmel Vaaraamun Nalvinai","Mersendru Seyyap Patum"],"en":["Before the tongue lie powerless, 'mid the gasp of gurgling breath,","Arouse thyself, and do good deeds beyond the power of death"],"s":"Let virtuous deeds be done quickly, before the hiccup comes making the tongue silent","ch":34,"sec":1,"th":"impermanence"},
  {"n":336,"ta":["நெருநல் உளனொருவன் இன்றில்லை என்னும்","பெருமை உடைத்துஇவ் வுலகு"],"tr":["Nerunal Ulanoruvan Indrillai Ennum","Perumai Utaiththuiv Vulaku"],"en":["Existing yesterday, today to nothing hurled!","Such greatness owns this transitory world"],"s":"This world possesses the greatness that one who yesterday was is not today","ch":34,"sec":1,"th":"impermanence"},
  {"n":337,"ta":["ஒருபொழுதும் வாழ்வது அறியார் கருதுப","கோடியும் அல்ல பல"],"tr":["Orupozhudhum Vaazhvadhu Ariyaar Karudhupa","Kotiyum Alla Pala"],"en":["Who know not if their happy lives shall last the day,","In fancies infinite beguile the hours away"],"s":"Innumerable are the thoughts which occupy the mind of  (the unwise), who know not that they shall live another moment","ch":34,"sec":1,"th":"impermanence"},
  {"n":338,"ta":["குடம்பை தனித்துஒழியப் புள்பறந் தற்றே","உடம்பொடு உயிரிடை நட்பு"],"tr":["Kutampai Thaniththu Ozhiyap Pulparan","Thatre Utampotu Uyiritai Natpu"],"en":["Birds fly away, and leave the nest deserted bare;","Such is the short-lived friendship soul and body share"],"s":"The love of the soul to the body is like  (the love of) a bird to its egg which it flies away from and leaves empty","ch":34,"sec":1,"th":"impermanence"},
  {"n":339,"ta":["உறங்கு வதுபோலுஞ் சாக்காடு உறங்கி","விழிப்பது போலும் பிறப்பு"],"tr":["Urangu Vadhupolunj Chaakkaatu Urangi","Vizhippadhu Polum Pirappu"],"en":["Death is sinking into slumbers deep;","Birth again is waking out of sleep"],"s":"Death is like sleep; birth is like awaking from it","ch":34,"sec":1,"th":"impermanence"},
  {"n":340,"ta":["புக்கில் அமைந்தின்று கொல்லோ உடம்பினுள்","துச்சில் இருந்த உயிர்க்கு"],"tr":["Pukkil Amaindhindru Kollo Utampinul","Thuchchil Irundha Uyirkku"],"en":["The soul in fragile shed as lodger courts repose:","Is it because no home's conclusive rest it knows"],"s":"It seems as if the soul, which takes a temporary shelter in a body, had not attained a home","ch":34,"sec":1,"th":"impermanence"},
  {"n":341,"ta":["யாதனின் யாதனின் நீங்கியான் நோதல்","அதனின் அதனின் இலன்"],"tr":["Yaadhanin Yaadhanin Neengiyaan Nodhal","Adhanin Adhanin Ilan"],"en":["From whatever, aye, whatever, man gets free,","From what, aye, from that, no more of pain hath he"],"s":"Whatever thing, a man has renounced, by that thing; he cannot suffer pain","ch":35,"sec":1,"th":"calm"},
  {"n":342,"ta":["வேண்டின்உண் டாகத் துறக்க துறந்தபின்","ஈண்டுஇயற் பால பல"],"tr":["Ventin Un Taakath Thurakka","Thurandhapin Eentuiyar Paala Pala"],"en":["'Renunciation' made- ev'n here true pleasures men acquire;","'Renounce' while time is yet, if to those pleasures you aspire"],"s":"After a man has renounced  (all things), there will still be many things in this world  (which he may enjoy); if he should desire them, let him, while it is time abandon  (the world)","ch":35,"sec":1,"th":"calm"},
  {"n":343,"ta":["அடல்வேண்டும் ஐந்தன் புலத்தை விடல்வேண்டும்","வேண்டிய வெல்லாம் ஒருங்கு"],"tr":["Atalventum Aindhan Pulaththai Vitalventum","Ventiya Vellaam Orungu"],"en":["'Perceptions of the five' must all expire;","Relinquished in its order each desire"],"s":"Let the five senses be destroyed; and at the same time, let everything be abandoned that  (the ascetic) has  (formerly) desired","ch":35,"sec":1,"th":"calm"},
  {"n":344,"ta":["இயல்பாகும் நோன்பிற்கொன்று இன்மை உடைமை","மயலாகும் மற்றும் பெயர்த்து"],"tr":["Iyalpaakum Nonpirkondru Inmai Utaimai","Mayalaakum Matrum Peyarththu"],"en":["'Privation absolute' is penance true;","'Possession' brings bewilderment anew"],"s":"To be altogether destitute is the proper condition of those who perform austerities; if they possess anything, it will change  (their resolution) and bring them back to their confused state","ch":35,"sec":1,"th":"calm"},
  {"n":345,"ta":["மற்றும் தொடர்ப்பாடு எவன்கொல் பிறப்பறுக்கல்","உற்றார்க்கு உடம்பும் மிகை"],"tr":["Matrum Thotarppaatu Evankol Pirapparukkal","Utraarkku Utampum Mikai"],"en":["To those who sev'rance seek from being's varied strife,","Flesh is burthen sore; what then other bonds of life"],"s":"What means the addition of other things those who are attempting to cut off  (future) births, when even their body is too much  (for them)","ch":35,"sec":1,"th":"calm"},
  {"n":346,"ta":["யான்எனது என்னும் செருக்குஅறுப்பான் வானோர்க்கு","உயர்ந்த உலகம் புகும்"],"tr":["Yaan Enadhu Ennum Serukku","Aruppaan Vaanorkku Uyarndha Ulakam"],"en":["Who kills conceit that utters 'I' and 'mine',","Shall enter realms above the powers divine"],"s":"Shall enter realms above the powers divine","ch":35,"sec":1,"th":"calm"},
  {"n":347,"ta":["பற்றி விடாஅ இடும்பைகள் பற்றினைப்","பற்றி விடாஅ தவர் க்கு"],"tr":["Patri Vitaaa Itumpaikal Patrinaip","Patri Vitaaa Thavarkku"],"en":["Who cling to things that cling and eager clasp,","Griefs cling to them with unrelaxing grasp"],"s":"Sorrows will never let go their hold of those who give not up their hold of desire","ch":35,"sec":1,"th":"calm"},
  {"n":348,"ta":["தலைப்பட்டார் தீரத் துறந்தார் மயங்கி","வலைப்பட்டார் மற்றை யவர்"],"tr":["Thalaippattaar Theerath Thurandhaar Mayangi","Valaippattaar Matrai Yavar"],"en":["Who thoroughly 'renounce' on highest height are set;","The rest bewildered, lie entangled in the net"],"s":"Those who have entirely renounced  (all things and all desire) have obtained  (absorption into God); all others wander in confusion, entangled in the net of  (many) births","ch":35,"sec":1,"th":"calm"},
  {"n":349,"ta":["பற்றற்ற கண்ணே பிறப்பறுக்கும் மற்று","நிலையாமை காணப் படும்"],"tr":["Patratra Kanne Pirapparukkum Matru","Nilaiyaamai Kaanap Patum"],"en":["When that which clings falls off, severed is being's tie;","All else will then be seen as instability"],"s":"At the moment in which desire has been abandoned,  (other) births will be cut off; when that has not been done, instability will be seen","ch":35,"sec":1,"th":"calm"},
  {"n":350,"ta":["பற்றுக பற்றற்றான் பற்றினை அப்பற்றைப்","பற்றுக பற்று விடற்கு"],"tr":["Patruka Patratraan Patrinai Appatraip","Patruka Patru Vitarku"],"en":["Cling thou to that which He, to Whom nought clings, hath bid thee cling,","Cling to that bond, to get thee free from every clinging thing"],"s":"Desire the desire of Him who is without desire; in order to renounce desire, desire that desire","ch":35,"sec":1,"th":"calm"},
  {"n":351,"ta":["பொருளல்ல வற்றைப் பொருளென்று உணரும்","மருளானாம் மாணாப் பிறப்பு"],"tr":["Porulalla Vatraip Porulendru Unarum","Marulaanaam Maanaap Pirappu"],"en":["Of things devoid of truth as real things men deem;","Cause of degraded birth the fond delusive dream"],"s":"Inglorious births are produced by the confusion  (of mind) which considers those things to be real which are not real","ch":36,"sec":1,"th":"wisdom"},
  {"n":352,"ta":["இருள்நீங்கி இன்பம் பயக்கும் மருள்நீங்கி","மாசறு காட்சி யவர்க்கு"],"tr":["Irulneengi Inpam Payakkum Marulneengi","Maasaru Kaatchi Yavarkku"],"en":["Darkness departs, and rapture springs to men who see,","The mystic vision pure, from all delusion free"],"s":"A clear, undimmed vision of things will deliver its possessors from the darkness of future births, and confer the felicity  (of heaven)","ch":36,"sec":1,"th":"wisdom"},
  {"n":353,"ta":["ஐயத்தின் நீங்கித் தெளிந்தார்க்கு வையத்தின்","வானம் நணிய துடைத்து"],"tr":["Aiyaththin Neengith Thelindhaarkku Vaiyaththin","Vaanam Naniya Thutaiththu"],"en":["When doubts disperse, and mists of error roll","Away, nearer is heav'n than earth to sage's soul"],"s":"Heaven is nearer than earth to those men of purified minds who are freed from from doubt","ch":36,"sec":1,"th":"wisdom"},
  {"n":354,"ta":["ஐயுணர்வு எய்தியக் கண்ணும் பயமின்றே","மெய்யுணர்வு இல்லா தவர்க்கு"],"tr":["Aiyunarvu Eydhiyak Kannum Payamindre","Meyyunarvu Illaa Thavarkku"],"en":["Five-fold perception gained, what benefits accrue","To them whose spirits lack perception of the true"],"s":"Even those who have all the knowledge which can be attained by the five senses, will derive no benefit from it, if they are without a knowledge of the true nature of things","ch":36,"sec":1,"th":"wisdom"},
  {"n":355,"ta":["எப்பொருள் எத்தன்மைத் தாயினும் அப்பொருள்","மெய்ப்பொருள் காண்பது அறிவு"],"tr":["Epporul Eththanmaith Thaayinum Apporul","Meypporul Kaanpadhu Arivu"],"en":["Whatever thing, of whatsoever kind it be,","'Tis wisdom's part in each the very thing to see"],"s":"(True) knowledge is the perception concerning every thing of whatever kind, that that thing is the true thing","ch":36,"sec":1,"th":"wisdom"},
  {"n":356,"ta":["கற்றீண்டு மெய்ப்பொருள் கண்டார் தலைப்படுவர்","மற்றீண்டு வாரா நெறி"],"tr":["Katreentu Meypporul Kantaar Thalaippatuvar","Matreentu Vaaraa Neri"],"en":["Who learn, and here the knowledge of the true obtain,","Shall find the path that hither cometh not again"],"s":"They, who in this birth have learned to know the True Being, enter the road which returns not into this world","ch":36,"sec":1,"th":"wisdom"},
  {"n":357,"ta":["ஓர்த்துள்ளம் உள்ளது உணரின் ஒருதலையாப்","பேர்த்துள்ள வேண்டா பிறப்பு"],"tr":["Orththullam Ulladhu Unarin Orudhalaiyaap","Perththulla Ventaa Pirappu"],"en":["The mind that knows with certitude what is, and ponders well,","Its thoughts on birth again to other life need not to dwell"],"s":"Let it not be thought that there is another birth for him whose mind having thoroughly considered  (all it has been taught) has known the True Being","ch":36,"sec":1,"th":"wisdom"},
  {"n":358,"ta":["பிறப்பென்னும் பேதைமை நீங்கச் சிறப்பென்னும்","செம்பொருள் காண்பது அறிவு"],"tr":["Pirappennum Pedhaimai Neengach Chirappennum","Semporul Kaanpadhu Arivu"],"en":["When folly, cause of births, departs; and soul can view","The truth of things, man's dignity- 'tis wisdom true"],"s":"True knowledge consists in the removal of ignorance; which is  (the cause of) births, and the perception of the True Being who is  (the bestower of) heaven","ch":36,"sec":1,"th":"wisdom"},
  {"n":359,"ta":["சார்புணர்ந்து சார்பு கெடஒழுகின் மற்றழித்துச்","சார்தரா சார்தரு நோய்"],"tr":["Saarpunarndhu Saarpu Ketaozhukin Matrazhiththuch","Chaardharaa Saardharu Noi"],"en":["The true 'support' who knows- rejects 'supports' he sought before-Sorrow that clings all destroys,","shall cling to him no more"],"s":"He who so lives as to know Him who is the support of all things and abandon all desire, will be freed from the evils which would otherwise cleave to him and destroy  (his efforts after absorption)","ch":36,"sec":1,"th":"wisdom"},
  {"n":360,"ta":["காமம் வெகுளி மயக்கம் இவ்மூன்றன்","நாமம் கெடக்கெடும் நோய்"],"tr":["Kaamam Vekuli Mayakkam Ivaimundran","Naamam Ketakketum Noi"],"en":["When lust and wrath and error's triple tyranny is o'er,","Their very names for aye extinct, then pain shall be no more"],"s":"If the very names of these three things, desire, anger, and confusion of mind, be destroyed, then will also perish evils  (which flow from them)","ch":36,"sec":1,"th":"wisdom"},
  {"n":361,"ta":["அவாஎன்ப எல்லா உயிர்க்கும் எஞ்ஞான்றும்","தவாஅப் பிறப்பீனும் வித்து"],"tr":["Avaaenpa Ellaa Uyirkkum Enj","Gnaandrum Thavaaap Pirappeenum Viththu"],"en":["The wise declare, through all the days, to every living thing","That ceaseless round of birth from seed of strong desire doth spring"],"s":"(The wise) say that the seed, which produces unceasing births, at all times, to all creatures, is desire","ch":37,"sec":1,"th":"calm"},
  {"n":362,"ta":["வேண்டுங்கால் வேண்டும் பிறவாமை மற்றது","வேண்டாமை வேண்ட வரும்"],"tr":["Ventungaal Ventum Piravaamai Matradhu","Ventaamai Venta Varum"],"en":["If desire you feel, freedom from changing birth require!","'I' will come, if you desire to 'scape, set free from all desire"],"s":"If anything be desired, freedom from births should be desired; that  (freedom from births) will be attained by desiring to be without desire","ch":37,"sec":1,"th":"calm"},
  {"n":363,"ta":["வேண்டாமை அன்ன விழுச்செல்வம் ஈண்டில்லை","ஆண்டும் அஃதொப்பது இல"],"tr":["Ventaamai Anna Vizhuselvam Eentillai","Aantum Aqdhoppadhu Il"],"en":["No glorious wealth is here like freedom from desire;","To bliss like this not even there can soul aspire"],"s":"The greatest wealth in this world is to want nothing. Nothing in any world is better than that.","ch":37,"sec":1,"th":"calm"},
  {"n":364,"ta":["தூஉய்மை என்பது அவாவின்மை மற்றது","வாஅய்மை வேண்ட வரும்"],"tr":["Thoouymai Enpadhu Avaavinmai Matradhu","Vaaaimai Venta Varum"],"en":["Desire's decease as purity men know;","That, too, from yearning search for truth will grow"],"s":"Purity  (of mind) consists in freedom from desire; and that  (freedom from desire) is the fruit of the love of truth","ch":37,"sec":1,"th":"calm"},
  {"n":365,"ta":["அற்றவர் என்பார் அவாஅற்றார் மற்றையார்","அற்றாக அற்றது இலர்"],"tr":["Atravar Enpaar Avaaatraar Matraiyaar","Atraaka Atradhu Ilar"],"en":["Men freed from bonds of strong desire are free;","None other share such perfect liberty"],"s":"They are said to be free  (from future birth) who are freed from desire; all others  (who, whatever else they may be free from, are not freed from desire) are not thus free","ch":37,"sec":1,"th":"calm"},
  {"n":366,"ta":["அஞ்சுவ தோரும் அறனே ஒருவனை","வஞ்சிப்ப தோரும் அவா"],"tr":["Anjuva Thorum Arane Oruvanai","Vanjippa Thorum Avaa"],"en":["Desire each soul beguiles;","True virtue dreads its wiles"],"s":"It is the chief duty of  (an ascetic) to watch against desire with  (jealous) fear; for it has power to deceive  (and destroy) him","ch":37,"sec":1,"th":"calm"},
  {"n":367,"ta":["அவாவினை ஆற்ற அறுப்பின் தவாவினை","தான்வேண்டு மாற்றான் வரும்"],"tr":["Avaavinai Aatra Aruppin Thavaavinai","Thaanventu Maatraan Varum"],"en":["Who thoroughly rids his life of passion-prompted deed,","Deeds of unfailing worth shall do, which, as he plans, succeed"],"s":"If a man thoroughly cut off all desire, the deeds, which confer immortality, will come to him, in the path in which he seeks them","ch":37,"sec":1,"th":"calm"},
  {"n":368,"ta":["அவாஇல்லார்க்கு கில்லாகுந் துன்பம் அஃதுண்டே","தவாஅது மேன்மேல் வரும்"],"tr":["Avaaillaarkku Killaagum Thunbam Aqdhuonte","Thavaadhu Menmel Varum"],"en":["Affliction is not known where no desires abide;","Where these are, endless rises sorrow’s tide"],"s":"Where there is no craving, there is no sorrow. Where craving stays, sorrow keeps growing.","ch":37,"sec":1,"th":"calm"},
  {"n":369,"ta":["இன்பம் இடையறா தீண்டும் அவாவென்னும்","துன்பத்துள் துன்பங் கெடின்"],"tr":["Inpam Itaiyaraa Theentum Avaavennum","Thunpaththul Thunpang Ketin"],"en":["When dies away desire, that woe of woes","Ev'n here the soul unceasing rapture knows"],"s":"Even while in this body, joy will never depart  (from the mind, in which) desire, that sorrow of sorrows, has been destroyed","ch":37,"sec":1,"th":"calm"},
  {"n":370,"ta":["ஆரா இயற்கை அவாநீப்பின் அந்நிலையே","பேரா இயற்கை தரும்"],"tr":["Aaraa Iyarkai Avaaneeppin Annilaiye","Peraa Iyarkai Tharum"],"en":["Drive from thy soul desire insatiate;","Straight'way is gained the moveless blissful state"],"s":"The removal of desire, whose nature it is never to be satisfied, will immediately confer a nature that can never be changed","ch":37,"sec":1,"th":"calm"},
  {"n":371,"ta":["ஆகூழால் தோன்றும் அசைவின்மை கைப்பொருள்","போகூழால் தோன்றும் மடி"],"tr":["Aakoozhaal Thondrum Asaivinmai Kaipporul","Pokoozhaal Thondrum Mati"],"en":["Wealth-giving fate power of unflinching effort brings;","From fate that takes away idle remissness springs"],"s":"Perseverance comes from a prosperous fate, and idleness from an adverse fate","ch":38,"sec":1,"th":"effort"},
  {"n":372,"ta":["பேதைப் படுக்கும் இழவூழ் அறிவகற்றும்","ஆகலூழ் உற்றக் கடை"],"tr":["Pedhaip Patukkum Izhavoozh Arivakatrum","Aakaloozh Utrak Katai"],"en":["The fate that loss ordains makes wise men's wisdom foolishness;","The fate that gain bestows with ampler powers will wisdom bless"],"s":"An adverse fate produces folly, and a prosperous fate produces enlarged knowledge","ch":38,"sec":1,"th":"effort"},
  {"n":373,"ta":["நுண்ணிய நூல்பல கற்பினும் மற்றுந்தன்","உண்மை யறிவே மிகும்"],"tr":["Nunniya Noolpala Karpinum Matrundhan","Unmai Yarive Mikum"],"en":["In subtle learning manifold though versed man be,","'The wisdom, truly his, will gain supremacy"],"s":"Although  (a man) may study the most polished treatises, the knowledge which fate has decreed to him will still prevail","ch":38,"sec":1,"th":"effort"},
  {"n":374,"ta":["இருவேறு உலகத்து இயற்கை திருவேறு","தெள்ளிய ராதலும் வேறு"],"tr":["Iruveru Ulakaththu Iyarkai Thiruveru","Thelliya Raadhalum Veru"],"en":["Two fold the fashion of the world: some live in fortune's light;","While other some have souls in wisdom's radiance bright"],"s":"There are  (through fate) two different natures in the world, hence the difference  (observable in men) in  (their acquisition of) wealth, and in their attainment of knowledge","ch":38,"sec":1,"th":"effort"},
  {"n":375,"ta":["நல்லவை எல்லாஅந் தீயவாம் தீயவும்","நல்லவாம் செல்வம் செயற்கு"],"tr":["Nallavai Ellaaan Theeyavaam Theeyavum","Nallavaam Selvam Seyarku"],"en":["All things that good appear will oft have ill success;","All evil things prove good for gain of happiness"],"s":"In the acquisition of property, every thing favourable becomes unfavourable, and  (on the other hand) everything unfavourable becomes favourable,  (through the power of fate)","ch":38,"sec":1,"th":"effort"},
  {"n":376,"ta":["பரியினும் ஆகாவாம் பாலல்ல உய்த்துச்","சொரியினும் போகா தம"],"tr":["Pariyinum Aakaavaam Paalalla Uyththuch","Choriyinum Pokaa Thama"],"en":["Things not your own will yield no good, howe'er you guard with pain;","Your own, howe'er you scatter them abroad, will yours remain"],"s":"Whatever is not conferred by fate cannot be preserved although it be guarded with most painful care; and that, which fate has made his, cannot be lost, although one should even take it and throw it away","ch":38,"sec":1,"th":"effort"},
  {"n":377,"ta":["வகுத்தான் வகுத்த வகையல்லால் கோடி","தொகுத்தார்க்கு துய்த்தல் அரிது"],"tr":["Vakuththaan Vakuththa Vakaiyallaal Koti","Thokuththaarkku Thuyththal Aridhu"],"en":["Save as the 'sharer' shares to each in due degree,","To those who millions store enjoyment scarce can be"],"s":"Even those who gather together millions will only enjoy them, as it has been determined by the disposer  (of all things)","ch":38,"sec":1,"th":"effort"},
  {"n":378,"ta":["துறப்பார்மன் துப்புர வில்லார் உறற்பால","ஊட்டா கழியு மெனின்"],"tr":["Thurappaarman Thuppura Villaar Urarpaala","Oottaa Kazhiyu Menin"],"en":["The destitute with ascetics merit share,","If fate to visit with predestined ills would spare"],"s":"The destitute will renounce desire  (and become ascetics), if  (fate) do not make them suffer the hindrances to which they are liable, and they pass away","ch":38,"sec":1,"th":"effort"},
  {"n":379,"ta":["நன்றாங்கால் நல்லவாக் காண்பவர் அன்றாங்கால்","அல்லற் படுவதெவன்"],"tr":["Nandraangal Nallavaak Kaanpavar Andraangal","Allal Paduvadhevan"],"en":["When good things come, men view them all as gain;","When evils come, why then should they complain"],"s":"When good things come, people call it fortune. When hard times come, why blame fortune?","ch":38,"sec":1,"th":"effort"},
  {"n":380,"ta":["ஊழிற் பெருவலி யாவுள மற்றொன்று","சூழினுந் தான்முந் துறும்"],"tr":["Oozhir Peruvali Yaavula Matrondru","Soozhinun Thaanmun Thurum"],"en":["What powers so great as those of Destiny? Man's skill","Some other thing contrives; but fate's beforehand still"],"s":"What is stronger than fate? If we think of an expedient  (to avert it), it will itself be with us before  (the thought)","ch":38,"sec":1,"th":"effort"},
  {"n":381,"ta":["படைகுடி கூழ்அமைச்சு நட்பரண் ஆறும்","உடையான் அரசருள் ஏறு"],"tr":["Pataikuti Koozhamaichchu Natparan Aarum","Utaiyaan Arasarul Eru"],"en":["An army, people, wealth, a minister, friends, fort:","six things-Who owns them all, a lion lives amid the kings"],"s":"He who possesses these six things, an army, a people, wealth, ministers, friends and a fortress, is a lion among kings","ch":39,"sec":2,"th":"governance"},
  {"n":382,"ta":["அஞ்சாமை ஈகை அறிவூக்கம் இந்நான்கும்","எஞ்சாமை வேந்தர்க் கியல்பு"],"tr":["Anjaamai Eekai Arivookkam Innaankum","Enjaamai Vendhark Kiyalpu"],"en":["Courage, a liberal hand, wisdom, and energy: these four","Are qualities a king adorn for evermore"],"s":"Never to fail in these four things, fearlessness, liberality, wisdom, and energy, is the kingly character","ch":39,"sec":2,"th":"governance"},
  {"n":383,"ta":["தூங்காமை கல்வி துணிவுடைமை இம்மூன்றும்","நீங்கா நிலனான் பவர்க்கு"],"tr":["Thoongaamai Kalvi Thunivutaimai Immoondrum","Neengaa Nilanaan Pavarkku"],"en":["A sleepless promptitude, knowledge, decision strong:","These three for aye to rulers of the land belong"],"s":"These three things, viz, vigilance, learning, and bravery, should never be wanting in the ruler of a country","ch":39,"sec":2,"th":"governance"},
  {"n":384,"ta":["அறனிழுக்கா தல்லவை நீக்கி மறனிழுக்கா","மானம் உடைய தரசு"],"tr":["Aranizhukkaa Thallavai Neekki Maranizhukkaa","Maanam Utaiya Tharasu"],"en":["Kingship, in virtue failing not, all vice restrains,","In courage failing not, it honour's grace maintains"],"s":"He is a king who, with manly modesty, swerves not from virtue, and refrains from vice","ch":39,"sec":2,"th":"governance"},
  {"n":385,"ta":["இயற்றலும் ஈட்டலுங் காத்தலும் காத்த","வகுத்தலும் வல்ல தரசு"],"tr":["Iyatralum Eettalung Kaaththalum Kaaththa","Vakuththalum Valla Tharasu"],"en":["A king is he who treasure gains, stores up, defends,","And duly for his kingdom's weal expends"],"s":"He is a king who is able to acquire  (wealth), to lay it up, to guard, and to distribute it","ch":39,"sec":2,"th":"governance"},
  {"n":386,"ta":["காட்சிக் கெளியன் கடுஞ்சொல்லன் அல்லனேல்","மீக்கூறும் மன்னன் நிலம்"],"tr":["Kaatchik Keliyan Katunjollan Allanel","Meekkoorum Mannan Nilam"],"en":["Where king is easy of access, where no harsh word repels,","That land's high praises every subject swells"],"s":"The whole world will exalt the country of the king who is easy of access, and who is free from harsh language","ch":39,"sec":2,"th":"governance"},
  {"n":387,"ta":["இன்சொலால் ஈத்தளிக்க வல்லார்க்குத் தன்சொலால்","தான்கண் டனைத்திவ் வுலகு"],"tr":["Insolaal Eeththalikka Vallaarkkuth Thansolaal","Thaankan Tanaiththiv Vulaku"],"en":["With pleasant speech, who gives and guards with powerful liberal hand,","He sees the world obedient all to his command"],"s":"The world will praise and submit itself to the mind of the king who is able to give with affability, and to protect all who come to him","ch":39,"sec":2,"th":"governance"},
  {"n":388,"ta":["முறைசெய்து காப்பாற்றும் மன்னவன் மக்கட்கு","இறையென்று வைக்கப் படும்"],"tr":["Muraiseydhu Kaappaatrum Mannavan Makkatku","Iraiyendru Vaikkap Patum"],"en":["Who guards the realm and justice strict maintains,","That king as god o'er subject people reigns"],"s":"That king, will be esteemed a God among men, who performs his own duties, and protects  (his subjects).","ch":39,"sec":2,"th":"governance"},
  {"n":389,"ta":["செவிகைப்பச் சொற்பொறுக்கும் பண்புடை வேந்தன்","கவிகைக்கீழ்த் தங்கும் உலகு"],"tr":["Sevikaippach Chorporukkum Panputai Vendhan","Kavikaikkeezhth Thangum Ulaku"],"en":["The king of worth, who can words bitter to his ear endure,","Beneath the shadow of his power the world abides secure"],"s":"The whole world will dwell under the umbrella of the king, who can bear words that embitter the ear","ch":39,"sec":2,"th":"governance"},
  {"n":390,"ta":["கொடையளி செங்கோல் குடியோம்பல் நான்கும்","உடையானாம் வேந்தர்க் கொளி"],"tr":["Kotaiyali Sengol Kutiyompal Naankum","Utaiyaanaam Vendhark Koli"],"en":["Gifts, grace, right sceptre, care of people's weal;","These four a light of dreaded kings reveal"],"s":"He is the light of kings who has there four things, beneficence, benevolence, rectitude, and care for his people","ch":39,"sec":2,"th":"governance"},
  {"n":391,"ta":["கற்க கசடறக் கற்பவை கற்றபின்","நிற்க அதற்குத் தக"],"tr":["Karka Kasatarak Karpavai Katrapin","Nirka Adharkuth Thaka"],"en":["So learn that you may full and faultless learning gain,","Then in obedience meet to lessons learnt remain"],"s":"Let a man learn thoroughly whatever he may learn, and let his conduct be worthy of his learning","ch":40,"sec":2,"th":"learning"},
  {"n":392,"ta":["எண்ணென்ப ஏனை எழுத்தென்ப இவ்விரண்டும்","கண்ணென்ப வாழும் உயிர்க்கு"],"tr":["Ennenpa Anai Ezhuthenpa Ivvirandrum","Kannenpa Vaazhum Uyirku"],"en":["The twain that lore of numbers and of letters give","Are eyes, the wise declare, to all on earth that live"],"s":"Numbers and letters together are like eyes for people. Learning opens your sight.","ch":40,"sec":2,"th":"learning"},
  {"n":393,"ta":["கண்ணுடையர் என்பவர் கற்றோர் முகத்திரண்டு","புண்ணுடையர் கல்லா தவர்"],"tr":["Kannutaiyar Enpavar Katror Mukaththirantu","Punnutaiyar Kallaa Thavar"],"en":["Men who learning gain have eyes, men say;","Blockheads' faces pairs of sores display"],"s":"The learned are said to have eyes, but the unlearned have  (merely) two sores in their face","ch":40,"sec":2,"th":"learning"},
  {"n":394,"ta":["உவப்பத் தலைக்கூடி உள்ளப் பிரிதல்","அனைத்தே புலவர் தொழில்"],"tr":["Uvappath Thalaikkooti Ullap Piridhal","Anaiththe Pulavar Thozhil"],"en":["You meet with joy, with pleasant thought you part;","Such is the learned scholar's wonderous art"],"s":"It is the part of the learned to give joy to those whom they meet, and on leaving, to make them think  (Oh! when shall we meet them again.)","ch":40,"sec":2,"th":"learning"},
  {"n":395,"ta":["உடையார்முன் இல்லார்போல் ஏக்கற்றுங் கற்றார்","கடையரே கல்லா தவர்"],"tr":["Utaiyaarmun Illaarpol Ekkatrung Katraar","Kataiyare Kallaa Thavar"],"en":["With soul submiss they stand, as paupers front a rich man's face;","Yet learned men are first; th'unlearned stand in lowest place"],"s":"The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy","ch":40,"sec":2,"th":"learning"},
  {"n":396,"ta":["தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக்","கற்றனைத் தூறும் அறிவு"],"tr":["Thottanaith Thoendum Manarkeni Maantharkkuk","Katranai Thoendum Arivu"],"en":["In sandy soil, when deep you delve, you reach the springs below;","The more you learn, the freer streams of wisdom flow"],"s":"Dig deep in sand and water springs up. The more you learn, the more wisdom flows.","ch":40,"sec":2,"th":"learning"},
  {"n":397,"ta":["யாதானும் நாடாமால் ஊராமால் என்னொருவன்","சாந்துணையுங் கல்லாத வாறு"],"tr":["Yaadhaanum Naataamaal Ooraamaal Ennoruvan","Saandhunaiyung Kallaadha Vaaru"],"en":["The learned make each land their own, in every city find a home;","Who, till they die; learn nought, along what weary ways they roam"],"s":"How is it that any one can remain without learning, even to his death, when  (to the learned man) every country is his own  (country), and every town his own  (town)?","ch":40,"sec":2,"th":"learning"},
  {"n":398,"ta":["ஒருமைக்கண் தான்கற்ற கல்வி ஒருவற்கு","எழுமையும் ஏமாப் புடைத்து"],"tr":["Orumaikkan Thaan Katra Kalvi","Oruvarku Ezhumaiyum Emaap Putaiththu"],"en":["The man who store of learning gains,","In one, through seven worlds, bliss attains"],"s":"The learning, which a man has acquired in one birth, will yield him pleasure during seven births","ch":40,"sec":2,"th":"learning"},
  {"n":399,"ta":["தாமின் புறுவது உலகின் புறக்கண்டு","காமுறுவர் கற்றறிந் தார்"],"tr":["Thaamin Puruvadhu Ulakin Purak","Kantu Kaamuruvar Katrarin Thaar"],"en":["Their joy is joy of all the world, they see; thus more","The learners learn to love their cherished lore"],"s":"The learned will long  (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it","ch":40,"sec":2,"th":"learning"},
  {"n":400,"ta":["கேடில் விழுச்செல்வம் கல்வி யொருவற்கு","மாடல்ல மற்றை யவை"],"tr":["Ketil Vizhuchchelvam Kalvi Yoruvarku","Maatalla Matrai Yavai"],"en":["Learning is excellence of wealth that none destroy;","To man nought else affords reality of joy"],"s":"Learning is the true imperishable riches; all other things are not riches","ch":40,"sec":2,"th":"learning"},
  {"n":401,"ta":["அரங்கின்றி வட்டாடி யற்றே நிரம்பிய","நூலின்றிக் கோட்டி கொளல்"],"tr":["Arangindri Vattaati Yatre Nirampiya","Noolindrik Kotti Kolal"],"en":["Like those at draughts would play without the chequered square,","Men void of ample lore would counsels of the learned share"],"s":"To speak in an assembly  (of the learned) without fullness of knowledge, is like playing at chess  (on a board) without squares","ch":41,"sec":2,"th":"learning"},
  {"n":402,"ta":["கல்லாதான் சொற்கா முறுதல் முலையிரண்டும்","இல்லாதாள் பெண்காமுற் றற்று"],"tr":["Kallaadhaan Sorkaa Murudhal Mulaiyirantum","Illaadhaal Penkaamur Ratru"],"en":["Like those who doat on hoyden's undeveloped charms are they,","Of learning void, who eagerly their power of words display"],"s":"The desire of the unlearned to speak  (in an assembly), is like a woman without breasts desiring  (the enjoyment of ) woman-hood","ch":41,"sec":2,"th":"learning"},
  {"n":403,"ta":["கல்லா தவரும் நனிநல்லர் கற்றார்முன்","சொல்லா திருக்கப் பெறின்"],"tr":["Kallaa Thavarum Naninallar Katraarmun","Sollaa Thirukkap Perin"],"en":["The blockheads, too, may men of worth appear,","If they can keep from speaking where the learned hear"],"s":"The unlearned also are very excellent men, if they know how to keep silence before the learned","ch":41,"sec":2,"th":"learning"},
  {"n":404,"ta":["கல்லாதான் ஒட்பம் கழியநன் றாயினும்","கொள்ளார் அறிவுடை யார்"],"tr":["Kallaadhaan Otpam Kazhiyanan Raayinum","Kollaar Arivutai Yaar"],"en":["From blockheads' lips, when words of wisdom glibly flow,","The wise receive them not, though good they seem to show"],"s":"Although the natural knowledge of an unlearned man may be very good, the wise will not accept for true knowledge","ch":41,"sec":2,"th":"learning"},
  {"n":405,"ta":["கல்லா ஒருவன் தகைமை தலைப்பெய்து","சொல்லாடச் சோர்வு படும்"],"tr":["Kallaa Oruvan Thakaimai Thalaippeydhu","Sollaatach Chorvu Patum"],"en":["As worthless shows the worth of man unlearned,","When council meets, by words he speaks discerned"],"s":"The self-conceit of an unlearned man will fade away, as soon as he speaks in an assembly  (of","ch":41,"sec":2,"th":"learning"},
  {"n":406,"ta":["உளரென்னும் மாத்திரையர் அல்லால் பயவாக்","களரனையர் கல்லா தவர்"],"tr":["Ularennum Maaththiraiyar Allaal Payavaak","Kalaranaiyar Kallaa Thavar"],"en":["'They are': so much is true of men untaught;","But, like a barren field, they yield us nought"],"s":"The unlearned are like worthless barren land: all that can be said of them is, that they exist","ch":41,"sec":2,"th":"learning"},
  {"n":407,"ta":["நுண்மாண் நுழைபுலம் இல்லான் எழில்நலம்","மண்மாண் புனைபாவை யற்று"],"tr":["Nunmaan Nuzhaipulam Illaan Ezhilnalam","Manmaan Punaipaavai Yatru"],"en":["Who lack the power of subtle, large, and penetrating sense,","Like puppet, decked with ornaments of clay, their beauty's vain pretence"],"s":"The beauty and goodness of one who is destitute of knowledge by the study of great and exquisite works, is like  (the beauty and goodness) of a painted earthen doll","ch":41,"sec":2,"th":"learning"},
  {"n":408,"ta":["நல்லார்கண் பட்ட வறுமையின் இன்னாதே","கல்லார்கண் பட் ட திரு"],"tr":["Nallaarkan Patta Varumaiyin Innaadhe","Kallaarkan Patta Thiru"],"en":["To men unlearned, from fortune's favour greater-evil springs","Than poverty to men of goodly wisdom brings"],"s":"Wealth, gained by the unlearned, will give more sorrow than the poverty which may come upon the learned","ch":41,"sec":2,"th":"learning"},
  {"n":409,"ta":["மேற்பிறந்தா ராயினும் கல்லாதார் கீழ்ப்பிறந்தும்","கற்றார் அனைத்திலர் பாடு"],"tr":["Merpirandhaa Raayinum Kallaadhaar Keezhppirandhum","Katraar Anaiththilar Paatu"],"en":["Lower are men unlearned, though noble be their race,","Than low-born men adorned with learning's grace"],"s":"The unlearned, though born in a high caste, are not equal in dignity to the learned; though they may have been born in a low caste","ch":41,"sec":2,"th":"learning"},
  {"n":410,"ta":["விலங்கொடு மக்கள் அனையர் இலங்குநூல்","கற்றாரோடு ஏனை யவர்"],"tr":["Vilangotu Makkal Anaiyar Ilangunool","Katraarotu Enai Yavar"],"en":["Learning's irradiating grace who gain,","Others excel, as men the bestial train"],"s":"As beasts by the side of men, so are other men by the side of those who are learned in celebrated works","ch":41,"sec":2,"th":"learning"},
  {"n":411,"ta":["செல்வத்துட் செல்வஞ் செவிச்செல்வம் அச்செல்வம்","செல்வத்து ளெல்லாந் தலை"],"tr":["Selvaththut Selvanj Chevichchelvam Achchelvam","Selvaththu Lellaan Thalai"],"en":["Wealth of wealth is wealth acquired be ear attent;","Wealth mid all wealth supremely excellent"],"s":"Wealth  (gained) by the ear is wealth of wealth; that wealth is the chief of all wealth","ch":42,"sec":2,"th":"learning"},
  {"n":412,"ta":["செவுக்குண வில்லாத போழ்து சிறிது","வயிற்றுக்கும் ஈயப் படும்"],"tr":["Sevikkuna Villaadha Pozhdhu Siridhu","Vayitrukkum Eeyap Patum"],"en":["When 'tis no longer time the listening ear to feed","With trifling dole of food supply the body's need"],"s":"When there is no food for the ear, give a little also to the stomach","ch":42,"sec":2,"th":"learning"},
  {"n":413,"ta":["செவியுணவிற் கேள்வி யுடையார் அவியுணவின்","ஆன்றாரோ டொப்பர் நிலத்து"],"tr":["Seviyunavir Kelvi Yutaiyaar Aviyunavin","Aandraaro Toppar Nilaththu"],"en":["Who feed their ear with learned teachings rare,","Are like the happy gods oblations rich who share"],"s":"Those who in this world enjoy instruction which is the food of the ear, are equal to the Gods, who enjoy the food of the sacrifices","ch":42,"sec":2,"th":"learning"},
  {"n":414,"ta":["கற்றில னாயினுங் கேட்க அஃதொருவற்கு","ஒற்கத்தின் ஊற்றாந் துணை"],"tr":["Katrila Naayinung Ketka Aqdhoruvarku","Orkaththin Ootraan Thunai"],"en":["Though learning none hath he, yet let him hear alway:","In weakness this shall prove a staff and stay"],"s":"Although a man be without learning, let him listen  (to the teaching of the learned); that will be to him a staff in adversity","ch":42,"sec":2,"th":"learning"},
  {"n":415,"ta":["இழுக்கல் உடையுழி ஊற்றுக்கோல் அற்றே","ஒழுக்க முடையார்வாய்ச் சொல்"],"tr":["Izhukkal Utaiyuzhi Ootrukkol Atre","Ozhukka Mutaiyaarvaaich Chol"],"en":["Like staff in hand of him in slippery ground who strays","Are words from mouth of those who walk in righteous ways"],"s":"The words of the good are like a staff in a slippery place","ch":42,"sec":2,"th":"learning"},
  {"n":416,"ta":["எனைத்தானும் நல்லவை கேட்க அனைத்தானும்","ஆன்ற பெருமை தரும்"],"tr":["Enaiththaanum Nallavai Ketka Anaiththaanum","Aandra Perumai Tharum"],"en":["Let each man good things learn, for e'en as he","Shall learn, he gains increase of perfect dignity"],"s":"Let a man listen, never so little, to good  (instruction), even that will bring him great dignity","ch":42,"sec":2,"th":"learning"},
  {"n":417,"ta":["பிழைத்துணர்ந்தும் பேதைமை சொல்லா ரிழைத்துணர்ந்","தீண்டிய கேள்வி யவர்"],"tr":["Pizhaith Thunarndhum Pedhaimai Sollaa","Rizhaiththunarn Theentiya Kelvi Yavar"],"en":["Not e'en through inadvertence speak they foolish word,","With clear discerning mind who've learning's ample lessons heard"],"s":"Not even when they have imperfectly understood  (a matter), will those men speak foolishly, who have profoundly studied and diligently listened  (to instruction)","ch":42,"sec":2,"th":"learning"},
  {"n":418,"ta":["கேட்பினுங் கேளாத் தகையவே கேள்வியால்","தோட்கப் படாத செவி"],"tr":["Ketpinung Kelaath Thakaiyave Kelviyaal","Thotkap Pataadha Sevi"],"en":["Where teaching hath not oped the learner's ear,","The man may listen, but he scarce can hear"],"s":"The ear which has not been bored by instruction, although it hears, is deaf","ch":42,"sec":2,"th":"learning"},
  {"n":419,"ta":["நுணங்கிய கேள்விய ரல்லார் வணங்கிய","வாயின ராதல் அரிது"],"tr":["Nunangiya Kelviya Rallaar Vanangiya","Vaayina Raadhal Aridhu"],"en":["'Tis hard for mouth to utter gentle, modest word,","When ears discourse of lore refined have never heard"],"s":"It is a rare thing to find modesty, a reverend mouth- with those who have not received choice instruction","ch":42,"sec":2,"th":"learning"},
  {"n":420,"ta":["செவியிற் சுவையுணரா வாயுணர்வின் மாக்கள்","அவியினும் வாழினும் என்?"],"tr":["Seviyir Suvaiyunaraa Vaayunarvin Maakkal","Aviyinum Vaazhinum En?"],"en":["His mouth can taste, but ear no taste of joy can give!","What matter if he die, or prosperous live"],"s":"What does it matter whether those men live or die, who can judge of tastes by the mouth, and not by the ear?","ch":42,"sec":2,"th":"learning"},
  {"n":421,"ta":["அறிவற்றங் காக்குங் கருவி செறுவார்க்கும்","உள்ளழிக்க லாகா அரண்"],"tr":["Arivatrang Kaakkung Karuvi Seruvaarkkum","Ullazhikka Laakaa Aran"],"en":["True wisdom wards off woes, A circling fortress high;","Its inner strength man's eager foes Unshaken will defy"],"s":"Wisdom is a weapon to ward off destruction; it is an inner fortress which enemies cannot destroy","ch":43,"sec":2,"th":"learning"},
  {"n":422,"ta":["சென்ற இடத்தால் செலவிடா தீதொரீஇ","நன்றின்பால் உய்ப்ப தறிவு"],"tr":["Sendra Itaththaal Selavitaa Theedhoreei","Nandrinpaal Uyppa Tharivu"],"en":["Wisdom restrains, nor suffers mind to wander where it would;","From every evil calls it back, and guides in way of good"],"s":"Not to permit the mind to go where it lists, to keep it from evil, and to employ it in good, this is wisdom","ch":43,"sec":2,"th":"learning"},
  {"n":423,"ta":["எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள்","மெய்ப்பொருள் காண்ப தறிவு"],"tr":["Epporul Yaaryaarvaaik Ketpinum Apporul","Meypporul Kaanpa Tharivu"],"en":["Though things diverse from divers sages' lips we learn,","'Tis wisdom's part in each the true thing to discern"],"s":"To discern the truth in every thing, by whomsoever spoken, is wisdom","ch":43,"sec":2,"th":"learning"},
  {"n":424,"ta":["எண்பொருள வாகச் செலச்சொல்லித் தான்பிறர்வாய்","நுண்பொருள் காண்ப தறிவு"],"tr":["Enporula Vaakach Chelachchollith Thaanpirarvaai","Nunporul Kaanpa Tharivu"],"en":["Wisdom hath use of lucid speech, words that acceptance win,","And subtle sense of other men's discourse takes in"],"s":"To speak so as that the meaning may easily enter the mind of the hearer, and to discern the subtlest thought which may lie hidden in the words of others, this is wisdom","ch":43,"sec":2,"th":"learning"},
  {"n":425,"ta":["உலகம் தழீஇய தொட்பம் மலர்தலும்","கூம்பலும் இல்ல தறிவு"],"tr":["Ulakam Thazheeiya Thotpam Malardhalum","Koompalum Illa Tharivu"],"en":["Wisdom embraces frank the world, to no caprice exposed;","Unlike the lotus flower, now opened wide, now petals strictly closed"],"s":"To secure the friendship of the great is true wisdom; it is  (also) wisdom to keep  (that friendship unchanged, and) not opening and closing  (like the lotus flower)","ch":43,"sec":2,"th":"learning"},
  {"n":426,"ta":["எவ்வ துறைவது உலகம் உலகத்தோடு","அவ்வ துறைவ தறிவு"],"tr":["Evva Thuraivadhu Ulakam Ulakaththotu","Avva Thuraiva Tharivu"],"en":["As dwells the world, so with the world to dwell","In harmony- this is to wisely live and well"],"s":"To live as the world lives, is wisdom","ch":43,"sec":2,"th":"learning"},
  {"n":427,"ta":["அறிவுடையார் ஆவ தறிவார் அறிவிலார்","அஃதறி கல்லா தவர்"],"tr":["Arivutaiyaar Aava Tharivaar Arivilaar","Aqdhari Kallaa Thavar"],"en":["The wise discern, the foolish fail to see,","And minds prepare for things about to be"],"s":"The wise are those who know beforehand what will happen; those who do not know this are the unwise","ch":43,"sec":2,"th":"learning"},
  {"n":428,"ta":["அஞ்சுவ தஞ்சாமை பேதைமை அஞ்சுவது","அஞ்சல் அறிவார் தொழில்"],"tr":["Anjuva Thanjaamai Pedhaimai Anjuvadhu","Anjal Arivaar Thozhil"],"en":["Folly meets fearful ills with fearless heart;","To fear where cause of fear exists is wisdom's part"],"s":"Not to fear what ought to be feared, is folly; it is the work of the wise to fear what should be feared","ch":43,"sec":2,"th":"learning"},
  {"n":429,"ta":["எதிரதாக் காக்கும் அறிவினார்க் கில்லை","அதிர வருவதோர் நோய்"],"tr":["Edhiradhaak Kaakkum Arivinaark Killai","Adhira Varuvadhor Noi"],"en":["The wise with watchful soul who coming ills foresee;","From coming evil's dreaded shock are free"],"s":"No terrifying calamity will happen to the wise, who  (foresee) and guard against coming evils","ch":43,"sec":2,"th":"learning"},
  {"n":430,"ta":["அறிவுடையார் எல்லா முடையார் அறிவிலார்","என்னுடைய ரேனும் இலர்"],"tr":["Arivutaiyaar Ellaa Mutaiyaar Arivilaar","Ennutaiya Renum Ilar"],"en":["The wise is rich, with ev'ry blessing blest;","The fool is poor, of everything possessed"],"s":"Those who possess wisdom, possess every thing; those who have not wisdom, whatever they may possess, have nothing","ch":43,"sec":2,"th":"learning"},
  {"n":431,"ta":["செருக்குஞ் சினமும் சிறுமையும் இல்லார்","பெருக்கம் பெருமித நீர்த்து"],"tr":["Serukkunj Chinamum Sirumaiyum Illaar","Perukkam Perumidha Neerththu"],"en":["Who arrogance, and wrath, and littleness of low desire restrain,","To sure increase of lofty dignity attain"],"s":"Truly great is the excellence of those  (kings) who are free from pride, anger, and lust","ch":44,"sec":2,"th":"wisdom"},
  {"n":432,"ta":["இவறலும் மாண்பிறந்த மானமும் மாணா","உவகையும் ஏதம் இறைக்கு"],"tr":["Ivaralum Maanpirandha Maanamum Maanaa","Uvakaiyum Edham Iraikku"],"en":["A niggard hand, o'erweening self-regard, and mirth","Unseemly, bring disgrace to men of kingly brith"],"s":"Avarice, undignified pride, and low pleasures are faults in a king","ch":44,"sec":2,"th":"wisdom"},
  {"n":433,"ta":["தினைத்துணையாங் குற்றம் வரினும் பனைத்துணையாக்","கொள்வர் பழிநாணு வார்"],"tr":["Thinaiththunaiyaang Kutram Varinum Panaiththunaiyaak","Kolvar Pazhinaanu Vaar"],"en":["Though small as millet-seed the fault men deem;","As palm tree vast to those who fear disgrace 'twill seem"],"s":"Those who fear guilt, if they commit a fault small as a millet seed, will consider it to be as large as a palmyra tree","ch":44,"sec":2,"th":"wisdom"},
  {"n":434,"ta":["குற்றமே காக்க பொருளாகக் குற்றமே","அற்றந் த்ரூஉம் பகை"],"tr":["Kutrame Kaakka Porulaakak Kutrame","Atran Tharooum Pakai"],"en":["Freedom from faults is wealth; watch heedfully","'Gainst these, for fault is fatal enmity"],"s":"Guard against faults as a matter  (of great consequence; for) faults are a deadly enemy","ch":44,"sec":2,"th":"wisdom"},
  {"n":435,"ta":["வருமுன்னர்க் காவாதான் வாழ்க்கை எரிமுன்னர்","வைத்தூறு போலக் கெடும்"],"tr":["Varumunnark Kaavaadhaan Vaazhkkai Erimunnar","Vaiththooru Polak Ketum"],"en":["His joy who guards not 'gainst the coming evil day,","Like straw before the fire shall swift consume away"],"s":"The prosperity of him who does not timely guard against faults, will perish like straw before fire","ch":44,"sec":2,"th":"wisdom"},
  {"n":436,"ta":["தன்குற்றம் நீக்கிப் பிறர்குற்றங் காண்கிற்பின்","என்குற்ற மாகும் இறைக்கு?"],"tr":["Thankutram Neekkip Pirarkutrang Kaankirpin","Enkutra Maakum Iraikku?"],"en":["Faultless the king who first his own faults cures, and then","Permits himself to scan faults of other men"],"s":"What fault will remain in the king who has put away his own evils, and looks after the evils of others","ch":44,"sec":2,"th":"wisdom"},
  {"n":437,"ta":["செயற்பால செய்யா திவறியான் செல்வம்","உயற்பால தன்றிக் கெடும்"],"tr":["Seyarpaala Seyyaa Thivariyaan Selvam","Uyarpaala Thandrik Ketum"],"en":["Who leaves undone what should be done, with niggard mind,","His wealth shall perish, leaving not a wrack behind"],"s":"The wealth of the avaricious man, who does not expend it for the purposes for which he ought to expend it will waste away and not continue","ch":44,"sec":2,"th":"wisdom"},
  {"n":438,"ta":["பற்றுள்ளம் என்னும் இவறன்மை எற்றுள்ளும்","எண்ணப் படுவதொன் றன்று"],"tr":["Patrullam Ennum Ivaranmai Etrullum","Ennap Patuvadhon Randru"],"en":["The greed of soul that avarice men call,","When faults are summed, is worst of all"],"s":"Griping avarice is not to be reckoned as one among other faults;  (it stands alone - greater than all)","ch":44,"sec":2,"th":"wisdom"},
  {"n":439,"ta":["வியவற்க எஞ்ஞான்றும் தன்னை நயவற்க","நன்றி பயவா வினை"],"tr":["Viyavarka Egngnaandrum Thannai Nayavarka","Nandri Payavaa Vinai"],"en":["Never indulge in self-complaisant mood,","Nor deed desire that yields no gain of good"],"s":"Let no  (one) praise himself, at any time; let him not desire to do useless things","ch":44,"sec":2,"th":"wisdom"},
  {"n":440,"ta":["காதல காதல் அறியாமை உய்க்கிற்பின்","ஏதில ஏதிலார் நூல்"],"tr":["Kaadhala Kaadhal Ariyaamai Uykkirpin","Edhila Edhilaar Nool"],"en":["If, to your foes unknown, you cherish what you love,","Counsels of men who wish you harm will harmless prove"],"s":"If  (a king) enjoys, privately the things which he desires, the designs of his enemies will be useless","ch":44,"sec":2,"th":"wisdom"},
  {"n":441,"ta":["அறனறிந்து மூத்த அறிவுடையார் கேண்மை","திறனறிந்து தேர்ந்து கொளல்"],"tr":["Aranarindhu Mooththa Arivutaiyaar Kenmai","Thiranarindhu Therndhu Kolal"],"en":["As friends the men who virtue know, and riper wisdom share,","Their worth weighed well, the king should choose with care"],"s":"Let  (a king) ponder well its value, and secure the friendship of men of virtue and of mature knowledge","ch":45,"sec":2,"th":"governance"},
  {"n":442,"ta":["உற்றநோய் நீக்கி உறாஅமை முற்காக்கும்","பெற்றியார்ப் பேணிக் கொளல்"],"tr":["Utranoi Neekki Uraaamai Murkaakkum","Petriyaarp Penik Kolal"],"en":["Cherish the all-accomplished men as friends,","Whose skill the present ill removes, from coming ill defends"],"s":"Let  (a king) procure and kindly care for men who can overcome difficulties when they occur, and guard against them before they happen","ch":45,"sec":2,"th":"governance"},
  {"n":443,"ta":["அரியவற்று ளெல்லாம் அரிதே பெரியாரைப்","பேணித் தமராக் கொளல்"],"tr":["Ariyavatru Lellaam Aridhe Periyaaraip","Penith Thamaraak Kolal"],"en":["To cherish men of mighty soul, and make them all their own,","Of kingly treasures rare, as rarest gift is known"],"s":"To cherish great men and make them his own, is the most difficult of all difficult things","ch":45,"sec":2,"th":"governance"},
  {"n":444,"ta":["தம்மிற் பெரியார் தமரா ஒழுகுதல்","வன்மையு ளெல்லாந் தலை"],"tr":["Thammir Periyaar Thamaraa Ozhukudhal","Vanmaiyu Lellaan Thalai"],"en":["To live with men of greatness that their own excels,","As cherished friends, is greatest power that with a monarch dwells"],"s":"So to act as to make those men, his own, who are greater than himself is of all powers the highest","ch":45,"sec":2,"th":"governance"},
  {"n":445,"ta":["சூழ்வார்கண் ணாக ஒழுகலான் மன்னவன்","சூழ்வாரைக் சூழ்ந்து கொளல்"],"tr":["Soozhvaarkan Naaka Ozhukalaan Mannavan","Soozhvaaraik Soozhndhu Kolal"],"en":["The king, since counsellors are monarch's eyes,","Should counsellors select with counsel wise"],"s":"As a king must use his ministers as eyes  (in managing his kingdom), let him well examine their character and qualifications before he engages them","ch":45,"sec":2,"th":"governance"},
  {"n":446,"ta":["தக்கா ரினத்தனாய்த் தானொழுக வல்லானைச்","செற்றார் செயக்கிடந்த தில்"],"tr":["Thakkaa Rinaththanaaith Thaanozhuka Vallaanaich","Chetraar Seyakkitandha Thil"],"en":["The king, who knows to live with worthy men allied,","Has nought to fear from any foeman's pride"],"s":"There will be nothing left for enemies to do, against him who has the power of acting  (so as to secure) the fellowship of worthy men","ch":45,"sec":2,"th":"governance"},
  {"n":447,"ta":["இடிக்குந் துணையாரை யாள்வரை யாரே","கெடுக்குந் தகைமை யவர்"],"tr":["Itikkun Thunaiyaarai Yaalvarai Yaare","Ketukkun Thakaimai Yavar"],"en":["What power can work his fall, who faithful ministers","Employs, that thunder out reproaches when he errs"],"s":"Who are great enough to destroy him who has servants that have power to rebuke him?","ch":45,"sec":2,"th":"governance"},
  {"n":448,"ta":["இடிப்பாரை இல்லாத ஏமரா மன்னன்","கெடுப்பா ரிலானுங் கெடும்"],"tr":["Itippaarai Illaadha Emaraa Mannan","Ketuppaa Rilaanung Ketum"],"en":["The king with none to censure him, bereft of safeguards all,","Though none his ruin work, shall surely ruined fall"],"s":"The king, who is without the guard of men who can rebuke him, will perish, even though there be no one to destroy him","ch":45,"sec":2,"th":"governance"},
  {"n":449,"ta":["முதலிலார்க ஊதிய மில்லை மதலையாஞ்","சார்பிலார்க் கில்லை நிலை"],"tr":["Mudhalilaarkku Oodhiya Millai Madhalaiyaanjjch","Aarpilaark Killai Nilai"],"en":["Who owns no principal, can have no gain of usury;","Who lacks support of friends, knows no stability"],"s":"There can be no gain to those who have no capital; and in like manner there can be no permanence to","ch":45,"sec":2,"th":"governance"},
  {"n":450,"ta":["பல்லார் பகைகொளலிற் பத்தடுத்த தீமைத்தே","நல்லார் தொடர்கை விடல்"],"tr":["Pallaar Pakai Kolalir Paththatuththa","Theemaiththe Nallaar Thotarkai Vital"],"en":["Than hate of many foes incurred, works greater woe","Ten-fold, of worthy men the friendship to forego"],"s":"It is tenfold more injurious to abandon the friendship of the good, than to incur the hatred of the many","ch":45,"sec":2,"th":"governance"},
  {"n":451,"ta":["சிற்றினம் அஞ்சும் பெருமை சிறுமைதான்","சுற்றமாச் சூழ்ந்து விடும்"],"tr":["Sitrinam Anjum Perumai Sirumaidhaan","Sutramaach Choozhndhu Vitum"],"en":["The great of soul will mean association fear;","The mean of soul regard mean men as kinsmen dear"],"s":"(True) greatness fears the society of the base; it is only the low - minded who will regard them as friends","ch":46,"sec":2,"th":"friendship"},
  {"n":452,"ta":["நிலத்தியல்பால் நீர்திரிந் தற்றாகும் மாந்தர்க்கு","இனத்தியல்ப தாகும் அறிவு"],"tr":["Nilaththiyalpaal Neerdhirin Thatraakum Maandharkku","Inaththiyalpa Thaakum Arivu"],"en":["The waters' virtues change with soil through which they flow;","As man's companionship so will his wisdom show"],"s":"As water changes  (its nature), from the nature of the soil  (in which it flows), so will the character of men resemble that of their associates","ch":46,"sec":2,"th":"friendship"},
  {"n":453,"ta":["மனத்தானாம் மாந்தர்க் குணர்ச்சி இனத்தானாம்","இன்னான் எனப்படுஞ் சொல்"],"tr":["Manaththaanaam Maandhark Kunarchchi Inaththaanaam","Innaan Enappatunj Chol"],"en":["Perceptions manifold in men are of the mind alone;","The value of the man by his companionship is known"],"s":"The power of knowing is from the mind;  (but) his character is from that of his associates","ch":46,"sec":2,"th":"friendship"},
  {"n":454,"ta":["மனத்து ளதுபோலக் காட்டி ஒருவற்கு","இனத்துள தாகும் அறிவு"],"tr":["Manaththu Ladhupolak Kaatti Oruvarku","Inaththula Thaakum Arivu"],"en":["Man's wisdom seems the offspring of his mind;","'Tis outcome of companionship we find"],"s":"Wisdom appears to rest in the mind, but it really exists to a man in his companions","ch":46,"sec":2,"th":"friendship"},
  {"n":455,"ta":["மனந்தூய்மை செய்வினை தூய்மை இரண்டும்","இனந்தூய்மை தூவா வரும்"],"tr":["Manandhooimai Seyvinai Thooimai Irantum","Inandhooimai Thoovaa Varum"],"en":["Both purity of mind, and purity of action clear,","Leaning no staff of pure companionship, to man draw near"],"s":"Chaste company is the staff on which come, these two things, viz, purity of mind and purity of conduct","ch":46,"sec":2,"th":"friendship"},
  {"n":456,"ta":["மனந்தூயார்க் கெச்சம்நன் றாகும் இனந்தூயார்க்கு","இல்லைநன் றாகா வினை"],"tr":["Manandhooyaark Kechchamnan Raakum Inandhooyaarkku","Illainan Raakaa Vinai"],"en":["From true pure-minded men a virtuous race proceeds;","To men of pure companionship belong no evil deeds"],"s":"To the pure-minded there will be a good posterity By those whose associates are pure, no deeds will be done that are not good","ch":46,"sec":2,"th":"friendship"},
  {"n":457,"ta":["மனநலம் மன்னுயிர்க் காக்கம் இனநலம்","எல்லாப் புகழும் தரும்"],"tr":["Mananalam Mannuyirk Kaakkam Inanalam","Ellaap Pukazhum Tharum"],"en":["Goodness of mind to lives of men increaseth gain;","And good companionship doth all of praise obtain"],"s":"Goodness of mind will give wealth, and good society will bring with it all praise, to men","ch":46,"sec":2,"th":"friendship"},
  {"n":458,"ta":["மனநலம் நன்குடைய ராயினும் சான்றோர்க்கு","இனநலம் ஏமாப் புடைத்து"],"tr":["Mananalam Nankutaiya Raayinum Saandrorkku","Inanalam Emaap Putaiththu"],"en":["To perfect men, though minds right good belong,","Yet good companionship is confirmation strong"],"s":"Yet good companionship is confirmation strong","ch":46,"sec":2,"th":"friendship"},
  {"n":459,"ta":["மனநலத்தின் ஆகும் மறுமைமற் றஃதும்","இனநலத்தின் ஏமாப் புடைத்து"],"tr":["Mananalaththin Aakum Marumaimar Raqdhum","Inanalaththin Emaap Putaiththu"],"en":["Although to mental goodness joys of other life belong,","Yet good companionship is confirmation strong"],"s":"Future bliss is  (the result) of goodness of mind; and even this acquires strength from the society of the good","ch":46,"sec":2,"th":"friendship"},
  {"n":460,"ta":["நல்லினத்தி னூங்குந் துணையில்லை தீயினத்தின்","அல்லற் படுப்பதூஉம் இல்"],"tr":["Nallinaththi Noongun Thunaiyillai Theeyinaththin","Allar Patuppadhooum Il"],"en":["Than good companionship no surer help we know;","Than bad companionship nought causes direr woe"],"s":"There is no greater help than the company of the good; there is no greater source of sorrow than the company of the wicked","ch":46,"sec":2,"th":"friendship"},
  {"n":461,"ta":["அழிவதூஉம் ஆவதூஉம் ஆகி வழிபயக்கும்","ஊதியமும் சூழ்ந்து செயல்"],"tr":["Azhivadhooum Aavadhooum Aaki Vazhipayakkum","Oodhiyamum Soozhndhu Seyal"],"en":["Expenditure, return, and profit of the deed","In time to come; weigh these- than to the act proceed"],"s":"Let a man reflect on what will be lost, what will be acquired and  (from these) what will be his ultimate gain, and  (then, let him) act","ch":47,"sec":2,"th":"governance"},
  {"n":462,"ta":["தெரிந்த இனத்தொடு தேர்ந்தெண்ணிச் செய்வார்க்கு","அரும்பொருள் யாதொன்றும் இல்"],"tr":["Therindha Inaththotu Therndhennich Cheyvaarkku","Arumporul Yaadhondrum Il"],"en":["With chosen friends deliberate; next use the private thought;","Then act By those who thus proceed all works with ease are wrought"],"s":"There is nothing too difficult to  (be attained by) those who, before they act, reflect well themselves, and thoroughly consider  (the matter) with chosen friends","ch":47,"sec":2,"th":"governance"},
  {"n":463,"ta":["ஆக்கம் கருதி முதலிழக்கும் செய்வினை","ஊக்கார் அறிவுடை யார்"],"tr":["Aakkam Karudhi Mudhalizhakkum Seyvinai","Ookkaar Arivutai Yaar"],"en":["To risk one's all and lose, aiming at added gain,","Is rash affair, from which the wise abstain"],"s":"Wise men will not, in the hopes of profit, undertake works that will consume their principal","ch":47,"sec":2,"th":"governance"},
  {"n":464,"ta":["தெளிவி லதனைத் தொடங்கார் இளிவென்னும்","ஏதப்பாடு அஞ்சு பவர்"],"tr":["Thelivi Ladhanaith Thotangaar Ilivennum","Edhappaatu Anju Pavar"],"en":["A work of which the issue is not clear,","Begin not they reproachful scorn who fear"],"s":"Those who fear reproach will not commence anything which has not been  (thoroughly considered) and made clear to them","ch":47,"sec":2,"th":"governance"},
  {"n":465,"ta":["வகையறச் சூழா தெழுதல் பகைவரைப்","பாத்திப் படுப்பதோ ராறு"],"tr":["Vakaiyarach Choozhaa Thezhudhal Pakaivaraip","Paaththip Patuppadho Raaru"],"en":["With plans not well matured to rise against your foe,","Is way to plant him out where he is sure to grow"],"s":"One way to promote the prosperity of an enemy, is  (for a king) to set out  (to war) without having thoroughly weighed his ability  (to cope with its chances)","ch":47,"sec":2,"th":"governance"},
  {"n":466,"ta":["செய்தக்க அல்ல செயக்கெடும் செய்தக்க","செய்யாமை யானுங் கெடும்"],"tr":["Seydhakka Alla Seyak Ketum","Seydhakka Seyyaamai Yaanung Ketum"],"en":["'Tis ruin if man do an unbefitting thing;","Fit things to leave undone will equal ruin bring"],"s":"He will perish who does not what is not fit to do; and he also will perish who does not do what it is fit to","ch":47,"sec":2,"th":"governance"},
  {"n":467,"ta":["எண்ணித் துணிக கருமம் துணிந்தபின்","எண்ணுவம் என்பது இழுக்கு"],"tr":["Ennith Thunika Karumam Thunindhapin","Ennuvam Enpadhu Izhukku"],"en":["Think, and then dare the deed! Who cry,","'Deed dared, we'll think, ' disgraced shall be"],"s":"Consider, and then undertake a matter; after having undertaken it, to say \"We will consider,\" is folly","ch":47,"sec":2,"th":"governance"},
  {"n":468,"ta":["ஆற்றின் வருந்தா வருத்தம் பலர்நின்று","போற்றினும் பொத்துப் படும்"],"tr":["Aatrin Varundhaa Varuththam Palarnindru","Potrinum Poththup Patum"],"en":["On no right system if man toil and strive,","Though many men assist, no work can thrive"],"s":"The work, which is not done by suitable methods, will fail though many stand to uphold it","ch":47,"sec":2,"th":"governance"},
  {"n":469,"ta":["நன்றாற்ற லுள்ளுந் தவுறுண்டு அவரவர்","பண்பறிந் தாற்றாக் கடை"],"tr":["Nandraatra Lullun Thavuruntu Avaravar","Panparin Thaatraak Katai"],"en":["Though well the work be done, yet one mistake is made,","To habitudes of various men when no regard is paid"],"s":"There are failures even in acting well, when it is done without knowing the various dispositions of men","ch":47,"sec":2,"th":"governance"},
  {"n":470,"ta":["எள்ளாத எண்ணிச் செயல்வேண்டும் தம்மோடு","கொள்ளாத கொள்ளாது உலகு"],"tr":["Ellaadha Ennich Cheyalventum Thammotu","Kollaadha Kollaadhu Ulaku"],"en":["Plan and perform no work that others may despise;","What misbeseems a king the world will not approve as wise"],"s":"Let a man reflect, and do things which bring no reproach; the world will not approve, with him, of things which do not become of his position to adopt","ch":47,"sec":2,"th":"governance"},
  {"n":471,"ta":["வினைவலியும் தன்வலியும் மாற்றான் வலியும்","துணைவலியும் தூக்கிச் செயல்"],"tr":["Vinaivaliyum Thanvaliyum Maatraan Valiyum","Thunaivaliyum Thookkich Cheyal"],"en":["The force the strife demands, the force he owns, the force of foes,","The force of friends; these should he weigh ere to the war he goes"],"s":"Let  (one) weigh well the strength of the deed  (he purposes to do), his own strength, the strength of his enemy, and the strength of the allies  (of both), and then let him act","ch":48,"sec":2,"th":"governance"},
  {"n":472,"ta":["ஒல்வ தறிவது அறிந்ததன் கண்தங்கிச்","செல்வார்க்குச் செல்லாதது இல்"],"tr":["Olva Tharivadhu Arindhadhan Kandhangich","Chelvaarkkuch Chellaadhadhu Il"],"en":["Who know what can be wrought, with knowledge of the means, on this,","Their mind firm set, go forth, nought goes with them amiss"],"s":"There is nothing which may not be accomplished by those who, before they attack  (an enemy), make themselves acquainted with their own ability, and with whatever else is  (needful) to be known, and","ch":48,"sec":2,"th":"governance"},
  {"n":473,"ta":["உடைத்தம் வலியறியார் ஊக்கத்தின் ஊக்கி","இடைக்கண் முரிந்தார் பலர்"],"tr":["Utaiththam Valiyariyaar Ookkaththin Ookki","Itaikkan Murindhaar Palar"],"en":["Ill-deeming of their proper powers, have many monarchs striven,","And midmost of unequal conflict fallen asunder riven"],"s":"There are many who, ignorant of their  (want of) power  (to meet it), have haughtily set out to war, and broken down in the midst of it","ch":48,"sec":2,"th":"governance"},
  {"n":474,"ta":["அமைந்தாங் கொழுகான் அளவறியான் தன்னை","வியந்தான் விரைந்து கெடும்"],"tr":["Amaindhaang Kozhukaan Alavariyaan Thannai","Viyandhaan Viraindhu Ketum"],"en":["Who not agrees with those around, no moderation knows,","In self-applause indulging, swift to ruin goes"],"s":"He will quickly perish who, ignorant of his own resources flatters himself of his greatness, and does","ch":48,"sec":2,"th":"governance"},
  {"n":475,"ta":["பீலிபெய் சாகாடும் அச்சிறும் அப்பண்டஞ்","சால மிகுத்துப் பெயின்"],"tr":["Peelipey Saakaatum Achchirum Appantanjjch","Aala Mikuththup Peyin"],"en":["With peacock feathers light, you load the wain;","Yet, heaped too high, the axle snaps in twain"],"s":"The axle tree of a bandy, loaded only with peacocks' feathers will break, if it be greatly overloaded","ch":48,"sec":2,"th":"governance"},
  {"n":476,"ta":["நுனிக்கொம்பர் ஏறினார் அஃதிறந் தூக்கின்","உயிர்க்கிறுதி ஆகி விடும்"],"tr":["Nunikkompar Erinaar Aqdhiran Thookkin","Uyirkkirudhi Aaki Vitum"],"en":["Who daring climbs, and would himself upraise","Beyond the branch's tip, with life the forfeit pays"],"s":"There will be an end to the life of him who, having climbed out to the end of a branch, ventures to go further","ch":48,"sec":2,"th":"governance"},
  {"n":477,"ta":["ஆற்றின் அறவறிந்து ஈக அதுபொருள்","போற்றி வழங்கு நெறி"],"tr":["Aatrin Aravarindhu Eeka Adhuporul","Potri Vazhangu Neri"],"en":["With knowledge of the measure due, as virtue bids you give!","That is the way to guard your wealth, and seemly live"],"s":"Let a man know the measure of his ability  (to give), and let him give accordingly; such giving is the way to preserve his property","ch":48,"sec":2,"th":"governance"},
  {"n":478,"ta":["ஆகாறு அளவிட்டி தாயினுங் கேடில்லை","போகாறு அகலாக் கடை"],"tr":["Aakaaru Alavitti Thaayinung Ketillai","Pokaaru Akalaak Katai"],"en":["Incomings may be scant; but yet, no failure there,","If in expenditure you rightly learn to spare"],"s":"Even though the income  (of a king) be small, it will not cause his  (ruin), if his outgoings be not larger than his income","ch":48,"sec":2,"th":"governance"},
  {"n":479,"ta":["அளவறிந்து வாழாதான் வாழ்க்கை உளபோல","இல்லாகித் தோன்றாக் கெடும்"],"tr":["Alavara�ndhu Vaazhaadhaan Vaazhkkai Ulapola","Illaakith Thondraak Ketum"],"en":["Who prosperous lives and of enjoyment knows no bound,","His seeming wealth, departing, nowhere shall be found"],"s":"The prosperity of him who lives without knowing the measure  (of his property), will perish, even while it seems to continue","ch":48,"sec":2,"th":"governance"},
  {"n":480,"ta":["உளவரை தூக்காத ஒப்புர வாண்மை","வளவரை வல்லைக் கெடும்"],"tr":["Ulavarai Thookkaadha Oppura Vaanmai","Valavarai Vallaik Ketum"],"en":["Beneficence that measures not its bound of means,","Will swiftly bring to nought the wealth on which it leans"],"s":"The measure of his wealth will quickly perish, whose liberality weighs not the measure of his property","ch":48,"sec":2,"th":"governance"},
  {"n":481,"ta":["பகல்வெல்லும் கூகையைக் காக்கை இகல்வெல்லும்","வேந்தர்க்கு வேண்டும் பொழுது"],"tr":["Pakalvellum Kookaiyaik Kaakkai Ikalvellum","Vendharkku Ventum Pozhudhu"],"en":["A crow will conquer owl in broad daylight;","The king that foes would crush, needs fitting time to fight"],"s":"A crow will overcome an owl in the day time; so the king who would conquer his enemy must have  (a suitable) time","ch":49,"sec":2,"th":"governance"},
  {"n":482,"ta":["பருவத்தோடு ஒட்ட ஒழுகல் திருவினைத்","தீராமை ஆர்க்குங் கயிறு"],"tr":["Paruvaththotu Otta Ozhukal Thiruvinaith","Theeraamai Aarkkung Kayiru"],"en":["The bond binds fortune fast is ordered effort made,","Strictly observant still of favouring season's aid"],"s":"Acting at the right season, is a cord that will immoveably bind success  (to a king)","ch":49,"sec":2,"th":"governance"},
  {"n":483,"ta":["அருவினை யென்ப உளவோ கருவியான்","காலம் அற஧ந்து செயின்"],"tr":["Aruvinai Yenpa Ulavo Karuviyaan","Kaalam Arindhu Seyin"],"en":["Can any work be hard in very fact,","If men use fitting means in timely act"],"s":"Is there anything difficult for him to do, who acts, with  (the right) instruments at the right time?","ch":49,"sec":2,"th":"governance"},
  {"n":484,"ta":["ஞாலம் கருதினுங் கைகூடுங் காலம்","கருதி இடத்தாற் செயின்"],"tr":["Gnaalam Karudhinung Kaikootung Kaalam","Karudhi Itaththaar Seyin"],"en":["The pendant world's dominion may be won,","In fitting time and place by action done"],"s":"Though  (a man) should meditate  (the conquest of) the world, he may accomplish it if he acts in the right time, and at the right place","ch":49,"sec":2,"th":"governance"},
  {"n":485,"ta":["காலம் கருதி இருப்பர் கலங்காது","ஞாலம் கருது பவர்"],"tr":["Kaalam Karudhi Iruppar Kalangaadhu","Gnaalam Karudhu Pavar"],"en":["Who think the pendant world itself to subjugate,","With mind unruffled for the fitting time must wait"],"s":"They who thoughtfully consider and wait for the  (right) time  (for action), may successfully meditate  (the conquest of) the world","ch":49,"sec":2,"th":"governance"},
  {"n":486,"ta":["ஊக்க முடையான் ஒடுக்கம் பொருதகர்","தாக்கற்குப் பேருந் தகைத்து"],"tr":["Ookka Mutaiyaan Otukkam Porudhakar","Thaakkarkup Perun Thakaiththu"],"en":["The men of mighty power their hidden energies repress,","As fighting ram recoils to rush on foe with heavier stress"],"s":"The self-restraint of the energetic  (while waiting for a suitable opportunity), is like the drawing back of a fighting-ram in order to butt","ch":49,"sec":2,"th":"governance"},
  {"n":487,"ta":["பொள்ளென ஆங்கே புறம்வேரார் காலம்பார்த்து","உள்வேர்ப்பர் ஒள்ளி யவர்"],"tr":["Pollena Aange Puramveraar Kaalampaarththu","Ulverppar Olli Yavar"],"en":["The glorious once of wrath enkindled make no outward show,","At once; they bide their time, while hidden fires within them glow"],"s":"The wise will not immediately and hastily shew out their anger; they will watch their time, and restrain it within","ch":49,"sec":2,"th":"governance"},
  {"n":488,"ta":["செறுநரைக் காணின் சுமக்க இறுவரை","காணின் கிழக்காம் தலை"],"tr":["Serunaraik Kaanin Sumakka Iruvarai","Kaanin Kizhakkaam Thalai"],"en":["If foes' detested form they see, with patience let them bear;","When fateful hour at last they spy,  the head lies there"],"s":"If one meets his enemy, let him show him all respect, until the time for his destruction is come; when that is come, his head will be easily brought low","ch":49,"sec":2,"th":"governance"},
  {"n":489,"ta":["எய்தற் கரியது இயைந்தக்கால் அந்நிலையே","செய்தற் கரிய செயல்"],"tr":["Eydhar Kariyadhu Iyaindhakkaal Annilaiye","Seydhar Kariya Seyal"],"en":["When hardest gain of opportunity at last is won,","With promptitude let hardest deed be done"],"s":"If a rare opportunity occurs, while it lasts, let a man do that which is rarely to be accomplished  (but for such an opportunity)","ch":49,"sec":2,"th":"governance"},
  {"n":490,"ta":["கொக்கொக்க கூம்பும் பருவத்து மற்றதன்","குத்தொக்க சீர்த்த இடத்து"],"tr":["Kokkokka Koompum Paruvaththu Matradhan","Kuththokka Seerththa Itaththu"],"en":["As heron stands with folded wing, so wait in waiting hour;","As heron snaps its prey, when fortune smiles, put forth your power"],"s":"At the time when one should use self-control, let him restrain himself like a heron; and, let him like it, strike, when there is a favourable opportunity","ch":49,"sec":2,"th":"governance"},
  {"n":491,"ta":["தொடங்கற்க எவ்வினையும் எள்ளற்க முற்றும்","இடங்கண்ட பின்அல் லது"],"tr":["Thotangarka Evvinaiyum Ellarka Mutrum","Itanganta Pinal Ladhu"],"en":["Begin no work of war, depise no foe,","Till place where you can wholly circumvent you know"],"s":"Let not  (a king) despise  (an enemy), nor undertake any thing  (against him), until he has obtained  (a suitable) place for besieging him","ch":50,"sec":2,"th":"governance"},
  {"n":492,"ta":["முரண்சேர்ந்த மொய்ம்பி னவர்க்கும் அரண்சேர்ந்தாம்","ஆக்கம் பலவுந் தரும்"],"tr":["Muranserndha Moimpi Navarkkum Aranserndhaam","Aakkam Palavun Tharum"],"en":["Though skill in war combine with courage tried on battle-field,","The added gain of fort doth great advantage yield"],"s":"Even to those who are men of power and expedients, an attack in connection with a fortification will yield many advantages","ch":50,"sec":2,"th":"governance"},
  {"n":493,"ta":["ஆற்றாரும் ஆற்றி அடுப இடனறிந்து","போற்றார்கண் போற்றிச் செயின்"],"tr":["Aatraarum Aatri Atupa Itanarindhu","Potraarkan Potrich Cheyin"],"en":["E'en weak ones mightily prevail, if place of strong defence,","They find, protect themselves, and work their foes offence"],"s":"Even the powerless will become powerful and conquer, if they select a proper field  (of action), and guard themselves, while they make war on their enemies","ch":50,"sec":2,"th":"governance"},
  {"n":494,"ta":["எண்ணியார் எண்ணம் இழப்பர் இடனறிந்து","துன்னியார் துன்னிச் செயின்"],"tr":["Enniyaar Ennam Izhappar Itanarindhu","Thunniyaar Thunnich Cheyin"],"en":["The foes who thought to triumph, find their thoughts were vain,","If hosts advance, seize vantage ground, and thence the fight maintain"],"s":"If they who draw near  (to fight) choose a suitable place to approach  (their enemy), the latter, will have to relinquish the thought which they once entertained, of conquering them","ch":50,"sec":2,"th":"governance"},
  {"n":495,"ta":["நெடும்புனலுள் வெல்லும் முதலை அடும்புனலின்","நீங்கின் அதனைப் பிற"],"tr":["Netumpunalul Vellum Mudhalai Atumpunalin","Neengin Adhanaip Pira"],"en":["The crocodile prevails in its own flow of water wide,","If this it leaves, 'tis slain by anything beside"],"s":"In deep water, a crocodile will conquer  (all other animals); but if it leave the water, other animals will conquer it","ch":50,"sec":2,"th":"governance"},
  {"n":496,"ta":["கடலோடா கால்வல் நெடுந்தேர் கடலோடும்","நாவாயும் ஓடா நிலத்து"],"tr":["Katalotaa Kaalval Netundher Katalotum","Naavaayum Otaa Nilaththu"],"en":["The lofty car, with mighty wheel, sails not o'er watery main,","The boat that skims the sea, runs not on earth's hard plain"],"s":"Wide chariots, with mighty wheels, will not run on the ocean; neither will ships that the traverse ocean, move on the earth","ch":50,"sec":2,"th":"governance"},
  {"n":497,"ta":["அஞ்சாமை அல்லால் துணைவேண்டா எஞ்சாமை","எண்ணி இடத்தால் செயின்"],"tr":["Anjaamai Allaal Thunaiventaa Enjaamai","Enni Itaththaal Seyin"],"en":["Save their own fearless might they need no other aid,","If in right place they fight, all due provision made"],"s":"You will need no other aid than fearlessness, if you thoroughly reflect  (on what you are to do), and select  (a suitable) place for your operations","ch":50,"sec":2,"th":"governance"},
  {"n":498,"ta":["சிறுபடையான் செல்லிடம் சேரின் உறுபடையான்","ஊக்கம் அழிந்து விடும்"],"tr":["Sirupataiyaan Sellitam Serin Urupataiyaan","Ookkam Azhindhu Vitum"],"en":["If lord of army vast the safe retreat assail","Of him whose host is small, his mightiest efforts fail"],"s":"The power of one who has a large army will perish, if he goes into ground where only a small army can act","ch":50,"sec":2,"th":"governance"},
  {"n":499,"ta":["சிறைநலனும் சீரும் இலரெனினும் மாந்தர்","உறைநிலத்தோடு ஒட்டல் அரிது"],"tr":["Sirainalanum Seerum Ilareninum Maandhar","Urainilaththotu Ottal Aridhu"],"en":["Though fort be none, and store of wealth they lack,","'Tis hard a people's homesteads to attack"],"s":"It is a hazardous thing to attack men in their own country, although they may neither have power nor a good fortress","ch":50,"sec":2,"th":"governance"},
  {"n":500,"ta":["காலாழ் களரில் நரியடும் கண்ணஞ்சா","வேலாள் முகத்த களிறு"],"tr":["Kaalaazh Kalaril Nariyatum Kannanjaa","Velaal Mukaththa Kaliru"],"en":["The jackal slays, in miry paths of foot-betraying fen,","The elephant of fearless eye and tusks transfixing armed men"],"s":"A fox can kill a fearless, warrior-faced elephant, if it go into mud in which its legs sink down","ch":50,"sec":2,"th":"governance"},
  {"n":501,"ta":["அறம்பொருள் இன்பம் உயிரச்சம் நான்கின்","திறந்தெரிந்து தேறப் படும்"],"tr":["Aramporul Inpam Uyirachcham Naankin","Thirandherindhu Therap Patum"],"en":["How treats he virtue, wealth and pleasure? How, when life's at stake,","Comports himself? This four-fold test of man will full assurance make"],"s":"Let  (a minister) be chosen, after he has been tried by means of these four things, viz, his virtue,  (love of) money,  (love of) sexual pleasure, and tear of  (losing) life","ch":51,"sec":2,"th":"governance"},
  {"n":502,"ta":["குடிப்பிறந்து குற்றத்தின் நீங்கி வடுப்பரியும்","நாணுடையான் சுட்டே தெளிவு"],"tr":["Kutippirandhu Kutraththin Neengi Vatuppariyum","Naanutaiyaan Sutte Thelivu"],"en":["Of noble race, of faultless worth, of generous pride","That shrinks from shame or stain; in him may king confide"],"s":"(The king's) choice should  (fall) on him, who is of good family, who is free from faults, and who has the modesty which fears the wounds  (of sin)","ch":51,"sec":2,"th":"governance"},
  {"n":503,"ta":["அரியகற்று ஆசற்றார் கண்ணும் தெரியுங்கால்","இன்மை அரிதே வெளிறு"],"tr":["Ariyakatru Aasatraar Kannum Theriyungaal","Inmai Aridhe Veliru"],"en":["Though deeply learned, unflecked by fault, 'tis rare to see,","When closely scanned, a man from all unwisdom free"],"s":"When even men, who have studied the most difficult works, and who are free from faults, are  (carefully) examined, it is a rare thing to find them without ignorance","ch":51,"sec":2,"th":"governance"},
  {"n":504,"ta":["குணம்நாடிக் குற்றமும் நாடி அவற்றுள்","மிகைநாடி மிக்க கொளல்"],"tr":["Kunamnaatik Kutramum Naati Avatrul","Mikainaati Mikka Kolal"],"en":["Weigh well the good of each, his failings closely scan,","As these or those prevail, so estimate the man"],"s":"Let  (a king) consider  (a man's) good qualities, as well as his faults, and then judge  (of his character) by that which prevails","ch":51,"sec":2,"th":"governance"},
  {"n":505,"ta":["பெருமைக்கும் ஏனைச் சிறுமைக்கும் தத்தம்","கருமமே கட்டளைக் கல்"],"tr":["Perumaikkum Enaich Chirumaikkum Thaththam","Karumame Kattalaik Kal"],"en":["Of greatness and of meanness too,","The deeds of each are touchstone true"],"s":"A man's deeds are the touchstone of his greatness and littleness","ch":51,"sec":2,"th":"governance"},
  {"n":506,"ta":["அற்றாரைத் தேறுதல் ஓம்புக மற்றவர்","பற்றிலர் நாணார் பழி"],"tr":["Atraaraith Therudhal Ompuka Matravar","Patrilar Naanaar Pazhi"],"en":["Beware of trusting men who have no kith of kin;","No bonds restrain such men, no shame deters from sin"],"s":"Let  (a king) avoid choosing men who have no relations; such men have no attachment, and thereforehave no fear of crime","ch":51,"sec":2,"th":"governance"},
  {"n":507,"ta":["காதன்மை கந்தா அறிவறியார்த் தேறுதல்","பேதைமை எல்லாந் தரும்"],"tr":["Kaadhanmai Kandhaa Arivariyaarth Therudhal","Pedhaimai Ellaan Tharum"],"en":["By fond affection led who trusts in men of unwise soul,","Yields all his being up to folly's blind control"],"s":"Yields all his being up to folly's blind control","ch":51,"sec":2,"th":"governance"},
  {"n":508,"ta":["தேரான் பிறனைத் தெளிந்தான் வழிமுறை","தீரா இடும்பை தரும்"],"tr":["Theraan Piranaith Thelindhaan Vazhimurai","Theeraa Itumpai Tharum"],"en":["Who trusts an untried stranger, brings disgrace,","Remediless, on all his race"],"s":"Sorrow that will not leave even his posterity will come upon him chooses a stranger whose character he has not known","ch":51,"sec":2,"th":"governance"},
  {"n":509,"ta":["தேறற்க யாரையும் தேராது தேர்ந்தபின்","தேறுக தேறும் பொருள்"],"tr":["Therarka Yaaraiyum Theraadhu Therndhapin","Theruka Therum Porul"],"en":["Trust no man whom you have not fully tried,","When tested, in his prudence proved confide"],"s":"Let  (a king) choose no one without previous consideration; after he has made his choice, let him unhesitatingly select for each such duties as are appropriate","ch":51,"sec":2,"th":"governance"},
  {"n":510,"ta":["தேரான் தெளிவும் தெளிந்தான்கண் ஐயுறவும்","தீரா இடும்பை தரும்"],"tr":["Theraan Thelivum Thelindhaankan Aiyuravum","Theeraa Itumpai Tharum"],"en":["Trust where you have not tried, doubt of a friend to feel,","Once trusted, wounds inflict that nought can heal"],"s":"To make choice of one who has not been examined, and to entertain doubts respecting one who has been chosen, will produce irremediable sorrow","ch":51,"sec":2,"th":"governance"},
  {"n":511,"ta":["நன்மையும் தீமையும் நாடி நலம்புரிந்த","தன்மையான் ஆளப் படும்"],"tr":["Nanmaiyum Theemaiyum Naati Nalampurindha","Thanmaiyaan Aalap Patum"],"en":["Who good and evil scanning, ever makes the good his joy;","Such man of virtuous mood should king employ"],"s":"He should be employed  (by a king), whose nature leads him to choose the good, after having weighed both the evil and the good in any undertaking","ch":52,"sec":2,"th":"governance"},
  {"n":512,"ta":["வாரி பெருக்கி வளம்படுத்து உற்றவை","ஆராய்வான் செய்க வினை"],"tr":["Vaari Perukki Valampatuththu Utravai","Aaraaivaan Seyka Vinai"],"en":["Who swells the revenues, spreads plenty o'er the land,","Seeks out what hinders progress, his the workman's hand"],"s":"Let him do  (the king's) work who can enlarge the sources  (of revenue), increase wealth and considerately prevent the accidents  (which would destroy it)","ch":52,"sec":2,"th":"governance"},
  {"n":513,"ta":["அன்பறிவு தேற்றம் அவாவின்மை இந்நான்கும்","நன்குடையான் கட்டே தெளிவு"],"tr":["Anparivu Thetram Avaavinmai Innaankum","Nankutaiyaan Katte Thelivu"],"en":["A loyal love with wisdom, clearness, mind from avarice free;","Who hath these four good gifts should ever trusted be"],"s":"Let the choice  (of a king) fall upon him who largely possesses these four things, love, knowledge, a clear mind and freedom from covetousness","ch":52,"sec":2,"th":"governance"},
  {"n":514,"ta":["எனைவகையான் தேறியக் கண்ணும் வினைவகையான்","வேறாகும் மாந்தர் பலர்"],"tr":["Enaivakaiyaan Theriyak Kannum Vinaivakaiyaan","Veraakum Maandhar Palar"],"en":["Even when tests of every kind are multiplied,","Full many a man proves otherwise, by action tried"],"s":"Even when  (a king) has tried them in every possible way, there are many men who change, from the nature of the works  (in which they may be employed)","ch":52,"sec":2,"th":"governance"},
  {"n":515,"ta":["அறிந்தாற்றிச் செய்கிற்பாற்கு அல்லால் வினைதான்","சிறந்தானென்று ஏவற்பாற் றன்று"],"tr":["Arindhaatrich Cheykirpaarku Allaal Vinaidhaan","Sirandhaanendru Evarpaar Randru"],"en":["No specious fav'rite should the king's commission bear,","But he that knows, and work performs with patient care"],"s":"(A king's) work can only be accomplished by a man of wisdom and patient endurance; it is not of a nature to be given to one from mere personal attachment","ch":52,"sec":2,"th":"governance"},
  {"n":516,"ta":["செய்வானை நாடி வினைநாடிக் காலத்தோடு","எய்த உணர்ந்து செயல்"],"tr":["Seyvaanai Naati Vinainaatik Kaalaththotu","Eydha Unarndhu Seyal"],"en":["Let king first ask, 'Who shall the deed perform? ' and 'What the deed?","'Of hour befitting both assured, let every work proceed"],"s":"Let  (a king) act, after having considered the agent  (whom he is to employ), the deed  (he desires to do), and the time which is suitable to it","ch":52,"sec":2,"th":"governance"},
  {"n":517,"ta":["இதனை இதனால் இவன்முடிக்கும் என்றாய்ந்து","அதனை அவன்கண் விடல்"],"tr":["Ithanai Ithanaal Ivanmutikkum Endraaindhu","Adhanai Avankan Vital"],"en":["'This man, this work shall thus work out, ' let thoughtful king command;","Then leave the matter wholly in his servant's hand"],"s":"After having considered, \"this man can accomplish this, by these means\", let  (the king) leave with him the discharge of that duty","ch":52,"sec":2,"th":"governance"},
  {"n":518,"ta":["வினைக்குரிமை நாடிய பின்றை அவனை","அதற்குரிய னாகச் செயல்"],"tr":["Vinaik Kurimai Naatiya Pindrai","Avanai Adharkuriya Naakach Cheyal"],"en":["As each man's special aptitude is known,","Bid each man make that special work his own"],"s":"Having considered what work a man is fit for, let  (the king) employ him in that work","ch":52,"sec":2,"th":"governance"},
  {"n":519,"ta":["வினைக்கண் வினையுடையான் கேண்மைவே றாக","நினைப்பானை நீங்கும் திரு"],"tr":["Vinaikkan Vinaiyutaiyaan Kenmaive Raaka","Ninaippaanai Neengum Thiru"],"en":["Fortune deserts the king who ill can bear,","Informal friendly ways of men his tolls who share"],"s":"Prosperity will leave  (the king) who doubts the friendship of the man who steadily labours in the discharge of his duties","ch":52,"sec":2,"th":"governance"},
  {"n":520,"ta":["நாடோறும் நாடுக மன்னன் வினைசெய்வான்","கோடாமை கோடா துலகு"],"tr":["Naatorum Naatuka Mannan Vinaiseyvaan","Kotaamai Kotaa Thulaku"],"en":["Let king search out his servants' deeds each day;","When these do right, the world goes rightly on its way"],"s":"Let a king daily examine the conduct of his servants; if they do not act crookedly, the world will not act crookedly","ch":52,"sec":2,"th":"governance"},
  {"n":521,"ta":["பற்றற்ற கண்ணும் பழைமைபா ராட்டுதல்","சுற்றத்தார் கண்ணே உள"],"tr":["Patratra Kannum Pazhaimaipaa Raattudhal","Sutraththaar Kanne Ula"],"en":["When wealth is fled, old kindness still to show,","Is kindly grace that only kinsmen know"],"s":"Even when  (a man's) property is all gone, relatives will act towards him with their accustomed  (kindness)","ch":53,"sec":2,"th":"friendship"},
  {"n":522,"ta":["விருப்பறாச் சுற்றம் இயையின் அருப்பறா","ஆக்கம் பலவும் தரும்"],"tr":["Virupparaach Chutram Iyaiyin Arupparaa","Aakkam Palavum Tharum"],"en":["The gift of kin's unfailing love bestows","Much gain of good, like flower that fadeless blows"],"s":"If  (a man's) relatives remain attached to him with unchanging love, it will be a source of everincreasing wealth","ch":53,"sec":2,"th":"friendship"},
  {"n":523,"ta":["அளவளா வில்லாதான் வாழ்க்கை குளவளாக்","கோடின்றி நீர்நிறைந் தற்று"],"tr":["Alavalaa Villaadhaan Vaazhkkai Kulavalaak","Kotindri Neernirain Thatru"],"en":["His joy of life who mingles not with kinsmen gathered round,","Is lake where streams pour in, with no encircling bound"],"s":"The wealth of one who does not mingle freely with his relatives, will be like the filling of water in a","ch":53,"sec":2,"th":"friendship"},
  {"n":524,"ta":["சுற்றத்தால் சுற்றப் படஒழுகல் செல்வந்தான்","பெற்றத்தால் பெற்ற பயன்"],"tr":["Sutraththaal Sutrap Pataozhukal Selvandhaan","Petraththaal Petra Payan"],"en":["The profit gained by wealth's increase,","Is living compassed round by relatives in peace"],"s":"To live surrounded by relatives, is the advantage to be derived from the acquisition of wealth","ch":53,"sec":2,"th":"friendship"},
  {"n":525,"ta":["கொடுத்தலும் இன்சொலும் ஆற்றின் அடுக்கிய","சுற்றத்தால் சுற்றப் படும்"],"tr":["Kotuththalum Insolum Aatrin Atukkiya","Sutraththaal Sutrap Patum"],"en":["Who knows the use of pleasant words, and liberal gifts can give,","Connections, heaps of them, surrounding him shall live"],"s":"He will be surrounded by numerous relatives who manifests generosity and affability","ch":53,"sec":2,"th":"friendship"},
  {"n":526,"ta":["பெருங்கொடையான் பேணான் வெகுளி அவனின்","மருங்குடையார் மாநிலத்து இல்"],"tr":["Perungotaiyaan Penaan Vekuli Avanin","Marungutaiyaar Maanilaththu Il"],"en":["Than one who gifts bestows and wrath restrains,","Through the wide world none larger following gains"],"s":"No one, in all the world, will have so many relatives  (about him), as he who makes large gift, and does not give way to anger","ch":53,"sec":2,"th":"friendship"},
  {"n":527,"ta":["காக்கை கரவா கரைந்துண்ணும் ஆக்கமும்","அன்னநீ ரார்க்கே உள"],"tr":["Kaakkai Karavaa Karaindhunnum Aakkamum","Annanee Raarkke Ula"],"en":["The crows conceal not, call their friends to come, then eat;","Increase of good such worthy ones shall meet"],"s":"The crows do not conceal  (their prey), but will call out for others  (to share with them) while they eat it; wealth will be with those who show a similar disposition  (towards their relatives)","ch":53,"sec":2,"th":"friendship"},
  {"n":528,"ta":["பொதுநோக்கான் வேந்தன் வரிசையா நோக்கின்","அதுநோக்கி வாழ்வார் பலர்"],"tr":["Podhunokkaan Vendhan Varisaiyaa Nokkin","Adhunokki Vaazhvaar Palar"],"en":["Where king regards not all alike, but each in his degree,","'Neath such discerning rule many dwell happily"],"s":"Many relatives will live near a king, when they observe that he does not look on all alike, but that he looks on each man according to his merit","ch":53,"sec":2,"th":"friendship"},
  {"n":529,"ta":["தமராகிக் தற்றுறந்தார் சுற்றம் அமராமைக்","காரணம் இன்றி வரும்"],"tr":["Thamaraakik Thatrurandhaar Sutram Amaraamaik","Kaaranam Indri Varum"],"en":["Who once were his, and then forsook him, as before","Will come around, when cause of disagreement is no more"],"s":"Those who have been friends and have afterwards forsaken him, will return and join themselves  (to him), when the cause of disagreement is not to be found in him","ch":53,"sec":2,"th":"friendship"},
  {"n":530,"ta":["உழைப்பிரிந்து காரணத்தின் வந்தானை வேந்தன்","இழைத் திருந்து எண்ணிக் கொளல்"],"tr":["Uzhaippirindhu Kaaranaththin Vandhaanai Vendhan","Izhaith Thirundhu Ennik Kolal"],"en":["Who causeless went away, then to return, for any cause, ask leave;","The king should sift their motives well, consider, and receive"],"s":"When one may have left him, and for some cause has returned to him, let the king fulfil the object  (for which he has come back) and thoughtfully receive him again","ch":53,"sec":2,"th":"friendship"},
  {"n":531,"ta":["இறந்த வெகுளியின் தீதே சிறந்த","உவகை மகிழ்ச்சியிற் சோர்வு"],"tr":["Irandha Vekuliyin Theedhe Sirandha","Uvakai Makizhchchiyir Sorvu"],"en":["'Tis greater ill, it rapture of o'erweening gladness to the soul","Bring self-forgetfulness than if transcendent wrath control"],"s":"More evil than excessive anger, is forgetfulness which springs from the intoxication of great joy","ch":54,"sec":2,"th":"governance"},
  {"n":532,"ta":["பொச்சாப்புக் கொல்லும் புகழை அறிவினை","நிச்ச நிரப்புக் கொன் றாங்கு"],"tr":["Pochchaappuk Kollum Pukazhai Arivinai","Nichcha Nirappuk Kon Raangu"],"en":["Perpetual, poverty is death to wisdom of the wise;","When man forgets himself his glory dies"],"s":"Forgetfulness will destroy fame, even as constant poverty destroys knowledge","ch":54,"sec":2,"th":"governance"},
  {"n":533,"ta":["பொச்சாப்பார்க் கில்லை புகழ்மை அதுஉலகத்து","எப்பால்நூ லோர்க்கும் துணிவு"],"tr":["Pochchaappaark Killai Pukazhmai Adhuulakaththu","Eppaalnoo Lorkkum Thunivu"],"en":["'To self-oblivious men no praise'; this rule","Decisive wisdom sums of every school"],"s":"Thoughtlessness will never acquire fame; and this tenet is upheld by all treatises in the world","ch":54,"sec":2,"th":"governance"},
  {"n":534,"ta":["அச்ச முடையார்க்கு அரணில்லை ஆங்கில்லை","பொச்சாப் புடையார்க்கு நன்கு"],"tr":["Achcha Mutaiyaarkku Aranillai Aangillai","Pochchaap Putaiyaarkku Nanku"],"en":["'To cowards is no fort's defence'; e'en so","The self-oblivious men no blessing know"],"s":"Just as the coward has no defence  (by whatever fortifications ha may be surrounded), so the thoughtless has no good  (whatever advantages he may possess)","ch":54,"sec":2,"th":"governance"},
  {"n":535,"ta":["முன்னுறக் காவாது இழுக்கியான் தன்பிழை","பின்னூறு இரங்கி விடும்"],"tr":["Munnurak Kaavaadhu Izhukkiyaan Thanpizhai","Pinnooru Irangi Vitum"],"en":["To him who nought foresees, recks not of anything,","The after woe shall sure repentance bring"],"s":"The thoughtless man, who provides not against the calamities that may happen, will afterwards repent for his fault","ch":54,"sec":2,"th":"governance"},
  {"n":536,"ta":["இழுக்காமை யார்மாட்டும் என்றும் வழுக்காமை","வாயின் அதுவொப்பது இல்"],"tr":["Izhukkaamai Yaarmaattum Endrum Vazhukkaamai","Vaayin Adhuvoppadhu Il"],"en":["Towards all unswerving, ever watchfulness of soul retain,","Where this is found there is no greater gain"],"s":"There is nothing comparable with the possession of unfailing thoughtfulness at all times; and towards all persons","ch":54,"sec":2,"th":"governance"},
  {"n":537,"ta":["அரியஎன்று ஆகாத இல்லைபொச் சாவாக்","கருவியால் போற்றிச் செயின்"],"tr":["Ariyaendru Aakaadha Illaipoch Chaavaak","Karuviyaal Potrich Cheyin"],"en":["Though things are arduous deemed, there's nought may not be won,","When work with mind's unslumbering energy and thought is done"],"s":"There is nothing too difficult to be accomplished, if a man set about it carefully, with unflinching endeavour","ch":54,"sec":2,"th":"governance"},
  {"n":538,"ta":["புகழ்ந்தவை போற்றிச் செயல்வேண்டும் செய்யாது","இகழ்ந்தார்க்கு எழுமையும் இல்"],"tr":["Pukazhndhavai Potrich Cheyalventum Seyyaadhu","Ikazhndhaarkku Ezhumaiyum Il"],"en":["Let things that merit praise thy watchful soul employ;","Who these despise attain through sevenfold births no joy"],"s":"Let  (a man) observe and do these things which have been praised  (by the wise); if he neglects and fails to perform them, for him there will be no  (happiness) throughout the seven births","ch":54,"sec":2,"th":"governance"},
  {"n":539,"ta":["இகழ்ச்சியின் கெட்டாரை உள்ளுக தாந்தம்","மகிழ்ச்சியின் மைந்துறும் போழ்து"],"tr":["Ikazhchchiyin Kettaarai Ulluka Thaandham","Makizhchchiyin Maindhurum Pozhdhu"],"en":["Think on the men whom scornful mind hath brought to nought,","When exultation overwhelms thy wildered thought"],"s":"Let  (a king) think of those who have been ruined by neglect, when his mind is elated with joy","ch":54,"sec":2,"th":"governance"},
  {"n":540,"ta":["உள்ளியது எய்தல் எளிதுமன் மற்றுந்தான்","உள்ளியது உள்ளப் பெறின்"],"tr":["Ulliyadhu Eydhal Elidhuman Matrundhaan","Ulliyadhu Ullap Perin"],"en":["'Tis easy what thou hast in mind to gain,","If what thou hast in mind thy mind retain"],"s":"It is easy for  (one) to obtain whatever he may think of, if he can again think of it","ch":54,"sec":2,"th":"governance"},
  {"n":541,"ta":["ஓர்ந்துகண் ணோடாது இறைபுரிந்து யார்மாட்டும்","தேர்ந்துசெய் வஃதே முறை"],"tr":["Orndhukan Notaadhu Iraipurindhu Yaarmaattum","Therndhusey Vaqdhe Murai"],"en":["Search out, to no one favour show; with heart that justice loves","Consult, then act; this is the rule that right approves"],"s":"To examine into  (the crimes which may be committed), to show no favour  (to any one), to desire to act with impartiality towards all, and to inflict  (such punishments) as may be wisely resolved on,","ch":55,"sec":2,"th":"governance"},
  {"n":542,"ta":["வானோக்கி வாழும் உலகெல்லாம் மன்னவன்","கோல் நோக்கி வாழுங் குடி"],"tr":["Vaanokki Vaazhum Ulakellaam Mannavan","Kol Nokki Vaazhung Kuti"],"en":["All earth looks up to heav'n whence raindrops fall;","All subjects look to king that ruleth all"],"s":"When there is rain, the living creation thrives; and so when the king rules justly, his subjects thrive","ch":55,"sec":2,"th":"governance"},
  {"n":543,"ta":["அந்தணர் நூற்கும் அறத்திற்கும் ஆதியாய்","நின்றது மன்னவன் கோல்"],"tr":["Andhanar Noorkum Araththirkum Aadhiyaai","Nindradhu Mannavan Kol"],"en":["Learning and virtue of the sages spring,","From all-controlling sceptre of the king"],"s":"The sceptre of the king is the firm support of the Vedas of the Brahmin, and of all virtues therein described","ch":55,"sec":2,"th":"governance"},
  {"n":544,"ta":["குடிதழீஇக் கோலோச்சும் மாநில மன்னன்","அடிதழீஇ நிற்கும் உலகு"],"tr":["Kutidhazheeik Kolochchum Maanila Mannan","Atidhazheei Nirkum Ulaku"],"en":["Whose heart embraces subjects all, lord over mighty land","Who rules, the world his feet embracing stands"],"s":"The world will constantly embrace the feet of the great king who rules over his subjects with love","ch":55,"sec":2,"th":"governance"},
  {"n":545,"ta":["இயல்புளிக் கோலோச்சும் மன்னவன் நாட்ட","பெயலும் விளையுளும் தொக்கு"],"tr":["Iyalpulik Kolochchum Mannavan Naatta","Peyalum Vilaiyulum Thokku"],"en":["Where king, who righteous laws regards, the sceptre wields,","There fall the showers, there rich abundance crowns the fields"],"s":"Rain and plentiful crops will ever dwell together in the country of the king who sways his sceptre with justice","ch":55,"sec":2,"th":"governance"},
  {"n":546,"ta":["வேலன்று வென்றி தருவது மன்னவன்","கோலதூஉங் கோடா தெனின்"],"tr":["Velandru Vendri Tharuvadhu Mannavan","Koladhooung Kotaa Thenin"],"en":["Not lance gives kings the victory,","But sceptre swayed with equity"],"s":"It is not the javelin that gives victory, but the king's sceptre, if it do no injustice","ch":55,"sec":2,"th":"governance"},
  {"n":547,"ta":["இறைகாக்கும் வையகம் எல்லாம் அவனை","முறைகாக்கும் முட்டாச் செயின்"],"tr":["Iraikaakkum Vaiyakam Ellaam Avanai","Muraikaakkum Muttaach Cheyin"],"en":["The king all the whole realm of earth protects;","And justice guards the king who right respects"],"s":"The king defends the whole world; and justice, when administered without defect, defends the king","ch":55,"sec":2,"th":"governance"},
  {"n":548,"ta":["எண்பதத்தான் ஓரா முறைசெய்யா மன்னவன்","தண்பதத்தான் தானே கெடும்"],"tr":["Enpadhaththaan Oraa Muraiseyyaa Mannavan","Thanpadhaththaan Thaane Ketum"],"en":["Hard of access, nought searching out, with partial hand","The king who rules, shall sink and perish from the land"],"s":"The king who gives not facile audience  (to those who approach him), and who does not examine and pass judgment  (on their complaints), will perish in disgrace","ch":55,"sec":2,"th":"governance"},
  {"n":549,"ta":["குடிபுறங் காத்தோம்பிக் குற்றம் கடிதல்","வடுவன்று வேந்தன் தொழில்"],"tr":["Kutipurang Kaaththompik Kutram Katidhal","Vatuvandru Vendhan Thozhil"],"en":["Abroad to guard, at home to punish, brings","No just reproach; 'tis work assigned to kings"],"s":"In guarding his subjects  (against injury from others), and in preserving them himself; to punish crime","ch":55,"sec":2,"th":"governance"},
  {"n":550,"ta":["கொலையிற் கொடியாரை வேந்தொறுத்தல் பைங்கூழ்","களைகட் டதனொடு நேர்"],"tr":["Kolaiyir Kotiyaarai Vendhoruththal Paingoozh","Kalaikat Tadhanotu Ner"],"en":["By punishment of death the cruel to restrain,","Is as when farmer frees from weeds the tender grain"],"s":"For a king to punish criminals with death, is like pulling up the weeds in the green corn","ch":55,"sec":2,"th":"governance"},
  {"n":551,"ta":["கொலைமேற்கொண் டாரிற் கொடிதே அலைமேற்கொண்டு","அல்லவை செய்தொழுகும் வேந்து"],"tr":["Kolaimerkon Taarir Kotidhe Alaimerkontu","Allavai Seydhozhukum Vendhu"],"en":["Than one who plies the murderer's trade, more cruel is the king","Who all injustice works, his subjects harassing"],"s":"The king who gives himself up to oppression and acts unjustly  (towards his subjects) is more cruel than the man who leads the life of a murderer","ch":56,"sec":2,"th":"governance"},
  {"n":552,"ta":["வேலொடு நின்றான் இடுவென் றதுபோலும்","கோலொடு நின்றான் இரவு"],"tr":["Velotu Nindraan Ituven Radhupolum","Kolotu Nindraan Iravu"],"en":["As 'Give' the robber cries with lance uplift,","So kings with sceptred hand implore a gift"],"s":"The request  (for money) of him who holds the sceptre is like the word of a highway robber who stands with a weapon in hand and says \"give up your wealth\"","ch":56,"sec":2,"th":"governance"},
  {"n":553,"ta":["நாடொறும் நாடி முறைசெய்யா மன்னவன்","நாடொறும் நாடு கெடும்"],"tr":["Naatorum Naati Muraiseyyaa Mannavan","Naatorum Naatu Ketum"],"en":["Who makes no daily search for wrongs, nor justly rules, that king","Doth day by day his realm to ruin bring"],"s":"The country of the king who does not daily examine into the wrongs done and distribute justice, will daily fall to ruin","ch":56,"sec":2,"th":"governance"},
  {"n":554,"ta":["கூழுங் குடியும் ஒருங்கிழக்கும் கோல்கோடிச்","சூழாது செய்யும் அரசு"],"tr":["Koozhung Kutiyum Orungizhakkum Kolkotich","Choozhaadhu Seyyum Arasu"],"en":["Whose rod from right deflects, who counsel doth refuse,","At once his wealth and people utterly shall lose"],"s":"The king, who, without reflecting  (on its evil consequences), perverts justice, will lose at once both his wealth and his subjects","ch":56,"sec":2,"th":"governance"},
  {"n":555,"ta":["அல்லற்பட்டு ஆற்றாது அழுதகண் ணீரன்றே","செல்வத்தைத் தேய்க்கும் படை"],"tr":["Allarpattu Aatraadhu Azhudhakan Neerandre","Selvaththaith Theykkum Patai"],"en":["His people's tears of sorrow past endurance, are not they","Sharp instruments to wear the monarch's wealth away"],"s":"Will not the tears, shed by a people who cannot endure the oppression which they suffer  (from their king), become a saw to waste away his wealth?","ch":56,"sec":2,"th":"governance"},
  {"n":556,"ta":["மன்னர்க்கு மன்னுதல் செங்கோன்மை அஃதின்றேல்","மன்னாவாம் மன்னர்க் கொளி"],"tr":["Mannarkku Mannudhal Sengonmai Aqdhindrel","Mannaavaam Mannark Koli"],"en":["To rulers' rule stability is sceptre right;","When this is not, quenched is the rulers' light"],"s":"Righteous government gives permanence to  (the fame of) kings; without that their fame will have no endurance","ch":56,"sec":2,"th":"governance"},
  {"n":557,"ta":["துளியின்மை ஞாலத்திற்கு எற்றற்றே வேந்தன்","அளியின்மை வாழும் உயிர்க்கு"],"tr":["Thuliyinmai Gnaalaththirku Etratre Vendhan","Aliyinmai Vaazhum Uyirkku"],"en":["As lack of rain to thirsty lands beneath,","Is lack of grace in kings to all that breathe"],"s":"As is the world without rain, so live a people whose king is without kindness","ch":56,"sec":2,"th":"governance"},
  {"n":558,"ta":["இன்மையின் இன்னாது உடைமை முறைசெய்யா","மன்னவன் கோற்கீழ்ப் படின்"],"tr":["Inmaiyin Innaadhu Utaimai Muraiseyyaa","Mannavan Korkeezhp Patin"],"en":["To poverty it adds a sharper sting,","To live beneath the sway of unjust king"],"s":"Property gives more sorrow than poverty, to those who live under the sceptre of a king without justice","ch":56,"sec":2,"th":"governance"},
  {"n":559,"ta":["முறைகோடி மன்னவன் செய்யின் உறைகோடி","ஒல்லாது வானம் பெயல்"],"tr":["Muraikoti Mannavan Seyyin Uraikoti","Ollaadhu Vaanam Peyal"],"en":["Where king from right deflecting, makes unrighteous gain,","The seasons change, the clouds pour down no rain"],"s":"If the king acts contrary to justice, rain will become unseasonable, and the heavens will withhold their showers","ch":56,"sec":2,"th":"governance"},
  {"n":560,"ta":["ஆபயன் குன்றும் அறுதொழிலோர் நூல்மறப்பர்","காவலன் காவான் எனின்"],"tr":["Aapayan Kundrum Arudhozhilor Noolmarappar","Kaavalan Kaavaan Enin"],"en":["Where guardian guardeth not, udder of kine grows dry,","And Brahmans' sacred lore will all forgotten lie"],"s":"If the guardian  (of the country) neglects to guard it, the produce of the cows will fail, and the men of six duties viz, the Brahmins will forget the vedas","ch":56,"sec":2,"th":"governance"},
  {"n":561,"ta":["தக்காங்கு நாடித் தலைச்செல்லா வண்ணத்தால்","ஒத்தாங்கு ஒறுப்பது வேந்து"],"tr":["Thakkaangu Naatith Thalaichchellaa Vannaththaal","Oththaangu Oruppadhu Vendhu"],"en":["Who punishes, investigation made in due degree,","So as to stay advance of crime, a king is he"],"s":"He is a king who having equitably examined  (any injustice which has been brought to his notice), suitably punishes it, so that it may not be again committed","ch":57,"sec":2,"th":"governance"},
  {"n":562,"ta":["கடிதோச்சி மெல்ல எறிக நெடிதாக்கம்","நீங்காமை வேண்டு பவர்"],"tr":["Katidhochchi Mella Erika Netidhaakkam","Neengaamai Ventu Pavar"],"en":["For length of days with still increasing joys on Heav'n who call,","Should raise the rod with brow severe, but let it gently fall"],"s":"Let the king, who desires that his prosperity may long remain, commence his preliminary enquires with strictness, and then punish with mildness","ch":57,"sec":2,"th":"governance"},
  {"n":563,"ta":["வெருவந்த செய்தொழுகும் வெங்கோல னாயின்","ஒருவந்தம் ஒல்லைக் கெடும்"],"tr":["Veruvandha Seydhozhukum Vengola Naayin","Oruvandham Ollaik Ketum"],"en":["Where subjects dread of cruel wrongs endure,","Ruin to unjust king is swift and sure"],"s":"The cruel-sceptred king, who acts so as to put his subjects in fear, will certainly and quickly come to ruin","ch":57,"sec":2,"th":"governance"},
  {"n":564,"ta":["இறைகடியன் என்றுரைக்கும் இன்னாச்சொல் வேந்தன்","உறைகடுகி ஒல்லைக் கெடும்"],"tr":["Iraikatiyan Endruraikkum Innaachchol Vendhan","Uraikatuki Ollaik Ketum"],"en":["'Ah! cruel is our king', where subjects sadly say,","His age shall dwindle, swift his joy of life decay"],"s":"The king who is spoken of as cruel will quickly perish; his life becoming shortened","ch":57,"sec":2,"th":"governance"},
  {"n":565,"ta":["அருஞ்செவ்வி இன்னா முகத்தான் பெருஞ்செல்வம்","பேஎய்கண் டன்னது உடைத்து"],"tr":["Arunjevvi Innaa Mukaththaan Perunjelvam","Peeykan Tannadhu Utaiththu"],"en":["Whom subjects scarce may see, of harsh forbidding countenance;","His ample wealth shall waste, blasted by demon's glance"],"s":"The great wealth of him who is difficult of access and possesses a sternness of countenance, is like that which has been obtained by a devil","ch":57,"sec":2,"th":"governance"},
  {"n":566,"ta":["கடுஞ்சொல்லன் கண்ணிலன் ஆயின் நெடுஞ்செல்வம்","நீடின்றி ஆங்கே கெடும்"],"tr":["Katunjollan Kannilan Aayin Netunjelvam","Neetindri Aange Ketum"],"en":["The tyrant, harsh in speach and hard of eye,","His ample joy, swift fading, soon shall die"],"s":"The abundant wealth of the king whose words are harsh and whose looks are void of kindness, will instantly perish instead of abiding long, with him","ch":57,"sec":2,"th":"governance"},
  {"n":567,"ta":["கடுமொழியும் கையிகந்த தண்டமும் வேந்தன்","அடுமுரண் தேய்க்கும் அரம்"],"tr":["Katumozhiyum Kaiyikandha Thantamum Vendhan","Atumuran Theykkum Aram"],"en":["Harsh words and punishments severe beyond the right,","Are file that wears away the monarch's conquering might"],"s":"Severe words and excessive punishments will be a file to waste away a king's power for destroying  (his enemies)","ch":57,"sec":2,"th":"governance"},
  {"n":568,"ta":["இனத்தாற்றி எண்ணாத வேந்தன் சினத்தாற்றிச்","சீறிற் சிறுகும் திரு"],"tr":["Inaththaatri Ennaadha Vendhan Sinaththaatrich","Cheerir Sirukum Thiru"],"en":["Who leaves the work to those around, and thinks of it no more;","If he in wrathful mood reprove, his prosperous days are o'er"],"s":"The prosperity of that king will waste away, who without reflecting  (on his affairs himself), commits them to his ministers, and  (when a failure occurs) gives way to anger, and rages against them","ch":57,"sec":2,"th":"governance"},
  {"n":569,"ta":["செருவந்த போழ்திற் சிறைசெய்யா வேந்தன்","வெருவந்து வெய்து கெடும்"],"tr":["Seruvandha Pozhdhir Siraiseyyaa Vendhan","Veruvandhu Veydhu Ketum"],"en":["Who builds no fort whence he may foe defy,","In time of war shall fear and swiftly die"],"s":"The king who has not provided himself with a place of defence, will in times of war be seized with fear and quickly perish","ch":57,"sec":2,"th":"governance"},
  {"n":570,"ta":["கல்லார்ப் பிணிக்கும் கடுங்கோல் அதுவல்லது","இல்லை நிலக்குப் பொறை"],"tr":["Kallaarp Pinikkum Katungol Adhuvalladhu","Illai Nilakkup Porai"],"en":["Tyrants with fools their counsels share:","Earth can no heavier burthen bear"],"s":"The earth bears up no greater burden than ignorant men whom a cruel sceptre attaches to itself  (as the ministers of its evil deeds)","ch":57,"sec":2,"th":"governance"},
  {"n":571,"ta":["கண்ணோட்டம் என்னும் கழிபெருங் காரிகை","உண்மையான் உண்டிவ் வுலகு"],"tr":["Kannottam Ennum Kazhiperung Kaarikai","Unmaiyaan Untiv Vulaku"],"en":["Since true benignity, that grace exceeding great, resides","In kingly souls, world in happy state abides"],"s":"The world exists through that greatest ornament  (of princes), a gracious demeanour","ch":58,"sec":2,"th":"governance"},
  {"n":572,"ta":["கண்ணோட்டத் துள்ளது உலகியல் அஃதிலார்","உண்மை நிலக்குப் பொறை"],"tr":["Kannottath Thulladhu Ulakiyal Aqdhilaar","Unmai Nilakkup Porai"],"en":["The world goes on its wonted way, since grace benign is there;","All other men are burthen for the earth to bear"],"s":"The prosperity of the world springs from the kindliness, the existence of those who have no  (kindliness) is a burden to the earth","ch":58,"sec":2,"th":"governance"},
  {"n":573,"ta":["பண்என்னாம் பாடற்கு இயைபின்றேல் கண்என்னாம்","கண்ணோட்டம் இல்லாத கண்"],"tr":["Panennaam Paatarku Iyaipindrel Kanennaam","Kannottam Illaadha Kan"],"en":["Where not accordant with the song, what use of sounding chords","What gain of eye that no benignant light affords"],"s":"Of what avail is a song if it be inconsistent with harmony? what is the use of eyes which possess no kindliness","ch":58,"sec":2,"th":"governance"},
  {"n":574,"ta":["உளபோல் முகத்தெவன் செய்யும் அளவினால்","கண்ணோட்டம் இல்லாத கண்"],"tr":["Ulapol Mukaththevan Seyyum Alavinaal","Kannottam Illaadha Kan"],"en":["The seeming eye of face gives no expressive light,","When not with duly meted kindness bright"],"s":"Beyond appearing to be in the face, what good do they do, those eyes in which is no well-regulated kindness?","ch":58,"sec":2,"th":"governance"},
  {"n":575,"ta":["கண்ணிற்கு அணிகலம் கண்ணோட்டம் அஃதின்றேல்","புண்ணென்று உணரப் படும்"],"tr":["Kannirku Anikalam Kannottam Aqdhindrel","Punnendru Unarap Patum"],"en":["Benignity is eyes' adorning grace;","Without it eyes are wounds disfiguring face"],"s":"Kind looks are the ornaments of the eyes; without these they will be considered  (by the wise) to be merely two sores","ch":58,"sec":2,"th":"governance"},
  {"n":576,"ta":["மண்ணோ டியைந்த மரத்தனையர் கண்ணோ","டியைந்துகண் ணோடா தவர்"],"tr":["Manno Tiyaindha Maraththanaiyar Kanno","Tiyaindhukan Notaa Thavar"],"en":["Whose eyes 'neath brow infixed diffuse no ray","Of grace; like tree in earth infixed are they"],"s":"They resemble the trees of the earth, who although they have eyes, never look kindly  (on others)","ch":58,"sec":2,"th":"governance"},
  {"n":577,"ta":["கண்ணோட்டம் இல்லவர் கண்ணிலர் கண்ணுடையார்","கண்ணோட்டம் இன்மையும் இல்"],"tr":["Kannottam Illavar Kannilar Kannutaiyaar","Kannottam Inmaiyum Il"],"en":["Eyeless are they whose eyes with no benignant lustre shine;","Who've eyes can never lack the light of grace benign"],"s":"Men without kind looks are men without eyes; those who  (really) have eyes are also not devoid of kind looks","ch":58,"sec":2,"th":"governance"},
  {"n":578,"ta":["கருமம் சிதையாமல் கண்ணோட வல்லார்க்கு","உரிமை உடைத்திவ் வுலகு"],"tr":["Karumam Sidhaiyaamal Kannota Vallaarkku","Urimai Utaiththiv Vulaku"],"en":["Who can benignant smile, yet leave no work undone;","By them as very own may all the earth be won"],"s":"The world is theirs  (kings) who are able to show kindness, without injury to their affairs,  (administration of justice)","ch":58,"sec":2,"th":"governance"},
  {"n":579,"ta":["ஒறுத்தாற்றும் பண்பினார் கண்ணும்கண் ணோடிப்","பொறுத்தாற்றும் பண்பே தலை"],"tr":["Oruththaatrum Panpinaar Kannumkan Notip","Poruththaatrum Panpe Thalai"],"en":["To smile on those that vex, with kindly face,","Enduring long, is most excelling grace"],"s":"Patiently to bear with, and show kindness to those who grieve us, is the most excellent of all dispositions","ch":58,"sec":2,"th":"governance"},
  {"n":580,"ta":["பெயக்கண்டும் நஞ்சுண் டமைவர் நயத்தக்க","நாகரிகம் வேண்டு பவர்"],"tr":["Peyakkantum Nanjun Tamaivar Nayaththakka","Naakarikam Ventu Pavar"],"en":["They drink with smiling grace, though poison interfused they see,","Who seek the praise of all-esteemed courtesy"],"s":"Those who desire  (to cultivate that degree of) urbanity which all shall love, even after swallowing the poison served to them by their friends, will be friendly with them","ch":58,"sec":2,"th":"governance"},
  {"n":581,"ta":["ஒற்றும் உரைசான்ற நூலும் இவையிரண்டும்","தெற்றென்க மன்னவன் கண்"],"tr":["Otrum Uraisaandra Noolum Ivaiyirantum","Thetrenka Mannavan Kan"],"en":["These two: the code renowned and spies,","In these let king confide as eyes"],"s":"Let a king consider as his eyes these two things, a spy and a book  (of laws) universally esteemed","ch":59,"sec":2,"th":"governance"},
  {"n":582,"ta":["எல்லார்க்கும் எல்லாம் நிகழ்பவை எஞ்ஞான்றும்","வல்லறிதல் வேந்தன் தொழில்"],"tr":["Ellaarkkum Ellaam Nikazhpavai Egngnaandrum","Vallaridhal Vendhan Thozhil"],"en":["Each day, of every subject every deed,","'Tis duty of the king to learn with speed"],"s":"'Tis duty of the king to learn with speed","ch":59,"sec":2,"th":"governance"},
  {"n":583,"ta":["ஒற்றினான் ஒற்றிப் பொருள்தெரியா மன்னவன்","கொற்றங் கொளக்கிடந்தது இல்"],"tr":["Otrinaan Otrip Poruldheriyaa Mannavan","Kotrang Kolakkitandhadhu Il"],"en":["By spies who spies, not weighing things they bring,","Nothing can victory give to that unwary king"],"s":"There is no way for a king to obtain conquests, who knows not the advantage of discoveries made by a spy","ch":59,"sec":2,"th":"governance"},
  {"n":584,"ta":["வினைசெய்வார் தம்சுற்றம் வேண்டாதார் என்றாங்கு","அனைவரையும் ஆராய்வது ஒற்று"],"tr":["Vinaiseyvaar Thamsutram Ventaadhaar Endraangu","Anaivaraiyum Aaraaivadhu Otru"],"en":["His officers, his friends, his enemies,","All these who watch are trusty spies"],"s":"He is a spy who watches all men, to wit, those who are in the king's employment, his relatives, and his enemies","ch":59,"sec":2,"th":"governance"},
  {"n":585,"ta":["கடாஅ உருவொடு கண்ணஞ்சாது யாண்டும்","உகாஅமை வல்லதே ஒற்று"],"tr":["Kataaa Uruvotu Kannanjaadhu Yaantum","Ukaaamai Valladhe Otru"],"en":["Of unsuspected mien and all-unfearing eyes,","Who let no secret out, are trusty spies"],"s":"A spy is one who is able to assume an appearance which may create no suspicion  (in the minds of others), who fears no man's face, and who never reveals  (his purpose)","ch":59,"sec":2,"th":"governance"},
  {"n":586,"ta":["துறந்தார் படிவத்த ராகி இறந்தாராய்ந்து","என்செயினும் சோர்விலது ஒற்று"],"tr":["Thurandhaar Pativaththa Raaki Irandhaaraaindhu","Enseyinum Sorviladhu Otru"],"en":["As monk or devotee, through every hindrance making way,","A spy, whate'er men do, must watchful mind display"],"s":"He is a spy who, assuming the appearance of an ascetic, goes into  (whatever place he wishes), examines into  (all, that is needful), and never discovers himself, whatever may be done to him","ch":59,"sec":2,"th":"governance"},
  {"n":587,"ta":["மறைந்தவை கேட்கவற் றாகி அறிந்தவை","ஐயப்பாடு இல்லதே ஒற்று"],"tr":["Maraindhavai Ketkavar Raaki Arindhavai","Aiyappaatu Illadhe Otru"],"en":["A spy must search each hidden matter out,","And full report must render, free from doubt"],"s":"A spy is one who is able to discover what is hidden and who retains no doubt concerning what he has known","ch":59,"sec":2,"th":"governance"},
  {"n":588,"ta":["ஒற்றொற்றித் தந்த பொருளையும் மற்றுமோர்","ஒற்றினால் ஒற்றிக் கொளல்"],"tr":["Otrotrith Thandha Porulaiyum Matrumor","Otrinaal Otrik Kolal"],"en":["Spying by spies, the things they tell","To test by other spies is well"],"s":"Let not a king receive the information which a spy has discovered and made known to him, until he has examined it by another spy","ch":59,"sec":2,"th":"governance"},
  {"n":589,"ta":["ஒற்றெற் றுணராமை ஆள்க உடன்மூவர்","சொற்றொக்க தேறப் படும்"],"tr":["Otrer Runaraamai Aalka Utanmoovar","Sotrokka Therap Patum"],"en":["One spy must not another see: contrive it so;","And things by three confirmed as truth you know"],"s":"Let a king employ spies so that one may have no knowledge of the other; and when the information of three agrees together, let him receive it","ch":59,"sec":2,"th":"governance"},
  {"n":590,"ta":["சிறப்பறிய ஒற்றின்கண் செய்யற்க செய்யின்","புறப்படுத்தான் ஆகும் மறை"],"tr":["Sirappariya Otrinkan Seyyarka Seyyin","Purappatuththaan Aakum Marai"],"en":["Reward not trusty spy in others' sight,","Or all the mystery will come to light"],"s":"Let not a king publicly confer on a spy any marks of his favour; if he does, he will divulge his own secret","ch":59,"sec":2,"th":"governance"},
  {"n":591,"ta":["உடையர் எனப்படுவது ஊக்கம் அஃதில்லார்","உடையது உடையரோ மற்று"],"tr":["Utaiyar Enappatuvadhu Ookkam Aqdhillaar","Utaiyadhu Utaiyaro Matru"],"en":["'Tis energy gives men o'er that they own a true control;","They nothing own who own not energy of soul"],"s":"Energy makes out the man of property; as for those who are destitute of it, do they  (really) possess what they possess?","ch":60,"sec":2,"th":"effort"},
  {"n":592,"ta":["உள்ளம் உடைமை உடைமை பொருளுடைமை","நில்லாது நீங்கி விடும்"],"tr":["Ullam Utaimai Utaimai Porulutaimai","Nillaadhu Neengi Vitum"],"en":["The wealth of mind man owns a real worth imparts,","Material wealth man owns endures not, utterly departs"],"s":"The possession of  (energy of) mind is true property; the possession of wealth passes away and abides not","ch":60,"sec":2,"th":"effort"},
  {"n":593,"ta":["ஆக்கம் இழந்தேமென்று அல்லாவார் ஊக்கம்","ஒருவந்தம் கைத்துடை யார்"],"tr":["Aakkam Izhandhemendru Allaavaar Ookkam","Oruvandham Kaiththutai Yaar"],"en":["'Lost is our wealth, ' they utter not this cry distressed,","The men of firm concentred energy of soul possessed"],"s":"They who are possessed of enduring energy will not trouble themselves, saying, \"we have lost our property.\"","ch":60,"sec":2,"th":"effort"},
  {"n":594,"ta":["ஆக்கம் அதர்வினாய்ச் செல்லும் அசைவிலா","ஊக்க முடையா னுழை"],"tr":["Aakkam Adharvinaaich Chellum Asaivilaa","Ookka Mutaiyaa Nuzhai"],"en":["The man of energy of soul inflexible,","Good fortune seeks him out and comes a friend to dwell"],"s":"Wealth will find its own way to the man of unfailing energy","ch":60,"sec":2,"th":"effort"},
  {"n":595,"ta":["வெள்ளத் தனைய மலர்நீட்டம் மாந்தர்தம்","உள்ளத் தனையது உயர்வு"],"tr":["Vellath Thanaiya Malarneettam Maandhardham","Ullath Thanaiyadhu Uyarvu"],"en":["With rising flood the rising lotus flower its stem unwinds;","The dignity of men is measured by their minds"],"s":"The stalks of water-flowers are proportionate to the depth of water; so is men's greatness proportionate to their minds","ch":60,"sec":2,"th":"effort"},
  {"n":596,"ta":["உள்ளுவ தெல்லாம் உயர்வுள்ளல் மற்றது","தள்ளினுந் தள்ளாமை நீர்த்து"],"tr":["Ulluva Thellaam Uyarvullal Matradhu","Thallinun Thallaamai Neerththu"],"en":["Whate'er you ponder, let your aim be loftly still,","Fate cannot hinder always, thwart you as it will"],"s":"In all that a king thinks of, let him think of his greatness; and if it should be thrust from him  (by fate), it will have the nature of not being thrust from him","ch":60,"sec":2,"th":"effort"},
  {"n":597,"ta":["சிதைவிடத்து ஒல்கார் உரவோர் புதையம்பிற்","பட்டுப்பா டூன்றுங் களிறு"],"tr":["Sidhaivitaththu Olkaar Uravor Pudhaiyampir","Pattuppaa Toondrung Kaliru"],"en":["The men of lofty mind quail not in ruin's fateful hour,","The elephant retains his dignity mind arrows' deadly shower"],"s":"The strong minded will not faint, even when all is lost; the elephant stands firm, even when wounded by a shower of arrows","ch":60,"sec":2,"th":"effort"},
  {"n":598,"ta":["உள்ளம் இலாதவர் எய்தார் உலகத்து","வள்ளியம் என்னுஞ் செருக்கு"],"tr":["Ullam Ilaadhavar Eydhaar Ulakaththu","Valliyam Ennunj Cherukku"],"en":["The soulless man can never gain","Th' ennobling sense of power with men"],"s":"Those who have no  (greatness of) mind, will not acquire the joy of saying in the world, \"we have excercised liaberality\"","ch":60,"sec":2,"th":"effort"},
  {"n":599,"ta":["பரியது கூர்ங்கோட்டது ஆயினும் யானை","஦வ்ருஉம் புலிதாக் குறின்"],"tr":["Pariyadhu Koorngottadhu Aayinum Yaanai","Veruum Pulidhaak Kurin"],"en":["Huge bulk of elephant with pointed tusk all armed,","When tiger threatens shrinks away alarmed"],"s":"Although the elephant has a large body, and a sharp tusk, yet it fears the attack of the tiger","ch":60,"sec":2,"th":"effort"},
  {"n":600,"ta":["உரமொருவற்கு உள்ள வெறுக்கைஅஃ தில்லார்","மரம்மக்க ளாதலே வேறு"],"tr":["Uramoruvarku Ulla Verukkaiaq Thillaar","Marammakka Laadhale Veru"],"en":["Firmness of soul in man is real excellance;","Others are trees, their human form a mere pretence"],"s":"Energy is mental wealth; those men who are destitute of it are only trees in the form of men","ch":60,"sec":2,"th":"effort"},
  {"n":601,"ta":["குடியென்னும் குன்றா விளக்கம் மடியென்னும்","மாசூர மாய்ந்து கெடும்"],"tr":["Kutiyennum Kundraa Vilakkam Matiyennum","Maasoora Maaindhu Ketum"],"en":["Of household dignity the lustre beaming bright,","Flickers and dies when sluggish foulness dims its light"],"s":"By the darkness, of idleness, the indestructible lamp of family  (rank) will be extinguished","ch":61,"sec":2,"th":"effort"},
  {"n":602,"ta":["மடியை மடியா ஒழுகல் குடியைக்","குடியாக வேண்டு பவர்"],"tr":["Matiyai Matiyaa Ozhukal Kutiyaik","Kutiyaaka Ventu Pavar"],"en":["Let indolence, the death of effort, die,","If you'd uphold your household's dignity"],"s":"Let those, who desire that their family may be illustrious, put away all idleness from their conduct","ch":61,"sec":2,"th":"effort"},
  {"n":603,"ta":["மடிமடிக் கொண்டொழுகும் பேதை பிறந்த","குடிமடியும் தன்னினும் முந்து"],"tr":["Matimatik Kontozhukum Pedhai Pirandha","Kutimatiyum Thanninum Mundhu"],"en":["Who fosters indolence within his breast, the silly elf!","The house from which he springs shall perish ere himself"],"s":"The  (lustre of the) family of the ignorant man, who acts under the influence of destructive laziness will perish, even before he is dead","ch":61,"sec":2,"th":"effort"},
  {"n":604,"ta":["குடிமடிந்து குற்றம் பெருகும் மடிமடிந்து","மாண்ட உஞற்றி லவர்க்கு"],"tr":["Kutimatindhu Kutram Perukum Matimatindhu","Maanta Ugnatri Lavarkku"],"en":["His family decays, and faults unheeded thrive,","Who, sunk in sloth, for noble objects doth not strive"],"s":"Family  (greatness) will be destroyed, and faults will increase, in those men who give way to laziness, and put forth no dignified exertions","ch":61,"sec":2,"th":"effort"},
  {"n":605,"ta":["நெடுநீர் மறவி மடிதுயில் நான்கும்","கெடுநீரார் காமக் கலன்"],"tr":["Netuneer Maravi Matidhuyil Naankum","Ketuneeraar Kaamak Kalan"],"en":["Delay, oblivion, sloth, and sleep: these four","Are pleasure-boat to bear the doomed to ruin's shore"],"s":"Procrastination, forgetfulness, idleness, and sleep, these four things, form the vessel which is desired by those destined to destruction","ch":61,"sec":2,"th":"effort"},
  {"n":606,"ta":["படியுடையார் பற்றமைந்தக் கண்ணும் மடியுடையார்","மாண்பயன் எய்தல் அரிது"],"tr":["Patiyutaiyaar Patramaindhak Kannum Matiyutaiyaar","Maanpayan Eydhal Aridhu"],"en":["Though lords of earth unearned possessions gain,","The slothful ones no yield of good obtain"],"s":"It is a rare thing for the idle, even when possessed of the riches of kings who ruled over the whole earth, to derive any great benefit from it","ch":61,"sec":2,"th":"effort"},
  {"n":607,"ta":["இடிபுரிந்து எள்ளுஞ்சொல் கேட்பர் மடிபுரிந்து","மாண்ட உஞற்றி லவர்"],"tr":["Itipurindhu Ellunj Chol Ketpar","Matipurindhu Maanta Ugnatri Lavar"],"en":["Who hug their sloth, nor noble works attempt,","Shall bear reproofs and words of just contempt"],"s":"Those who through idleness, and do not engage themselves in dignified exertion, will subject","ch":61,"sec":2,"th":"effort"},
  {"n":608,"ta":["மடிமை குடிமைக்கண் தங்கின்தன் ஒன்னார்க்கு","அடிமை புகுத்தி விடும்"],"tr":["Matimai Kutimaikkan Thangindhan Onnaarkku","Atimai Pukuththi Vitum"],"en":["If sloth a dwelling find mid noble family,","Bondsmen to them that hate them shall they be"],"s":"If idleness take up its abode in a king of high birth, it will make him a slave of his enemies","ch":61,"sec":2,"th":"effort"},
  {"n":609,"ta":["குடியாண்மை யுள்வந்த குற்றம் ஒருவன்","மடியாண்மை மாற்றக் கெடும்"],"tr":["Kutiyaanmai Yulvandha Kutram Oruvan","Matiyaanmai Maatrak Ketum"],"en":["Who changes slothful habits saves","Himself from all that household rule depraves"],"s":"When a man puts away idleness, the reproach which has come upon himself and his family will disappear","ch":61,"sec":2,"th":"effort"},
  {"n":610,"ta":["மடியிலா மன்னவன் எய்தும் அடியளந்தான்","தாஅய தெல்லாம் ஒருங்கு"],"tr":["Matiyilaa Mannavan Eydhum Atiyalandhaan","Thaaaya Thellaam Orungu"],"en":["The king whose life from sluggishness is rid,","Shall rule o'er all by foot of mighty god bestrid"],"s":"The king who never gives way to idleness will obtain entire possession of  (the whole earth) passed over by him who measured  (the worlds) with His foot","ch":61,"sec":2,"th":"effort"},
  {"n":611,"ta":["அருமை உடைத்தென்று அசாவாமை வேண்டும்","பெருமை முயற்சி தரும்"],"tr":["Arumai Utaiththendru Asaavaamai Ventum","Perumai Muyarsi Tharum"],"en":["Say not, 'Tis hard', in weak, desponding hour,","For strenuous effort gives prevailing power"],"s":"Yield not to the feebleness which says, \"this is too difficult to be done\"; labour will give the greatness  (of mind) which is necessary  (to do it)","ch":62,"sec":2,"th":"effort"},
  {"n":612,"ta":["வினைக்கண் வினைகெடல் ஓம்பல் வினைக்குறை","தீர்ந்தாரின் தீர்ந்தன்று உலகு"],"tr":["Vinaikkan Vinaiketal Ompal Vinaikkurai","Theerndhaarin Theerndhandru Ulaku"],"en":["In action be thou, 'ware of act's defeat;","The world leaves those who work leave incomplete"],"s":"Take care not to give up exertion in the midst of a work; the world will abandon those who abandon their unfinished work","ch":62,"sec":2,"th":"effort"},
  {"n":613,"ta":["தாளாண்மை என்னும் தகைமைக்கண் தங்கிற்றே","வேளாண்மை என்னுஞ் செருக்கு"],"tr":["Thaalaanmai Ennum Thakaimaikkan Thangitre","Velaanmai Ennunj Cherukku"],"en":["In strenuous effort doth reside","The power of helping others: noble pride"],"s":"The lustre of munificence will dwell only with the dignity of laboriousness or efforts","ch":62,"sec":2,"th":"effort"},
  {"n":614,"ta":["தாளாண்மை இல்லாதான் வேளாண்மை பேடிகை","வாளாண்மை போலக் கெடும்"],"tr":["Thaalaanmai Illaadhaan Velaanmai Petikai","Vaalaanmai Polak Ketum"],"en":["Beneficent intent in men by whom no strenuous work is wrought,","Like battle-axe in sexless being's hand availeth nought"],"s":"The liberality of him, who does not labour, will fail, like the manliness of a hermaphrodite, who has a sword in its hand","ch":62,"sec":2,"th":"effort"},
  {"n":615,"ta":["இன்பம் விழையான் வினைவிழைவான் தன்கேளிர்","துன்பம் துடைத்தூன்றும் தூண்"],"tr":["Inpam Vizhaiyaan Vinaivizhaivaan Thankelir","Thunpam Thutaiththoondrum Thoon"],"en":["Whose heart delighteth not in pleasure, but in action finds delight,","He wipes away his kinsmen's grief and stands the pillar of their might"],"s":"He who desires not pleasure, but desires labour, will be a pillar to sustain his relations, wiping away their sorrows","ch":62,"sec":2,"th":"effort"},
  {"n":616,"ta":["முயற்சி திருவினை ஆக்கும் முயற்றின்மை","இன்மை புகுத்தி விடும்"],"tr":["Muyarsi Thiruvinai Aakkum Muyatrinmai","Inmai Pukuththi Vitum"],"en":["Effort brings fortune's sure increase,","Its absence brings to nothingness"],"s":"Labour will produce wealth; idleness will bring poverty","ch":62,"sec":2,"th":"effort"},
  {"n":617,"ta":["மடியுளாள் மாமுகடி என்ப மடியிலான்","தாளுளான் தாமரையி னாள்"],"tr":["Matiyulaal Maamukati Enpa Matiyilaan","Thaalulaan Thaamaraiyi Naal"],"en":["In sluggishness is seen misfortune's lurid form, the wise declare;","Where man unslothful toils, she of the lotus flower is there"],"s":"They say that the black Mudevi  (the goddess of adversity) dwells with laziness, and the Latchmi  (the goddess of prosperity) dwells with the labour of the industrious","ch":62,"sec":2,"th":"effort"},
  {"n":618,"ta":["பொறியின்மை யார்க்கும் பழியன்று அறிவறிந்து","ஆள்வினை இன்மை பழி"],"tr":["Poriyinmai Yaarkkum Pazhiyandru Arivarindhu","Aalvinai Inmai Pazhi"],"en":["'Tis no reproach unpropitious fate should ban;","But not to do man's work is foul disgrace to man"],"s":"Adverse fate is no disgrace to any one; to be without exertion and without knowing what should be known, is disgrace","ch":62,"sec":2,"th":"effort"},
  {"n":619,"ta":["தெய்வத்தான் ஆகாதெனினும் முயற்சிதன்","மெய்வருத்தக் கூலி தரும்"],"tr":["Theiyaththaan Aagaa Theninum Muyarichidan","Meyvaruthak Kooli Tharum"],"en":["Though fate-divine should make your labour vain;","Effort its labour’s sure reward will gain"],"s":"Even if fate blocks the result, honest effort still pays its own reward.","ch":62,"sec":2,"th":"effort"},
  {"n":620,"ta":["ஊழையும் உப்பக்கம் காண்பர் உலைவின்றித்","தாழாது உஞற்று பவர்"],"tr":["Oozhaiyum Uppakkam Kaanpar Ulaivindrith","Thaazhaadhu Ugnatru Pavar"],"en":["Who strive with undismayed, unfaltering mind,","At length shall leave opposing fate behind"],"s":"They who labour on, without fear and without fainting will see even fate  (put) behind their back","ch":62,"sec":2,"th":"effort"},
  {"n":621,"ta":["இடுக்கண் வருங்கால் நகுக அதனை","அடுத்தூர்வது அஃதொப்ப தில்"],"tr":["Itukkan Varungaal Nakuka Adhanai","Atuththoorvadhu Aqdhoppa Thil"],"en":["Smile, with patient, hopeful heart, in troublous hour;","Meet and so vanquish grief; nothing hath equal power"],"s":"If troubles come, laugh; there is nothing like that, to press upon and drive away sorrow","ch":63,"sec":2,"th":"effort"},
  {"n":622,"ta":["வெள்ளத் தனைய இடும்பை அறிவுடையான்","உள்ளத்தின் உள்ளக் கெடும்"],"tr":["Vellath Thanaiya Itumpai Arivutaiyaan","Ullaththin Ullak Ketum"],"en":["Though sorrow, like a flood, comes rolling on,","When wise men's mind regards it,  it is gone"],"s":"A flood of troubles will be overcome by the  (courageous) thought which the minds of the wise will entertain, even in sorrow","ch":63,"sec":2,"th":"effort"},
  {"n":623,"ta":["இடும்பைக்கு இடும்பை படுப்பர் இடும்பைக்கு","இடும்பை படாஅ தவர்"],"tr":["Itumpaikku Itumpai Patuppar Itumpaikku","Itumpai Pataaa Thavar"],"en":["Who griefs confront with meek, ungrieving heart,","From them griefs, put to grief, depart"],"s":"They give sorrow to sorrow, who in sorrow do not suffer sorrow","ch":63,"sec":2,"th":"effort"},
  {"n":624,"ta":["மடுத்தவா யெல்லாம் பகடன்னான் உற்ற","இடுக்கண் இடர்ப்பாடு உடைத்து"],"tr":["Matuththavaa Yellaam Pakatannaan Utra","Itukkan Itarppaatu Utaiththu"],"en":["Like bullock struggle on through each obstructed way;","From such an one will troubles, troubled, roll away"],"s":"Troubles will vanish  (i. e., will be troubled) before the man who  (struggles against difficulties) as a","ch":63,"sec":2,"th":"effort"},
  {"n":625,"ta":["அடுக்கி வரினும் அழிவிலான் உற்ற","இடுக்கண் இடுக்கட் படும்"],"tr":["Atukki Varinum Azhivilaan Utra","Itukkan Itukkat Patum"],"en":["When griefs press on, but fail to crush the patient heart,","Then griefs defeated, put to grief, depart"],"s":"The troubles of that man will be troubled  (and disappear) who, however thickly they may come upon him, does not abandon  (his purpose)","ch":63,"sec":2,"th":"effort"},
  {"n":626,"ta":["அற்றேமென்று அல்லற் படுபவோ பெற்றேமென்று","ஓம்புதல் தேற்றா தவர்"],"tr":["Atremendru Allar Patupavo Petremendru","Ompudhal Thetraa Thavar"],"en":["Who boasted not of wealth, nor gave it all their heart,","Will not bemoan the loss, when prosperous days depart"],"s":"Will those men ever cry out in sorrow, \"we are destitute\" who,  (in their prosperity), give not way to  (undue desire) to keep their wealth","ch":63,"sec":2,"th":"effort"},
  {"n":627,"ta":["இலக்கம் உடம்பிடும்பைக் கென்று கலக்கத்தைக்","கையாறாக் கொள்ளாதாம் மேல்"],"tr":["Ilakkam Utampitumpaik Kendru Kalakkaththaik","Kaiyaaraak Kollaadhaam Mel"],"en":["'Man's frame is sorrow's target', the noble mind reflects,","Nor meets with troubled mind the sorrows it expects"],"s":"The great will not regard trouble as trouble, knowing that the body is the butt of trouble","ch":63,"sec":2,"th":"effort"},
  {"n":628,"ta":["இன்பம் விழையான் இடும்பை இயல்பென்பான்","துன்பம் உறுதல் இலன்"],"tr":["Inpam Vizhaiyaan Itumpai Iyalpenpaan","Thunpam Urudhal Ilan"],"en":["He seeks not joy, to sorrow man is born, he knows;","Such man will walk unharmed by touch of human woes"],"s":"That man never experiences sorrow, who does not seek for pleasure, and who considers distress to be natural  (to man)","ch":63,"sec":2,"th":"effort"},
  {"n":629,"ta":["இன்பத்துள் இன்பம் விழையாதான் துன்பத்துள்","துன்பம் உறுதல் இலன்"],"tr":["Inpaththul Inpam Vizhaiyaadhaan Thunpaththul","Thunpam Urudhal Ilan"],"en":["Mid joys he yields not heart to joys' control","Mid sorrows, sorrow cannot touch his soul"],"s":"He does not suffer sorrow, in sorrow who does not look for pleasure in pleasure","ch":63,"sec":2,"th":"effort"},
  {"n":630,"ta":["இன்னாமை இன்பம் எனக்கொளின் ஆகுந்தன்","ஒன்னார் விழையுஞ் சிறப்பு"],"tr":["Innaamai Inpam Enakkolin Aakundhan","Onnaar Vizhaiyunj Chirappu"],"en":["Who pain as pleasure takes, he shall acquire","The bliss to which his foes in vain aspire"],"s":"The elevation, which even his enemies will esteem, will be gained by him, who regards pain as pleasure","ch":63,"sec":2,"th":"effort"},
  {"n":631,"ta":["கருவியும் காலமும் செய்கையும் செய்யும்","அருவினையும் மாண்டது அமைச்சு"],"tr":["Karuviyum Kaalamum Seykaiyum Seyyum","Aruvinaiyum Maantadhu Amaichchu"],"en":["A minister is he who grasps, with wisdom large,","Means, time, work's mode, and functions rare he must discharge"],"s":"The minister is one who can make an excellent choice of means, time, manner of execution, and the difficult undertaking  (itself)","ch":64,"sec":2,"th":"governance"},
  {"n":632,"ta":["வன்கண் குடிகாத்தல் கற்றறிதல் ஆள்வினையோடு","ஐந்துடன் மாண்டது அமைச்சு"],"tr":["Vankan Kutikaaththal Katraridhal Aalvinaiyotu","Aindhutan Maantadhu Amaichchu"],"en":["A minister must greatness own of guardian power, determined mind,","Learn'd wisdom, manly effort with the former five combined"],"s":"The minister is one who in addition to the aforesaid five things excels in the possession of firmness,","ch":64,"sec":2,"th":"governance"},
  {"n":633,"ta":["பிரித்தலும் பேணிக் கொளலும் பிரிந்தார்ப்","பொருத்தலும் வல்ல தமைச்சு"],"tr":["Piriththalum Penik Kolalum Pirindhaarp","Poruththalum Valla Thamaichchu"],"en":["A minister is he whose power can foes divide,","Attach more firmly friends, of severed ones can heal the breaches wide"],"s":"The minister is one who can effect discord  (among foes), maintain the good-will of his friends and restore to friendship those who have seceded  (from him)","ch":64,"sec":2,"th":"governance"},
  {"n":634,"ta":["தெரிதலும் தேர்ந்து செயலும் ஒருதலையாச்","சொல்லலும் வல்லது அமைச்சு"],"tr":["Theridhalum Therndhu Seyalum Orudhalaiyaach","Chollalum Valladhu Amaichchu"],"en":["A minister has power to see the methods help afford,","To ponder long, then utter calm conclusive word"],"s":"The minister is one who is able to comprehend  (the whole nature of an undertaking), execute it in the best manner possible, and offer assuring advice  (in time of necessity)","ch":64,"sec":2,"th":"governance"},
  {"n":635,"ta":["அறனறிந்து ஆன்றமைந்த சொல்லான்எஞ் ஞான்றுந்","திறனறிந்தான் தேர்ச்சித் துணை"],"tr":["Aranarindhu Aandramaindha Sollaanenj Gnaandrun","Thiranarindhaan Therchchith Thunai"],"en":["The man who virtue knows, has use of wise and pleasant words","With plans for every season apt, in counsel aid affords"],"s":"He is the best helper  (of the king) who understanding the duties, of the latter, is by his special learning, able to tender the fullest advice, and at all times conversant with the best method  (of","ch":64,"sec":2,"th":"governance"},
  {"n":636,"ta":["மதிநுட்பம் நூலோடு உடையார்க்கு அதிநுட்பம்","யாவுள முன்நிற் பவை"],"tr":["Madhinutpam Noolotu Utaiyaarkku Adhinutpam","Yaavula Munnir Pavai"],"en":["When native subtilty combines with sound scholastic lore,","'Tis subtilty surpassing all, which nothing stands before"],"s":"What  (contrivances) are there so acute as to resist those who possess natural acuteness in addition to learning?","ch":64,"sec":2,"th":"governance"},
  {"n":637,"ta":["செயற்கை அறிந்தக் கடைத்தும் உலகத்து","இயற்கை அறிந்து செயல்"],"tr":["Seyarkai Arindhak Kataiththum Ulakaththu","Iyarkai Arindhu Seyal"],"en":["Though knowing all that books can teach, 'tis truest tact","To follow common sense of men in act"],"s":"Though you are acquainted with the  (theoretical) methods  (of performing an act), understand the ways of the world and act accordingly","ch":64,"sec":2,"th":"governance"},
  {"n":638,"ta":["அறிகொன்று அறியான் எனினும் உறுதி","உழையிருந்தான் கூறல் கடன்"],"tr":["Arikondru Ariyaan Eninum Urudhi","Uzhaiyirundhaan Kooral Katan"],"en":["'Tis duty of the man in place aloud to say","The very truth, though unwise king may cast his words away"],"s":"Although the king be utterly ignorant, it is the duty of the minister to give  (him) sound advice","ch":64,"sec":2,"th":"governance"},
  {"n":639,"ta":["பழுதெண்ணும் மந்திரியின் பக்கததுள் தெவ்வோர்","எழுபது கோடி உறும்"],"tr":["Pazhudhennum Mandhiriyin Pakkadhadhul Thevvor","Ezhupadhu Koti Urum"],"en":["A minister who by king's side plots evil things","Worse woes than countless foemen brings"],"s":"Far better are seventy crores of enemies  (for a king) than a minister at his side who intends  (his) ruin","ch":64,"sec":2,"th":"governance"},
  {"n":640,"ta":["முறைப்படச் சூழ்ந்தும் முடிவிலவே செய்வர்","திறப்பாடு இலாஅ தவர்"],"tr":["Muraippatach Choozhndhum Mutivilave Seyvar","Thirappaatu Ilaaa Thavar"],"en":["For gain of end desired just counsel nought avails","To minister, when tact in execution fails"],"s":"Those ministers who are destitute of  (executive) ability will fail to carry out their projects, although they may have contrived aright","ch":64,"sec":2,"th":"governance"},
  {"n":641,"ta":["நாநலம் என்னும் நலனுடைமை அந்நலம்","யாநலத்து உள்ளதூஉம் அன்று"],"tr":["Naanalam Ennum Nalanutaimai Annalam","Yaanalaththu Ulladhooum Andru"],"en":["A tongue that rightly speaks the right is greatest gain,","It stands alone midst goodly things that men obtain"],"s":"The possession of that goodness which is called the goodness of speech is  (even to others) better than any other goodness","ch":65,"sec":2,"th":"governance"},
  {"n":642,"ta":["ஆக்கமுங் கேடும் அதனால் வருதலால்","காத்தோம்பல் சொல்லின்கட் சோர்வு"],"tr":["Aakkamung Ketum Adhanaal Varudhalaal","Kaaththompal Sollinkat Sorvu"],"en":["Since gain and loss in life on speech depend,","From careless slip in speech thyself defend"],"s":"Since  (both) wealth and evil result from  (their) speech, ministers should most carefully guard themselves against faultiness therein","ch":65,"sec":2,"th":"governance"},
  {"n":643,"ta":["கேட்டார்ப் பிணிக்கும் தகையவாய்க் கேளாரும்","வேட்ப மொழிவதாம் சொல்"],"tr":["Kettaarp Pinikkum Thakaiyavaaik Kelaarum","Vetpa Mozhivadhaam Sol"],"en":["'Tis speech that spell-bound holds the listening ear,","While those who have not heard desire to hear"],"s":"The  (minister's) speech is that which seeks  (to express) elements as bind his friends  (to himself) and is so delivered as to make even his enemies desire  (his friendship)","ch":65,"sec":2,"th":"governance"},
  {"n":644,"ta":["திறனறிந்து சொல்லுக சொல்லை அறனும்","பொருளும் அதனினூஉங்கு இல்"],"tr":["Thiranarindhu Solluka Sollai Aranum","Porulum Adhaninooungu Il"],"en":["Speak words adapted well to various hearers' state;","No higher virtue lives, no gain more surely great"],"s":"Understand the qualities  (of your hearers) and  (then) make your speech; for superior to it, there is neither virtue nor wealth","ch":65,"sec":2,"th":"governance"},
  {"n":645,"ta":["சொல்லுக சொல்லைப் பிறிதோர்சொல் அச்சொல்லை","வெல்லுஞ்சொல் இன்மை அறிந்து"],"tr":["Solluka Sollaip Piridhorsol Achchollai","Vellunjol Inmai Arindhu"],"en":["Speak out your speech, when once 'tis past dispute","That none can utter speech that shall your speech refute"],"s":"Deliver your speech, after assuring yourself that no counter speech can defeat your own","ch":65,"sec":2,"th":"governance"},
  {"n":646,"ta":["வேட்பத்தாஞ் சொல்லிப் பிறர்சொல் பயன்கோடல்","மாட்சியின் மாசற்றார் கோள்"],"tr":["Vetpaththaanj Chollip Pirarsol Payankotal","Maatchiyin Maasatraar Kol"],"en":["Charming each hearer's ear, of others' words to seize the sense,","Is method wise of men of spotless excellence"],"s":"It is the opinion of those who are free from defects in diplomacy that the minister should speak so as to make his hearers desire  (to hear more) and grasp the meaning of what he hears himself","ch":65,"sec":2,"th":"governance"},
  {"n":647,"ta":["சொலல்வல்லன் சோர்விலன் அஞ்சான் அவனை","இகல்வெல்லல் யார்க்கும் அரிது"],"tr":["Solalvallan Sorvilan Anjaan Avanai","Ikalvellal Yaarkkum Aridhu"],"en":["Mighty in word, of unforgetful mind, of fearless speech,","'Tis hard for hostile power such man to overreach"],"s":"It is impossible for any one to conquer him by intrique who possesses power of speech, and is neither faulty nor timid","ch":65,"sec":2,"th":"governance"},
  {"n":648,"ta":["விரைந்து தொழில்கேட்கும் ஞாலம் நிரந்தினிது","சொல்லுதல் வல்லார்ப் பெறின்"],"tr":["Viraindhu Thozhilketkum Gnaalam Nirandhinidhu","Solludhal Vallaarp Perin"],"en":["Swiftly the listening world will gather round,","When men of mighty speech the weighty theme propound"],"s":"If there be those who can speak on various subjects in their proper order and in a pleasing manner, the world would readily accept them","ch":65,"sec":2,"th":"governance"},
  {"n":649,"ta":["பலசொல்லக் காமுறுவர் மன்றமா சற்ற","சிலசொல்லல் தேற்றா தவர்"],"tr":["Palasollak Kaamuruvar Mandramaa Satra","Silasollal Thetraa Thavar"],"en":["Who have not skill ten faultless words to utter plain,","Their tongues will itch with thousand words man's ears to pain"],"s":"They will desire to utter many words, who do not know how to speak a few faultless ones","ch":65,"sec":2,"th":"governance"},
  {"n":650,"ta":["இணருழ்த்தும் நாறா மலரனையர் கற்றது","உணர விரித்துரையா தார்"],"tr":["Inaruzhththum Naaraa Malaranaiyar Katradhu","Unara Viriththuraiyaa Thaar"],"en":["Like scentless flower in blooming garland bound","Are men who can't their lore acquired to other's ears expound"],"s":"Those who are unable to set forth their acquirements  (before others) are like flowers blossoming in a cluster and yet without fragrance","ch":65,"sec":2,"th":"governance"},
  {"n":651,"ta":["துணைநலம் ஆக்கம் த்ருஉம் வினைநலம்","வேண்டிய எல்லாந் தரும்"],"tr":["Thunainalam Aakkam Tharuum Vinainalam","Ventiya Ellaan Tharum"],"en":["The good external help confers is worldly gain;","By action good men every needed gift obtain"],"s":"The efficacy of support will yield  (only) wealth;  (but) the efficacy of action will yield all that is desired","ch":66,"sec":2,"th":"effort"},
  {"n":652,"ta":["என்றும் ஒருவுதல் வேண்டும் புகழொடு","நன்றி பயவா வினை"],"tr":["Endrum Oruvudhal Ventum Pukazhotu","Nandri Payavaa Vinai"],"en":["From action evermore thyself restrain","Of glory and of good that yields no gain"],"s":"Ministers should at all times avoid acts which, in addition to fame, yield no benefit  (for the future)","ch":66,"sec":2,"th":"effort"},
  {"n":653,"ta":["ஒஓதல் வேண்டும் ஒளிமாழ்கும் செய்வினை","ஆஅதும் என்னு மவர்"],"tr":["Oodhal Ventum Olimaazhkum Seyvinai","Aaadhum Ennu Mavar"],"en":["Who tell themselves that nobler things shall yet be won","All deeds that dim the light of glory must they shun"],"s":"Those who say, \"we will become  (better)\" should avoid the performance of acts that would destroy  (their fame)","ch":66,"sec":2,"th":"effort"},
  {"n":654,"ta":["இடுக்கண் படினும் இளிவந்த செய்யார்","நடுக்கற்ற காட்சி யவர்"],"tr":["Itukkan Patinum Ilivandha Seyyaar","Natukkatra Kaatchi Yavar"],"en":["Though troubles press, no shameful deed they do,","Whose eyes the ever-during vision view"],"s":"Those who have infallible judgement though threatened with peril will not do acts which have brought disgrace  (on former ministers)","ch":66,"sec":2,"th":"effort"},
  {"n":655,"ta":["எற்றென்று இரங்குவ செய்யற்க செய்வானேல்","மற்றன்ன செய்யாமை நன்று"],"tr":["Etrendru Iranguva Seyyarka Seyvaanel","Matranna Seyyaamai Nandru"],"en":["Do nought that soul repenting must deplore,","If thou hast sinned, 'tis well if thou dost sin no more"],"s":"Let a minister never do acts of which he would have to grieve saying, \"what is this I have done\";  (but) should he do  (them), it were good that he grieved not","ch":66,"sec":2,"th":"effort"},
  {"n":656,"ta":["ஈன்றாள் பசிகாண்பான் ஆயினுஞ் செய்யற்க","சான்றோர் பழிக்கும் வினை"],"tr":["Eendraal Pasikaanpaan Aayinunj Cheyyarka","Saandror Pazhikkum Vinai"],"en":["Though her that bore thee hung'ring thou behold, no deed","Do thou, that men of perfect soul have crime decreed"],"s":"Though a minister may see his mother starve; let him do not act which the wise would  (treat with contempt)","ch":66,"sec":2,"th":"effort"},
  {"n":657,"ta":["பழிமலைந்து எய்திய ஆக்கத்தின் சான்றோர்","கழிநல் குரவே தலை"],"tr":["Pazhimalaindhu Eydhiya Aakkaththin Saandror","Kazhinal Kurave Thalai"],"en":["Than store of wealth guilt-laden souls obtain,","The sorest poverty of perfect soul is richer gain"],"s":"Far more excellent is the extreme poverty of the wise than wealth obtained by heaping up of sinful","ch":66,"sec":2,"th":"effort"},
  {"n":658,"ta":["கடிந்த கடிந்தொரார் செய்தார்க்கு அவைதாம்","முடிந்தாலும் பீழை தரும்"],"tr":["Katindha Katindhoraar Seydhaarkku Avaidhaam","Mutindhaalum Peezhai Tharum"],"en":["To those who hate reproof and do forbidden thing","What prospers now, in after days shall anguish bring"],"s":"The actions of those, who have not desisted from doing deeds forbidden  (by the great), will, even if they succeed, cause them sorrow","ch":66,"sec":2,"th":"effort"},
  {"n":659,"ta":["அழக்கொண்ட எல்லாம் அழப்போம் இழப்பினும்","பிற்பயக்கும் நற்பா லவை"],"tr":["Azhak Konta Ellaam Azhappom","Izhappinum Pirpayakkum Narpaa Lavai"],"en":["What's gained through tears with tears shall go;","From loss good deeds entail harvests of blessings grow"],"s":"All that has been obtained with tears  (to the victim) will depart with tears  (to himself); but what has been by fair means; though with loss at first, will afterwards yield fruit","ch":66,"sec":2,"th":"effort"},
  {"n":660,"ta":["சலத்தால் பொருள்செய்தே மார்த்தல் பசுமண்","கலத்துள்நீர் பெய்திரீஇ யற்று"],"tr":["Salaththaal Porulseydhe Maarththal Pasuman","Kalaththulneer Peydhireei Yatru"],"en":["In pot of clay unburnt he water pours and would retain,","Who seeks by wrong the realm in wealth and safety to maintain"],"s":"(For a minister) to protect  (his king) with wealth obtained by foul means is like preserving a vessel of wet clay by filling it with water","ch":66,"sec":2,"th":"effort"},
  {"n":661,"ta":["வினைத்திட்பம் என்பது ஒருவன் மனத்திட்பம்","மற்றைய எல்லாம் பிற"],"tr":["Vinaiththitpam Enpadhu Oruvan Manaththitpam","Matraiya Ellaam Pira"],"en":["What men call 'power in action' know for 'power of mind","'Externe to man all other aids you find"],"s":"Firmness in action is  (simply) one's firmness of mind; all other  (abilities) are not of this nature","ch":67,"sec":2,"th":"governance"},
  {"n":662,"ta":["ஊறொரால் உற்றபின் ஒல்காமை இவ்விரண்டின்","ஆறென்பர் ஆய்ந்தவர் கோள்"],"tr":["Oororaal Utrapin Olkaamai Ivvirantin","Aarenpar Aaindhavar Kol"],"en":["'Each hindrance shun', 'unyielding onward press, If obstacle be there,","'These two define your way, so those that search out truth declare"],"s":"Not to perform a ruinous act, and not to be discouraged by the ruinous termination of an act, are the two maxims which, the wise say, from the principles of those who have investigated the subject","ch":67,"sec":2,"th":"governance"},
  {"n":663,"ta":["கடைக்கொட்கச் செய்தக்க தாண்மை இடைக்கொட்கின்","எற்றா விழுமந் தரும்"],"tr":["Kataikkotkach Cheydhakka Thaanmai Itaikkotkin","Etraa Vizhuman Tharum"],"en":["Man's fitting work is known but by success achieved;","In midst the plan revealed brings ruin ne'er to be retrieved"],"s":"So to perform an act as to publish it  (only) at its termination is  (true) manliness; for to announce it beforehand, will cause irremediable sorrow","ch":67,"sec":2,"th":"governance"},
  {"n":664,"ta":["சொல்லுதல் யார்க்கும் எளிய அரியவாம்","சொல்லிய வண்ணம் செயல்"],"tr":["Solludhal Yaarkkum Eliya Ariyavaam","Solliya Vannam Seyal"],"en":["Easy to every man the speech that shows the way;","Hard thing to shape one's life by words they say"],"s":"To say  (how an act is to be performed) is  (indeed) easy for any one; but far difficult it is to do according to what has been said","ch":67,"sec":2,"th":"governance"},
  {"n":665,"ta":["வீறெய்தி மாண்டார் வினைத்திட்பம் வேந்தன்கண்","ஊறெய்தி உள்ளப் படும்"],"tr":["Veereydhi Maantaar Vinaiththitpam Vendhankan","Ooreydhi Ullap Patum"],"en":["The power in act of men renowned and great,","With king acceptance finds and fame through all the state"],"s":"The firmness in action of those who have become great by the excellence  (of their counsel) will, by attaining its fulfilment in the person of the king, be esteemed  (by all).","ch":67,"sec":2,"th":"governance"},
  {"n":666,"ta":["எண்ணிய எண்ணியாங்கு எய்துவர் எண்ணியார்","திண்ணியர் ஆகப் பெறின்"],"tr":["Enniya Enniyaangu Eydhu Enniyaar","Thinniyar Aakap Perin"],"en":["Whate'er men think, ev'n as they think, may men obtain,","If those who think can steadfastness of will retain"],"s":"If those who have planned  (an undertaking) possess firmness  (in executing it) they will obtain what they have desired even as they have desired it","ch":67,"sec":2,"th":"governance"},
  {"n":667,"ta":["உருவுகண்டு எள்ளாமை வேண்டும் உருள்பெருந்தேர்க்கு","அச்சாணி அன்னார் உடைத்து"],"tr":["Uruvukantu Ellaamai Ventum Urulperundherkku","Achchaani Annaar Utaiththu"],"en":["Despise not men of modest bearing; Look not at form, but what men are:","For some there live, high functions sharing, Like linch-pin of the mighty car"],"s":"Let none be despised for  (their) size;  (for) the world has those who resemble the linch-pin of the big rolling car","ch":67,"sec":2,"th":"governance"},
  {"n":668,"ta":["கலங்காது கண்ட வினைக்கண் துளங்காது","தூக்கங் கடிந்து செயல்"],"tr":["Kalangaadhu Kanta Vinaikkan Thulangaadhu","Thookkang Katindhu Seyal"],"en":["What clearly eye discerns as right, with steadfast will,","And mind unslumbering, that should man fulfil"],"s":"An act that has been firmly resolved on must be as firmly carried out without delay","ch":67,"sec":2,"th":"governance"},
  {"n":669,"ta":["துன்பம் உறவரினும் செய்க துணிவாற்றி","இன்பம் பயக்கும் வினை"],"tr":["Thunpam Uravarinum Seyka Thunivaatri","Inpam Payakkum Vinai"],"en":["Though toil and trouble face thee, firm resolve hold fast,","And do the deeds that pleasure yield at last"],"s":"Though it should cause increasing sorrow  (at the outset), do with firmness the act that yield bliss  (in the end)","ch":67,"sec":2,"th":"governance"},
  {"n":670,"ta":["எனைத்திட்பம் எய்தியக் கண்ணும் வினைத்திட்பம்","வேண்டாரை வேண்டாது உலகு"],"tr":["Enaiththitpam Ey Thiyak Kannum","Vinaiththitpam Ventaarai Ventaadhu Ulaku"],"en":["The world desires not men of every power possessed,","Who power in act desire not,  crown of all the rest"],"s":"The great will not esteem those who esteem not firmness of action, whatever other abilities the latter may possess","ch":67,"sec":2,"th":"governance"},
  {"n":671,"ta":["சூழ்ச்சி முடிவு துணிவெய்தல் அத்துணிவு","தாழ்ச்சியுள் தங்குதல் தீது"],"tr":["Soozhchchi Mutivu Thuniveydhal Aththunivu","Thaazhchchiyul Thangudhal Theedhu"],"en":["The Resolve is counsel's end, If resolutions halt","In weak delays, still unfulfilled, 'tis grievous fault"],"s":"Consultation ends in forming a resolution  (to act);  (but) delay in the execution of that resolve is an evil","ch":68,"sec":2,"th":"governance"},
  {"n":672,"ta":["தூங்குக தூங்கிச் செயற்பால தூங்கற்க","தூங்காது செய்யும் வினை"],"tr":["Thoonguka Thoongich Cheyarpaala Thoongarka","Thoongaadhu Seyyum Vinai"],"en":["Slumber when sleepy work's in hand beware","Thou slumber not when action calls for sleepless care"],"s":"Sleep over such  (actions) as may be slept over;  (but) never over such as may not be slept over","ch":68,"sec":2,"th":"governance"},
  {"n":673,"ta":["ஒல்லும்வா யெல்லாம் வினைநன்றே ஒல்லாக்கால்","செல்லும்வாய் நோக்கிச் செயல்"],"tr":["Ollumvaa Yellaam Vinainandre Ollaakkaal","Sellumvaai Nokkich Cheyal"],"en":["When way is clear, prompt let your action be;","When not, watch till some open path you see"],"s":"Whenever it is possible  (to overcome your enemy) the act  (of fighting) is certainly good; if not, endeavour to employ some more successful method","ch":68,"sec":2,"th":"governance"},
  {"n":674,"ta":["வினைபகை என்றிரண்டின் எச்சம் நினையுங்கால்","தீயெச்சம் போலத் தெறும்"],"tr":["Vinaipakai Endrirantin Echcham Ninaiyungaal","Theeyechcham Polath Therum"],"en":["With work or foe, when you neglect some little thing,","If you reflect, like smouldering fire, 'twill ruin bring"],"s":"When duly considered, the incomplete execution of an undertaking and hostility will grow and destroy one like the  (unextinguished) remnant of a fire","ch":68,"sec":2,"th":"governance"},
  {"n":675,"ta":["பொருள்கருவி காலம் வினையிடனொடு ஐந்தும்","இருள்தீர எண்ணிச் செயல்"],"tr":["Porulkaruvi Kaalam Vinaiyitanotu Aindhum","Iruldheera Ennich Cheyal"],"en":["Treasure and instrument and time and deed and place of act","These five, till every doubt remove, think o'er with care exact"],"s":"Do an act after a due consideration of the  (following) five, viz money, means, time, execution and place","ch":68,"sec":2,"th":"governance"},
  {"n":676,"ta":["முடிவும் இடையூறும் முற்றியாங்கு எய்தும்","படுபயனும் பார்த்துச் செயல்"],"tr":["Mutivum Itaiyoorum Mutriyaangu Eydhum","Patupayanum Paarththuch Cheyal"],"en":["Accomplishment, the hindrances, large profits won","By effort these compare,  then let the work be done"],"s":"An act is to be performed after considering the exertion required, the obstacles to be encountered, and the great profit to be gained  (on its completion)","ch":68,"sec":2,"th":"governance"},
  {"n":677,"ta":["செய்வினை செய்வான் செயன்முறை அவ்வினை","உள்ளறிவான் உள்ளம் கொளல்"],"tr":["Seyvinai Seyvaan Seyanmurai Avvinai","Ullarivaan Ullam Kolal"],"en":["Who would succeed must thus begin first let him ask","The thoughts of them who thoroughly know the task"],"s":"The method of performance for one who has begun an act is to ascertain the mind of him who knows the secret thereof","ch":68,"sec":2,"th":"governance"},
  {"n":678,"ta":["வினையான் வினையாக்கிக் கோடல் நனைகவுள்","யானையால் யானையாத் தற்று"],"tr":["Vinaiyaan Vinaiyaakkik Kotal Nanaikavul","Yaanaiyaal Yaanaiyaath Thatru"],"en":["By one thing done you reach a second work's accomplishment;","So furious elephant to snare its fellow brute is sent"],"s":"To make one undertaking the means of accomplishing another  (similar to it) is like making one rutting elephant the means of capturing another","ch":68,"sec":2,"th":"governance"},
  {"n":679,"ta":["நட்டார்க்கு நல்ல செயலின் விரைந்ததே","ஒட்டாரை ஒட்டிக் கொளல்"],"tr":["Nattaarkku Nalla Seyalin Viraindhadhe","Ottaarai Ottik Kolal"],"en":["Than kindly acts to friends more urgent thing to do,","Is making foes to cling as friends attached to you"],"s":"One should rather hasten to secure the alliance of the foes  (of one's foes) than perform good offices to one's friends","ch":68,"sec":2,"th":"governance"},
  {"n":680,"ta":["உறைசிறியார் உள்நடுங்கல் அஞ்சிக் குறைபெறின்","கொள்வர் பெரியார்ப் பணிந்து"],"tr":["Uraisiriyaar Ulnatungal Anjik Kuraiperin","Kolvar Periyaarp Panindhu"],"en":["The men of lesser realm, fearing the people's inward dread,","Accepting granted terms, to mightier ruler bow the head"],"s":"Ministers of small states, afraid of their people being frightened, will yield to and acknowledge their superior foes, if the latter offer them a chance of reconciliation","ch":68,"sec":2,"th":"governance"},
  {"n":681,"ta":["அன்புடைமை ஆன்ற குடிப்பிறத்தல் வேந்தவாம்","பண்புடைமை தூதுரைப்பான் பண்பு"],"tr":["Anputaimai Aandra Kutippiraththal Vendhavaam","Panputaimai Thoodhuraippaan Panpu"],"en":["Benevolence high birth, the courtesy kings love:","These qualities the envoy of a king approve"],"s":"The qualification of an ambassador are affection  (for his relations) a fitting birth, and the possession of attributes pleasing to royalty","ch":69,"sec":2,"th":"governance"},
  {"n":682,"ta":["அன்பறிவு ஆராய்ந்த சொல்வன்மை தூதுரைப்பார்க்கு","இன்றி யமையாத மூன்று"],"tr":["Anparivu Aaraaindha Solvanmai Thoodhuraippaarkku","Indri Yamaiyaadha Moondru"],"en":["Love, knowledge, power of chosen words, three things,","Should he possess who speaks the words of kings"],"s":"Love  (to his sovereign), knowledge  (of his affairs), and a discriminating power of speech  (before other sovereigns) are the three sine qua non qualifications of an ambassador","ch":69,"sec":2,"th":"governance"},
  {"n":683,"ta":["நூலாருள் நூல்வல்லன் ஆகுதல் வேலாருள்","வென்றி வினையுரைப்பான் பண்பு"],"tr":["Noolaarul Noolvallan Aakudhal Velaarul","Vendri Vinaiyuraippaan Panpu"],"en":["Mighty in lore amongst the learned must he be,","Midst jav'lin-bearing kings who speaks the words of victory"],"s":"To be powerful in politics among those who are learned  (in ethics) is the character of him who speaks","ch":69,"sec":2,"th":"governance"},
  {"n":684,"ta":["அறிவுரு வாராய்ந்த கல்விஇம் மூன்றன்","செறிவுடையான் செல்க வினைக்கு"],"tr":["Arivuru Vaaraaindha Kalviim Moondran","Serivutaiyaan Selka Vinaikku"],"en":["Sense, goodly grace, and knowledge exquisite","Who hath these three for envoy's task is fit"],"s":"He may go on a mission  (to foreign rulers) who has combined in him all these three viz,  (natural) sense, an attractive bearing and well-tried learning","ch":69,"sec":2,"th":"governance"},
  {"n":685,"ta":["தொகச்சொல்லித் தூவாத நீக்கி நகச்சொல்லி","நன்றி பயப்பதாந் தூது"],"tr":["Thokach Chollith Thoovaadha Neekki","Nakachcholli Nandri Payappadhaan Thoodhu"],"en":["In terms concise, avoiding wrathful speech, who utters pleasant word,","An envoy he who gains advantage for his lord"],"s":"He is an ambassador who  (in the presence of foreign rulers) speaks briefly, avoids harshness, talks so as to make them smile, and thus brings good  (to his own sovereign)","ch":69,"sec":2,"th":"governance"},
  {"n":686,"ta":["கற்றுக்கண் அஞ்சான் செலச்சொல்லிக் காலத்தால்","தக்கது அறிவதாம் தூது"],"tr":["Katrukkan Anjaan Selachchollik Kaalaththaal","Thakkadhu Arivadhaam Thoodhu"],"en":["An envoy meet is he, well-learned, of fearless eye","Who speaks right home, prepared for each emergency"],"s":"He is an ambassador who having studied  (politics) talks impressively, is not afraid of angry looks, and knows  (to employ) the art suited to the time","ch":69,"sec":2,"th":"governance"},
  {"n":687,"ta":["கடனறிந்து காலங் கருதி இடனறிந்து","எண்ணி உரைப்பான் தலை"],"tr":["Katanarindhu Kaalang Karudhi Itanarindhu","Enni Uraippaan Thalai"],"en":["He is the best who knows what's due, the time considered well,","The place selects, then ponders long ere he his errand tell"],"s":"He is chief  (among ambassadors) who understands the proper decorum  (before foreign princes), seeks the  (proper) occasion, knows the  (most suitable) place, and delivers his message after  (due)","ch":69,"sec":2,"th":"governance"},
  {"n":688,"ta":["தூய்மை துணைமை துணிவுடைமை இம்மூன்றின்","வாய்மை வழியுரைப்பான் பண்பு"],"tr":["Thooimai Thunaimai Thunivutaimai Immoondrin","Vaaimai Vazhiyuraippaan Panpu"],"en":["Integrity, resources, soul determined, truthfulness","Who rightly speaks his message must these marks possess"],"s":"The qualifications of him who faithfully delivers his  (sovereign's) message are purity, the support  (of foreign ministers), and boldness, with truthfulness in addition to the  (aforesaid) three","ch":69,"sec":2,"th":"governance"},
  {"n":689,"ta":["விடுமாற்றம் வேந்தர்க்கு உரைப்பான் வடுமாற்றம்","வாய்சேரா வன்கணவன்"],"tr":["Vitumaatram Vendharkku Uraippaan Vatumaatram","Vaaiseraa Vanka Navan"],"en":["His faltering lips must utter no unworthy thing,","Who stands, with steady eye, to speak the mandates of his king"],"s":"He alone is fit to communicate  (his sovereign's) reply, who possesses the firmness not to utter even inadvertently what may reflect discredit  (on the latter)","ch":69,"sec":2,"th":"governance"},
  {"n":690,"ta":["இறுதி பயப்பினும் எஞ்சாது இறைவற்கு","உறுதி பயப்பதாம் தூது"],"tr":["Irudhi Payappinum Enjaadhu Iraivarku","Urudhi Payappadhaam Thoodhu"],"en":["Death to the faithful one his embassy may bring;","To envoy gains assured advantage for his king"],"s":"He is the ambassador who fearlessly seeks his sovereign's good though it should cost him his life  (to deliver his message)","ch":69,"sec":2,"th":"governance"},
  {"n":691,"ta":["அகலாது அணுகாது தீக்காய்வார் போல்க","இகல்வேந்தர்ச் சேர்ந்தொழுகு வார்"],"tr":["Akalaadhu Anukaadhu Theekkaaivaar Polka","Ikalvendharch Cherndhozhuku Vaar"],"en":["Who warm them at the fire draw not too near, nor keep too much aloof;","Thus let them act who dwell beneath of warlike kings the palace-roof"],"s":"Thus let them act who dwell beneath of warlike kings the palace-roof","ch":70,"sec":2,"th":"governance"},
  {"n":692,"ta":["மன்னர் விழைப விழையாமை மன்னரால்","மன்னிய ஆக்கந் தரும்"],"tr":["Mannar Vizhaipa Vizhaiyaamai Mannaraal","Manniya Aakkan Tharum"],"en":["To those who prize not state that kings are wont to prize,","The king himself abundant wealth supplies"],"s":"For ministers not to cover the things desired by their kings will through the kings themselves yield them everlasting wealth","ch":70,"sec":2,"th":"governance"},
  {"n":693,"ta":["போற்றின் அரியவை போற்றல் கடுத்தபின்","தேற்றுதல் யார்க்கும் அரிது"],"tr":["Potrin Ariyavai Potral Katuththapin","Thetrudhal Yaarkkum Aridhu"],"en":["Who would walk warily, let him of greater faults beware;","To clear suspicions once aroused is an achievement rare"],"s":"Ministers who would save themselves should avoid  (the commission of) serious errors for if the king's suspicion is once roused, no one can remove it","ch":70,"sec":2,"th":"governance"},
  {"n":694,"ta":["செவிச்சொல்லும் சேர்ந்த நகையும் அவித்தொழுகல்","ஆன்ற பெரியா ரகத்து"],"tr":["Sevichchollum Serndha Nakaiyum Aviththozhukal","Aandra Periyaa Rakaththu"],"en":["All whispered words and interchange of smiles repress,","In presence of the men who kingly power possess"],"s":"While in the presence of the sovereign, ministers should neither whisper to nor smile at others","ch":70,"sec":2,"th":"governance"},
  {"n":695,"ta":["எப்பொருளும் ஓரார் தொடரார்மற் றப்பொருளை","விட்டக்கால் கேட்க மறை"],"tr":["Epporulum Oraar Thotaraarmar Rapporulai","Vittakkaal Ketka Marai"],"en":["Seek not, ask not, the secret of the king to hear;","But if he lets the matter forth, give ear"],"s":"(When the king is engaged) in secret counsel  (with others), ministers should neither over-hear anything whatever nor pry into it with inquisitive questions, but  (wait to) listen when it is divulged  (by","ch":70,"sec":2,"th":"governance"},
  {"n":696,"ta":["குறிப்பறிந்து காலங் கருதி வெறுப்பில","வேண்டுப வேட்பச் சொலல்"],"tr":["Kuripparindhu Kaalang Karudhi Veruppila","Ventupa Vetpach Cholal"],"en":["Knowing the signs, waiting for fitting time, with courteous care,","Things not displeasing, needful things, declare"],"s":"Knowing the  (king's disposition and seeking the right time,  (the minister) should in a pleasing manner suggest things such as are desirable and not disagreeable","ch":70,"sec":2,"th":"governance"},
  {"n":697,"ta":["வேட்பன சொல்லி வினையில எஞ்ஞான்றும்","கேட்பினும் சொல்லா விடல்"],"tr":["Vetpana Solli Vinaiyila Egngnaandrum","Ketpinum Sollaa Vital"],"en":["Speak pleasant things, but never utter idle word;","Not though by monarch's ears with pleasure heard"],"s":"Ministers should  (always) give agreeable advice but on no occasion recommend useless actions, though requested  (to do so)","ch":70,"sec":2,"th":"governance"},
  {"n":698,"ta":["இளையர் இனமுறையர் என்றிகழார் நின்ற","ஒளியோடு ஒழுகப் படும்"],"tr":["Ilaiyar Inamuraiyar Endrikazhaar Nindra","Oliyotu Ozhukap Patum"],"en":["Say not, 'He's young, my kinsman, ' despising thus your king;","But reverence the glory kingly state doth bring"],"s":"Ministers should behave in accordance with the  (Divine) light in the person of kings and not despise them saying, \"He is our junior  (in age) and connected with our family!\"","ch":70,"sec":2,"th":"governance"},
  {"n":699,"ta":["கொளப்பட்டேம் என்றெண்ணிக் கொள்ளாத செய்யார்","துளக்கற்ற காட்சி யவர்"],"tr":["Kolappattem Endrennik Kollaadha Seyyaar","Thulakkatra Kaatchi Yavar"],"en":["'We've gained his grace, boots nought what graceless acts we do',","So deem not sages who the changeless vision view"],"s":"Those whose judgement is firm will not do what is disagreeable  (to the sovereign) saying  (within","ch":70,"sec":2,"th":"governance"},
  {"n":700,"ta":["பழையம் எனக்கருதிப் பண்பல்ல செய்யும்","கெழுதகைமை கேடு தரும்"],"tr":["Pazhaiyam Enakkarudhip Panpalla Seyyum","Kezhudhakaimai Ketu Tharum"],"en":["Who think 'We're ancient friends' and do unseemly things;","To these familiarity sure ruin brings"],"s":"The  (foolish) claim with which a minister does unbecoming acts because of his  (long) familiarity  (with the king) will ensure his ruin","ch":70,"sec":2,"th":"governance"},
  {"n":701,"ta":["கூறாமை நோக்கக் குறிப்பறிவான் எஞ்ஞான்றும்","மாறாநீர் வையக் கணி"],"tr":["Kooraamai Nokkake Kuripparivaan Egngnaandrum","Maaraaneer Vaiyak Kani"],"en":["Who knows the sign, and reads unuttered thought, the gem is he,","Of earth round traversed by the changeless sea"],"s":"The minister who by looking  (at the king) understands his mind without being told  (of it), will be a perpetual ornament to the world which is surrounded by a never-drying sea","ch":71,"sec":2,"th":"governance"},
  {"n":702,"ta":["ஐயப் படாஅது அகத்தது உணர்வானைத்","தெய்வத்தோ டொப்பக் கொளல்"],"tr":["Aiyap Pataaadhu Akaththadhu Unarvaanaith","Theyvaththo Toppak Kolal"],"en":["Undoubting, who the minds of men can scan,","As deity regard that gifted man"],"s":"He is to be esteemed a god who is able to ascertain without a doubt what is within  (one's mind)","ch":71,"sec":2,"th":"governance"},
  {"n":703,"ta":["குறிப்பிற் குறிப்புணர் வாரை உறுப்பினுள்","யாது கொடுத்தும் கொளல்"],"tr":["Kurippir Kurippunar Vaarai Uruppinul","Yaadhu Kotuththum Kolal"],"en":["Who by the sign the signs interprets plain,","Give any member up his aid to gain"],"s":"The king should ever give whatever  (is asked) of his belongings and secure him who, by the indications  (of his own mind) is able to read those of another","ch":71,"sec":2,"th":"governance"},
  {"n":704,"ta":["குறித்தது கூறாமைக் கொள்வாரோ டேனை","உறுப்போ ரனையரால் வேறு"],"tr":["Kuriththadhu Kooraamaik Kolvaaro Tenai","Uruppo Ranaiyaraal Veru"],"en":["Who reads what's shown by signs, though words unspoken be,","In form may seem as other men, in function nobler far is he"],"s":"Those who understand one's thoughts without being informed  (thereof) and those who do not, may  (indeed) resemble one another bodily; still are they different  (mentally)","ch":71,"sec":2,"th":"governance"},
  {"n":705,"ta":["குறிப்பிற் குறிப்புணரா வாயின் உறுப்பினுள்","என்ன பயத்தவோ கண்?"],"tr":["Kurippir Kurippunaraa Vaayin Uruppinul","Enna Payaththavo Kan?"],"en":["By sign who knows not sings to comprehend, what gain,","'Mid all his members, from his eyes does he obtain"],"s":"Of what use are the eyes amongst one's members, if they cannot by their own indications dive those of another?","ch":71,"sec":2,"th":"governance"},
  {"n":706,"ta":["அடுத்தது காட்டும் பளிங்குபோல் நெஞ்சம்","கடுத்தது காட்டும் முகம்"],"tr":["Atuththadhu Kaattum Palingupol Nenjam","Katuththadhu Kaattum Mukam"],"en":["As forms around in crystal mirrored clear we find,","The face will show what's throbbing in the mind"],"s":"As the mirror reflects what is near so does the face show what is uppermost in the mind","ch":71,"sec":2,"th":"governance"},
  {"n":707,"ta":["முகத்தின் முதுக்குறைந்தது உண்டோ உவப்பினும்","காயினும் தான்முந் துறும்"],"tr":["Mukaththin Mudhukkuraindhadhu Unto Uvappinum","Kaayinum Thaanmun Thurum"],"en":["Than speaking countenance hath aught more prescient skill?","Rejoice or burn with rage, 'tis the first herald still"],"s":"Is there anything so full of knowledge as the face?  (No) it precedes the mind, whether  (the latter is) pleased or vexed","ch":71,"sec":2,"th":"governance"},
  {"n":708,"ta":["முகம்நோக்கி நிற்க அமையும் அகம்நோக்கி","உற்ற துணர்வார்ப் பெறின்"],"tr":["Mukamnokki Nirka Amaiyum Akamnokki","Utra Thunarvaarp Perin"],"en":["To see the face is quite enough, in presence brought,","When men can look within and know the lurking thought"],"s":"If the king gets those who by looking into his mind can understand  (and remove) what has occurred  (to him) it is enough that he stand looking at their face","ch":71,"sec":2,"th":"governance"},
  {"n":709,"ta":["பகைமையும் கேண்மையும் கண்ணுரைக்கும் கண்ணின்","வகைமை உணர்வார்ப் பெறின்"],"tr":["Pakaimaiyum Kenmaiyum Kannuraikkum Kannin","Vakaimai Unarvaarp Perin"],"en":["The eye speaks out the hate or friendly soul of man;","To those who know the eye's swift varying moods to scan"],"s":"If a king gets ministers who can read the movements of the eye, the eyes  (of foreign kings) will  (themselves) reveal  (to him) their hatred or friendship","ch":71,"sec":2,"th":"governance"},
  {"n":710,"ta":["நுண்ணியம் என்பார் அளக்குங்கோல் காணுங்கால்","கண்ணல்லது இல்லை பிற"],"tr":["Nunniyam Enpaar Alakkungol Kaanungaal","Kannalladhu Illai Pira"],"en":["The men of keen discerning soul no other test apply (When you their secret ask) than man's revealing eye",""],"s":"The measuring-rod of those  (ministers) who say \"we are acute\" will on inquiry be found to be their  (own) eyes and nothing else","ch":71,"sec":2,"th":"governance"},
  {"n":711,"ta":["அவையறிநது ஆராய்ந்து சொல்லுக சொல்லின்","தொகையறிந்த தூய்மை யவர்"],"tr":["Avaiyarinadhu Aaraaindhu Solluka Sollin","Thokaiyarindha Thooimai Yavar"],"en":["Men pure in heart, who know of words the varied force,","Should to their audience known adapt their well-arranged discourse"],"s":"Let the pure who know the arrangement of words speak with deliberation after ascertaining  (the nature of) the court  (then assembled)","ch":72,"sec":2,"th":"governance"},
  {"n":712,"ta":["இடைதெரிந்து நன்குணர்ந்து சொல்லுக சொல்லின்","நடைதெரிந்த நன்மை யவர்"],"tr":["Itaidherindhu Nankunarndhu Solluka Sollin","Nataidherindha Nanmai Yavar"],"en":["Good men to whom the arts of eloquence are known,","Should seek occasion meet, and say what well they've made their own"],"s":"Let the good who know the uses of words speak with a clear knowledge after ascertaining the time  (suited to the court)","ch":72,"sec":2,"th":"governance"},
  {"n":713,"ta":["அவையறியார் சொல்லல்மேற் கொள்பவர் சொல்லின்","வகையறியார் வல்லதூஉம் இல்"],"tr":["Avaiyariyaar Sollalmer Kolpavar Sollin","Vakaiyariyaar Valladhooum Il"],"en":["Unversed in councils, who essays to speak","Knows not the way of suasive words,  and all is weak"],"s":"Those who undertake to speak without knowing the  (nature of the) court are ignorant of the quality of words as well as devoid of the power  (of learning)","ch":72,"sec":2,"th":"governance"},
  {"n":714,"ta":["ஒளியார்முன் ஒள்ளிய ராதல் வெளியார்முன்","வான்சுதை வண்ணம் கொளல்"],"tr":["Oliyaarmun Olliya Raadhal Veliyaarmun","Vaansudhai Vannam Kolal"],"en":["Before the bright ones shine as doth the light","Before the dull ones be as purest stucco white"],"s":"Ministers should be lights in the assembly of the enlightned, but assume the pure whiteness of mortar  (ignorance) in that of fools","ch":72,"sec":2,"th":"governance"},
  {"n":715,"ta":["நன்றென்ற வற்றுள்ளும் நன்றே முதுவருள்","முந்து கிளவாச் செறிவு"],"tr":["Nandrendra Vatrullum Nandre Mudhuvarul","Mundhu Kilavaach Cherivu"],"en":["Midst all good things the best is modest grace,","That speaks not first before the elders' face"],"s":"The modesty by which one does not rush forward and speak in  (an assembly of) superiors is the best among all  (one's) good qualities","ch":72,"sec":2,"th":"governance"},
  {"n":716,"ta":["ஆற்றின் நிலைதளர்ந் தற்றே வியன்புலம்","ஏற்றுணர்வார் முன்னர் இழுக்கு"],"tr":["Aatrin Nilaidhalarn Thatre Viyanpulam","Etrunarvaar Munnar Izhukku"],"en":["As in the way one tottering falls, is slip before","The men whose minds are filled with varied lore"],"s":"(For a minister) to blunder in the presence of those who have acquired a vast store of learning and know  (the value thereof) is like a good man stumbling  (and falling away) from the path  (of virtue)","ch":72,"sec":2,"th":"governance"},
  {"n":717,"ta":["கற்றறிந்தார் கல்வி விளங்கும் கசடறச்","சொல்தெரிதல் வல்லார் அகத்து"],"tr":["Katrarindhaar Kalvi Vilangum Kasatarach","Choldheridhal Vallaar Akaththu"],"en":["The learning of the learned sage shines bright","To those whose faultless skill can value it aright"],"s":"The learning of those who have read and understood  (much) will shine in the assembly of those who faultlessly examine  (the nature of) words","ch":72,"sec":2,"th":"governance"},
  {"n":718,"ta":["உணர்வ துடையார்முன் சொல்லல் வளர்வதன்","பாத்தியுள் நீர்சொரிந் தற்று"],"tr":["Unarva Thutaiyaarmun Sollal Valarvadhan","Paaththiyul Neersorin Thatru"],"en":["To speak where understanding hearers you obtain,","Is sprinkling water on the fields of growing grain"],"s":"Lecturing to those who have the ability to understand  (for themselves) is like watering a bed of plants that are growing  (of themselves)","ch":72,"sec":2,"th":"governance"},
  {"n":719,"ta":["புல்லவையுள் பொச்சாந்தும் சொல்லற்க நல்லவையுள்","நன்குசலச் சொல்லு வார்"],"tr":["Pullavaiyul Pochchaandhum Sollarka Nallavaiyul","Nankusalach Chollu Vaar"],"en":["In councils of the good, who speak good things with penetrating power,","In councils of the mean, let them say nought, e'en in oblivious hour"],"s":"Those who are able to speak good things impressively in an assembly of the good should not even forgetfully speak them in that of the low","ch":72,"sec":2,"th":"governance"},
  {"n":720,"ta":["அங்கணத்துள் உக்க அமிழ்தற்றால் தங்கணத்தார்","அல்லார்முன் கோட்டி கொளல்"],"tr":["Anganaththul Ukka Amizhdhatraal Thanganaththaar","Allaarmun Kotti Kolal"],"en":["Ambrosia in the sewer spilt, is word","Spoken in presence of the alien herd"],"s":"To utter  (a good word) in the assembly of those who are of inferior rank is like dropping nectar on the ground","ch":72,"sec":2,"th":"governance"},
  {"n":721,"ta":["வகையறிந்து வல்லவை வாய்சோரார் சொல்லின்","தொகையறிந்த தூய்மை யவர்"],"tr":["Vakaiyarindhu Vallavai Vaaisoraar Sollin","Thokaiyarindha Thooimai Yavar"],"en":["Men, pure in heart, who know of words the varied force,","The mighty council's moods discern, nor fail in their discourse"],"s":"The pure who know the classification of words having first ascertained the nature  (of the court) will not  (through fear) falter in their speech before the powerful body","ch":73,"sec":2,"th":"governance"},
  {"n":722,"ta":["கற்றாருள் கற்றார் எனப்படுவர் கற்றார்முன்","கற்ற செலச்சொல்லு வார்"],"tr":["Katraarul Katraar Enappatuvar Katraarmun","Katra Selachchollu Vaar"],"en":["Who what they've learned, in penetrating words heve learned to say,","Before the learn'd among the learn'd most learn'd are they"],"s":"Those who can agreeably set forth their acquirements before the learned will be regarded as the most learned among the learned","ch":73,"sec":2,"th":"governance"},
  {"n":723,"ta":["பகையகத்துச் சாவார் எளியர் அரியர்","அவையகத்து அஞ்சா தவர்"],"tr":["Pakaiyakaththuch Chaavaar Eliyar Ariyar","Avaiyakaththu Anjaa Thavar"],"en":["Many encountering death in face of foe will hold their ground;","Who speak undaunted in the council hall are rarely found"],"s":"Many indeed may  (fearlessly) die in the presence of  (their) foes;  (but) few are those who are fearless in the assembly  (of the learned)","ch":73,"sec":2,"th":"governance"},
  {"n":724,"ta":["கற்றார்முன் கற்ற செலச்சொல்லித் தாம்கற்ற","மிக்காருள் மிக்க கொளல்"],"tr":["Katraarmun Katra Selachchollith Thaamkatra","Mikkaarul Mikka Kolal"],"en":["What you have learned, in penetrating words speak out before","The learn'd; but learn what men more learn'd can teach you more"],"s":"(Ministers) should agreeably set forth their acquirements before the learned and acquire more  (knowledge) from their superiors  (in learning)","ch":73,"sec":2,"th":"governance"},
  {"n":725,"ta":["ஆற்றின் அளவறிந்து கற்க அவையஞ்சா","மாற்றங் கொடுத்தற் பொருட்டு"],"tr":["Aatrin Alavarindhu Karka Avaiyanjaa","Maatrang Kotuththar Poruttu"],"en":["By rule, to dialectic art your mind apply,","That in the council fearless you may make an apt reply"],"s":"In order to reply fearlessly before a foreign court,  (ministers) should learn logic according to the rules  (of grammar)","ch":73,"sec":2,"th":"governance"},
  {"n":726,"ta":["வாளொடென் வன்கண்ணர் அல்லார்க்கு நூலொடென்","நுண்ணவை அஞ்சு பவர்க்கு"],"tr":["Vaaloten Vankannar Allaarkku Nooloten","Nunnavai Anju Pavarkku"],"en":["To those who lack the hero's eye what can the sword avail","Or science what, to those before the council keen who quail"],"s":"What have they to do with a sword who are not valiant, or they with learning who are afraid of an intelligent assembly?","ch":73,"sec":2,"th":"governance"},
  {"n":727,"ta":["பகையகத்துப் பேடிகை ஒள்வாள் அவையகத்து","அஞ்சு மவன்கற்ற நூல்"],"tr":["Pakaiyakaththup Petikai Olvaal Avaiyakaththu","Anju Mavankatra Nool"],"en":["As shining sword before the foe which 'sexless being' bears,","Is science learned by him the council's face who fears"],"s":"The learning of him who is diffident before an assembly is like the shining sword of an hermaphrodite in the presence of his foes","ch":73,"sec":2,"th":"governance"},
  {"n":728,"ta":["பல்லவை கற்றும் பயமிலரே நல்லவையுள்","நன்கு செலச்சொல்லா தார்"],"tr":["Pallavai Katrum Payamilare Nallavaiyul","Nanku Selachchollaa Thaar"],"en":["Though many things they've learned, yet useless are they all,","To man who cannot well and strongly speak in council hall"],"s":"Those who cannot agreeably speak good things before a good assembly are indeed unprofitable persons inspite of all their various acquirements","ch":73,"sec":2,"th":"governance"},
  {"n":729,"ta":["கல்லா தவரின் கடையென்ப கற்றறிந்தும்","நல்லா ரவையஞ்சு வார்"],"tr":["Kallaa Thavarin Kataiyenpa Katrarindhum","Nallaa Ravaiyanju Vaar"],"en":["Who, though they've learned, before the council of the good men quake,","Than men unlearn'd a lower place must take"],"s":"They who, though they have learned and understood, are yet afraid of the assembly of the good, are said to be inferior  (even) to the illiterate","ch":73,"sec":2,"th":"governance"},
  {"n":730,"ta":["உளரெனினும் இல்லாரொடு ஒப்பர் களன்அஞ்சிக்","கற்ற செலச்சொல்லா தார்"],"tr":["Ulareninum Illaarotu Oppar Kalananjik","Katra Selachchollaa Thaar"],"en":["Who what they've learned, in penetrating words know not to say,","The council fearing, though they live, as dead are they"],"s":"Those who through fear of the assembly are unable to set forth their learning in an interesting manner, though alive, are yet like the dead","ch":73,"sec":2,"th":"governance"},
  {"n":731,"ta":["தள்ளா விளையுளும் தக்காரும் தாழ்விலாச்","செல்வரும் சேர்வது நாடு"],"tr":["Thallaa Vilaiyulum Thakkaarum Thaazhvilaach","Chelvarum Servadhu Naatu"],"en":["Where spreads fertility unfailing, where resides a band,","Of virtuous men, and those of ample wealth, call that a 'land'"],"s":"A kingdom is that in which  (those who carry on) a complete cultivation, virtuous persons, and","ch":74,"sec":2,"th":"governance"},
  {"n":732,"ta":["பெரும்பொருளால் பெட்டக்க தாகி அருங்கேட்டால்","ஆற்ற விளைவது நாடு"],"tr":["Perumporulaal Pettakka Thaaki Arungettaal","Aatra Vilaivadhu Naatu"],"en":["That is a 'land' which men desire for wealth's abundant share,","Yielding rich increase, where calamities are rare"],"s":"A kingdom is that which is desire for its immense wealth, and which grows greatly in prosperity, being free from destructive causes","ch":74,"sec":2,"th":"governance"},
  {"n":733,"ta":["பொறையொருங்கு மேல்வருங்கால் தாங்கி இறைவற்கு","இறையொருங்கு நேர்வது நாடு"],"tr":["Poraiyorungu Melvarungaal Thaangi Iraivarku","Iraiyorungu Nervadhu Naatu"],"en":["When burthens press, it bears; Yet, With unfailing hand","To king due tribute pays: that is the 'land'"],"s":"A kingdom is that which can bear any burden that may be pressed on it  (from adjoining kingdoms) and  (yet) pay the full tribute to its sovereign","ch":74,"sec":2,"th":"governance"},
  {"n":734,"ta":["உறுபசியும் ஓவாப் பிணியும் செறுபகையும்","சேரா தியல்வது நாடு"],"tr":["Urupasiyum Ovaap Piniyum Serupakaiyum","Seraa Thiyalvadhu Naatu"],"en":["That is a 'land' whose peaceful annals know,","Nor famine fierce, nor wasting plague, nor ravage of the foe"],"s":"A kingdom is that which continues to be free from excessive starvation, irremediable epidemics, and destructive foes","ch":74,"sec":2,"th":"governance"},
  {"n":735,"ta":["பல்குழுவும் பாழ்செய்யும் உட்பகையும் வேந்தலைக்கும்","கொல்குறும்பும் இல்லது நாடு"],"tr":["Palkuzhuvum Paazhseyyum Utpakaiyum Vendhalaikkum","Kolkurumpum Illadhu Naatu"],"en":["From factions free, and desolating civil strife, and band","Of lurking murderers that king afflict, that is the 'land'"],"s":"A kingdom is that which is without various  (irregular) associations, destructive internal enemies, and murderous savages who  (sometimes) harass the sovereign","ch":74,"sec":2,"th":"governance"},
  {"n":736,"ta":["கேடறியாக் கெட்ட இடத்தும் வளங்குன்றா","நாடென்ப நாட்டின் தலை"],"tr":["Ketariyaak Ketta Itaththum Valangundraa","Naatenpa Naattin Thalai"],"en":["Chief of all lands is that, where nought disturbs its peace;","Or, if invaders come, still yields its rich increase"],"s":"The learned say that the best kingdom is that which knows no evil  (from its foes), and, if injured  (at all), suffers no diminution in its fruitfulness","ch":74,"sec":2,"th":"governance"},
  {"n":737,"ta":["இருபுனலும் வாய்ந்த மலையும் வருபுனலும்","வல்லரணும் நாட்டிற்கு உறுப்பு"],"tr":["Irupunalum Vaaindha Malaiyum Varupunalum","Vallaranum Naattirku Uruppu"],"en":["Waters from rains and springs, a mountain near, and waters thence;","These make a land, with fortress' sure defence"],"s":"The constituents of a kingdom are the two waters  (from above and below), well situated hills and an undestructible fort","ch":74,"sec":2,"th":"governance"},
  {"n":738,"ta":["பிணியின்மை செல்வம் விளைவின்பம் ஏமம்","அணியென்ப நாட்டிவ் வைந்து"],"tr":["Piniyinmai Selvam Vilaivinpam Emam","Aniyenpa Naattiv Vaindhu"],"en":["A country's jewels are these five: unfailing health,","Fertility, and joy, a sure defence, and wealth"],"s":"Freedom from epidemics, wealth, produce, happiness and protection  (to subjects); these five, the learned, say, are the ornaments of a kingdom","ch":74,"sec":2,"th":"governance"},
  {"n":739,"ta":["நாடென்ப நாடா வளத்தன நாடல்ல","நாட வளந்தரு நாடு"],"tr":["Naatenpa Naataa Valaththana Naatalla","Naata Valandharu Naatu"],"en":["That is a land that yields increase unsought,","That is no land whose gifts with toil are bought"],"s":"The learned say that those are kingdom whose wealth is not laboured for, and those not, whose wealth is only obtained through labour","ch":74,"sec":2,"th":"governance"},
  {"n":740,"ta":["ஆங்கமை வெய்தியக் கண்ணும் பயமின்றே","வேந்தமை வில்லாத நாடு"],"tr":["Aangamai Veydhiyak Kannum Payamindre","Vendhamai Villaadha Naatu"],"en":["Though blest with all these varied gifts' increase,","A land gains nought that is not with its king at peace"],"s":"Although in possession of all the above mentioned excellences, these are indeed of no use to a country, in the absence of harmony between the sovereign and the sujects","ch":74,"sec":2,"th":"governance"},
  {"n":741,"ta":["ஆற்று பவர்க்கும் அரண்பொருள் அஞ்சித்தற்","போற்று பவர்க்கும் பொருள்"],"tr":["Aatru Pavarkkum Aranporul Anjiththar","Potru Pavarkkum Porul"],"en":["A fort is wealth to those who act against their foes;","Is wealth to them who, fearing, guard themselves from woes"],"s":"A fort is an object of importance to those who march  (against their foes) as well as to those who through fear  (of pursuers) would seek it for shelter","ch":75,"sec":2,"th":"governance"},
  {"n":742,"ta":["மணிநீரும் மண்ணும் மலையும் அணிநிழற்","காடும் உடைய தரண்"],"tr":["Manineerum Mannum Malaiyum Aninizhar","Kaatum Utaiya Tharan"],"en":["A fort is that which owns fount of waters crystal clear,","An open space, a hill, and shade of beauteous forest near"],"s":"A fort is that which has everlasting water, plains, mountains and cool shady forests","ch":75,"sec":2,"th":"governance"},
  {"n":743,"ta":["உயர்வகலம் திண்மை அருமைஇந் நான்கின்","அமைவரண் என்றுரைக்கும் நூல்"],"tr":["Uyarvakalam Thinmai Arumaiin Naankin","Amaivaran Endruraikkum Nool"],"en":["Height, breadth, strength, difficult access:","Science declares a fort must these possess"],"s":"The learned say that a fortress is an enclosure having these four  (qualities) viz, height, breadth, strength and inaccessibility","ch":75,"sec":2,"th":"governance"},
  {"n":744,"ta":["சிறுகாப்பிற் பேரிடத்த தாகி உறுபகை","ஊக்கம் அழிப்ப தரண்"],"tr":["Sirukaappir Peritaththa Thaaki Urupakai","Ookkam Azhippa Tharan"],"en":["A fort must need but slight defence, yet ample be,","Defying all the foeman's energy"],"s":"A fort is that which has an extensive space within, but only small places to be guarded, and such as can destroy the courage of besieging foes","ch":75,"sec":2,"th":"governance"},
  {"n":745,"ta":["கொளற்கரிதாய்க் கொண்டகூழ்த் தாகி அகத்தார்","நிலைக்கெளிதாம் நீரது அரண்"],"tr":["Kolarkaridhaaik Kontakoozhth Thaaki Akaththaar","Nilaikkelidhaam Neeradhu Aran"],"en":["Impregnable, containing ample stores of food,","A fort for those within, must be a warlike station good"],"s":"A fort is that which cannot be captured, which abounds in suitable provisions, and affords a position of easy defence to its inmates","ch":75,"sec":2,"th":"governance"},
  {"n":746,"ta":["எல்லாப் பொருளும் உடைத்தாய் இடத்துதவும்","நல்லாள் உடையது அரண்"],"tr":["Ellaap Porulum Utaiththaai Itaththudhavum","Nallaal Utaiyadhu Aran"],"en":["A fort, with all munitions amply stored,","In time of need should good reserves afford"],"s":"A fort is that which has all  (needful) things, and excellent heroes that can help it against destruction  (by foes)","ch":75,"sec":2,"th":"governance"},
  {"n":747,"ta":["முற்றியும் முற்றா தெறிந்தும் அறைப்படுத்தும்","பற்றற் கரியது அரண்"],"tr":["Mutriyum Mutraa Therindhum Araippatuththum","Patrar Kariyadhu Aran"],"en":["A fort should be impregnable to foes who gird it round,","Or aim there darts from far, or mine beneath the ground"],"s":"A fort is that which cannot be captured by blockading, assaulting, or undermining it","ch":75,"sec":2,"th":"governance"},
  {"n":748,"ta":["முற்றாற்றி முற்றி யவரையும் பற்றாற்றிப்","பற்றியார் வெல்வது அரண்"],"tr":["Mutraatri Mutri Yavaraiyum Patraatrip","Patriyaar Velvadhu Aran"],"en":["Howe'er the circling foe may strive access to win,","A fort should give the victory to those who guard within"],"s":"That is a fort whose inmates are able to overcome without losing their ground, even abler men who have besieged it","ch":75,"sec":2,"th":"governance"},
  {"n":749,"ta":["முனைமுகத்து மாற்றலர் சாய வினைமுகத்து","வீறெய்தி மாண்ட தரண்"],"tr":["Munaimukaththu Maatralar Saaya Vinaimukaththu","Veereydhi Maanta Tharan"],"en":["At outset of the strife a fort should foes dismay;","And greatness gain by deeds in every glorious day"],"s":"A fort is that which derives excellence from the stratagems made  (by its inmates) to defeat their enemies in the battlefield","ch":75,"sec":2,"th":"governance"},
  {"n":750,"ta":["எனைமாட்சித் தாகியக் கண்ணும் வினைமாட்சி","இல்லார்கண் இல்லது அரண்"],"tr":["Enaimaatchith Thaakiyak Kannum Vinaimaatchi","Illaarkan Illadhu Aran"],"en":["Howe'er majestic castled walls may rise,","To craven souls no fortress strength supplies"],"s":"Although a fort may possess all  (the above-said) excellence, it is, as it were without these, if its inmates possess not the excellence of action","ch":75,"sec":2,"th":"governance"},
  {"n":751,"ta":["பொருளல் லவரைப் பொருளாகச் செய்யும்","பொருளல்லது இல்லை பொருள்"],"tr":["Porulal Lavaraip Porulaakach Cheyyum","Porulalladhu Illai Porul"],"en":["Nothing exists save wealth, that can","Change man of nought to worthy man"],"s":"Besides wealth there is nothing that can change people of no importance into those of  (some) importance","ch":76,"sec":2,"th":"wealth"},
  {"n":752,"ta":["இல்லாரை எல்லாரும் எள்ளுவர் செல்வரை","எல்லாரும் செய்வர் சிறப்பு"],"tr":["Illaarai Ellaarum Elluvar Selvarai","Ellaarum Seyvar Sirappu"],"en":["Those who have nought all will despise;","All raise the wealthy to the skies"],"s":"All despise the poor;  (but) all praise the rich","ch":76,"sec":2,"th":"wealth"},
  {"n":753,"ta":["பொருளென்னும் பொய்யா விளக்கம் இருளறுக்கும்","எண்ணிய தேயத்துச் சென்று"],"tr":["Porulennum Poiyaa Vilakkam Irularukkum","Enniya Theyaththuch Chendru"],"en":["Wealth, the lamp unfailing, speeds to every land,","Dispersing darkness at its lord's command"],"s":"The imperishable light of wealth goes into regions desired  (by its owner) and destroys the darkness  (of enmity therein)","ch":76,"sec":2,"th":"wealth"},
  {"n":754,"ta":["அறன்ஈனும் இன்பமும் ஈனும் திறனறிந்து","தீதின்றி வந்த பொருள்"],"tr":["Araneenum Inpamum Eenum Thiranarindhu","Theedhindri Vandha Porul"],"en":["Their wealth, who blameless means can use aright,","Is source of virtue and of choice delight"],"s":"The wealth acquired with a knowledge of the proper means and without foul practices will yield virtue and happiness","ch":76,"sec":2,"th":"wealth"},
  {"n":755,"ta":["அருளொடும் அன்பொடும் வாராப் பொருளாக்கம்","புல்லார் புரள விடல்"],"tr":["Arulotum Anpotum Vaaraap Porulaakkam","Pullaar Purala Vital"],"en":["Wealth gained by loss of love and grace,","Let man cast off from his embrace"],"s":"(Kings) should rather avoid than seek the accumulation of wealth which does not flow in with mercy and love","ch":76,"sec":2,"th":"wealth"},
  {"n":756,"ta":["உறுபொருளும் உல்கு பொருளும்தன் ஒன்னார்த்","தெறுபொருளும் வேந்தன் பொருள்"],"tr":["Uruporulum Ulku Porulumdhan Onnaarth","Theruporulum Vendhan Porul"],"en":["Wealth that falls to him as heir,","wealth from the kingdom's dues,"],"s":"The spoils of slaughtered foes; these are the royal revenues","ch":76,"sec":2,"th":"wealth"},
  {"n":757,"ta":["அருளென்னும் அன்பீன் குழவி பொருளென்னும்","செல்வச் செவிலியால் உண்டு"],"tr":["Arulennum Anpeen Kuzhavi Porulennum","Selvach Cheviliyaal Untu"],"en":["'Tis love that kindliness as offspring bears:","And wealth as bounteous nurse the infant rears"],"s":"The child mercy which is borne by love grows under the care of the rich nurse of wealth","ch":76,"sec":2,"th":"wealth"},
  {"n":758,"ta":["குன்றேறி யானைப்போர் கண்டற்றால் தன்கைத்தொன்று","உண்டாகச் செய்வான் வினை"],"tr":["Kundreri Yaanaip Por Kantatraal","Thankaiththondru Untaakach Cheyvaan Vinai"],"en":["As one to view the strife of elephants who takes his stand,","On hill he's climbed, is he who works with money in his hand"],"s":"An undertaking of one who has wealth in one's hands is like viewing an elephant-fight from a hill-top","ch":76,"sec":2,"th":"wealth"},
  {"n":759,"ta":["செய்க பொருளைச் செறுநர் செருக்கறுக்கும்","எஃகதனிற் கூரிய தில்"],"tr":["Seyka Porulaich Cherunar Serukkarukkum","Eqkadhanir Kooriya Thil"],"en":["Make money! Foeman's insolence o'ergrown","To lop away no keener steel is known"],"s":"Accumulate wealth; it will destroy the arrogance of  (your) foes; there is no weapon sharper than it","ch":76,"sec":2,"th":"wealth"},
  {"n":760,"ta":["ஒண்பொருள் காழ்ப்ப இயற்றியார்க்கு எண்பொருள்","ஏனை இரண்டும் ஒருங்கு"],"tr":["Onporul Kaazhppa Iyatriyaarkku Enporul","Enai Irantum Orungu"],"en":["Who plenteous store of glorious wealth have gained,","By them the other two are easily obtained"],"s":"To those who have honestly acquired an abundance of riches, the other two,  (virtue and pleasure) are things easy  (of acquisition)","ch":76,"sec":2,"th":"wealth"},
  {"n":761,"ta":["உறுப்பமைந்து ஊறஞ்சா வெல்படை வேந்தன்","வெறுக்கையுள் எல்லாம் தலை"],"tr":["Uruppamaindhu Ooranjaa Velpatai Vendhan","Verukkaiyul Ellaam Thalai"],"en":["A conquering host, complete in all its limbs, that fears no wound,","Mid treasures of the king is chiefest found"],"s":"The army which is complete in  (its) parts and conquers without fear of wounds is the chief wealth of the king","ch":77,"sec":2,"th":"governance"},
  {"n":762,"ta":["உலைவிடத்து ஊறஞ்சா வன்கண் தொலைவிடத்துத்","தொல்படைக் கல்லால் அரிது"],"tr":["Ulaivitaththu Ooranjaa Vankan Tholaivitaththuth","Tholpataik Kallaal Aridhu"],"en":["In adverse hour, to face undaunted might of conquering foe,","Is bravery that only veteran host can show"],"s":"Ancient army can alone have the valour which makes it stand by its king at the time of defeat, fearless of wounds and unmindful of its reduced strength","ch":77,"sec":2,"th":"governance"},
  {"n":763,"ta":["ஒலித்தக்கால் என்னாம் உவரி எலிப்பகை","நாகம் உயிர்ப்பக் கெடும்"],"tr":["Oliththakkaal Ennaam Uvari Ela�ppakai","Naakam Uyirppak Ketum"],"en":["Though, like the sea, the angry mice send forth their battle cry;","What then? The dragon breathes upon them, and they die"],"s":"What if  (a host of) hostile rats roar like the sea? They will perish at the mere breath of the cobra","ch":77,"sec":2,"th":"governance"},
  {"n":764,"ta":["அழிவின்றி அறைபோகா தாகி வழிவந்த","வன்க ணதுவே படை"],"tr":["Azhivindri Araipokaa Thaaki Vazhivandha","Vanka Nadhuve Patai"],"en":["That is a host, by no defeats, by no desertions shamed,","For old hereditary courage famed"],"s":"That indeed is an army which has stood firm of old without suffering destruction or deserting  (to the enemy)","ch":77,"sec":2,"th":"governance"},
  {"n":765,"ta":["கூற்றுடன்று மேல்வரினும் கூடி எதிர்நிற்கும்","ஆற்ற லதுவே படை"],"tr":["Kootrutandru Melvarinum Kooti Edhirnirkum","Aatra Ladhuve Patai"],"en":["That is a 'host' that joins its ranks, and mightily withstands,","Though death with sudden wrath should fall upon its bands"],"s":"That indeed is an army which is capable of offering a united resistance, even if Yama advances against it with fury","ch":77,"sec":2,"th":"governance"},
  {"n":766,"ta":["மறமானம் மாண்ட வழிச்செலவு தேற்றம்","எனநான்கே ஏமம் படைக்கு"],"tr":["Maramaanam Maanta Vazhichchelavu Thetram","Enanaanke Emam Pataikku"],"en":["Valour with honour, sure advance in glory's path, with confidence;","To warlike host these four are sure defence"],"s":"Valour, honour, following in the excellent-footsteps  (of its predecessors) and trust-worthiness; these four alone constitute the safeguard of an army","ch":77,"sec":2,"th":"governance"},
  {"n":767,"ta":["தார்தாங்கிச் செல்வது தானை தலைவந்த","போர்தாங்கும் தன்மை அறிந்து"],"tr":["Thaardhaangich Chelvadhu Thaanai Thalaivandha","Pordhaangum Thanmai Arindhu"],"en":["A valiant army bears the onslaught, onward goes,","Well taught with marshalled ranks to meet their coming foes"],"s":"That is an army which knowing the art of warding off an impending struggle, can bear against the dust-van  (of a hostile force)","ch":77,"sec":2,"th":"governance"},
  {"n":768,"ta":["அடல்தகையும் ஆற்றலும் இல்லெனினும் தானை","படைத்தகையால் பாடு பெறும்"],"tr":["Ataldhakaiyum Aatralum Illeninum Thaanai","Pataiththakaiyaal Paatu Perum"],"en":["Though not in war offensive or defensive skilled;","An army gains applause when well equipped and drilled"],"s":"Though destitute of courage to fight and strength  (to endure), an army may yet gain renown by the splendour of its appearance","ch":77,"sec":2,"th":"governance"},
  {"n":769,"ta":["சிறுமையும் செல்லாத் துனியும் வறுமையும்","இல்லாயின் வெல்லும் படை"],"tr":["Sirumaiyum Sellaath Thuniyum Varumaiyum","Illaayin Vellum Patai"],"en":["Where weakness, clinging fear and poverty","Are not, the host will gain the victory"],"s":"An army can triumph  (over its foes) if it is free from diminution; irremediable aversion and poverty","ch":77,"sec":2,"th":"governance"},
  {"n":770,"ta":["நிலைமக்கள் சால உடைத்தெனினும் தானை","தலைமக்கள் இல்வழி இல்"],"tr":["Nilaimakkal Saala Utaiththeninum Thaanai","Thalaimakkal Ilvazhi Il"],"en":["Though men abound, all ready for the war,","No army is where no fit leaders are"],"s":"Though an army may contain a large number of permanent soldiers, it cannot last if it has no generals","ch":77,"sec":2,"th":"governance"},
  {"n":771,"ta":["என்னைமுன் நில்லன்மின் தெவ்விர் பலரென்னை","முன்நின்று கல்நின் றவர்"],"tr":["Ennaimun Nillanmin Thevvir Palarennai","Munnindru Kalnin Ravar"],"en":["Ye foes stand not before my lord for many a one","Who did my lord withstand, now stands in stone"],"s":"O my foes, stand not before my leader;  (for) many are those who did so but afterwards stood  (in the shape of) statues","ch":78,"sec":2,"th":"governance"},
  {"n":772,"ta":["கான முயலெய்த அம்பினில் யானை","பிழைத்தவேல் ஏந்தல் இனிது"],"tr":["Kaana Muyaleydha Ampinil Yaanai","Pizhaiththavel Endhal Inidhu"],"en":["Who aims at elephant, though dart should fail, has greater praise","Than he who woodland hare with winged arrow slays"],"s":"It is more pleasant to hold the dart that has missed an elephant than that which has hit hare in the forest","ch":78,"sec":2,"th":"governance"},
  {"n":773,"ta":["பேராண்மை என்ப தறுகண்ஒன் றுற்றக்கால்","ஊராண்மை மற்றதன் எஃகு"],"tr":["Peraanmai Enpa Tharukanon Rutrakkaal","Ooraanmai Matradhan Eqku"],"en":["Fierceness in hour of strife heroic greatness shows;","Its edge is kindness to our suffering foes"],"s":"The learned say that fierceness  (incontest with a foe) is indeed great valour; but to become a benefactor in case of accident  (to a foe) is the extreme  (limit) of that valour","ch":78,"sec":2,"th":"governance"},
  {"n":774,"ta":["கைவேல் களிற்றொடு போக்கி வருபவன்","மெய்வேல் பறியா நகும்"],"tr":["Kaivel Kalitrotu Pokki Varupavan","Meyvel Pariyaa Nakum"],"en":["At elephant he hurls the dart in hand; for weapon pressed,","He laughs and plucks the javelin from his wounded breast"],"s":"The hero who after casting the lance in his hand on an elephant, comes  (in search of another) will pluck the one  (that sticks) in his body and laugh  (exultingly)","ch":78,"sec":2,"th":"governance"},
  {"n":775,"ta":["விழித்தகண் வேல்கொண டெறிய அழித்திமைப்பின்","ஒட்டன்றோ வன்க ணவர்க்கு"],"tr":["Vizhiththakan Velkona Teriya Azhiththimaippin","Ottandro Vanka Navarkku"],"en":["To hero fearless must it not defeat appear,","If he but wink his eye when foemen hurls his spear"],"s":"Is it not a defeat to the valiant to wink and destroy their ferocious look when a lance in cast at them  (by their foe)?","ch":78,"sec":2,"th":"governance"},
  {"n":776,"ta":["விழுப்புண் படாதநாள் எல்லாம் வழுக்கினுள்","வைக்கும்தன் நாளை எடுத்து"],"tr":["Vizhuppun Pataadhanaal Ellaam Vazhukkinul","Vaikkumdhan Naalai Etuththu"],"en":["The heroes, counting up their days, set down as vain","Each day when they no glorious wound sustain"],"s":"The hero will reckon among wasted days all those on which he had not received severe wounds","ch":78,"sec":2,"th":"governance"},
  {"n":777,"ta":["சுழலும் இசைவேண்டி வேண்டா உயிரார்","கழல்யாப்புக் காரிகை நீர்த்து"],"tr":["Suzhalum Isaiventi Ventaa Uyiraar","Kazhalyaappuk Kaarikai Neerththu"],"en":["Who seek for world-wide fame, regardless of their life,","The glorious clasp adorns, sign of heroic strife"],"s":"The fastening of ankle-ring by those who disire a world-wide renown and not  (the safety of) their lives is like adorning  (themselves)","ch":78,"sec":2,"th":"governance"},
  {"n":778,"ta":["உறின்உயிர் அஞ்சா மறவர் இறைவன்","செறினும் சீர்குன்றல் இலர்"],"tr":["Urinuyir Anjaa Maravar Iraivan","Serinum Seerkundral Ilar"],"en":["Fearless they rush where'er 'the tide of battle rolls';","The king's reproof damps not the ardour of their eager souls"],"s":"The heroes who are not afraid of losing their life in a contest will not cool their ardour, even if the king prohibits  (their fighting)","ch":78,"sec":2,"th":"governance"},
  {"n":779,"ta":["இழைத்தது இகவாமைச் சாவாரை யாரே","பிழைத்தது ஒறுக்கிற் பவர்"],"tr":["Izhaiththadhu Ikavaamaich Chaavaarai Yaare","Pizhaiththadhu Orukkir Pavar"],"en":["Who says they err, and visits them scorn,","Who die and faithful guard the vow they've sworn"],"s":"Who would reproach with failure those who seal their oath with their death?","ch":78,"sec":2,"th":"governance"},
  {"n":780,"ta":["புரந்தார்கண் நீர்மல்கச் சாகிற்பின் சாக்காடு","இரந்துகோள் தக்கது உடைத்து"],"tr":["Purandhaarkan Neermalkach Chaakirpin Saakkaatu","Irandhukol Thakkadhu Utaiththu"],"en":["If monarch's eyes o'erflow with tears for hero slain,","Who would not beg such boon of glorious death to gain"],"s":"If  (heroes) can so die as to fill with tears the eyes of their rulers, such a death deserves to be obtained even by begging","ch":78,"sec":2,"th":"governance"},
  {"n":781,"ta":["செயற்கரிய யாவுள நட்பின் அதுபோல்","வினைக்கரிய யாவுள காப்பு"],"tr":["Seyarkariya Yaavula Natpin Adhupol","Vinaikkariya Yaavula Kaappu"],"en":["What so hard for men to gain as friendship true","What so sure defence 'gainst all that foe can do"],"s":"What so sure defence 'gainst all that foe can do?","ch":79,"sec":2,"th":"friendship"},
  {"n":782,"ta":["நிறைநீர நீரவர் கேண்மை பிறைமதிப்","பின்னீர பேதையார் நட்பு"],"tr":["Niraineera Neeravar Kenmai Piraimadhip","Pinneera Pedhaiyaar Natpu"],"en":["Friendship with men fulfilled of good Waxes like the crescent moon;","Friendship with men of foolish mood, Like the full orb, waneth soon"],"s":"The friendship of the wise waxes like the new moon;  (but) that of fools wanes like the full moon","ch":79,"sec":2,"th":"friendship"},
  {"n":783,"ta":["நவில்தொறும் நூல்நயம் போலும் பயில்தொறும்","பண்புடை யாளர் தொடர்பு"],"tr":["Navildhorum Noolnayam Polum Payildhorum","Panputai Yaalar Thotarpu"],"en":["Learned scroll the more you ponder, Sweeter grows the mental food;","So the heart by use grows fonder, Bound in friendship with the good"],"s":"Like learning, the friendship of the noble, the more it is cultivated, the more delightful does it become","ch":79,"sec":2,"th":"friendship"},
  {"n":784,"ta":["நகுதற் பொருட்டன்று நட்டல் மிகுதிக்கண்","மேற்செனறு இடித்தற் பொருட்டு"],"tr":["Nakudhar Poruttandru Nattal Mikudhikkan","Mersenaru Itiththar Poruttu"],"en":["Nor for laughter only friendship all the pleasant day,","But for strokes of sharp reproving, when from right you stray"],"s":"Friendship is to be practised not for the purpose of laughing but for that of being beforehand in giving one another sharp rebukes in case of transgression","ch":79,"sec":2,"th":"friendship"},
  {"n":785,"ta":["புணர்ச்சி பழகுதல் வேண்டா உணர்ச்சிதான்","நட்பாங் கிழமை தரும்"],"tr":["Punarchchi Pazhakudhal Ventaa Unarchchidhaan","Natpaang Kizhamai Tharum"],"en":["Not association constant, not affection's token bind;","'Tis the unison of feeling friends unites of kindred mind"],"s":"Living together and holding frequent intercourse are not necessary  (for friendship);  (mutual) understanding can alone create a claim for it","ch":79,"sec":2,"th":"friendship"},
  {"n":786,"ta":["முகநக நட்பது நட்பன்று நெஞ்சத்து","அகநக நட்பது நட்பு"],"tr":["Mukanaka Natpadhu Natpandru Nenjaththu","Akanaka Natpadhu Natpu"],"en":["Not the face's smile of welcome shows the friend sincere,","But the heart's rejoicing gladness when the friend is near"],"s":"The love that dwells  (merely in the smiles of the face is not friendship;  (but) that which dwells deep in the smiles of the heart is true friendship","ch":79,"sec":2,"th":"friendship"},
  {"n":787,"ta":["அழிவி னவைநீக்கி ஆறுய்த்து அழிவின்கண்","அல்லல் உழப்பதாம் நட்பு"],"tr":["Azhivi Navaineekki Aaruyththu Azhivinkan","Allal Uzhappadhaam Natpu"],"en":["Friendship from ruin saves, in way of virtue keeps;","In troublous time, it weeps with him who weeps"],"s":"(True) friendship turns aside from evil  (ways) makes  (him) walk in the  (good) way, and, in case of loss if shares his sorrow  (with him)","ch":79,"sec":2,"th":"friendship"},
  {"n":788,"ta":["உடுக்கை இழந்தவன் கைபோல ஆங்கே","இடுக்கண் களைவதாம் நட்பு"],"tr":["Utukkai Izhandhavan Kaipola Aange","Itukkan Kalaivadhaam Natpu"],"en":["As hand of him whose vesture slips away,","Friendship at once the coming grief will stay"],"s":"(True) friendship hastens to the rescue of the afflicted  (as readily) as the hand of one whose garment is loosened  (before an assembly)","ch":79,"sec":2,"th":"friendship"},
  {"n":789,"ta":["நட்பிற்கு வீற்றிருக்கை யாதெனின் கொட்பின்றி","ஒல்லும்வாய் ஊன்றும் நிலை"],"tr":["Natpirku Veetrirukkai Yaadhenin Kotpindri","Ollumvaai Oondrum Nilai"],"en":["And where is friendship's royal seat? In stable mind,","Where friend in every time of need support may find"],"s":"Friendship may be said to be on its throne when it possesses the power of supporting one at all times and under all circumstances,  (in the practice or virtue and wealth)","ch":79,"sec":2,"th":"friendship"},
  {"n":790,"ta":["இனையர் இவரெமக்கு இன்னம்யாம் என்று","புனையினும் புல்லென்னும் நட்பு"],"tr":["Inaiyar Ivaremakku Innamyaam Endru","Punaiyinum Pullennum Natpu"],"en":["Mean is the friendship that men blazon forth,","'He's thus to me' and 'such to him my worth'"],"s":"Though friends may praise one another saying, \"He is so intimate with us, and we so much  (with him)\";  (still) such friendship will appear mean","ch":79,"sec":2,"th":"friendship"},
  {"n":791,"ta":["நாடாது நட்டலிற் கேடில்லை நட்டபின்","வீடில்லை நட்பாள் பவர்க்கு"],"tr":["Naataadhu Nattalir Ketillai Nattapin","Veetillai Natpaal Pavarkku"],"en":["To make an untried man your friend is ruin sure;","For friendship formed unbroken must endure"],"s":"As those who are of a friendly nature will not forsake  (a friend) after once loving  (him), there is no evil so great as contracting a friendship without due inquiry","ch":80,"sec":2,"th":"friendship"},
  {"n":792,"ta":["ஆய்ந்தாய்ந்து கொள்ளாதான் கேண்மை கடைமுறை","தான்சாம் துயரம் தரும்"],"tr":["Aaindhaaindhu Kollaadhaan Kenmai Kataimurai","Thaansaam Thuyaram Tharum"],"en":["Alliance with the man you have not proved and proved again,","In length of days will give you mortal pain"],"s":"The friendship contracted by him who has not made repeated inquiry will in the end grieve  (him) to death","ch":80,"sec":2,"th":"friendship"},
  {"n":793,"ta":["குணமும் குடிமையும் குற்றமும் குன்றா","இனனும் அறிந்தியாக்க நட்பு"],"tr":["Kunamum Kutimaiyum Kutramum Kundraa","Inanum Arindhiyaakka Natpu"],"en":["Temper, descent, defects, associations free","From blame: know these, then let the man be friend to thee"],"s":"Make friendship  (with one) after ascertaining  (his) character, birth, defects and the whole of one's relations","ch":80,"sec":2,"th":"friendship"},
  {"n":794,"ta":["குடிப்பிறந்து தன்கண் பழிநாணு வானைக்","கொடுத்தும் கொளல்வேண்டும் நட்பு"],"tr":["Kutippirandhu Thankan Pazhinaanu Vaanaik","Kotuththum Kolalventum Natpu"],"en":["Who, born of noble race, from guilt would shrink with shame,","Pay any price so you as friend that man may claim"],"s":"The friendship of one who belongs to a  (good) family and is afraid of  (being charged with) guilt, is worth even purchasing","ch":80,"sec":2,"th":"friendship"},
  {"n":795,"ta":["அழச்சொல்லி அல்லது இடித்து வழக்கறிய","வல்லார்நடபு ஆய்ந்து கொளல்"],"tr":["Azhachcholli Alladhu Itiththu Vazhakkariya","Vallaarnatapu Aaindhu Kolal"],"en":["Make them your chosen friend whose words repentance move,","With power prescription's path to show, while evil they reprove"],"s":"You should examine and secure the friendship of those who can speak so as to make you weep over a crime  (before its commission) or rebuke you severely  (after you have done it) and are able to teach","ch":80,"sec":2,"th":"friendship"},
  {"n":796,"ta":["கேட்டினும் உண்டோர் உறுதி கிளைஞரை","நீட்டி அளப்பதோர் கோல்"],"tr":["Kettinum Untor Urudhi Kilaignarai","Neetti Alappadhor Kol"],"en":["Ruin itself one blessing lends:","'Tis staff that measures out one's friends"],"s":"Even in ruin there is some good;  (for) it is a rod by which one may measure fully  (the affection of one's) relations","ch":80,"sec":2,"th":"friendship"},
  {"n":797,"ta":["ஊதியம் என்பது ஒருவற்குப் பேதையார்","கேண்மை ஒரீஇ விடல்"],"tr":["Oodhiyam Enpadhu Oruvarkup Pedhaiyaar","Kenmai Oreei Vital"],"en":["'Tis gain to any man, the sages say,","Friendship of fools to put away"],"s":"It is indead a gain for one to renounce the friendship of fools","ch":80,"sec":2,"th":"friendship"},
  {"n":798,"ta":["உள்ளற்க உள்ளம் சிறுகுவ கொள்ளற்க","அல்லற்கண் ஆற்றறுப்பார் நட்பு"],"tr":["Ullarka Ullam Sirukuva Kollarka","Allarkan Aatraruppaar Natpu"],"en":["Think not the thoughts that dwarf the soul; nor take","For friends the men who friends in time of grief forsake"],"s":"Do not think of things that discourage your mind, nor contract friendship with those who would forsake you in adversity","ch":80,"sec":2,"th":"friendship"},
  {"n":799,"ta":["கெடுங்காலைக் கைவிடுவார் கேண்மை அடுங்காலை","உள்ளினும் உள்ளஞ் சுடும்"],"tr":["Ketungaalaik Kaivituvaar Kenmai Atungaalai","Ullinum Ullanj Chutum"],"en":["Of friends deserting us on ruin's brink,","'Tis torture e'en in life's last hour to think"],"s":"The very thought of the friendship of those who have deserted one at the approach of adversity will burn one's mind at the time of death","ch":80,"sec":2,"th":"friendship"},
  {"n":800,"ta":["மருவுக மாசற்றார் கேண்மைஒன் றீத்தும்","ஒருவுக ஒப்பிலார் நட்பு"],"tr":["Maruvuka Maasatraar Kenmaion Reeththum","Oruvuka Oppilaar Natpu"],"en":["Cling to the friendship of the spotless one's; whate'er you pay","Renounce alliance with the men of evil way"],"s":"Continue to enjoy the friendship of the pure;  (but) renounce even with a gift, the friendship of those who do not agree  (with the world)","ch":80,"sec":2,"th":"friendship"},
  {"n":801,"ta":["பழைமை எனப்படுவது யாதெனின் யாதும்","கிழமையைக் கீழ்ந்திடா நட்பு"],"tr":["Pazhaimai Enappatuvadhu Yaadhenin Yaadhum","Kizhamaiyaik Keezhndhitaa Natpu"],"en":["Familiarity is friendship's silent pact,","That puts restraint on no familiar act"],"s":"Imtimate friendship is that which cannot in the least be injured by  (things done through the) right  (of longstanding intimacy)","ch":81,"sec":2,"th":"friendship"},
  {"n":802,"ta":["நட்பிற் குறுப்புக் கெழுதகைமை மற்றதற்கு","உப்பாதல் சான்றோர் கடன்"],"tr":["Natpir Kuruppuk Kezhudhakaimai Matradharku","Uppaadhal Saandror Katan"],"en":["Familiar freedom friendship's very frame supplies;","To be its savour sweet is duty of the wise"],"s":"The constituents of friendship are  (things done through) the right of intimacy; to be pleased with such a right is the duty of the wise","ch":81,"sec":2,"th":"friendship"},
  {"n":803,"ta":["பழகிய நட்பெவன் செய்யுங் கெழுதகைமை","செய்தாங்கு அமையாக் கடை"],"tr":["Pazhakiya Natpevan Seyyung Kezhudhakaimai","Seydhaangu Amaiyaak Katai"],"en":["When to familiar acts men kind response refuse,","What fruit from ancient friendship's use"],"s":"Of what avail is long-standing friendship, if friends do not admit as their own actions done through the right of intimacy?","ch":81,"sec":2,"th":"friendship"},
  {"n":804,"ta":["விழைதகையான் வேண்டி இருப்பர் கெழுதகையாற்","கேளாது நட்டார் செயின்"],"tr":["Vizhaidhakaiyaan Venti Iruppar Kezhudhakaiyaar","Kelaadhu Nattaar Seyin"],"en":["When friends unbidden do familiar acts with loving heart,","Friends take the kindly deed in friendly part"],"s":"If friends, through the right of friendship, do  (anything) without being asked, the wise will be pleased with them on account of its desirability","ch":81,"sec":2,"th":"friendship"},
  {"n":805,"ta":["பேதைமை ஒன்றோ பெருங்கிழமை என்றுணர்க","நோதக்க நட்டார் செயின்"],"tr":["Pedhaimai Ondro Perungizhamai Endrunarka","Nodhakka Nattaar Seyin"],"en":["Not folly merely, but familiar carelessness,","Esteem it, when your friends cause you distress"],"s":"If friends should perform what is painful, understand that it is owing not only to ignorance, but also to the strong claims of intimacy","ch":81,"sec":2,"th":"friendship"},
  {"n":806,"ta":["எல்லைக்கண் நின்றார் துறவார் தொலைவிடத்தும்","தொல்லைக்கண் நின்றார் தொடர்பு"],"tr":["Ellaikkan Nindraar Thuravaar Tholaivitaththum","Thollaikkan Nindraar Thotarpu"],"en":["Who stand within the bounds quit not, though loss impends,","Association with the old familiar friends"],"s":"Those who stand within the limits  (of true friendship) will not even in adversity give up the intimacy of long-standing friends","ch":81,"sec":2,"th":"friendship"},
  {"n":807,"ta":["அழிவந்த செய்யினும் அன்பறார் அன்பின்","வழிவந்த கேண்மை யவர்"],"tr":["Azhivandha Seyyinum Anparaar Anpin","Vazhivandha Kenmai Yavar"],"en":["True friends, well versed in loving ways,","Cease not to love, when friend their love betrays"],"s":"Those who have  (long) stood in the path of affection will not give it up even if their friends cause  (them) their ruin","ch":81,"sec":2,"th":"friendship"},
  {"n":808,"ta":["கேளிழுக்கம் கேளாக் கெழுதகைமை வல்லார்க்கு","நாளிழுக்கம் நட்டார் செயின்"],"tr":["Kelizhukkam Kelaak Kezhudhakaimai Vallaarkku","Naalizhukkam Nattaar Seyin"],"en":["In strength of friendship rare of friend's disgrace who will not hear,","The day his friend offends will day of grace to him appear"],"s":"To those who understand that by which they should not listen to  (tales about) the faults of their friends, that is a  (profitable) day on which the latter may commit a fault","ch":81,"sec":2,"th":"friendship"},
  {"n":809,"ta":["கெடாஅ வழிவந்த கேண்மையார் கேண்மை","விடாஅர் விழையும் உலகு"],"tr":["Ketaaa Vazhivandha Kenmaiyaar Kenmai","Vitaaar Vizhaiyum Ulaku"],"en":["Friendship of old and faithful friends,","Who ne'er forsake, the world commends"],"s":"They will be loved by the world, who have not forsaken the friendship of those with whom they have kept up an unbroken long-standing intimacy","ch":81,"sec":2,"th":"friendship"},
  {"n":810,"ta":["விழையார் விழையப் படுப பழையார்கண்","பண்பின் தலைப்பிரியா தார்"],"tr":["Vizhaiyaar Vizhaiyap Patupa Pazhaiyaarkan","Panpin Thalaippiriyaa Thaar"],"en":["Ill-wishers even wish them well, who guard","For ancient friends, their wonted kind regard"],"s":"Even enemies will love those who have never changed in their affection to their long-standingfriends","ch":81,"sec":2,"th":"friendship"},
  {"n":811,"ta":["பருகுவார் போலினும் பண்பிலார் கேண்மை","பெருகலிற் குன்றல் இனிது"],"tr":["Parukuvaar Polinum Panpilaar Kenmai","Perukalir Kundral Inidhu"],"en":["Though evil men should all-absorbing friendship show,","Their love had better die away than grow"],"s":"The decrease of friendship with those who look as if they would eat you up  (through excess of love) while they are really destitute of goodness is far better than its increase","ch":82,"sec":2,"th":"friendship"},
  {"n":812,"ta":["உறின்நட்டு அறினொருஉம் ஒப்பிலார் கேண்மை","பெறினும் இழப்பினும் என்?"],"tr":["Urinnattu Arinoruum Oppilaar Kenmai","Perinum Izhappinum En?"],"en":["What though you gain or lose friendship of men of alien heart,","Who when you thrive are friends, and when you fail depart"],"s":"Of what avail is it to get or lose the friendship of those who love when there is gain and leave when there is none?","ch":82,"sec":2,"th":"friendship"},
  {"n":813,"ta":["உறுவது சீர்தூக்கும் நட்பும் பெறுவது","கொள்வாரும் கள்வரும் நேர்"],"tr":["Uruvadhu Seerdhookkum Natpum Peruvadhu","Kolvaarum Kalvarum Ner"],"en":["These are alike: the friends who ponder friendship's gain","Those who accept whate'er you give, and all the plundering train"],"s":"Friendship who calculate the profits  (of their friendship), prostitutes who are bent on obtaining their gains, and thieves are  (all) of the same character","ch":82,"sec":2,"th":"friendship"},
  {"n":814,"ta":["அமரகத்து ஆற்றறுக்கும் கல்லாமா அன்னார்","தமரின் தனிமை தலை"],"tr":["Amarakaththu Aatrarukkum Kallaamaa Annaar","Thamarin Thanimai Thalai"],"en":["A steed untrained will leave you in the tug of war;","Than friends like that to dwell alone is better far"],"s":"Solitude is more to be desired than the society of those who resemble the untrained horses which throw down  (their riders) in the fields of battle","ch":82,"sec":2,"th":"friendship"},
  {"n":815,"ta":["செய்தேமஞ் சாராச் சிறியவர் புன்கேண்மை","எய்தலின் எய்தாமை நன்று"],"tr":["Seydhemanj Chaaraach Chiriyavar Punkenmai","Eydhalin Eydhaamai Nandru"],"en":["'Tis better not to gain than gain the friendship profitless","Of men of little minds, who succour fails when dangers press"],"s":"It is far better to avoid that to contract the evil friendship of the base who cannot protect  (their friends) even when appointed to do so","ch":82,"sec":2,"th":"friendship"},
  {"n":816,"ta":["பேதை பெருங்கெழீஇ நட்பின் அறிவுடையார்","ஏதின்மை கோடி உறும்"],"tr":["Pedhai Perungezheei Natpin Arivutaiyaar","Edhinmai Koti Urum"],"en":["Better ten million times incur the wise man's hate,","Than form with foolish men a friendship intimate"],"s":"The hatred of the wise is ten-million times more profitable than the excessive intimacy of the fool","ch":82,"sec":2,"th":"friendship"},
  {"n":817,"ta":["நகைவகைய ராகிய நட்பின் பகைவரால்","பத்தடுத்த கோடி உறும்"],"tr":["Nakaivakaiya Raakiya Natpin Pakaivaraal","Paththatuththa Koti Urum"],"en":["From foes ten million fold a greater good you gain,","Than friendship yields that's formed with laughers vain"],"s":"What comes from enemies is a hundred million times more profitable than what comes from the friendship of those who cause only laughter","ch":82,"sec":2,"th":"friendship"},
  {"n":818,"ta":["ஒல்லும் கருமம் உடற்று பவர்கேண்மை","சொல்லாடார் சோர விடல்"],"tr":["Ollum Karumam Utatru Pavarkenmai","Sollaataar Sora Vital"],"en":["Those men who make a grievous toil of what they do","On your behalf, their friendship silently eschew"],"s":"Gradually abandon without revealing  (beforehand) the friendship of those who pretend inability to carry out what they  (really) could do","ch":82,"sec":2,"th":"friendship"},
  {"n":819,"ta":["கனவினும் இன்னாது மன்னோ வினைவேறு","சொல்வேறு பட்டார் தொடர்பு"],"tr":["Kanavinum Innaadhu Manno Vinaiveru","Solveru Pattaar Thotarpu"],"en":["E'en in a dream the intercourse is bitterness","With men whose deeds are other than their words profess"],"s":"The friendship of those whose actions do not agree with their words will distress  (one) even in  (one's) dreams","ch":82,"sec":2,"th":"friendship"},
  {"n":820,"ta":["எனைத்தும் குறுகுதல் ஓம்பல் மனைக்கெழீஇ","மன்றில் பழிப்பார் தொடர்பு"],"tr":["Enaiththum Kurukudhal Ompal Manaikkezheei","Mandril Pazhippaar Thotarpu"],"en":["In anywise maintain not intercourse with those,","Who in the house are friends, in hall are slandering foes"],"s":"Avoid even the least approach to a contraction of friendship with those who would love you in private but ridicule you in public","ch":82,"sec":2,"th":"friendship"},
  {"n":821,"ta":["சீரிடம் காணின் எறிதற்குப் பட்டடை","நேரா நிரந்தவர் நட்பு"],"tr":["Seeritam Kaanin Eridharkup Pattatai","Neraa Nirandhavar Natpu"],"en":["Anvil where thou shalt smitten be, when men occasion find,","Is friendship's form without consenting mind"],"s":"The friendship of those who behave like friends without inward affection is a weapon that may be thrown when a favourable opportunity presents itself","ch":83,"sec":2,"th":"friendship"},
  {"n":822,"ta":["இனம்போன்று இனமல்லார் கேண்மை மகளிர்","மனம்போல வேறு படும்"],"tr":["Inampondru Inamallaar Kenmai Makalir","Manampola Veru Patum"],"en":["Friendship of those who seem our kin, but are not really kind","Will change from hour to hour like woman's mind"],"s":"The friendship of those who seem to be friends while they are not, will change like the love of women","ch":83,"sec":2,"th":"friendship"},
  {"n":823,"ta":["பலநல்ல கற்றக் கடைத்து மனநல்லர்","ஆகுதல் மாணார்க் கரிது"],"tr":["Palanalla Katrak Kataiththu Mananallar","Aakudhal Maanaark Karidhu"],"en":["To heartfelt goodness men ignoble hardly may attain,","Although abundant stores of goodly lore they gain"],"s":"Though  (one's) enemies may have mastered many good books, it will be impossible for them to become truly loving at heart","ch":83,"sec":2,"th":"friendship"},
  {"n":824,"ta":["முகத்தின் இனிய நகாஅ அகத்தின்னா","வஞ்சரை அஞ்சப் படும்"],"tr":["Mukaththin Iniya Nakaaa Akaththinnaa","Vanjarai Anjap Patum"],"en":["'Tis fitting you should dread dissemblers' guile,","Whose hearts are bitter while their faces smile"],"s":"One should fear the deceitful who smile sweetly with their face but never love with their heart","ch":83,"sec":2,"th":"friendship"},
  {"n":825,"ta":["மனத்தின் அமையா தவரை எனைத்தொன்றும்","சொல்லினால் தேறற்பாற்று அன்று"],"tr":["Manaththin Amaiyaa Thavarai Enaiththondrum","Sollinaal Therarpaatru Andru"],"en":["When minds are not in unison, 'its never; just,","In any words men speak to put your trust"],"s":"In nothing whatever is it proper to rely on the words of those who do not love with their heart","ch":83,"sec":2,"th":"friendship"},
  {"n":826,"ta":["நட்டார்போல் நல்லவை சொல்லினும் ஒட்டார்சொல்","ஒல்லை உணரப் படும்"],"tr":["Nattaarpol Nallavai Sollinum Ottaarsol","Ollai Unarap Patum"],"en":["Though many goodly words they speak in friendly tone,","The words of foes will speedily be known"],"s":"Though  (one's) foes may utter good things as though they were friends, once will at once understand  (their evil, import)","ch":83,"sec":2,"th":"friendship"},
  {"n":827,"ta":["சொல்வணக்கம் ஒன்னார்கண் கொள்ளற்க வில்வணக்கம்","தீங்கு குறித்தமை யான்"],"tr":["Solvanakkam Onnaarkan Kollarka Vilvanakkam","Theengu Kuriththamai Yaan"],"en":["To pliant speech from hostile lips give thou no ear;","'Tis pliant bow that show the deadly peril near"],"s":"Since the bending of the bow bespeaks evil, one should not accept  (as good) the humiliating speeches of one's foes","ch":83,"sec":2,"th":"friendship"},
  {"n":828,"ta":["தொழுதகை யுள்ளும் படையொடுங்கும் ஒன்னார்","அழுதகண் ணீரும் அனைத்து"],"tr":["Thozhudhakai Yullum Pataiyotungum Onnaar","Azhudhakan Neerum Anaiththu"],"en":["In hands that worship weapon ten hidden lies;","Such are the tears that fall from foeman's eyes"],"s":"A weapon may be hid in the very hands with which  (one's) foes adore  (him)  (and) the tears they shed are of the same nature","ch":83,"sec":2,"th":"friendship"},
  {"n":829,"ta":["மிகச்செய்து தம்மெள்ளு வாரை நகச்செய்து","நட்பினுள் சாப்புல்லற் பாற்று"],"tr":["Mikachcheydhu Thammellu Vaarai Nakachcheydhu","Natpinul Saappullar Paatru"],"en":["'Tis just, when men make much of you, and then despise,","To make them smile, and slap in friendship's guise"],"s":"It is the duty of kings to affect great love but make it die  (inwardly); as regard those foes who shew them great friendship but despise them  (in their heart)","ch":83,"sec":2,"th":"friendship"},
  {"n":830,"ta":["பகைநட்பாம் காலம் வருங்கால் முகநட்டு","அகநட்பு ஒரீஇ விடல்"],"tr":["Pakainatpaam Kaalam Varungaal Mukanattu","Akanatpu Oreei Vital"],"en":["When time shall come that foes as friends appear,","Then thou, to hide a hostile heart, a smiling face may'st wear"],"s":"When one's foes begin to affect friendship, one should love them with one's looks, and, cherishing no love in the heart, give up  (even the former)","ch":83,"sec":2,"th":"friendship"},
  {"n":831,"ta":["பேதைமை என்பதொன்று யாதெனின் ஏதங்கொண்டு","ஊதியம் போக விடல்"],"tr":["Pedhaimai Enpadhondru Yaadhenin Edhangontu","Oodhiyam Poka Vital"],"en":["What one thing merits folly's special name.","Letting gain go, loss for one's own to claim"],"s":"Folly is one  (of the chief defects); it is that which  (makes one) incur loss and forego gain","ch":84,"sec":2,"th":"wisdom"},
  {"n":832,"ta":["பேதைமையுள் எல்லாம் பேதைமை காதன்மை","கையல்ல தன்கட் செயல்"],"tr":["Pedhaimaiyul Ellaam Pedhaimai Kaadhanmai","Kaiyalla Thankat Seyal"],"en":["'Mid follies chiefest folly is to fix your love","On deeds which to your station unbefitting prove"],"s":"The greatest folly is that which leads one to take delight in doing what is forbidden","ch":84,"sec":2,"th":"wisdom"},
  {"n":833,"ta":["நாணாமை நாடாமை நாரின்மை யாதொன்றும்","பேணாமை பேதை தொழில்"],"tr":["Naanaamai Naataamai Naarinmai Yaadhondrum","Penaamai Pedhai Thozhil"],"en":["Ashamed of nothing, searching nothing out, of loveless heart,","Nought cherishing, 'tis thus the fool will play his part"],"s":"Shamelessness indifference  (to what must be sought after), harshness, and aversion for everything  (that ought to be desired) are the qualities of the fool","ch":84,"sec":2,"th":"wisdom"},
  {"n":834,"ta":["ஓதி உணர்ந்தும் பிறர்க்குரைத்தும் தானடங்காப்","பேதையின் பேதையார் இல்"],"tr":["Odhi Unarndhum Pirarkkuraiththum Thaanatangaap","Pedhaiyin Pedhaiyaar Il"],"en":["The sacred law he reads and learns, to other men expounds,","Himself obeys not; where can greater fool be found"],"s":"There are no greater fools than he who, though he has read and understood  (a great deal) and even taught it to others, does not walk according to his own teaching","ch":84,"sec":2,"th":"wisdom"},
  {"n":835,"ta":["ஒருமைச் செயலாற்றும் பேதை எழுமையும்","தான்புக் கழுந்தும் அளறு"],"tr":["Orumaich Cheyalaatrum Pedhai Ezhumaiyum","Thaanpuk Kazhundhum Alaru"],"en":["The fool will merit hell in one brief life on earth,","In which he entering sinks through sevenfold round of birth"],"s":"A fool can procure in a single birth a hell into which he may enter and suffer through all the seven births","ch":84,"sec":2,"th":"wisdom"},
  {"n":836,"ta":["பொய்படும் ஒன்றோ புனைபூணும் கையறியாப்","பேதை வினைமேற் கொளின்"],"tr":["Poipatum Ondro Punaipoonum Kaiyariyaap","Pedhai Vinaimer Kolin"],"en":["When fool some task attempts with uninstructed pains,","It fails; nor that alone, himself he binds with chains"],"s":"If the fool, who knows not how to act undertakes a work, he will  (certainly) fail  (But) is it all? He will even adorn himself with fetters","ch":84,"sec":2,"th":"wisdom"},
  {"n":837,"ta":["ஏதிலார் ஆரத் தமர்பசிப்பர் பேதை","பெருஞ்செல்வம் உற்றக் கடை"],"tr":["Edhilaar Aarath Thamarpasippar Pedhai","Perunjelvam Utrak Katai"],"en":["When fools are blessed with fortune's bounteous store,","Their foes feed full, their friends are prey to hunger sore"],"s":"If a fool happens to get an immense fortune, his neighbours will enjoy it while his relations starve","ch":84,"sec":2,"th":"wisdom"},
  {"n":838,"ta":["மையல் ஒருவன் களித்தற்றால் பேதைதன்","கையொன்று உடைமை பெறின்"],"tr":["Maiyal Oruvan Kaliththatraal Pedhaidhan","Kaiyondru Utaimai Perin"],"en":["When folly's hand grasps wealth's increase, 'twill be","As when a mad man raves in drunken glee"],"s":"A fool happening to possess something is like the intoxication of one who is  (already) giddy","ch":84,"sec":2,"th":"wisdom"},
  {"n":839,"ta":["பெரிதினிது பேதையார் கேண்மை பிரிவின்கண்","பீழை தருவதொன் றில்"],"tr":["Peridhinidhu Pedhaiyaar Kenmai Pirivinkan","Peezhai Tharuvadhon Ril"],"en":["Friendship of fools is very pleasant thing,","Parting with them will leave behind no sting"],"s":"The friendship between fools is exceedingly delightful  (to each other): for at parting there will be","ch":84,"sec":2,"th":"wisdom"},
  {"n":840,"ta":["கழாஅக்கால் பள்ளியுள் வைத்தற்றால் சான்றோர்","குழாஅத்துப் பேதை புகல்"],"tr":["Kazhaaakkaal Palliyul Vaiththatraal Saandror","Kuzhaaaththup Pedhai Pukal"],"en":["Like him who seeks his couch with unwashed feet,","Is fool whose foot intrudes where wise men meet"],"s":"The appearance of a fool in an assembly of the learned is like placing  (one's) unwashed feet on a bed","ch":84,"sec":2,"th":"wisdom"},
  {"n":841,"ta":["அறிவின்மை இன்மையுள் இன்மை பிறிதின்மை","இன்மையா வையா துலகு"],"tr":["Arivinmai Inmaiyul Inmai Piridhinmai","Inmaiyaa Vaiyaa Thulaku"],"en":["Want of knowledge, 'mid all wants the sorest want we deem;","Want of other things the world will not as want esteem"],"s":"The want of wisdom is the greatest of all wants; but that of wealth the world will not regard as such","ch":85,"sec":2,"th":"learning"},
  {"n":842,"ta":["அறிவிலான் நெஞ்சுவந்து ஈதல் பிறிதியாதும்","இல்லை பெறுவான் தவம்"],"tr":["Arivilaan Nenjuvandhu Eedhal Piridhiyaadhum","Illai Peruvaan Thavam"],"en":["The gift of foolish man, with willing heart bestowed, is nought,","But blessing by receiver's penance bought"],"s":"(The cause of) a fool cheerfully giving  (something) is nothing else but the receiver's merit  (in a former birth)","ch":85,"sec":2,"th":"learning"},
  {"n":843,"ta":["அறிவிலார் தாந்தம்மைப் பீழிக்கும் பீழை","செறுவார்க்கும் செய்தல் அரிது"],"tr":["Arivilaar Thaandhammaip Peezhikkum Peezhai","Seruvaarkkum Seydhal Aridhu"],"en":["With keener anguish foolish men their own hearts wring,","Than aught that even malice of their foes can bring"],"s":"The suffering that fools inflict upon themselves is hardly possible even to foes","ch":85,"sec":2,"th":"learning"},
  {"n":844,"ta":["வெண்மை எனப்படுவ தியாதெனின் ஒண்மை","உடையம்யாம் என்னும் செருக்கு"],"tr":["Venmai Enappatuva Thiyaadhenin Onmai","Utaiyamyaam Ennum Serukku"],"en":["What is stupidity? The arrogance that cries,","'Behold, we claim the glory of the wise. '"],"s":"What is called want of wisdom is the vanity which says, \"We are wise\"","ch":85,"sec":2,"th":"learning"},
  {"n":845,"ta":["கல்லாத மேற்கொண் டொழுகல் கசடற","வல்லதூஉம் ஐயம் தரும்"],"tr":["Kallaadha Merkon Tozhukal Kasatara","Valladhooum Aiyam Tharum"],"en":["If men what they have never learned assume to know,","Upon their real learning's power a doubt 'twill throw"],"s":"Fools pretending to know what has not been read  (by them) will rouse suspicion even as to what they have thoroughly mastered","ch":85,"sec":2,"th":"learning"},
  {"n":846,"ta":["அற்றம் மறைத்தலோ புல்லறிவு தம்வயின்","குற்றம் மறையா வழி"],"tr":["Atram Maraiththalo Pullarivu Thamvayin","Kutram Maraiyaa Vazhi"],"en":["Fools are they who their nakedness conceal,","And yet their faults unveiled reveal"],"s":"Even to cover one's nakedness would be folly, if  (one's) faults were not covered  (by forsaking them)","ch":85,"sec":2,"th":"learning"},
  {"n":847,"ta":["அருமறை சோரும் அறிவிலான் செய்யும்","பெருமிறை தானே தனக்கு"],"tr":["Arumarai Sorum Arivilaan Seyyum","Perumirai Thaane Thanakku"],"en":["From out his soul who lets the mystic teachings die,","Entails upon himself abiding misery"],"s":"The fool who neglects precious counsel does, of his own accord, a great injury to himself","ch":85,"sec":2,"th":"learning"},
  {"n":848,"ta":["ஏவவும் செய்கலான் தான்தேறான் அவ்வுயிர்","போஒம் அளவுமோர் நோய்"],"tr":["Evavum Seykalaan Thaandheraan Avvuyir","Poom Alavumor Noi"],"en":["Advised, he heeds not; of himself knows nothing wise;","This man's whole life is all one plague until he dies"],"s":"The fool will not perform  (his duties) even when advised nor ascertain them himself; such a soul is a","ch":85,"sec":2,"th":"learning"},
  {"n":849,"ta":["காணாதான் காட்டுவான் தான்காணான் காணாதான்","கண்டானாம் தான்கண்ட வாறு"],"tr":["Kaanaadhaan Kaattuvaan Thaankaanaan Kaanaadhaan","Kantaanaam Thaankanta Vaaru"],"en":["That man is blind to eyes that will not see who knowledge shows;","The blind man still in his blind fashion knows"],"s":"One who would teach a fool will  (simply) betray his folly; and the fool would  (still) think himself \"wise in his own conceit\"","ch":85,"sec":2,"th":"learning"},
  {"n":850,"ta":["உலகத்தார் உண்டென்பது இல்லென்பான் வையத்து","அலகையா வைக்கப் படும்"],"tr":["Ulakaththaar Untenpadhu Illenpaan Vaiyaththu","Alakaiyaa Vaikkap Patum"],"en":["Who what the world affirms as false proclaim,","O'er all the earth receive a demon's name"],"s":"He who denies the existence of what the world believes in will be regarded as a demon on earth","ch":85,"sec":2,"th":"learning"},
  {"n":851,"ta":["இகலென்ப எல்லா உயிர்க்கும் பகலென்னும்","பண்பின்மை பார஧க்கும் நோய்"],"tr":["Ikalenpa Ellaa Uyirkkum Pakalennum","Panpinmai Paarikkum Noi"],"en":["Hostility disunion's plague will bring,","That evil quality, to every living thing"],"s":"The disease which fosters the evil of disunion among all creatures is termed hatred by the wise","ch":86,"sec":2,"th":"friendship"},
  {"n":852,"ta":["பகல்கருதிப் பற்றா செயினும் இகல்கருதி","இன்னாசெய் யாமை தலை"],"tr":["Pakalkarudhip Patraa Seyinum Ikalkarudhi","Innaasey Yaamai Thalai"],"en":["Though men disunion plan, and do thee much despite","'Tis best no enmity to plan, nor evil deeds requite"],"s":"Though disagreeable things may be done from  (a feeling of) disunion, it is far better that nothing painful be done from  (that of) hatred","ch":86,"sec":2,"th":"friendship"},
  {"n":853,"ta":["இகலென்னும் எவ்வநோய் நீக்கின் தவலில்லாத்","தாவில் விளக்கம் தரும்"],"tr":["Ikalennum Evvanoi Neekkin Thavalillaath","Thaavil Vilakkam Tharum"],"en":["If enmity, that grievous plague, you shun,","Endless undying praises shall be won"],"s":"To rid one-self of the distressing dtsease of hatred will bestow  (on one) a never-decreasing imperishable fame","ch":86,"sec":2,"th":"friendship"},
  {"n":854,"ta":["இன்பத்துள் இன்பம் பயக்கும் இகலென்னும்","துன்பத்துள் துன்பங் கெடின்"],"tr":["Inpaththul Inpam Payakkum Ikalennum","Thunpaththul Thunpang Ketin"],"en":["Joy of joys abundant grows,","When malice dies that woe of woes"],"s":"If hatred which is the greatest misery is destroyed, it will yield the greatest delight","ch":86,"sec":2,"th":"friendship"},
  {"n":855,"ta":["இகலெதிர் சாய்ந்தொழுக வல்லாரை யாரே","மிக்லூக்கும் தன்மை யவர்"],"tr":["Ikaledhir Saaindhozhuka Vallaarai Yaare","Mikalookkum Thanmai Yavar"],"en":["If men from enmity can keep their spirits free,","Who over them shall gain the victory"],"s":"Who indeed would think of conquering those who naturally shrink back from hatred?","ch":86,"sec":2,"th":"friendship"},
  {"n":856,"ta":["இகலின் மிகலினிது என்பவன் வாழ்க்கை","தவலும் கெடலும் நணித்து"],"tr":["Ikalin Mikalinidhu Enpavan Vaazhkkai","Thavalum Ketalum Naniththu"],"en":["The life of those who cherished enmity hold dear,","To grievous fault and utter death is near"],"s":"Failure and ruin are not far from him who says it is sweet to excel in hatred","ch":86,"sec":2,"th":"friendship"},
  {"n":857,"ta":["மிகல்மேவல் மெய்ப்பொருள் காணார் இகல்மேவல்","இன்னா அறிவி னவர்"],"tr":["Mikalmeval Meypporul Kaanaar Ikalmeval","Innaa Arivi Navar"],"en":["The very truth that greatness gives their eyes can never see,","Who only know to work men woe, fulfilled of enmity"],"s":"Who only know to work men woe, fulfilled of enmity","ch":86,"sec":2,"th":"friendship"},
  {"n":858,"ta":["இகலிற்கு எதிர்சாய்தல் ஆக்கம் அதனை","மிக்லூக்கின் ஊக்குமாம் கேடு"],"tr":["Ikalirku Edhirsaaidhal Aakkam Adhanai","Mikalookkin Ookkumaam Ketu"],"en":["'Tis gain to turn the soul from enmity;","Ruin reigns where this hath mastery"],"s":"Shrinking back from hatred will yield wealth; indulging in its increase will hasten ruin","ch":86,"sec":2,"th":"friendship"},
  {"n":859,"ta":["இகல்காணான் ஆக்கம் வருங்கால் அதனை","மிகல்காணும் கேடு தரற்கு"],"tr":["Ikalkaanaan Aakkam Varungaal Adhanai","Mikalkaanum Ketu Thararku"],"en":["Men think not hostile thought in fortune's favouring hour,","They cherish enmity when in misfortune's power"],"s":"At the approach of wealth one will not think of hatred  (but) to secure one's ruin, one will look to its increase","ch":86,"sec":2,"th":"friendship"},
  {"n":860,"ta":["இகலானாம் இன்னாத எல்லாம் நகலானாம்","நன்னயம் என்னும் செருக்கு"],"tr":["Ikalaanaam Innaadha Ellaam Nakalaanaam","Nannayam Ennum Serukku"],"en":["From enmity do all afflictive evils flow;","But friendliness doth wealth of kindly good bestow"],"s":"All calamities are caused by hatred; but by the delight  (of friendship) is caused the great wealth of good virtues","ch":86,"sec":2,"th":"friendship"},
  {"n":861,"ta":["வலியார்க்கு மாறேற்றல் ஓம்புக ஓம்பா","மெலியார்மேல் மேக பகை"],"tr":["Valiyaarkku Maaretral Ompuka Ompaa","Meliyaarmel Meka Pakai"],"en":["With stronger than thyself, turn from the strife away;","With weaker shun not, rather court the fray"],"s":"Avoid offering resistance to the strong;  (but) never fail to cherish enmity towards the weak","ch":87,"sec":2,"th":"friendship"},
  {"n":862,"ta":["அன்பிலன் ஆன்ற துணையிலன் தான்துவ்வான்","என்பரியும் ஏதிலான் துப்பு"],"tr":["Anpilan Aandra Thunaiyilan Thaandhuvvaan","Enpariyum Edhilaan Thuppu"],"en":["No kinsman's love, no strength of friends has he;","How can he bear his foeman's enmity"],"s":"How can he who is unloving, destitute of powerful aids, and himself without strength overcome the might of his foe?","ch":87,"sec":2,"th":"friendship"},
  {"n":863,"ta":["அஞ்சும் அறியான் அமைவிலன் ஈகலான்","தஞ்சம் எளியன் பகைக்கு"],"tr":["Anjum Ariyaan Amaivilan Eekalaan","Thanjam Eliyan Pakaikku"],"en":["A craven thing! knows nought, accords with none, gives nought away;","To wrath of any foe he falls an easy prey"],"s":"In the estimation of foes miserably weak is he, who is timid, ignorant, unsociable and niggardly","ch":87,"sec":2,"th":"friendship"},
  {"n":864,"ta":["நீங்கான் வெகுளி நிறையிலன் எஞ்ஞான்றும்","யாங்கணும் யார்க்கும் எளிது"],"tr":["Neengaan Vekuli Niraiyilan Egngnaandrum","Yaanganum Yaarkkum Elidhu"],"en":["His wrath still blazes, every secret told; each day","This man's in every place to every foe an easy prey"],"s":"He who neither refrains from anger nor keeps his secrets will at all times and in all places be easily conquered by all","ch":87,"sec":2,"th":"friendship"},
  {"n":865,"ta":["வழிநோக்கான் வாய்ப்பன செய்யான் பழிநோக்கான்","பண்பிலன் பற்றார்க்கு இனிது"],"tr":["Vazhinokkaan Vaaippana Seyyaan Pazhinokkaan","Panpilan Patraarkku Inidhu"],"en":["No way of right he scans, no precepts bind, no crimes affright,","No grace of good he owns; such man's his foes' delight"],"s":"(A) pleasing  (object) to his foes is he who reads not moral works, does nothing that is enjoined by them cares not for reproach and is not possessed of good qualities","ch":87,"sec":2,"th":"friendship"},
  {"n":866,"ta":["காணாச் சினத்தான் கழிபெருங் காமத்தான்","பேணாமை பேணப் படும்"],"tr":["Kaanaach Chinaththaan Kazhiperung Kaamaththaan","Penaamai Penap Patum"],"en":["Blind in his rage, his lustful passions rage and swell;","If such a man mislikes you, like it well"],"s":"Highly to be desired is the hatred of him whose anger is blind, and whose lust increases beyond measure","ch":87,"sec":2,"th":"friendship"},
  {"n":867,"ta":["கொடுத்தும் கொளல்வேண்டும் மன்ற அடுத்திருந்து","மாணாத செய்வான் பகை"],"tr":["Kotuththum Kolalventum Mandra Atuththirundhu","Maanaadha Seyvaan Pakai"],"en":["Unseemly are his deeds, yet proffering aid, the man draws nigh:","His hate- 'tis cheap at any price- be sure to buy"],"s":"It is indeed necessary to obtain even by purchase the hatred of him who having begun  (a work) does what is not conductive  (to its accomplishment)","ch":87,"sec":2,"th":"friendship"},
  {"n":868,"ta":["குணனிலனாய்க் குற்றம் பலவாயின் மாற்றார்க்கு","இனனிலனாம் ஏமாப் புடைத்து"],"tr":["Kunanilanaaik Kutram Palavaayin Maatraarkku","Inanilanaam Emaap Putaiththu"],"en":["No gracious gifts he owns, faults many cloud his fame;","His foes rejoice, for none with kindred claim"],"s":"He will become friendless who is without  (any good) qualities and whose faults are many;  (such a character) is a help to  (his) foes","ch":87,"sec":2,"th":"friendship"},
  {"n":869,"ta":["செறுவார்க்குச் சேணிகவா இன்பம் அறிவிலா","அஞ்சும் பகைவர்ப் பெறின்"],"tr":["Seruvaarkkuch Chenikavaa Inpam Arivilaa","Anjum Pakaivarp Perin"],"en":["The joy of victory is never far removed from those","Who've luck to meet with ignorant and timid foes"],"s":"There will be no end of lofty delights to the victorious, if their foes are  (both) ignorant and timid","ch":87,"sec":2,"th":"friendship"},
  {"n":870,"ta":["கல்லான் வெகுளும் சிறுபொருள் எஞ்ஞான்றும்","ஒல்லானை ஒல்லா தொளி"],"tr":["Kallaan Vekulum Siruporul Egngnaandrum","Ollaanai Ollaa Tholi"],"en":["The task of angry war with men unlearned in virtue's lore","Who will not meet, glory shall meet him never more"],"s":"The light  (of fame) will never be gained by him who gains not the trifling reputation of having fought an unlearned  (foe)","ch":87,"sec":2,"th":"friendship"},
  {"n":871,"ta":["பகைஎன்னும் பண்பி லதனை ஒருவன்","நகையேயும் வேண்டற்பாற்று அன்று"],"tr":["Pakaiennum Panpi Ladhanai Oruvan","Nakaiyeyum Ventarpaatru Andru"],"en":["For Hate, that ill-conditioned thing not e'en in jest","Let any evil longing rule your breast"],"s":"The evil of hatred is not of a nature to be desired by one even in sport","ch":88,"sec":2,"th":"friendship"},
  {"n":872,"ta":["வில்லேர் உழவர் பகைகொளினும் கொள்ளற்க","சொல்லேர் உழவர் பகை"],"tr":["Viller Uzhavar Pakaikolinum Kollarka","Soller Uzhavar Pakai"],"en":["Although you hate incur of those whose ploughs are bows,","Make not the men whose ploughs are words your foes"],"s":"Though you may incur the hatred of warriors whose ploughs are bows, incur not that of ministers whose ploughs are words","ch":88,"sec":2,"th":"friendship"},
  {"n":873,"ta":["ஏமுற் றவரினும் ஏழை தமியனாய்ப்","பல்லார் பகைகொள் பவன்"],"tr":["Emur Ravarinum Ezhai Thamiyanaaip","Pallaar Pakaikol Pavan"],"en":["Than men of mind diseased, a wretch more utterly forlorn,","Is he who stands alone, object of many foeman's scorn"],"s":"He who being alone, incurs the hatred of many is more infatuated than even mad men","ch":88,"sec":2,"th":"friendship"},
  {"n":874,"ta":["பகைநட்பாக் கொண்டொழுகும் பண்புடை யாளன்","தகைமைக்கண் தங்கிற்று உலகு"],"tr":["Pakainatpaak Kontozhukum Panputai Yaalan","Thakaimaikkan Thangitru Ulaku"],"en":["The world secure on his dexterity depends,","Whose worthy rule can change his foes to friends"],"s":"Whose worthy rule can change his foes to friends","ch":88,"sec":2,"th":"friendship"},
  {"n":875,"ta":["தன்துணை இன்றால் பகையிரண்டால் தான்ஒருவன்","இன்துணையாக் கொள்கவற்றின் ஒன்று"],"tr":["Thandhunai Indraal Pakaiyirantaal Thaanoruvan","Indhunaiyaak Kolkavatrin Ondru"],"en":["Without ally, who fights with twofold enemy o'ermatched,","Must render one of these a friend attached"],"s":"He who is alone and helpless while his foes are two should secure one of them as an agreeable help  (to himself)","ch":88,"sec":2,"th":"friendship"},
  {"n":876,"ta":["தேறினும் தேறா விடினும் அழிவின்கண்","தேறான் பகாஅன் விடல்"],"tr":["Thera�num Theraa Vitinum Azhivinkan","Theraan Pakaaan Vital"],"en":["Whether you trust or not, in time of sore distress,","Questions of diff'rence or agreement cease to press"],"s":"Though  (one's foe is) aware or not of one's misfortune one should act so as neither to join nor separate  (from him)","ch":88,"sec":2,"th":"friendship"},
  {"n":877,"ta":["நோவற்க நொந்தது அறியார்க்கு மேவற்க","மென்மை பகைவர் அகத்து"],"tr":["Novarka Nondhadhu Ariyaarkku Mevarka","Menmai Pakaivar Akaththu"],"en":["To those who know them not, complain not of your woes;","Nor to your foeman's eyes infirmities disclose"],"s":"Relate not your suffering even to friends who are ignorant of it, nor refer to your weakness in the presence of your foes","ch":88,"sec":2,"th":"friendship"},
  {"n":878,"ta":["வகையறிந்து தற்செய்து தற்காப்ப மாயும்","பகைவர்கண் பட்ட செருக்கு"],"tr":["Vakaiyarindhu Tharseydhu Tharkaappa Maayum","Pakaivarkan Patta Serukku"],"en":["Know thou the way, then do thy part, thyself defend;","Thus shall the pride of those that hate thee have an end"],"s":"The joy of one's foes will be destroyed if one guards oneself by knowing the way  (of acting) and securing assistance","ch":88,"sec":2,"th":"friendship"},
  {"n":879,"ta":["இளைதாக முள்மரம் கொல்க களையுநர்","கைகொல்லும் காழ்த்த இடத்து"],"tr":["Ilaidhaaka Mulmaram Kolka Kalaiyunar","Kaikollum Kaazhththa Itaththu"],"en":["Destroy the thorn, while tender point can work thee no offence;","Matured by time, 'twill pierce the hand that plucks it thence"],"s":"A thorny tree should be felled while young,  (for) when it is grown it will destroy the hand of the feller","ch":88,"sec":2,"th":"friendship"},
  {"n":880,"ta":["உயிர்ப்ப உளரல்லர் மன்ற செயிர்ப்பவர்","செம்மல் சிதைக்கலா தார்"],"tr":["Uyirppa Ularallar Mandra Seyirppavar","Semmal Sidhaikkalaa Thaar"],"en":["But breathe upon them, and they surely die,","Who fail to tame the pride of angry enemy"],"s":"Those who do not destroy the pride of those who hate  (them) will certainly not exist even to breathe","ch":88,"sec":2,"th":"friendship"},
  {"n":881,"ta":["நிழல்நீரும் இன்னாத இன்னா தமர்நீரும்","இன்னாவாம் இன்னா செயின்"],"tr":["Nizhalneerum Innaadha Innaa Thamarneerum","Innaavaam Innaa Seyin"],"en":["Water and shade, if they unwholesome prove, will bring you pain","And qualities of friends who treacherous act, will be your bane"],"s":"Shade and water are not pleasant,  (if) they cause disease; so are the qualities of  (one's) relations not agreeable,  (if) they cause pain","ch":89,"sec":2,"th":"friendship"},
  {"n":882,"ta":["வாள்போல பகைவரை அஞ்சற்க அஞ்சுக","கேள்போல் பகைவர் தொடர்பு"],"tr":["Vaalpola Pakaivarai Anjarka Anjuka","Kelpol Pakaivar Thotarpu"],"en":["Dread not the foes that as drawn swords appear;","Friendship of foes, who seem like kinsmen, fear"],"s":"Fear not foes  (who say they would cut) like a sword;  (but) fear the friendship of foes  (who seemingly","ch":89,"sec":2,"th":"friendship"},
  {"n":883,"ta":["உட்பகை அஞ்சித்தற் காக்க உலைவிடத்து","மட்பகையின் மாணத் தெறும்"],"tr":["Utpakai Anjiththar Kaakka Ulaivitaththu","Matpakaiyin Maanath Therum"],"en":["Of hidden hate beware, and guard thy life;","In troublous time 'twill deeper wound than potter's knife"],"s":"Fear internal enmity and guard yourself;  (if not) it will destroy  (you) in an evil hour, as surely as the tool which cuts the potter's clay","ch":89,"sec":2,"th":"friendship"},
  {"n":884,"ta":["மனமாணா உட்பகை தோன்றின் இனமாணா","ஏதம் பலவும் தரும்"],"tr":["Manamaanaa Utpakai Thondrin Inamaanaa","Edham Palavum Tharum"],"en":["If secret enmities arise that minds pervert,","Then even kin unkind will work thee grievous hurt"],"s":"The secret enmity of a person whose mind in unreformed will lead to many evils causing disaffection among  (one's) relations","ch":89,"sec":2,"th":"friendship"},
  {"n":885,"ta":["உறல்முறையான் உட்பகை தோன்றின் இறல்முறையான்","ஏதம் பலவும் தரும்"],"tr":["Uralmuraiyaan Utpakai Thondrin Iralmuraiyaan","Edham Palavum Tharum"],"en":["Amid one's relatives if hidden hath arise,","'Twill hurt inflict in deadly wise"],"s":"If there appears internal hatred in a  (king's) family; it will lead to many a fatal crime","ch":89,"sec":2,"th":"friendship"},
  {"n":886,"ta":["ஒன்றாமை ஒன்றியார் கட்படின் எஞ்ஞான்றும்","பொன்றாமை ஒன்றல் அரிது"],"tr":["Ondraamai Ondriyaar Katpatin Egngnaandrum","Pondraamai Ondral Aridhu"],"en":["If discord finds a place midst those who dwelt at one before,","'Tis ever hard to keep destruction from the door"],"s":"If hatred arises among  (one's) own people, it will be hardly possible  (for one) to escape death","ch":89,"sec":2,"th":"friendship"},
  {"n":887,"ta":["செப்பின் புணர்ச்சிபோல் கூடினும் கூடாதே","உட்பகை உற்ற குடி"],"tr":["Seppin Punarchchipol Kootinum Kootaadhe","Utpakai Utra Kuti"],"en":["As casket with its cover, though in one they live alway,","No union to the house where hate concealed hath sway"],"s":"Never indeed will a family subject to internal hatred unite  (really) though it may present an apparent union like that of a casket and its lid","ch":89,"sec":2,"th":"friendship"},
  {"n":888,"ta":["அரம்பொருத பொன்போலத் தேயும் உரம்பொருது","உட்பகை உற்ற குடி"],"tr":["Aramporudha Ponpolath Theyum Uramporudhu","Utpakai Utra Kuti"],"en":["As gold with which the file contends is worn away,","So strength of house declines where hate concealed hath sway"],"s":"A family subject to internal hatred will wear out and lose its strength like iron that has been filed away","ch":89,"sec":2,"th":"friendship"},
  {"n":889,"ta":["எட்பக வன்ன சிறுமைத்தே ஆயினும்","உட்பகை உள்ளதாங் கேடு"],"tr":["Etpaka Vanna Sirumaiththe Aayinum","Utpakai Ulladhaang Ketu"],"en":["Though slight as shred of 'seasame' seed it be,","Destruction lurks in hidden enmity"],"s":"Although internal hatred be as small as the fragment of the sesamum  (seed), still does destruction dwell in it","ch":89,"sec":2,"th":"friendship"},
  {"n":890,"ta":["உடம்பாடு இலாதவர் வாழ்க்கை குடங்கருள்","பாம்போடு உடனுறைந் தற்று"],"tr":["Utampaatu Ilaadhavar Vaazhkkai Kutangarul","Paampotu Utanurain Thatru"],"en":["Domestic life with those who don't agree,","Is dwelling in a shed with snake for company"],"s":"Living with those who do not agree  (with one) is like dwelling with a cobra  (in the same) hut","ch":89,"sec":2,"th":"friendship"},
  {"n":891,"ta":["ஆற்றுவார் ஆற்றல் இகழாமை போற்றுவார்","போற்றலுள் எல்லாம் தலை"],"tr":["Aatruvaar Aatral Ikazhaamai Potruvaar","Potralul Ellaam Thalai"],"en":["The chiefest care of those who guard themselves from ill,","Is not to slight the powers of those who work their mighty will"],"s":"Not to disregard the power of those who can carry out  (their wishes) is more important than all the watchfulness of those who guard  (themselves against evil)","ch":90,"sec":2,"th":"friendship"},
  {"n":892,"ta":["பெரியாரைப் பேணாது ஒழுகிற் பெரியாரால்","பேரா இடும்பை தரும்"],"tr":["Periyaaraip Penaadhu Ozhukir Periyaaraal","Peraa Itumpai Tharum"],"en":["If men will lead their lives reckless of great men's will,","Such life, through great men's powers, will bring perpetual ill"],"s":"To behave without respect for the great  (rulers) will make them do  (us) irremediable evils","ch":90,"sec":2,"th":"friendship"},
  {"n":893,"ta":["கெடல்வேண்டின் கேளாது செய்க அடல்வேண்டின்","ஆற்று பவர்கண் இழுக்கு"],"tr":["Ketalventin Kelaadhu Seyka Atalventin","Aatru Pavarkan Izhukku"],"en":["Who ruin covet let them shut their ears, and do despite","To those who, where they list to ruin have the might"],"s":"If a person desires ruin, let him not listen to the righteous dictates of law, but commit crimes against those who are able to slay  (other sovereigns)","ch":90,"sec":2,"th":"friendship"},
  {"n":894,"ta":["கூற்றத்தைக் கையால் விளித்தற்றால் ஆற்றுவார்க்கு","ஆற்றாதார் இன்னா செயல்"],"tr":["Kootraththaik Kaiyaal Viliththatraal Aatruvaarkku","Aatraadhaar Innaa Seyal"],"en":["When powerless man 'gainst men of power will evil deeds essay,","Tis beck'ning with the hand for Death to seize them for its prey"],"s":"The weak doing evil to the strong is like beckoning Yama to come  (and destroy them)","ch":90,"sec":2,"th":"friendship"},
  {"n":895,"ta":["யாண்டுச்சென்று யாண்டும் உளராகார் வெந்துப்பின்","வேந்து செறப்பட் டவர்"],"tr":["Yaantuch Chendru Yaantum Ularaakaar","Vendhuppin Vendhu Serappat Tavar"],"en":["Who dare the fiery wrath of monarchs dread,","Where'er they flee, are numbered with the dead"],"s":"Those who have incurred the wrath of a cruel and mighty potentate will not prosper wherever they may go","ch":90,"sec":2,"th":"friendship"},
  {"n":896,"ta":["எரியால் சுடப்படினும் உய்வுண்டாம் உய்யார்","பெரியார்ப் பிழைத்தொழுகு வார்"],"tr":["Eriyaal Sutappatinum Uyvuntaam Uyyaar","Periyaarp Pizhaiththozhuku Vaar"],"en":["Though in the conflagration caught, he may escape from thence:","He 'scapes not who in life to great ones gives offence"],"s":"Though burnt by a fire  (from a forest), one may perhaps live;  (but) never will he live who has shown disrespect to the great  (devotees)","ch":90,"sec":2,"th":"friendship"},
  {"n":897,"ta":["வகைமாண்ட வாழ்க்கையும் வான்பொருளும் என்னாம்","தகைமாண்ட தக்கார் செறின்"],"tr":["Vakaimaanta Vaazhkkaiyum Vaanporulum Ennaam","Thakaimaanta Thakkaar Serin"],"en":["Though every royal gift, and stores of wealth your life should crown,","What are they, if the worthy men of mighty virtue frown"],"s":"If a king incurs the wrath of the righteous great, what will become of his government with its splendid auxiliaries and  (all) its untold wealth?","ch":90,"sec":2,"th":"friendship"},
  {"n":898,"ta":["குன்றன்னார் குன்ற மதிப்பின் குடியொடு","நின்றன்னார் மாய்வர் நிலத்து"],"tr":["Kundrannaar Kundra Madhippin Kutiyotu","Nindrannaar Maaivar Nilaththu"],"en":["If they, whose virtues like a mountain rise, are light esteemed;","They die from earth who, with their households, ever-during seemed"],"s":"If  (the) hill-like  (devotees) resolve on destruction, those who seemed to be everlasting will be destroyed root and branch from the earth","ch":90,"sec":2,"th":"friendship"},
  {"n":899,"ta":["ஏந்திய கொள்கையார் சீறின் இடைமுரிந்து","வேந்தனும் வேந்து கெடும்"],"tr":["Endhiya Kolkaiyaar Seerin Itaimurindhu","Vendhanum Vendhu Ketum"],"en":["When blazes forth the wrath of men of lofty fame,","Kings even fall from high estate and perish in the flame"],"s":"Kings even fall from high estate and perish in the flame","ch":90,"sec":2,"th":"friendship"},
  {"n":900,"ta":["இறந்தமைந்த சார்புடையர் ஆயினும் உய்யார்","சிறந்தமைந்த சீரார் செறின்"],"tr":["Irandhamaindha Saarputaiyar Aayinum Uyyaar","Sirandhamaindha Seeraar Serin"],"en":["Though all-surpassing wealth of aid the boast,","If men in glorious virtue great are wrath, they're lost"],"s":"Though in possession of numerous auxiliaries, they will perish who are-exposed to the wrath of the noble whose penance is boundless","ch":90,"sec":2,"th":"friendship"},
  {"n":901,"ta":["மனைவிழைவார் மாண்பயன் எய்தார் வினைவிழையார்","வேண்டாப் பொருளும் அது"],"tr":["Manaivizhaivaar Maanpayan Eydhaar Vinaivizhaiyaar","Ventaap Porulum Adhu"],"en":["Who give their soul to love of wife acquire not nobler gain;","Who give their soul to strenuous deeds such meaner joys disdain"],"s":"Those who lust after their wives will not attain the excellence of virtue; and it is just this that is not desired by those who are bent on acquiring wealth","ch":91,"sec":2,"th":"friendship"},
  {"n":902,"ta":["பேணாது பெண்விழைவான் ஆக்கம் பெரியதோர்","நாணாக நாணுத் தரும்"],"tr":["Penaadhu Penvizhaivaan Aakkam Periyadhor","Naanaaka Naanuth Tharum"],"en":["Who gives himself to love of wife, careless of noble name","His wealth will clothe him with o'erwhelming shame"],"s":"The wealth of him who, regardless  (of his manliness), devotes himself to his wife's feminine nature will cause great shame  (to ali men) and to himself;","ch":91,"sec":2,"th":"friendship"},
  {"n":903,"ta":["இல்லாள்கண் தாழ்ந்த இயல்பின்மை எஞ்ஞான்றும்","நல்லாருள் நாணுத் தரும்"],"tr":["Illaalkan Thaazhndha Iyalpinmai Egngnaandrum","Nallaarul Naanuth Tharum"],"en":["Who to his wife submits, his strange, unmanly mood","Will daily bring him shame among the good"],"s":"The frailty that stoops to a wife will always make  (her husband) feel ashamed among the good","ch":91,"sec":2,"th":"friendship"},
  {"n":904,"ta":["மனையாளை அஞ்சும் மறுமையி லாளன்","வினையாண்மை வீறெய்த லின்று"],"tr":["Manaiyaalai Anjum Marumaiyi Laalan","Vinaiyaanmai Veereydha Lindru"],"en":["No glory crowns e'en manly actions wrought","By him who dreads his wife, nor gives the other world a thought"],"s":"The undertaking of one, who fears his wife and is therefore destitute of  (bliss), will never be applauded","ch":91,"sec":2,"th":"friendship"},
  {"n":905,"ta":["இல்லாளை அஞ்சுவான் அஞ்சுமற் றெஞ்ஞான்றும்","நல்லார்க்கு நல்ல செயல்"],"tr":["Illaalai Anjuvaan Anjumar Regngnaandrum","Nallaarkku Nalla Seyal"],"en":["Who quakes before his wife will ever tremble too,","Good deeds to men of good deserts to do"],"s":"He that fears his wife will always be afraid of doing good deeds  (even) to the good","ch":91,"sec":2,"th":"friendship"},
  {"n":906,"ta":["இமையாரின் வாழினும் பாடிலரே இல்லாள்","அமையார்தோள் அஞ்சு பவர்"],"tr":["Imaiyaarin Vaazhinum Paatilare Illaal","Amaiyaardhol Anju Pavar"],"en":["Though, like the demi-gods, in bliss they dwell secure from harm,","Those have no dignity who fear the housewife's slender arm"],"s":"They that fear the bamboo-like shoulders of their wives will be destitute of manliness though they may flourish like the Gods","ch":91,"sec":2,"th":"friendship"},
  {"n":907,"ta":["பெண்ணேவல் செய்தொழுகும் ஆண்மையின் நாணுடைப்","பெண்ணே பெருமை உடைத்து"],"tr":["Penneval Seydhozhukum Aanmaiyin Naanutaip","Penne Perumai Utaiththu"],"en":["The dignity of modest womanhood excels","His manliness, obedient to a woman's law who dwells"],"s":"Even shame faced womanhood is more to be esteemed than the shameless manhood that performs","ch":91,"sec":2,"th":"friendship"},
  {"n":908,"ta":["நட்டார் குறைமுடியார் நன்றாற்றார் நன்னுதலாள்","பெட் டாங்கு ஒழுகு பவர்"],"tr":["Nattaar Kuraimutiyaar Nandraatraar Nannudhalaal","Pettaangu Ozhuku Pavar"],"en":["Who to the will of her with beauteous brow their lives conform,","Aid not their friends in need, nor acts of charity perform"],"s":"Those who yield to the wishes of their wives will neither relieve the wants of  (their) friends nor perform virtuous deeds","ch":91,"sec":2,"th":"friendship"},
  {"n":909,"ta":["அறவினையும் ஆன்ற பொருளும் பிறவினையும்","பெண்ஏவல் செய்வார்கண் இல்"],"tr":["Aravinaiyum Aandra Porulum Piravinaiyum","Peneval Seyvaarkan Il"],"en":["No virtuous deed, no seemly wealth, no pleasure, rests","With them who live obedient to their wives' behests"],"s":"From those who obey the commands of their wives are to be expected neither deeds of virtue, nor those of wealth nor  (even) those of pleasure","ch":91,"sec":2,"th":"friendship"},
  {"n":910,"ta":["எண்சேர்ந்த நெஞ்சத் திடனுடையார்க்கு எஞ்ஞான்றும்","பெண்சேர்ந்தாம் பேதைமை இல்"],"tr":["Enserndha Nenjath Thitanutaiyaarkku Egngnaandrum","Penserndhaam Pedhaimai Il"],"en":["Where pleasures of the mind, that dwell in realms of thought, abound,","Folly, that springs from overweening woman's love, is never found"],"s":"The foolishness that results from devotion to a wife will never be found in those who possess a reflecting mind and a prosperity  (flowing) therefrom","ch":91,"sec":2,"th":"friendship"},
  {"n":911,"ta":["அன்பின் விழையார் பொருள்விழையும் ஆய்தொடியார்","இன்சொல் இழுக்குத் தரும்"],"tr":["Anpin Vizhaiyaar Porulvizhaiyum Aaidhotiyaar","Insol Izhukkuth Tharum"],"en":["Those that choice armlets wear who seek not thee with love,","But seek thy wealth, their pleasant words will ruin prove"],"s":"The sweet words of elegant braceleted  (prostitutes) who desire  (a man) not from affection but from avarice, will cause sorrow","ch":92,"sec":2,"th":"friendship"},
  {"n":912,"ta":["பயன்தூக்கிப் பண்புரைக்கும் பண்பின் மகளிர்","நயன்தூக்கி நள்ளா விடல்"],"tr":["Payandhookkip Panpuraikkum Panpin Makalir","Nayandhookki Nallaa Vital"],"en":["Who weigh the gain, and utter virtuous words with vicious heart,","Weighing such women's worth, from their society depart"],"s":"One must ascertain the character of the ill-natured women who after ascertaining the wealth  (of a man) speak  (as if they were) good natured-ones, and avoid intercourse  (with them)","ch":92,"sec":2,"th":"friendship"},
  {"n":913,"ta":["பொருட்பெண்டிர் பொய்ம்மை முயக்கம் இருட்டறையில்","ஏத஧ல் பிணந்தழீஇ அற்று"],"tr":["Porutpentir Poimmai Muyakkam Iruttaraiyil","Edhil Pinandhazheei Atru"],"en":["As one in darkened room, some stranger corpse inarms,","Is he who seeks delight in mercenary women's charms"],"s":"The false embraces of wealth-loving women are like  (hired men) embracing a strange corpse in a dark room","ch":92,"sec":2,"th":"friendship"},
  {"n":914,"ta":["பொருட்பொருளார் புன்னலந் தோயார் அருட்பொருள்","ஆயும் அறிவி னவர்"],"tr":["Porutporulaar Punnalan Thoyaar Arutporul","Aayum Arivi Navar"],"en":["Their worthless charms, whose only weal is wealth of gain,","From touch of these the wise, who seek the wealth of grace, abstain"],"s":"The wise who seek the wealth of grace will not desire the base favours of those who regard wealth  (and not pleasure) as  (their) riches","ch":92,"sec":2,"th":"friendship"},
  {"n":915,"ta":["பொதுநலத்தார் புன்னலம் தோயார் மதிநலத்தின்","மாண்ட அறிவி னவர்"],"tr":["Podhunalaththaar Punnalam Thoyaar Madhinalaththin","Maanta Arivi Navar"],"en":["From contact with their worthless charms, whose charms to all are free,","The men with sense of good and lofty wisdom blest will flee;"],"s":"Those whose knowledge is made excellent by their  (natural) sense will not covet the trffling delights","ch":92,"sec":2,"th":"friendship"},
  {"n":916,"ta":["தந்நலம் பாரிப்பார் தோயார் தகைசெருக்கிப்","புன்னலம் பாரிப்பார் தோள்"],"tr":["Thannalam Paarippaar Thoyaar Thakaiserukkip","Punnalam Paarippaar Thol"],"en":["From touch of those who worthless charms, with wanton arts, display,","The men who would their own true good maintain will turn away"],"s":"Those who would spread  (the fame of) their own goodness will not desire the shoulders of those, who rejoice in their accomplishments and bestow their despicable favours  (on all who pay)","ch":92,"sec":2,"th":"friendship"},
  {"n":917,"ta":["நிறைநெஞ்சம் இல்லவர் தோய்வார் பிறநெஞ்சிற்","பேணிப் புணர்பவர் தோள்"],"tr":["Nirainenjam Illavar Thoivaar Piranenjir","Penip Punarpavar Thol"],"en":["Who cherish alien thoughts while folding in their feigned embrace,","These none approach save those devoid of virtue's grace"],"s":"Those who are destitute of a perfectly  (reformed) mind will covet the shoulders of those who embrace  (them) while their hearts covet other things","ch":92,"sec":2,"th":"friendship"},
  {"n":918,"ta":["ஆயும் அறிவினர் அல்லார்க்கு அணங்கென்ப","மாய மகளிர் முயக்கு"],"tr":["Aayum Arivinar Allaarkku Anangenpa","Maaya Makalir Muyakku"],"en":["As demoness who lures to ruin woman's treacherous love","To men devoid of wisdom's searching power will prove"],"s":"The wise say that to such as are destitute of discerning sense the embraces of faithless women are  (as ruinous as those of) the celestail female","ch":92,"sec":2,"th":"friendship"},
  {"n":919,"ta":["வரைவிலா மாணிழையார் மென்தோள் புரையிலாப்","பூரியர்கள் ஆழும் அளறு"],"tr":["Varaivilaa Maanizhaiyaar Mendhol Puraiyilaap","Pooriyarkal Aazhum Alaru"],"en":["The wanton's tender arm, with gleaming jewels decked,","Is hell, where sink degraded souls of men abject"],"s":"The delicate shoulders of prostitutes with excellent jewels are a hell into which are plunged the ignorant base","ch":92,"sec":2,"th":"friendship"},
  {"n":920,"ta":["இருமனப் பெண்டிரும் கள்ளும் கவறும்","திருநீக்கப் பட்டார் தொடர்பு"],"tr":["Irumanap Pentirum Kallum Kavarum","Thiruneekkap Pattaar Thotarpu"],"en":["Women of double minds, strong drink, and dice; to these giv'n o'er,","Are those on whom the light of Fortune shines no more"],"s":"Treacherous women, liquor, and gambling are the associates of such as have forsaken by Fortune","ch":92,"sec":2,"th":"friendship"},
  {"n":921,"ta":["உட்கப் படாஅர் ஒளியிழப்பர் எஞ்ஞான்றும்","கட்காதல் கொண்டொழுகு வார்"],"tr":["Utkap Pataaar Oliyizhappar Egngnaandrum","Katkaadhal Kontozhuku Vaar"],"en":["Who love the palm's intoxicating juice, each day,","No rev'rence they command, their glory fades away"],"s":"Those who always thirst after drink will neither inspire fear  (in others) nor retain the light  (of their fame)","ch":93,"sec":2,"th":"calm"},
  {"n":922,"ta":["உண்ணற்க கள்ளை உணில்உண்க சான்றோரான்","எண்ணப் படவேண்டா தார்"],"tr":["Unnarka Kallai Unilunka Saandroraan","Ennap Pataventaa Thaar"],"en":["Drink not inebriating draught Let him count well the cost","Who drinks, by drinking, all good men's esteem is lost"],"s":"Let no liquor be drunk; if it is desired, let it be drunk by those who care not for esteem of the great","ch":93,"sec":2,"th":"calm"},
  {"n":923,"ta":["ஈன்றாள் முகத்தேயும் இன்னாதால் என்மற்றுச்","சான்றோர் முகத்துக் களி"],"tr":["Eendraal Mukaththeyum Innaadhaal Enmatruch","Chaandror Mukaththuk Kali"],"en":["The drunkard's joy is sorrow to his mother's eyes;","What must it be in presence of the truly wise"],"s":"Intoxication is painful even in the presence of  (one's) mother; what will it not then be in that of the wise?","ch":93,"sec":2,"th":"calm"},
  {"n":924,"ta":["நாண்என்னும் நல்லாள் புறங்கொடுக்கும் கள்ளென்னும்","பேணாப் பெருங்குற்றத் தார்க்கு"],"tr":["Naanennum Nallaal Purangotukkum Kallennum","Penaap Perungutrath Thaarkku"],"en":["Shame, goodly maid, will turn her back for aye on them","Who sin the drunkard's grievous sin, that all condemn"],"s":"The fair maid of modesty will turn her back on those who are guilty of the great and abominable crime of drunkenness","ch":93,"sec":2,"th":"calm"},
  {"n":925,"ta":["கையறி யாமை உடைத்தே பொருள்கொடுத்து","மெய்யறி யாமை கொளல்"],"tr":["Kaiyari Yaamai Utaiththe Porulkotuththu","Meyyari Yaamai Kolal"],"en":["With gift of goods who self-oblivion buys,","Is ignorant of all that man should prize"],"s":"To give money and purchase unconsciousness is the result of one's ignorance of  (one's own actions)","ch":93,"sec":2,"th":"calm"},
  {"n":926,"ta":["துஞ்சினார் செத்தாரின் வேறல்லர் எஞ்ஞான்றும்","நஞ்சுண்பார் கள்ளுண் பவர்"],"tr":["Thunjinaar Seththaarin Verallar Egngnaandrum","Nanjunpaar Kallun Pavar"],"en":["Sleepers are as the dead, no otherwise they seem;","Who drink intoxicating draughts, they poison quaff, we deem"],"s":"They that sleep resemble the deed;  (likewise) they that drink are no other than poison-eaters","ch":93,"sec":2,"th":"calm"},
  {"n":927,"ta":["உள்ளொற்றி உள்ளூர் நகப்படுவர் எஞ்ஞான்றும்","கள்ளொற்றிக் கண்சாய் பவர்"],"tr":["Ullotri Ulloor Nakappatuvar Egngnaandrum","Kallotrik Kansaai Pavar"],"en":["Who turn aside to drink, and droop their heavy eye,","Shall be their townsmen's jest, when they the fault espy"],"s":"Those who always intoxicate themselves by a private  (indulgence in) drink; will have their secrets detected and laughed at by their fellow-townsmen","ch":93,"sec":2,"th":"calm"},
  {"n":928,"ta":["களித்தறியேன் என்பது கைவிடுக நெஞ்சத்து","ஒளித்ததூஉம் ஆங்கே மிகும்"],"tr":["Kaliththariyen Enpadhu Kaivituka Nenjaththu","Oliththadhooum Aange Mikum"],"en":["No more in secret drink, and then deny thy hidden fraud;","What in thy mind lies hid shall soon be known abroad"],"s":"Let  (the drunkard) give up saying \"I have never drunk\";  (for) the moment  (he drinks) he will simply betray his former attempt to conceal","ch":93,"sec":2,"th":"calm"},
  {"n":929,"ta":["களித்தானைக் காரணம் காட்டுதல் கீழ்நீர்க்","குளித்தானைத் தீத்துரீஇ அற்று"],"tr":["Kaliththaanaik Kaaranam Kaattudhal Keezhneerk","Kuliththaanaith Theeththureei Atru"],"en":["Like him who, lamp in hand, would seek one sunk beneath the wave","Is he who strives to sober drunken man with reasonings grave"],"s":"Reasoning with a drunkard is like going under water with a torch in search of a drowned man","ch":93,"sec":2,"th":"calm"},
  {"n":930,"ta":["கள்ளுண்ணாப் போழ்திற் களித்தானைக் காணுங்கால்","உள்ளான்கொல் உண்டதன் சோர்வு"],"tr":["Kallunnaap Pozhdhir Kaliththaanaik Kaanungaal","Ullaankol Untadhan Sorvu"],"en":["When one, in sober interval, a drunken man espies,","Does he not think, 'Such is my folly in my revelries'"],"s":"When  (a drunkard) who is sober sees one who is not, it looks as if he remembered not the evil effects of his  (own) drink","ch":93,"sec":2,"th":"calm"},
  {"n":931,"ta":["வேண்டற்க வென்றிடினும் சூதினை வென்றதூஉம்","தூண்டிற்பொன் மீன்விழுங்கி அற்று"],"tr":["Ventarka Vendritinum Soodhinai Vendradhooum","Thoontirpon Meenvizhungi Atru"],"en":["Seek not the gamester's play; though you should win,","Your gain is as the baited hook the fish takes in"],"s":"Though able to win, let not one desire gambling;  (for) even what is won is like a fish swallowing the iron in fish-hook","ch":94,"sec":2,"th":"calm"},
  {"n":932,"ta":["ஒன்றெய்தி நூறிழக்கும் சூதர்க்கும் உண்டாங்கொல்","நன்றெய்தி வாழ்வதோர் ஆறு"],"tr":["Ondreydhi Noorizhakkum Soodharkkum Untaangol","Nandreydhi Vaazhvadhor Aaru"],"en":["Is there for gamblers, too, that gaining one a hundred lose, some way","That they may good obtain, and see a prosperous day"],"s":"That they may good obtain, and see a prosperous day? Is there indeed a means of livelihood that can bestow happiness on gamblers who gain one and lose a hundred?","ch":94,"sec":2,"th":"calm"},
  {"n":933,"ta":["உருளாயம் ஓவாது கூறின் பொருளாயம்","போஒய்ப் புறமே படும்"],"tr":["Urulaayam Ovaadhu Koorin Porulaayam","Pooip Purame Patum"],"en":["If prince unceasing speak of nought but play,","Treasure and revenue will pass from him away"],"s":"If the king is incessantly addicted to the rolling dice in the hope of gain, his wealth and the resources thereof will take their departure and fall into other's hands","ch":94,"sec":2,"th":"calm"},
  {"n":934,"ta":["சிறுமை பலசெய்து சீரழக்கும் சூதின்","வறுமை தருவதொன்று இல்"],"tr":["Sirumai Palaseydhu Seerazhikkum Soodhin","Varumai Tharuvadhondru Il"],"en":["Gaming brings many woes, and ruins fair renown;","Nothing to want brings men so surely down"],"s":"There is nothing else that brings  (us) poverty like gambling which causes many a misery and destroys  (one's) reputation","ch":94,"sec":2,"th":"calm"},
  {"n":935,"ta":["கவறும் கழகமும் கையும் தருக்கி","இவறியார் இல்லாகி யார்"],"tr":["Kavarum Kazhakamum Kaiyum Tharukki","Ivariyaar Illaaki Yaar"],"en":["The dice, and gaming-hall, and gamester's art, they eager sought,","Thirsting for gain- the men in other days who came to nought"],"s":"Penniless are those who by reason of their attachment would never forsake gambling, the gamblingplace and the handling  (of dice)","ch":94,"sec":2,"th":"calm"},
  {"n":936,"ta":["அகடாரார் அல்லல் உழப்பர்சூ தென்னும்","முகடியான் மூடப்பட் டார்"],"tr":["Akataaraar Allal Uzhapparsoo Thennum","Mukatiyaan Mootappat Taar"],"en":["Gambling's Misfortune's other name: o'er whom she casts her veil,","They suffer grievous want, and sorrows sore bewail"],"s":"Those who are swallowed by the goddess called \"gambling\" will never have their hunger satisfied, but suffer the pangs of hell in the next world","ch":94,"sec":2,"th":"calm"},
  {"n":937,"ta":["பழகிய செல்வமும் பண்பும் கெடுக்கும்","கழகத்துக் காலை புகின்"],"tr":["Pazhakiya Selvamum Panpum Ketukkum","Kazhakaththuk Kaalai Pukin"],"en":["Ancestral wealth and noble fame to ruin haste,","If men in gambler's halls their precious moments waste"],"s":"To waste time at the place of gambling will destroy inherited wealth and goodness of character","ch":94,"sec":2,"th":"calm"},
  {"n":938,"ta":["பொருள்கெடுத்துப் பொய்மேற் கொளீஇ அருள்கெடுத்து","அல்லல் உழப்பிக்கும் சூது"],"tr":["Porul Ketuththup Poimer Koleei","Arulketuththu Allal Uzhappikkum Soodhu"],"en":["Gambling wastes wealth, to falsehood bends the soul: it drives away","All grace, and leaves the man to utter misery a prey"],"s":"Gambling destroys property, teaches falsehood, puts an end to benevolence, and brings in misery  (here and hereafter)","ch":94,"sec":2,"th":"calm"},
  {"n":939,"ta":["உடைசெல்வம் ஊண்ஒளி கல்விஎன்று ஐந்தும்","அடையாவாம் ஆயங் கொளின்"],"tr":["Utaiselvam Oonoli Kalviendru Aindhum","Ataiyaavaam Aayang Kolin"],"en":["Clothes, wealth, food, praise, and learning, all depart","From him on gambler's gain who sets his heart"],"s":"The habit of gambling prevents the attainment of these five: clothing, wealth, food, fame and learning","ch":94,"sec":2,"th":"calm"},
  {"n":940,"ta":["இழத்தொறூஉம் காதலிக்கும் சூதேபோல் துன்பம்","உழத்தொறூஉம் காதற்று உயிர்"],"tr":["Izhaththoru�um Kaadhalikkum Soodhepol Thunpam","Uzhaththoru�um Kaadhatru Uyir"],"en":["Howe'er he lose, the gambler's heart is ever in the play;","E'en so the soul, despite its griefs, would live on earth alway"],"s":"As the gambler loves  (his vice) the more he loses by it, so does the soul love  (the body) the more it suffers through it","ch":94,"sec":2,"th":"calm"},
  {"n":941,"ta":["மிகினும் குறையினும் நோய்செய்யும் நூலோர்","வளிமுதலா எண்ணிய மூன்று"],"tr":["Mikinum Kuraiyinum Noiseyyum Noolor","Valimudhalaa Enniya Moondru"],"en":["The learned books count three, with wind as first; of these,","As any one prevail, or fail; 'twill cause disease"],"s":"If  (food and work are either) excessive or deficient, the three things enumerated by  (medical) writers, flatulence, biliousness, and phlegm, will cause  (one) disease","ch":95,"sec":2,"th":"calm"},
  {"n":942,"ta":["மருந்தென வேண்டாவாம் யாக்கைக்கு அருந்தியது","அற்றது போற்றி உணின்"],"tr":["Marundhena Ventaavaam Yaakkaikku Arundhiyadhu","Atradhu Potri Unin"],"en":["No need of medicine to heal your body's pain,","If, what you ate before digested well, you eat again"],"s":"No medicine is necessary for him who eats after assuring  (himself) that what he has  (already) eaten has been digested","ch":95,"sec":2,"th":"calm"},
  {"n":943,"ta":["அற்றால் அறவறிந்து உண்க அஃதுடம்பு","பெற்றான் நெடிதுய்க்கும் ஆறு"],"tr":["Atraal Aravarindhu Unka Aqdhutampu","Petraan Netidhuykkum Aaru"],"en":["Who has a body gained may long the gift retain,","If, food digested well, in measure due he eat again"],"s":"If  (one's food has been) digested let one eat with moderation;  (for) that is the way to prolong the life of an embodied soul","ch":95,"sec":2,"th":"calm"},
  {"n":944,"ta":["அற்றது அறிந்து கடைப்பிடித்து மாறல்ல","துய்க்க துவரப் பசித்து"],"tr":["Atradhu Arindhu Kataippitiththu Maaralla","Thuykka Thuvarap Pasiththu"],"en":["Knowing the food digested well, when hunger prompteth thee,","With constant care, the viands choose that well agree"],"s":"(First) assure yourself that your food has been digested and never fail to eat, when very hungry, whatever is not disagreeable  (to you)","ch":95,"sec":2,"th":"calm"},
  {"n":945,"ta":["மாறுபாடு இல்லாத உண்டி மறுத்துண்ணின்","ஊறுபாடு இல்லை உயிர்க்கு"],"tr":["Maarupaatu Illaadha Unti Maruththunnin","Oorupaatu Illai Uyirkku"],"en":["With self-denial take the well-selected meal;","So shall thy frame no sudden sickness feel"],"s":"There will be no disaster to one's life if one eats with moderation, food that is not disagreeable","ch":95,"sec":2,"th":"calm"},
  {"n":946,"ta":["இழிவறிந்து உண்பான்கண் இன்பம்போல் நிற்கும்","கழிபேர் இரையான்கண் நோய்"],"tr":["Izhivarindhu Unpaankan Inpampol Nirkum","Kazhiper Iraiyaankan Noi"],"en":["On modest temperance as pleasures pure,","So pain attends the greedy epicure"],"s":"As pleasure dwells with him who eats moderately, so disease  (dwells) with the glutton who eats voraciously","ch":95,"sec":2,"th":"calm"},
  {"n":947,"ta":["தீயள வன்றித் தெரியான் பெரிதுண்ணின்","நோயள வின்றிப் படும்"],"tr":["Theeyala Vandrith Theriyaan Peridhunnin","Noyala Vindrip Patum"],"en":["Who largely feeds, nor measure of the fire within maintains,","That thoughtless man shall feel unmeasured pains"],"s":"He will be afflicted with numberless diseases, who eats immoderately, ignorant  (of the rules of health)","ch":95,"sec":2,"th":"calm"},
  {"n":948,"ta":["நோய்நாடி நோய்முதல் நாடி அதுதணிக்கும்","வாய்நாடி வாய்ப்பச் செயல்"],"tr":["Noinaati Noimudhal Naati Adhudhanikkum","Vaainaati Vaaippach Cheyal"],"en":["Disease, its cause, what may abate the ill:","Let leech examine these, then use his skill"],"s":"Let the physician enquire into the  (nature of the) disease, its cause and its method of cure and treat it faithfully according to  (medical rule)","ch":95,"sec":2,"th":"calm"},
  {"n":949,"ta":["உற்றான் அளவும் பிணியளவும் காலமும்","கற்றான் கருதிச் செயல்"],"tr":["Utraan Alavum Piniyalavum Kaalamum","Katraan Karudhich Cheyal"],"en":["The habitudes of patient and disease, the crises of the ill","These must the learned leech think over well, then use his skill"],"s":"The learned  (physician) should ascertain the condition of his patient; the nature of his disease, and the season  (of the year) and  (then) proceed  (with his treatment)","ch":95,"sec":2,"th":"calm"},
  {"n":950,"ta":["உற்றவன் தீர்ப்பான் மருந்துழைச் செல்வானென்று","அப்பால் நாற் கூற்றே மருந்து"],"tr":["Utravan Theerppaan Marundhuzhaich Chelvaanendru","Appaal Naar Kootre Marundhu"],"en":["For patient, leech, and remedies, and him who waits by patient's side,","The art of medicine must fourfold code of laws provide"],"s":"Medical science consists of four parts, viz, patient, physician, medicine and compounder; and each of these  (again) contains four sub-divisions","ch":95,"sec":2,"th":"calm"},
  {"n":951,"ta":["இற்பிறந்தார் கண்அல்லது இல்லை இயல்பாகச்","செப்பமும் நாணும் ஒருங்கு"],"tr":["Irpirandhaar Kanalladhu Illai Iyalpaakach","Cheppamum Naanum Orungu"],"en":["Save in the scions of a noble house, you never find","Instinctive sense of right and virtuous shame combined"],"s":"Consistency  (of thought, word and deed) and fear  (of sin) are conjointly natural only to the high-born","ch":96,"sec":2,"th":"wisdom"},
  {"n":952,"ta":["ஒழுக்கமும் வாய்மையும் நாணும்இம் மூன்றும்","இழுக்கார் குடிப்பிறந் தார்"],"tr":["Ozhukkamum Vaaimaiyum Naanum Im","Moondrum Izhukkaar Kutippiran Thaar"],"en":["In these three things the men of noble birth fail not:","In virtuous deed and truthful word, and chastened thought"],"s":"The high-born will never deviate from these three; good manners, truthfulness and modesty","ch":96,"sec":2,"th":"wisdom"},
  {"n":953,"ta":["நகைஈகை இன்சொல் இகழாமை நான்கும்","வகையென்ப வாய்மைக் குடிக்கு"],"tr":["Nakaieekai Insol Ikazhaamai Naankum","Vakaiyenpa Vaaimaik Kutikku"],"en":["The smile, the gift, the pleasant word, unfailing courtesy","These are the signs, they say, of true nobility"],"s":"A cheerful countenance, liberality, pleasant words, and an unreviling disposition, these four are said to be the proper qualities of the truly high-born","ch":96,"sec":2,"th":"wisdom"},
  {"n":954,"ta":["அடுக்கிய கோடி பெறினும் குடிப்பிறந்தார்","குன்றுவ செய்தல் இலர்"],"tr":["Atukkiya Koti Perinum Kutippirandhaar","Kundruva Seydhal Ilar"],"en":["Millions on millions piled would never win","The men of noble race to soul-degrading sin"],"s":"Though blessed with immense wealth, the noble will never do anything unbecoming","ch":96,"sec":2,"th":"wisdom"},
  {"n":955,"ta":["வழங்குவ துள்வீழ்ந்தக் கண்ணும் பழங்குடி","பண்பில் தலைப்பிரிதல் இன்று"],"tr":["Vazhanguva Thulveezhndhak Kannum Pazhanguti","Panpil Thalaippiridhal Indru"],"en":["Though stores for charity should fail within, the ancient race","Will never lose its old ancestral grace"],"s":"Though their means fall off, those born in ancient families, will not lose their character  (for liberality)","ch":96,"sec":2,"th":"wisdom"},
  {"n":956,"ta":["சலம்பற்றிச் சால்பில செய்யார்மா சற்ற","குலம்பற்றி வாழ்தும் என் பார்"],"tr":["Salampatrich Chaalpila Seyyaarmaa Satra","Kulampatri Vaazhdhum En Paar"],"en":["Whose minds are set to live as fits their sire's unspotted fame,","Stooping to low deceit, commit no deeds that gender shame"],"s":"Those who seek to preserve the irreproachable honour of their families will not viciously do what is detrimental thereto","ch":96,"sec":2,"th":"wisdom"},
  {"n":957,"ta":["குடிப்பிறந்தார் கண்விளங்கும் குற்றம் விசும்பின்","மத஧க்கண் மறுப்போல் உயர்ந்து"],"tr":["Kutippirandhaar Kanvilangum Kutram Visumpin","Madhikkan Maruppol Uyarndhu"],"en":["The faults of men of noble race are seen by every eye,","As spots on her bright orb that walks sublime the evening sky"],"s":"As spots on her bright orb that walks sublime the evening sky","ch":96,"sec":2,"th":"wisdom"},
  {"n":958,"ta":["நலத்தின்கண் நாரின்மை தோன்றின் அவனைக்","குலத்தின்கண் ஐயப் படும்"],"tr":["Nalaththinkan Naarinmai Thondrin Avanaik","Kulaththinkan Aiyap Patum"],"en":["If lack of love appear in those who bear some goodly name,","'Twill make men doubt the ancestry they claim"],"s":"If one of a good family betrays want of affection, his descent from it will be called in question","ch":96,"sec":2,"th":"wisdom"},
  {"n":959,"ta":["நிலத்தில் கிடந்தமை கால்காட்டும் காட்டும்","குலத்தில் பிறந்தார்வாய்ச் சொல்"],"tr":["Nilaththil Kitandhamai Kaalkaattum Kaattum","Kulaththil Pirandhaarvaaich Chol"],"en":["Of soil the plants that spring thereout will show the worth:","The words they speak declare the men of noble birth"],"s":"As the sprout indicates the nature of the soil,  (so) the speech of the noble indicates  (that of one's birth)","ch":96,"sec":2,"th":"wisdom"},
  {"n":960,"ta":["நலம்வேண்டின் நாணுடைமை வேண்டும் குலம்வேண்டின்","வேண்டுக யார்க்கும் பணிவு"],"tr":["Nalamventin Naanutaimai Ventum Kulam","Ventin Ventuka Yaarkkum Panivu"],"en":["Who seek for good the grace of virtuous shame must know;","Who seek for noble name to all must reverence show"],"s":"He who desires a good name must desire modesty; and he who desires  (the continuance of) a family greatness must be submissive to all","ch":96,"sec":2,"th":"wisdom"},
  {"n":961,"ta":["இன்றி அமையாச் சிறப்பின ஆயினும்","குன்ற வருப விடல்"],"tr":["Indri Amaiyaach Chirappina Aayinum","Kundra Varupa Vital"],"en":["Though linked to splendours man no otherwise may gain,","Reject each act that may thine honour's clearness stain"],"s":"Actions that would degrade  (one's) family should not be done; though they may be so important that not doing them would end in death","ch":97,"sec":2,"th":"wisdom"},
  {"n":962,"ta":["சீரினும் சீரல்ல செய்யாரே சீரொடு","பேராண்மை வேண்டு பவர்"],"tr":["Seerinum Seeralla Seyyaare Seerotu","Peraanmai Ventu Pavar"],"en":["Who seek with glory to combine honour's untarnished fame,","Do no inglorious deeds, though men accord them glory's name"],"s":"Those who desire  (to maintain their) honour, will surely do nothing dishonourable, even for the sake of fame","ch":97,"sec":2,"th":"wisdom"},
  {"n":963,"ta":["பெருக்கத்து வேண்டும் பணிதல் சிறிய","சுருக்கத்து வேண்டும் உயர்வு"],"tr":["Perukkaththu Ventum Panidhal Siriya","Surukkaththu Ventum Uyarvu"],"en":["Bow down thy soul, with increase blest, in happy hour;","Lift up thy heart, when stript of all by fortune's power"],"s":"In great prosperity humility is becoming; dignity, in great adversity","ch":97,"sec":2,"th":"wisdom"},
  {"n":964,"ta":["தலையின் இழிந்த மயிரனையர் மாந்தர்","நிலையின் இழிந்தக் கடை"],"tr":["Thalaiyin Izhindha Mayiranaiyar Maandhar","Nilaiyin Izhindhak Katai"],"en":["Like hairs from off the head that fall to earth,","When fall'n from high estate are men of noble birth"],"s":"They who have fallen from their  (high) position are like the hair which has fallen from the head","ch":97,"sec":2,"th":"wisdom"},
  {"n":965,"ta":["குன்றின் அனையாரும் குன்றுவர் குன்றுவ","குன்றி அனைய செயின்"],"tr":["Kundrin Anaiyaarum Kundruvar Kundruva","Kundri Anaiya Seyin"],"en":["If meanness, slight as 'abrus' grain, by men be wrought,","Though like a hill their high estate, they sink to nought"],"s":"Even those who are exalted like a hill will be thought low, if they commit deeds that are debasing","ch":97,"sec":2,"th":"wisdom"},
  {"n":966,"ta":["புகழ்இன்றால் புத்தேள்நாட்டு உய்யாதால் என்மற்று","இகழ்வார்பின் சென்று நிலை"],"tr":["Pukazhindraal Puththelnaattu Uyyaadhaal Enmatru","Ikazhvaarpin Sendru Nilai"],"en":["It yields no praise, nor to the land of Gods throws wide the gate:","Why follow men who scorn, and at their bidding wait"],"s":"Why follow men who scorn, and at their bidding wait?","ch":97,"sec":2,"th":"wisdom"},
  {"n":967,"ta":["ஒட்டார்பின் சென்றொருவன் வாழ்தலின் அந்நிலையே","கெட்டான் எனப்படுதல் நன்று"],"tr":["Ottaarpin Sendroruvan Vaazhdhala�n Annilaiye","Kettaan Enappatudhal Nandru"],"en":["Better 'twere said, 'He's perished! ' than to gain","The means to live, following in foeman's train"],"s":"It is better for a man to be said of him that he died in his usual state than that he eked out his life by following those who disgraced him","ch":97,"sec":2,"th":"wisdom"},
  {"n":968,"ta":["மருந்தோமற்று ஊன்ஓம்பும் வாழ்க்கை பெருந்தகைமை","பீடழிய வந்த இடத்து"],"tr":["Marundhomatru Oonompum Vaazhkkai Perundhakaimai","Peetazhiya Vandha Itaththu"],"en":["When high estate has lost its pride of honour meet,","Is life, that nurses this poor flesh, as nectar sweet"],"s":"For the high-born to keep their body in life when their honour is gone will certainly not prove a remedy against death","ch":97,"sec":2,"th":"wisdom"},
  {"n":969,"ta":["மயிர்நீப்பின் வாழாக் கவரிமா அன்னார்","உயிர்நீப்பர் மானம் வரின்"],"tr":["Mayirneeppin Vaazhaak Kavarimaa Annaar","Uyirneeppar Maanam Varin"],"en":["Like the wild ox that, of its tuft bereft, will pine away,","Are those who, of their honour shorn, will quit the light of day"],"s":"Those who give up  (their) life when  (their) honour is at stake are like the yark which kills itself at the loss of  (even one of) its hairs","ch":97,"sec":2,"th":"wisdom"},
  {"n":970,"ta":["இளிவரின் வாழாத மானம் உடையார்","ஒளிதொழுது ஏத்தும் உலகு"],"tr":["Ilivarin Vaazhaadha Maanam Utaiyaar","Olidhozhudhu Eththum Ulaku"],"en":["Who, when dishonour comes, refuse to live, their honoured memory","Will live in worship and applause of all the world for aye"],"s":"The world will  (always) praise and adore the fame of the honourable who would rather die than suffer indignity","ch":97,"sec":2,"th":"wisdom"},
  {"n":971,"ta":["ஒளிஒருவற்கு உள்ள வெறுக்கை இளிஒருவற்கு","அஃதிறந்து வாழ்தும் எனல்"],"tr":["Olioruvarku Ulla Verukkai Ilioruvarku","Aqdhirandhu Vaazhdhum Enal"],"en":["The light of life is mental energy; disgrace is his","Who says, 'I 'ill lead a happy life devoid of this. '"],"s":"One's light is the abundance of one's courage; one's darkness is the desire to live destitute of such  (a state of mind.)","ch":98,"sec":2,"th":"equality"},
  {"n":972,"ta":["பிறப்பொக்கும் எல்லா உயிர்க்கும் சிறப்பொவ்வா","செய்தொழில் வேற்றுமையான்"],"tr":["Pirappokkum Ellaa Uyirkkum Sirappovvaa","Seydhozhil Vetrumai Yaan"],"en":["All men that live are one in circumstances of birth;","Diversities of works give each his special worth"],"s":"Every person is born the same. Only what they do makes them different.","ch":98,"sec":2,"th":"equality"},
  {"n":973,"ta":["மேலிருந்தும் மேலல்லார் மேலல்லர் கீழிருந்தும்","கீழல்லார் கீழல் லவர்"],"tr":["Melirundhum Melallaar Melallar Keezhirundhum","Keezhallaar Keezhal Lavar"],"en":["The men of lofty line, whose souls are mean, are never great","The men of lowly birth, when high of soul, are not of low estate"],"s":"Though  (raised) above, the base cannot become great; though  (brought) low, the great cannot become base","ch":98,"sec":2,"th":"equality"},
  {"n":974,"ta":["ஒருமை மகளிரே போலப் பெருமையும்","தன்னைத்தான் கொண்டொழுகின் உண்டு"],"tr":["Orumai Makalire Polap Perumaiyum","Thannaiththaan Kontozhukin Untu"],"en":["Like single-hearted women, greatness too,","Exists while to itself is true"],"s":"Exists while to itself is true","ch":98,"sec":2,"th":"equality"},
  {"n":975,"ta":["பெருமை யுடையவர் ஆற்றுவார் ஆற்றின்","அருமை உடைய செயல்"],"tr":["Perumai Yutaiyavar Aatruvaar Aatrin","Arumai Utaiya Seyal"],"en":["The man endowed with greatness true,","Rare deeds in perfect wise will do"],"s":"(Though reduced) the great will be able to perform, in the proper way, deeds difficult  (for others to do)","ch":98,"sec":2,"th":"equality"},
  {"n":976,"ta":["சிறியார் உணர்ச்சியுள் இல்லை பெரியாரைப்","பேணிக் கொள் வேம் என்னும் நோக்கு"],"tr":["Siriyaar Unarchchiyul Illai Periyaaraip","Penikkol Vemennum Nokku"],"en":["'As votaries of the truly great we will ourselves enroll,","'Is thought that enters not the mind of men of little soul"],"s":"It is never in the nature of the base to seek the society of the great and partake of their nature","ch":98,"sec":2,"th":"equality"},
  {"n":977,"ta":["இறப்பே புரிந்த தொழிற்றாம் சிறப்புந்தான்","சீரல் லவர்கண் படின்"],"tr":["Irappe Purindha Thozhitraam Sirappundhaan","Seeral Lavarkan Patin"],"en":["Whene'er distinction lights on some unworthy head,","Then deeds of haughty insolence are bred"],"s":"Even nobility of birth, wealth and learning, if in  (the possession of) the base, will  (only) produce everincreasing pride","ch":98,"sec":2,"th":"equality"},
  {"n":978,"ta":["பணியுமாம் என்றும் பெருமை சிறுமை","அணியுமாம் தன்னை வியந்து"],"tr":["Paniyumaam Endrum Perumai Sirumai","Aniyumaam Thannai Viyandhu"],"en":["Greatness humbly bends, but littleness always","Spreads out its plumes, and loads itself with praise"],"s":"The great will always humble himself; but the mean will exalt himself in self-admiration","ch":98,"sec":2,"th":"equality"},
  {"n":979,"ta":["பெருமை பெருமிதம் இன்மை சிறுமை","பெருமிதம் ஊர்ந்து விடல்"],"tr":["Perumai Perumidham Inmai Sirumai","Perumidham Oorndhu Vital"],"en":["Greatness is absence of conceit; meanness, we deem,","Riding on car of vanity supreme"],"s":"Freedom from conceit is  (the nature of true) greatness;  (while) obstinacy therein is  (that of) meanness","ch":98,"sec":2,"th":"equality"},
  {"n":980,"ta":["அற்றம் மறைக்கும் பெருமை சிறுமைதான்","குற்றமே கூறி விடும்"],"tr":["Atram Maraikkum Perumai Sirumaidhaan","Kutrame Koori Vitum"],"en":["Greatness will hide a neighbour's shame;","Meanness his faults to all the world proclaim"],"s":"The great hide the faults of others; the base only divulge them","ch":98,"sec":2,"th":"equality"},
  {"n":981,"ta":["கடன்என்ப நல்லவை எல்லாம் கடன்அறிந்து","சான்றாண்மை மேற்கொள் பவர்க்கு"],"tr":["Katanenpa Nallavai Ellaam Katanarindhu","Saandraanmai Merkol Pavarkku"],"en":["All goodly things are duties to the men, they say","Who set themselves to walk in virtue's perfect way"],"s":"It is said that those who are conscious of their duty and behave with a perfect goodness will regard as natural all that is good","ch":99,"sec":2,"th":"wisdom"},
  {"n":982,"ta":["குணநலம் சான்றோர் நலனே பிறநலம்","எந்நலத்து உள்ளதூஉம் அன்று"],"tr":["Kunanalam Saandror Nalane Piranalam","Ennalaththu Ulladhooum Andru"],"en":["The good of inward excellence they claim,","The perfect men; all other good is only good in name"],"s":"The only delight of the perfect is that of their goodness; all other  (sensual) delights are not to be included among any  (true) delights","ch":99,"sec":2,"th":"wisdom"},
  {"n":983,"ta":["அன்புநாண் ஒப்புரவு கண்ணோட்டம் வாய்மையொடு","ஐந்துசால் ஊன்றிய தூண்"],"tr":["Anpunaan Oppuravu Kannottam Vaaimaiyotu","Aindhusaal Oondriya Thoon"],"en":["Love, modesty, beneficence, benignant grace,","With truth, are pillars five of perfect virtue's resting-place"],"s":"Affection, fear  (of sin), benevolence, favour and truthfulness; these are the five pillars on which perfect goodness rests","ch":99,"sec":2,"th":"wisdom"},
  {"n":984,"ta":["கொல்லா நலத்தது நோன்மை பிறர்தீமை","சொல்லா நலத்தது சால்பு"],"tr":["Kollaa Nalaththadhu Nonmai Pirardheemai","Sollaa Nalaththadhu Saalpu"],"en":["The type of 'penitence' is virtuous good that nothing slays;","To speak no ill of other men is perfect virtue's praise"],"s":"Penance consists in the goodness that kills not, and perfection in the goodness that tells not others' faults","ch":99,"sec":2,"th":"wisdom"},
  {"n":985,"ta":["ஆற்றுவார் ஆற்றல் பணிதல் அதுசான்றோர்","மாற்றாரை மாற்றும் படை"],"tr":["Aatruvaar Aatral Panidhal Adhusaandror","Maatraarai Maatrum Patai"],"en":["Submission is the might of men of mighty acts; the sage","With that same weapon stills his foeman's rage"],"s":"Stooping  (to inferiors) is the strength of those who can accomplish  (an undertaking); and that is the weapon with which the great avert their foes","ch":99,"sec":2,"th":"wisdom"},
  {"n":986,"ta":["சால்பிற்குக் கட்டளை யாதெனின் தோல்வி","துலையல்லார் கண்ணும் கொளல்"],"tr":["Saalpirkuk Kattalai Yaadhenin Tholvi","Thulaiyallaar Kannum Kolal"],"en":["What is perfection's test? The equal mind","To bear repulse from even meaner men resigned"],"s":"The touch-stone of perfection is to receive a defeat even at the hands of one's inferiors","ch":99,"sec":2,"th":"wisdom"},
  {"n":987,"ta":["இன்னாசெய் தார்க்கும் இனியவே செய்யாக்கால்","என்ன பயத்ததோ சால்பு"],"tr":["Innaasey Thaarkkum Iniyave Seyyaakkaal","Enna Payaththadho Saalpu"],"en":["What fruit doth your perfection yield you, say!","Unless to men who work you ill good repay"],"s":"Of what avail is perfect goodness if it cannot do pleasing things even to those who have pained  (it)?","ch":99,"sec":2,"th":"wisdom"},
  {"n":988,"ta":["இன்மை ஒருவற்கு இளிவன்று சால்பென்னும்","திண்மை உண் டாகப் பெறின்"],"tr":["Inmai Oruvarku Ilivandru Saalpennum","Thinmai Un Taakap Perin"],"en":["To soul with perfect virtue's strength endued,","Brings no disgrace the lack of every earthly good"],"s":"Poverty is no disgrace to one who abounds in good qualities","ch":99,"sec":2,"th":"wisdom"},
  {"n":989,"ta":["ஊழி பெயரினும் தாம்பெயரார் சான்றாண்மைக்கு","ஆழி எனப்படு வார்"],"tr":["Oozhi Peyarinum Thaampeyaraar Saandraanmaikku","Aazhi Enappatu Vaar"],"en":["Call them of perfect virtue's sea the shore,","Who, though the fates should fail, fail not for evermore"],"s":"Those who are said to be the shore of the sea of perfection will never change, though ages may change","ch":99,"sec":2,"th":"wisdom"},
  {"n":990,"ta":["சான்றவர் சான்றாண்மை குன்றின் இருநிலந்தான்","தாங்காது மன்னோ பொறை"],"tr":["Saandravar Saandraanmai Kundrin Irunilandhaan","Thaangaadhu Manno Porai"],"en":["The mighty earth its burthen to sustain must cease,","If perfect virtue of the perfect men decrease"],"s":"If there is a defect in the character of the perfect,  (even) the great world cannot bear  (its) burden","ch":99,"sec":2,"th":"wisdom"},
  {"n":991,"ta":["எண்பதத்தால் எய்தல் எளிதென்ப யார்மாட்டும்","பண்புடைமை என்னும் வழக்கு"],"tr":["Enpadhaththaal Eydhal Elidhenpa Yaarmaattum","Panputaimai Ennum Vazhakku"],"en":["Who easy access give to every man, they say,","Of kindly courtesy will learn with ease the way"],"s":"If one is easy of access to all, it will be easy for one to obtain the virtue called goodness","ch":100,"sec":2,"th":"compassion"},
  {"n":992,"ta":["அன்புடைமை ஆன்ற குடிப்பிறத்தல் இவ்விரண்டும்","பண்புடைமை என்னும் வழக்கு"],"tr":["Anputaimai Aandra Kutippiraththal Ivvirantum","Panputaimai Ennum Vazhakku"],"en":["Benevolence and high born dignity,","These two are beaten paths of courtesy"],"s":"Affectionateness and birth in a good family, these two constitute what is called a proper behaviour to all","ch":100,"sec":2,"th":"compassion"},
  {"n":993,"ta":["உறுப்பொத்தல் மக்களொப்பு அன்றால் வெறுத்தக்க","பண்பொத்தல் ஒப்பதாம் ஒப்பு"],"tr":["Uruppoththal Makkaloppu Andraal Veruththakka","Panpoththal Oppadhaam Oppu"],"en":["Men are not one because their members seem alike to outward view;","Similitude of kindred quality makes likeness true"],"s":"Resemblance of bodies is no resemblance of souls; true resemblance is the resemblance of qualities that attract","ch":100,"sec":2,"th":"compassion"},
  {"n":994,"ta":["நயனொடு நன்றி புரிந்த பயனுடையார்","பண்புபா ராட்டும் உலகு"],"tr":["Nayanotu Nandri Purindha Payanutaiyaar","Panpupaa Raattum Ulaku"],"en":["Of men of fruitful life, who kindly benefits dispense,","The world unites to praise the 'noble excellence. '"],"s":"The world applauds the character of those whose usefulness results from their equity and charity","ch":100,"sec":2,"th":"compassion"},
  {"n":995,"ta":["நகையுள்ளும் இன்னா திகழ்ச்சி பகையுள்ளும்","பண்புள பாடறிவார் மாட்டு"],"tr":["Nakaiyullum Innaa Thikazhchchi Pakaiyullum","Panpula Paatarivaar Maattu"],"en":["Contempt is evil though in sport They who man's nature know,","E'en in their wrath, a courteous mind will show"],"s":"Reproach is painful to one even in sport; those  (therefore) who know the nature of others exhibit  (pleasing) qualities even when they are hated","ch":100,"sec":2,"th":"compassion"},
  {"n":996,"ta":["பண்புடையார்ப் பட்டுண்டு உலகம் அதுஇன்றேல்","மண்புக்கு மாய்வது மன்"],"tr":["Panputaiyaarp Pattuntu Ulakam Adhuindrel","Manpukku Maaivadhu Man"],"en":["The world abides; for 'worthy' men its weight sustain","Were it not so, 'twould fall to dust again"],"s":"The  (way of the) world subsists by contact with the good; if not, it would bury itself in the earth and perish","ch":100,"sec":2,"th":"compassion"},
  {"n":997,"ta":["அரம்போலும் கூர்மைய ரேனும் மரம்போல்வர்","மக்கட்பண்பு இல்லா தவர்"],"tr":["Arampolum Koormaiya Renum Marampolvar","Makkatpanpu Illaa Thavar"],"en":["Though sharp their wit as file, as blocks they must remain,","Whose souls are void of 'courtesy humane'"],"s":"He who is destitute of  (true) human qualities  (only) resembles a tree, though he may possess the sharpness of a file","ch":100,"sec":2,"th":"compassion"},
  {"n":998,"ta":["நண்பாற்றார் ஆகி நயமில செய்வார்க்கும்","பண்பாற்றார் ஆதல் கடை"],"tr":["Nanpaatraar Aaki Nayamila Seyvaarkkum","Panpaatraar Aadhal Katai"],"en":["Though men with all unfriendly acts and wrongs assail,","'Tis uttermost disgrace in 'courtesy' to fail"],"s":"It is wrong  (for the wise) not to exhibit  (good) qualities even towards those who bearing no friendship  (for them) do only what is hateful","ch":100,"sec":2,"th":"compassion"},
  {"n":999,"ta":["நகல்வல்லர் அல்லார்க்கு மாயிரு ஞாலம்","பகலும்பாற் பட்டன்று இருள்"],"tr":["Nakalvallar Allaarkku Maayiru Gnaalam","Pakalumpaar Pattandru Irul"],"en":["To him who knows not how to smile in kindly mirth,","Darkness in daytime broods o'er all the vast and mighty earth"],"s":"To those who cannot rejoice, the wide world is buried darkness even in  (broad) day light","ch":100,"sec":2,"th":"compassion"},
  {"n":1000,"ta":["பண்பிலான் பெற்ற பெருஞ்செல்வம் நன்பால்","கலந்தீமை யால்திரிந் தற்று"],"tr":["Panpilaan Petra Perunjelvam Nanpaal","Kalandheemai Yaaldhirin Thatru"],"en":["Like sweet milk soured because in filthy vessel poured,","Is ample wealth in churlish man's unopened coffers stored"],"s":"The great wealth obtained by one who has no goodness will perish like pure milk spoilt by the","ch":100,"sec":2,"th":"compassion"},
  {"n":1001,"ta":["வைத்தான்வாய் சான்ற பெரும்பொருள் அஃதுண்ணான்","செத்தான் செயக்கிடந்தது இல்"],"tr":["Vaiththaanvaai Saandra Perumporul Aqdhunnaan","Seththaan Seyakkitandhadhu Il"],"en":["Who fills his house with ample store, enjoying none,","Is dead Nought with the useless heap is done"],"s":"He who does not enjoy the immense riches he has heaped up in his house, is  (to be reckoned as) dead,  (for) there is nothing achieved  (by him)","ch":101,"sec":2,"th":"wealth"},
  {"n":1002,"ta":["பொருளானாம் எல்லாமென்று ஈயாது இவறும்","மருளானாம் மாணாப் பிறப்பு"],"tr":["Porulaanaam Ellaamendru Eeyaadhu Ivarum","Marulaanaam Maanaap Pirappu"],"en":["Who giving nought, opines from wealth all blessing springs,","Degraded birth that doting miser's folly brings"],"s":"He who knows that wealth yields every pleasure and yet is so blind as to lead miserly life will be born a demon","ch":101,"sec":2,"th":"wealth"},
  {"n":1003,"ta":["ஈட்டம் இவறி இசைவேண்டா ஆடவர்","தோற்றம் நிலக்குப் பொறை"],"tr":["Eettam Ivari Isaiventaa Aatavar","Thotram Nilakkup Porai"],"en":["Who lust to heap up wealth, but glory hold not dear,","It burthens earth when on the stage of being they appear"],"s":"A burden to the earth are men bent on the acquisition of riches and not  (true) fame","ch":101,"sec":2,"th":"wealth"},
  {"n":1004,"ta":["எச்சமென்று என்எண்ணுங் கொல்லோ ஒருவரால்","நச்சப் படாஅ தவன்"],"tr":["Echchamendru Enennung Kollo Oruvaraal","Nachchap Pataaa Thavan"],"en":["Whom no one loves, when he shall pass away,","What doth he look to leave behind, I pray"],"s":"What will the miser who is not liked  (by any one) regard as his own  (in the world to come)?","ch":101,"sec":2,"th":"wealth"},
  {"n":1005,"ta":["கொடுப்பதூஉம் துய்ப்பதூஉம் இல்லார்க்கு அடுக்கிய","கோடியுண் டாயினும் இல்"],"tr":["Kotuppadhooum Thuyppadhooum Illaarkku Atukkiya","Kotiyun Taayinum Il"],"en":["Amid accumulated millions they are poor,","Who nothing give and nought enjoy of all they store"],"s":"Those who neither give  (to others) nor enjoy  (their property) are  (truly) destitute, though possessing immense riches","ch":101,"sec":2,"th":"wealth"},
  {"n":1006,"ta":["ஏதம் பெருஞ்செல்வம் தான்துவ்வான் தக்கார்க்கொன்று","ஈதல் இயல்பிலா தான்"],"tr":["Edham Perunjelvam Thaandhuvvaan Thakkaarkkondru","Eedhal Iyalpilaa Thaan"],"en":["Their ample wealth is misery to men of churlish heart,","Who nought themselves enjoy, and nought to worthy men impart"],"s":"He who enjoys not  (his riches) nor relieves the wants of the worthy is a disease to his wealth","ch":101,"sec":2,"th":"wealth"},
  {"n":1007,"ta":["அற்றார்க்கொன்று ஆற்றாதான் செல்வம் மிகநலம்","பெற்றாள் தமியள்மூத் தற்று"],"tr":["Atraarkkondru Aatraadhaan Selvam Mikanalam","Petraal Thamiyalmooth Thatru"],"en":["Like woman fair in lonelihood who aged grows,","Is wealth of him on needy men who nought bestows"],"s":"The wealth of him who never bestows anything on the destitute is like a woman of beauty growing old without a husband","ch":101,"sec":2,"th":"wealth"},
  {"n":1008,"ta":["நச்சப் படாதவன் செல்வம் நடுவூருள்","நச்சு மரம்பழுத் தற்று"],"tr":["Nachchap Pataadhavan Selvam Natuvoorul","Nachchu Marampazhuth Thatru"],"en":["When he whom no man loves exults in great prosperity,","'Tis as when fruits in midmost of the town some poisonous tree"],"s":"The wealth of him who is disliked  (by all) is like the fruit-bearing of the etty tree in the midst of a town","ch":101,"sec":2,"th":"wealth"},
  {"n":1009,"ta":["அன்பொரீஇத் தற்செற்று அறநோக்காது ஈட்டிய","ஒண்பொருள் கொள்வார் பிறர்"],"tr":["Anporeeith Tharsetru Aranokkaadhu Eettiya","Onporul Kolvaar Pirar"],"en":["Who love abandon, self-afflict, and virtue's way forsake","To heap up glittering wealth, their hoards shall others take"],"s":"To heap up glittering wealth, their hoards shall others take","ch":101,"sec":2,"th":"wealth"},
  {"n":1010,"ta":["சீருடைச் செல்வர் சிறுதுனி மாரி","வறங்கூர்ந் தனையது உடைத்து"],"tr":["Seerutaich Chelvar Sirudhuni Maari","Varangoorn Thanaiyadhu Utaiththu"],"en":["'Tis as when rain cloud in the heaven grows day,","When generous wealthy man endures brief poverty"],"s":"The short-lived poverty of those who are noble and rich is like the clouds becoming poor  (for a while)","ch":101,"sec":2,"th":"wealth"},
  {"n":1011,"ta":["கருமத்தால் நாணுதல் நாணுந் திருநுதல்","நல்லவர் நாணுப் பிற"],"tr":["Karumaththaal Naanudhal Naanun Thirunudhal","Nallavar Naanup Pira"],"en":["To shrink abashed from evil deed is 'generous shame';","Other is that of bright-browed one of virtuous fame"],"s":"True modesty is the fear of  (evil) deeds; all other modesty is  (simply) the bashfulness of virtuous maids","ch":102,"sec":2,"th":"calm"},
  {"n":1012,"ta":["ஊணுடை எச்சம் உயிர்க்கெல்லாம் வேறல்ல","நாணுடைமை மாந்தர் சிறப்பு"],"tr":["Oonutai Echcham Uyirkkellaam Veralla","Naanutaimai Maandhar Sirappu"],"en":["Food, clothing, and other things alike all beings own;","By sense of shame the excellence of men is known"],"s":"Food, clothing and the like are common to all men but modesty is peculiar to the good","ch":102,"sec":2,"th":"calm"},
  {"n":1013,"ta":["ஊனைக் குறித்த உயிரெல்லாம் நாண்என்னும்","நன்மை குறித்தது சால்பு"],"tr":["Oonaik Kuriththa Uyirellaam Naanennum","Nanmai Kuriththadhu Saalpu"],"en":["All spirits homes of flesh as habitation claim,","And perfect virtue ever dwells with shame"],"s":"As the body is the abode of the spirit, so the excellence of modesty is the abode of perfection","ch":102,"sec":2,"th":"calm"},
  {"n":1014,"ta":["அணிஅன்றோ நாணுடைமை சான்றோர்க்கு அஃதின்றேல்","பிணிஅன்றோ பீடு நடை"],"tr":["Aniandro Naanutaimai Saandrorkku Aqdhindrel","Piniandro Peetu Natai"],"en":["And is not shame an ornament to men of dignity?","Without it step of stately pride is piteous thing to see"],"s":"Is not the modesty ornament of the noble? Without it, their haughtiness would be a pain  (to others)","ch":102,"sec":2,"th":"calm"},
  {"n":1015,"ta":["பிறர்பழியும் தம்பழியும் நாணுவார் நாணுக்கு","உறைபதி என்னும் உலகு"],"tr":["Pirarpazhiyum Thampazhiyum Naanuvaar Naanukku","Uraipadhi Ennum Ulaku"],"en":["As home of virtuous shame by all the world the men are known,","Who feel ashamed for others, guilt as for their own"],"s":"The world regards as the abode of modesty him who fear his own and other's guilt","ch":102,"sec":2,"th":"calm"},
  {"n":1016,"ta":["நாண்வேலி கொள்ளாது மன்னோ வியன்ஞாலம்","பேணலர் மேலா யவர்"],"tr":["Naanveli Kollaadhu Manno Viyangnaalam","Penalar Melaa Yavar"],"en":["Unless the hedge of shame inviolate remain,","For men of lofty soul the earth's vast realms no charms retain"],"s":"The great make modesty their barrier  (of defence) and not the wide world","ch":102,"sec":2,"th":"calm"},
  {"n":1017,"ta":["நாணால் உயிரைத் துறப்பர் உயிர்ப்பொருட்டால்","நாண்துறவார் நாணாள் பவர்"],"tr":["Naanaal Uyiraith Thurappar Uyirpporuttaal","Naandhuravaar Naanaal Pavar"],"en":["The men of modest soul for shame would life an offering make,","But ne'er abandon virtuous shame for life's dear sake"],"s":"The modest would rather lose their life for the sake of modesty than lose modesty for the sake of life","ch":102,"sec":2,"th":"calm"},
  {"n":1018,"ta":["பிறர்நாணத் தக்கது தான்நாணா னாயின்","அறம்நாணத் தக்கது உடைத்து"],"tr":["Pirarnaanath Thakkadhu Thaannaanaa Naayin","Aramnaanath Thakkadhu Utaiththu"],"en":["Though know'st no shame, while all around asha med must be:","Virtue will shrink away ashamed of thee"],"s":"Virtue is likely to forsake him who shamelessly does what others are ashamed of","ch":102,"sec":2,"th":"calm"},
  {"n":1019,"ta":["குலஞ்சுடும் கொள்கை பிழைப்பின் நலஞ்சுடும்","நாணின்மை நின்றக் கடை"],"tr":["Kulanjutum Kolkai Pizhaippin Nalanjutum","Naaninmai Nindrak Katai"],"en":["'Twill race consume if right observance fail;","'Twill every good consume if shamelessness prevail"],"s":"Want of manners injures one's family; but want of modesty injures one's character","ch":102,"sec":2,"th":"calm"},
  {"n":1020,"ta":["நாண்அகத் தில்லார் இயக்கம் மரப்பாவை","நாணால் உயிர்மருட்டி அற்று"],"tr":["Naanakath Thillaar Iyakkam Marappaavai","Naanaal Uyirmarutti Atru"],"en":["'Tis as with strings a wooden puppet apes life's functions, when","Those void of shame within hold intercourse with men"],"s":"The actions of those who are without modesty at heart are like those of puppet moved by a string","ch":102,"sec":2,"th":"calm"},
  {"n":1021,"ta":["கருமம் செயஒருவன் கைதூவேன் என்னும்","பெருமையின் பீடுடையது இல்"],"tr":["Karumam Seyaoruvan Kaidhooven Ennum","Perumaiyin Peetutaiyadhu Il"],"en":["Who says 'I'll do my work, nor slack my hand',","His greatness, clothed with dignity supreme, shall stand"],"s":"There is no higher greatness than that of one saying I will not cease in my effort  (to raise my family)","ch":103,"sec":2,"th":"family"},
  {"n":1022,"ta":["ஆள்வினையும் ஆன்ற அறிவும் எனஇரண்டின்","நீள்வினையால் நீளும் குடி"],"tr":["Aalvinaiyum Aandra Arivum Enairantin","Neelvinaiyaal Neelum Kuti"],"en":["The manly act and knowledge full, when these combine","In deed prolonged, then lengthens out the race's line"],"s":"One's family is raised by untiring perseverance in both effort and wise contrivances","ch":103,"sec":2,"th":"family"},
  {"n":1023,"ta":["குடிசெய்வல் என்னும் ஒருவற்குத் தெய்வம்","மடிதற்றுத் தான்முந் துறும்"],"tr":["Kutiseyval Ennum Oruvarkuth Theyvam","Matidhatruth Thaanmun Thurum"],"en":["'I'll make my race renowned, ' if man shall say,","With vest succinct the goddess leads the way"],"s":"The Deity will clothe itself and appear before him who resolves on raising his family","ch":103,"sec":2,"th":"family"},
  {"n":1024,"ta":["சூழாமல் தானே முடிவெய்தும் தம்குடியைத்","தாழாது உஞற்று பவர்க்கு"],"tr":["Soozhaamal Thaane Mutiveydhum Thamkutiyaith","Thaazhaadhu Ugnatru Pavarkku"],"en":["Who labours for his race with unremitting pain,","Without a thought spontaneously, his end will gain"],"s":"Those who are prompt in their efforts  (to better their family) need no deliberation, such efforts will of themselves succeed","ch":103,"sec":2,"th":"family"},
  {"n":1025,"ta":["குற்றம் இலனாய்க் குடிசெய்து வாழ்வானைச்","சுற்றமாச் சுற்றும் உலகு"],"tr":["Kutram Ilanaaik Kutiseydhu Vaazhvaanaich","Chutramaach Chutrum Ulaku"],"en":["With blameless life who seeks to build his race's fame,","The world shall circle him, and kindred claim"],"s":"People will eagerly seek the friendship of the prosperous soul who has raised his family without foul means","ch":103,"sec":2,"th":"family"},
  {"n":1026,"ta":["நல்லாண்மை என்பது ஒருவற்குத் தான்பிறந்த","இல்லாண்மை ஆக்கிக் கொளல்"],"tr":["Nallaanmai Enpadhu Oruvarkuth Thaanpirandha","Illaanmai Aakkik Kolal"],"en":["Of virtuous manliness the world accords the praise","To him who gives his powers, the house from which he sprang to raise"],"s":"A man's true manliness consists in making himself the head and benefactor of his family","ch":103,"sec":2,"th":"family"},
  {"n":1027,"ta":["அமரகத்து வன்கண்ணர் போலத் தமரகத்தும்","ஆற்றுவார் மேற்றே பொறை"],"tr":["Amarakaththu Vankannar Polath Thamarakaththum","Aatruvaar Metre Porai"],"en":["The fearless hero bears the brunt amid the warrior throng;","Amid his kindred so the burthen rests upon the strong"],"s":"Amid his kindred so the burthen rests upon the strong","ch":103,"sec":2,"th":"family"},
  {"n":1028,"ta":["குடிசெய்வார்க் கில்லை பருவம் மடிசெய்து","மானங் கருதக் கெடும்"],"tr":["Kutiseyvaark Killai Paruvam Matiseydhu","Maanang Karudhak Ketum"],"en":["Wait for no season, when you would your house uprear;","'Twill perish, if you wait supine, or hold your honour dear"],"s":"As a family suffers by  (one's) indolence and false dignity there is to be so season  (good or bad) to those who strive to raise their family","ch":103,"sec":2,"th":"family"},
  {"n":1029,"ta":["இடும்பைக்கே கொள்கலம் கொல்லோ குடும்பத்தைக்","குற்ற மறைப்பான் உடம்பு"],"tr":["Itumpaikke Kolkalam Kollo Kutumpaththaik","Kutra Maraippaan Utampu"],"en":["Is not his body vase that various sorrows fill,","Who would his household screen from every ill"],"s":"Is it only to suffering that his body is exposed who undertakes to preserve his family from evil?","ch":103,"sec":2,"th":"family"},
  {"n":1030,"ta":["இடுக்கண்கால் கொன்றிட வீழும் அடுத்தூன்றும்","நல்லாள் இலாத குடி"],"tr":["Itukkankaal Kondrita Veezhum Atuththoondrum","Nallaal Ilaadha Kuti"],"en":["When trouble the foundation saps the house must fall,","If no strong hand be nigh to prop the tottering wall"],"s":"If there are none to prop up and maintain a family  (in distress), it will fall at the stroke of the axe of misfortune","ch":103,"sec":2,"th":"family"},
  {"n":1031,"ta":["சுழன்றும்ஏர்ப் பின்னது உலகம் அதனால்","உழந்தும் உழவே தலை"],"tr":["Suzhandrumerp Pinnadhu Ulakam Adhanaal","Uzhandhum Uzhave Thalai"],"en":["Howe'er they roam, the world must follow still the plougher's team;","Though toilsome, culture of the ground as noblest toil esteem"],"s":"Agriculture, though laborious, is the most excellent  (form of labour); for people, though they go about  (in search of various employments), have at last to resort to the farmer","ch":104,"sec":2,"th":"effort"},
  {"n":1032,"ta":["உழுவார் உலகத்தார்க்கு ஆணிஅஃ தாற்றாது","எழுவாரை எல்லாம் பொறுத்து"],"tr":["Uzhuvaar Ulakaththaarkku Aaniaq Thaatraadhu","Ezhuvaarai Ellaam Poruththu"],"en":["The ploughers are the linch-pin of the world; they bear","Them up who other works perform, too weak its toils to share"],"s":"Agriculturists are  (as it were) the linch-pin of the world for they support all other workers who cannot till the soil","ch":104,"sec":2,"th":"effort"},
  {"n":1033,"ta":["உழுதுண்டு வாழ்வாரே வாழ்வார்மற் றெல்லாம்","தொழுதுண்டு பின்செல் பவர்"],"tr":["Uzhudhuntu Vaazhvaare Vaazhvaarmar Rellaam","Thozhudhuntu Pinsel Pavar"],"en":["Who ploughing eat their food, they truly live:","The rest to others bend subservient, eating what they give"],"s":"They alone live who live by agriculture; all others lead a cringing, dependent life","ch":104,"sec":2,"th":"effort"},
  {"n":1034,"ta":["பலகுடை நீழலும் தங்குடைக்கீழ்க் காண்பர்","அலகுடை நீழ லவர்"],"tr":["Palakutai Neezhalum Thangutaikkeezhk Kaanpar","Alakutai Neezha Lavar"],"en":["O'er many a land they 'll see their monarch reign,","Whose fields are shaded by the waving grain"],"s":"Patriotic farmers desire to bring all other states under the control of their own king","ch":104,"sec":2,"th":"effort"},
  {"n":1035,"ta":["இரவார் இரப்பார்க்கொன்று ஈவர் கரவாது","கைசெய்தூண் மாலை யவர்"],"tr":["Iravaar Irappaarkkondru Eevar Karavaadhu","Kaiseydhoon Maalai Yavar"],"en":["They nothing ask from others, but to askers give,","Who raise with their own hands the food on which they live"],"s":"Those whose nature is to live by manual labour will never beg but give something to those who beg","ch":104,"sec":2,"th":"effort"},
  {"n":1036,"ta":["உழவினார் கைம்மடங்கின் இல்லை விழைவதூஉம்","விட்டேம்என் பார்க்கும் நிலை"],"tr":["Uzhavinaar Kaimmatangin Illai Vizhaivadhooum","Vittemen Paarkkum Nilai"],"en":["For those who 've left what all men love no place is found,","When they with folded hands remain who till the ground"],"s":"If the farmer's hands are slackened, even the ascetic state will fail","ch":104,"sec":2,"th":"effort"},
  {"n":1037,"ta":["தொடிப்புழுதி கஃசா உணக்கின் பிடித்தெருவும்","வேண்டாது சாலப் படும்"],"tr":["Thotippuzhudhi Kaqsaa Unakkin Pitiththeruvum","Ventaadhu Saalap Patum"],"en":["Reduce your soil to that dry state, When ounce is quarter-ounce's weight;","Without one handful of manure, Abundant crops you thus secure"],"s":"If the land is dried so as to reduce one ounce of earth to a quarter, it will grow plentifully even without a handful of manure","ch":104,"sec":2,"th":"effort"},
  {"n":1038,"ta":["ஏரினும் நன்றால் எருவிடுதல் கட்டபின்","நீரினும் நன்றதன் காப்பு"],"tr":["Erinum Nandraal Eruvitudhal Kattapin","Neerinum Nandradhan Kaappu"],"en":["To cast manure is better than to plough;","Weed well; to guard is more than watering now"],"s":"Manuring is better than ploughing; after weeding, watching is better than watering  (it)","ch":104,"sec":2,"th":"effort"},
  {"n":1039,"ta":["செல்லான் கிழவன் இருப்பின் நிலம்புலந்து","இல்லாளின் ஊடி விடும்"],"tr":["Sellaan Kizhavan Iruppin Nilampulandhu","Illaalin Ooti Vitum"],"en":["When master from the field aloof hath stood;","Then land will sulk, like wife in angry mood"],"s":"If the owner does not  (personally) attend to his cultivation, his land will behave like an angry wife and yield him no pleasure","ch":104,"sec":2,"th":"effort"},
  {"n":1040,"ta":["இலமென்று அசைஇ இருப்பாரைக் காணின்","நிலமென்னும் நல்லாள் நகும்"],"tr":["Ilamendru Asaii Iruppaaraik Kaanin","Nilamennum Nallaal Nakum"],"en":["The earth, that kindly dame, will laugh to see,","Men seated idle pleading poverty"],"s":"The maiden, Earth, will laugh at the sight of those who plead poverty and lead an idle life","ch":104,"sec":2,"th":"effort"},
  {"n":1041,"ta":["இன்மையின் இன்னாதது யாதெனின் இன்மையின்","இன்மையே இன்னா தது"],"tr":["Inmaiyin Innaadhadhu Yaadhenin Inmaiyin","Inmaiye Innaa Thadhu"],"en":["You ask what sharper pain than poverty is known;","Nothing pains more than poverty, save poverty alone"],"s":"There is nothing that afflicts  (one) like poverty","ch":105,"sec":2,"th":"impermanence"},
  {"n":1042,"ta":["இன்மை எனவொரு பாவி மறுமையும்","இம்மையும் இன்றி வரும்"],"tr":["Inmai Enavoru Paavi Marumaiyum","Immaiyum Indri Varum"],"en":["Malefactor matchless! poverty destroys","This world's and the next world's joys"],"s":"When cruel poverty comes on, it deprives one of both the present and future  (bliss)","ch":105,"sec":2,"th":"impermanence"},
  {"n":1043,"ta":["தொல்வரவும் தோலும் கெடுக்கும் தொகையாக","நல்குரவு என்னும் நசை"],"tr":["Tholvaravum Tholum Ketukkum Thokaiyaaka","Nalkuravu Ennum Nasai"],"en":["Importunate desire, which poverty men name,","Destroys both old descent and goodly fame"],"s":"Hankering poverty destroys at once the greatness of  (one's) ancient descent and  (the dignity of one's) speech","ch":105,"sec":2,"th":"impermanence"},
  {"n":1044,"ta":["இற்பிறந்தார் கண்ணேயும் இன்மை இளிவந்த","சொற்பிறக்கும் சோர்வு தரும்"],"tr":["Irpirandhaar Kanneyum Inmai Ilivandha","Sorpirakkum Sorvu Tharum"],"en":["From penury will spring, 'mid even those of noble race,","Oblivion that gives birth to words that bring disgrace"],"s":"Even in those of high birth, poverty will produce the fault of uttering mean words","ch":105,"sec":2,"th":"impermanence"},
  {"n":1045,"ta":["நல்குரவு என்னும் இடும்பையுள் பல்குரைத்","துன்பங்கள் சென்று படும்"],"tr":["Nalkuravu Ennum Itumpaiyul Palkuraith","Thunpangal Sendru Patum"],"en":["From poverty, that grievous woe,","Attendant sorrows plenteous grow"],"s":"The misery of poverty brings in its train many  (more) miseries","ch":105,"sec":2,"th":"impermanence"},
  {"n":1046,"ta":["நற்பொருள் நன்குணர்ந்து சொல்லினும் நல்கூர்ந்தார்","சொற்பொருள் சோர்வு படும்"],"tr":["Narporul Nankunarndhu Sollinum Nalkoorndhaar","Sorporul Sorvu Patum"],"en":["Though deepest sense, well understood, the poor man's words convey,","Their sense from memory of mankind will fade away"],"s":"The words of the poor are profitless, though they may be sound in thought and clear in expression","ch":105,"sec":2,"th":"impermanence"},
  {"n":1047,"ta":["அறஞ்சாரா நல்குரவு ஈன்றதா யானும்","பிறன்போல நோக்கப் படும்"],"tr":["Aranjaaraa Nalkuravu Eendradhaa Yaanum","Piranpola Nokkap Patum"],"en":["From indigence devoid of virtue's grace,","The mother e'en that bare, estranged, will turn her face"],"s":"He that is reduced to absolute poverty will be regarded as a stranger even by his own mother","ch":105,"sec":2,"th":"impermanence"},
  {"n":1048,"ta":["இன்றும் வருவது கொல்லோ நெருநலும்","கொன்றது போலும் நிரப்பு"],"tr":["Indrum Varuvadhu Kollo Nerunalum","Kondradhu Polum Nirappu"],"en":["And will it come today as yesterday,","The grief of want that eats my soul away"],"s":"Is the poverty that almost killed me yesterday, to meet me today too?","ch":105,"sec":2,"th":"impermanence"},
  {"n":1049,"ta":["நெருப்பினுள் துஞ்சலும் ஆகும் நிரப்பினுள்","யாதொன்றும் கண்பாடு அரிது"],"tr":["Neruppinul Thunjalum Aakum Nirappinul","Yaadhondrum Kanpaatu Aridhu"],"en":["Amid the flames sleep may men's eyelids close,","In poverty the eye knows no repose"],"s":"One may sleep in the midst of fire; but by no means in the midst of poverty","ch":105,"sec":2,"th":"impermanence"},
  {"n":1050,"ta":["துப்புர வில்லார் துவரத் துறவாமை","உப்பிற்கும் காடிக்கும் கூற்று"],"tr":["Thuppura Villaar Thuvarath Thuravaamai","Uppirkum Kaatikkum Kootru"],"en":["Unless the destitute will utterly themselves deny,","They cause their neighbour's salt and vinegar to die"],"s":"The destitute poor, who do not renounce their bodies, only consume their neighbour's salt and water","ch":105,"sec":2,"th":"impermanence"},
  {"n":1051,"ta":["இரக்க இரத்தக்கார்க் காணின் கரப்பின்","அவர்பழி தம்பழி அன்று"],"tr":["Irakka Iraththakkaark Kaanin Karappin","Avarpazhi Thampazhi Andru"],"en":["When those you find from whom 'tis meet to ask,  for aid apply;","Theirs is the sin, not yours, if they the gift deny"],"s":"If you meet with those that may be begged of, you may beg;  (but) if they withhold  (their gift) it is their blame and not yours","ch":106,"sec":2,"th":"impermanence"},
  {"n":1052,"ta":["இன்பம் ஒருவற்கு இரத்தல் இரந்தவை","துன்பம் உறாஅ வரின்"],"tr":["Inpam Oruvarku Iraththal Irandhavai","Thunpam Uraaa Varin"],"en":["Even to ask an alms may pleasure give,","If what you ask without annoyance you receive"],"s":"Even begging may be pleasant, if what is begged for is obtained without grief  (to him that begs)","ch":106,"sec":2,"th":"impermanence"},
  {"n":1053,"ta":["கரப்பிலா நெஞ்சின் கடனறிவார் முன்நின்று","இரப்புமோ ரேஎர் உடைத்து"],"tr":["Karappilaa Nenjin Katanarivaar Munnindru","Irappumo Reer Utaiththu"],"en":["The men who nought deny, but know what's due, before their face","To stand as suppliants affords especial grace"],"s":"There is even a beauty in standing before and begging of those who are liberal in their gifts and understand their duty  (to beggars)","ch":106,"sec":2,"th":"impermanence"},
  {"n":1054,"ta":["இரத்தலும் ஈதலே போலும் கரத்தல்","கனவிலும் தேற்றாதார் மாட்டு"],"tr":["Iraththalum Eedhale Polum Karaththal","Kanavilum Thetraadhaar Maattu"],"en":["Like giving alms, may even asking pleasant seem,","From men who of denial never even dream"],"s":"To beg of such as never think of withholding  (their charity) even in their dreams, is in fact the same as giving  (it oneself);","ch":106,"sec":2,"th":"impermanence"},
  {"n":1055,"ta":["கரப்பிலார் வையகத்து உண்மையால் கண்ணின்று","இரப்பவர் மேற்கொள் வது"],"tr":["Karappilaar Vaiyakaththu Unmaiyaal Kannindru","Irappavar Merkol Vadhu"],"en":["Because on earth the men exist, who never say them nay,","Men bear to stand before their eyes for help to pray"],"s":"As there are in the world those that give without refusing, there are  (also) those that prefer to beg by simply standing before them","ch":106,"sec":2,"th":"impermanence"},
  {"n":1056,"ta":["கரப்பிடும்பை யில்லாரைக் காணின் நிரப்பிடும்பை","எல்லாம் ஒருங்கு கெடும்"],"tr":["Karappitumpai Yillaaraik Kaanin Nirappitumpai","Ellaam Orungu Ketum"],"en":["It those you find from evil of 'denial' free,","At once all plague of poverty will flee"],"s":"All the evil of begging will be removed at the sight of those who are far from the evil of refusing","ch":106,"sec":2,"th":"impermanence"},
  {"n":1057,"ta":["இகழ்ந்தெள்ளாது ஈவாரைக் காணின் மகிழ்ந்துள்ளம்","உள்ளுள் உவப்பது உடைத்து"],"tr":["Ikazhndhellaadhu Eevaaraik Kaanin Makizhndhullam","Ullul Uvappadhu Utaiththu"],"en":["If men are found who give and no harsh words of scorn employ,","The minds of askers, through and through, will thrill with joy"],"s":"Beggars rejoice exceedingly when they behold those who bestow  (their alms) with kindness and courtesy","ch":106,"sec":2,"th":"impermanence"},
  {"n":1058,"ta":["இரப்பாரை இல்லாயின் ஈர்ங்கண்மா ஞாலம்","மரப்பாவை சென்றுவந் தற்று"],"tr":["Irappaarai Illaayin Eernganmaa Gnaalam","Marappaavai Sendruvan Thatru"],"en":["If askers cease, the mighty earth, where cooling fountains flow,","Will be a stage where wooden puppets come and go"],"s":"If there were no beggars,  (the actions done in) the cool wide world would only resemble the movement of a puppet","ch":106,"sec":2,"th":"impermanence"},
  {"n":1059,"ta":["ஈவார்கண் என்னுண்டாம் தோற்றம் இரந்துகோள்","மேவார் இலாஅக் கடை"],"tr":["Eevaarkan Ennuntaam Thotram Irandhukol","Mevaar Ilaaak Katai"],"en":["What glory will there be to men of generous soul,","When none are found to love the askers' role"],"s":"What  (praise) would there be to givers  (of alms) if there were no beggars to ask for and reveive  (them)","ch":106,"sec":2,"th":"impermanence"},
  {"n":1060,"ta":["இரப்பான் வெகுளாமை வேண்டும் நிரப்பிடும்பை","தானேயும் சாலும் கரி"],"tr":["Irappaan Vekulaamai Ventum Nirappitumpai","Thaaneyum Saalum Kari"],"en":["Askers refused from wrath must stand aloof;","The plague of poverty itself is ample proof"],"s":"He who begs ought not to be angry  (at a refusal); for even the misery of  (his own) poverty should be a sufficient reason  (for so doing)","ch":106,"sec":2,"th":"impermanence"},
  {"n":1061,"ta":["கரவாது உவந்தீயும் கண்ணன்னார் கண்ணும்","இரவாமை கோடி உறும்"],"tr":["Karavaadhu Uvandheeyum Kannannaar Kannum","Iravaamai Koti Urum"],"en":["Ten million-fold 'tis greater gain, asking no alms to live,","Even from those, like eyes in worth, who nought concealing gladly give"],"s":"Not to beg  (at all) even from those excellent persons who cheerfully give without refusing, will do immense good","ch":107,"sec":2,"th":"impermanence"},
  {"n":1062,"ta":["இரந்தும் உயிர்வாழ்தல் வேண்டின் பரந்து","கெடுக உலகியற்றி யான்"],"tr":["Irandhum Uyirvaazhdhal Ventin Parandhu","Ketuka Ulakiyatri Yaan"],"en":["If he that shaped the world desires that men should begging go,","Through life's long course, let him a wanderer be and perish so"],"s":"If the Creator of the world has decreed even begging as a means of livelihood, may he too go abegging and perish","ch":107,"sec":2,"th":"impermanence"},
  {"n":1063,"ta":["இன்மை இடும்பை இரந்துதீர் வாமென்னும்","வன்மையின் வன்பாட்ட தில்"],"tr":["Inmai Itumpai Irandhudheer Vaamennum","Vanmaiyin Vanpaatta Thil"],"en":["Nothing is harder than the hardness that will say,","'The plague of penury by asking alms we'll drive away. '"],"s":"There is no greater folly than the boldness with which one seeks to remedy the evils of poverty by begging  (rather than by working)","ch":107,"sec":2,"th":"impermanence"},
  {"n":1064,"ta":["இடமெல்லாம் கொள்ளாத் தகைத்தே இடமில்லாக்","காலும் இரவொல்லாச் சால்பு"],"tr":["Itamellaam Kollaath Thakaiththe Itamillaak","Kaalum Iravollaach Chaalpu"],"en":["Who ne'er consent to beg in utmost need, their worth","Has excellence of greatness that transcends the earth"],"s":"Even the whole world cannot sufficiently praise the dignity that would not beg even in the midst of destitution","ch":107,"sec":2,"th":"impermanence"},
  {"n":1065,"ta":["தெண்ணீர் அடுபுற்கை ஆயினும் தாள்தந்தது","உண்ணலின் ஊங்கினிய தில்"],"tr":["Thenneer Atupurkai Aayinum Thaaldhandhadhu","Unnalin Oonginiya Thil"],"en":["Nothing is sweeter than to taste the toil-won cheer,","Though mess of pottage as tasteless as the water clear"],"s":"Even thin gruel is ambrosia to him who has obtained it by labour","ch":107,"sec":2,"th":"impermanence"},
  {"n":1066,"ta":["ஆவிற்கு நீரென்று இரப்பினும் நாவிற்கு","இரவின் இளிவந்த தில்"],"tr":["Aavirku Neerendru Irappinum Naavirku","Iravin Ilivandha Thil"],"en":["E'en if a draught of water for a cow you ask,","Nought's so distasteful to the tongue as beggar's task"],"s":"There is nothing more disgraceful to one's tongue than to use it in begging water even for a cow","ch":107,"sec":2,"th":"impermanence"},
  {"n":1067,"ta":["இரப்பன் இரப்பாரை எல்லாம் இரப்பின்","கரப்பார் இரவன்மின் என்று"],"tr":["Irappan Irappaarai Ellaam Irappin","Karappaar Iravanmin Endru"],"en":["One thing I beg of beggars all, 'If beg ye may,","Of those who hide their wealth, beg not, I pray. '"],"s":"I beseech all beggars and say, \"If you need to beg, never beg of those who give unwillingly.\"","ch":107,"sec":2,"th":"impermanence"},
  {"n":1068,"ta":["இரவென்னும் ஏமாப்பில் தோணி கரவென்னும்","பார்தாக்கப் பக்கு விடும்"],"tr":["Iravennum Emaappil Thoni Karavennum","Paardhaakkap Pakku Vitum"],"en":["The fragile bark of beggary","Wrecked on denial's rock will lie"],"s":"The unsafe raft of begging will split when it strikes on the rock of refusal","ch":107,"sec":2,"th":"impermanence"},
  {"n":1069,"ta":["இரவுள்ள உள்ளம் உருகும் கரவுள்ள","உள்ளதூஉம் இன்றிக் கெடும்"],"tr":["Iravulla Ullam Urukum Karavulla","Ulladhooum Indrik Ketum"],"en":["The heart will melt away at thought of beggary,","With thought of stern repulse 'twill perish utterly"],"s":"To think of  (the evil of) begging is enough to melt one's heart; but to think of refusal is enough to break it","ch":107,"sec":2,"th":"impermanence"},
  {"n":1070,"ta":["கரப்பவர்க்கு யாங்கொளிக்கும் கொல்லோ இரப்பவர்","சொல்லாடப் போஒம் உயிர்"],"tr":["Karappavarkku Yaangolikkum Kollo Irappavar","Sollaatap Poom Uyir"],"en":["E'en as he asks, the shamefaced asker dies;","Where shall his spirit hide who help denies"],"s":"Saying \"No\" to a beggar takes away his life.  (but as that very word will kill the refuser) where then would the latter's life hide itself?","ch":107,"sec":2,"th":"impermanence"},
  {"n":1071,"ta":["மக்களே போல்வர் கயவர் அவரன்ன","ஒப்பாரி யாங்கண்ட தில்"],"tr":["Makkale Polvar Kayavar Avaranna","Oppaari Yaanganta Thil"],"en":["The base resemble men in outward form, I ween;","But counterpart exact to them I've never seen"],"s":"The base resemble men perfectly  (as regards form); and we have not seen such  (exact) resemblance  (among any other species)","ch":108,"sec":2,"th":"wisdom"},
  {"n":1072,"ta":["நன்றறி வாரிற் கயவர் திருவுடையர்","நெஞ்சத்து அவலம் இலர்"],"tr":["Nandrari Vaarir Kayavar Thiruvutaiyar","Nenjaththu Avalam Ilar"],"en":["Than those of grateful heart the base must luckier be,","Their minds from every anxious thought are free"],"s":"The low enjoy more felicity than those who know what is good; for the former are not troubled with anxiety  (as to the good)","ch":108,"sec":2,"th":"wisdom"},
  {"n":1073,"ta":["தேவர் அனையர் கயவர் அவருந்தாம்","மேவன செய்தொழுக லான்"],"tr":["Thevar Anaiyar Kayavar Avarundhaam","Mevana Seydhozhuka Laan"],"en":["The base are as the Gods; they too","Do ever what they list to do"],"s":"The base resemble the Gods; for the base act as they like","ch":108,"sec":2,"th":"wisdom"},
  {"n":1074,"ta":["அகப்பட்டி ஆவாரைக் காணின் அவரின்","மிகப்பட்டுச் செம்மாக்கும் கீழ்"],"tr":["Akappatti Aavaaraik Kaanin Avarin","Mikappattuch Chemmaakkum Keezh"],"en":["When base men those behold of conduct vile,","They straight surpass them, and exulting smile"],"s":"The base feels proud when he sees persons whose acts meaner than his own","ch":108,"sec":2,"th":"wisdom"},
  {"n":1075,"ta":["அச்சமே கீழ்களது ஆசாரம் எச்சம்","அவாவுண்டேல் உண்டாம் சிறிது"],"tr":["Achchame Keezhkaladhu Aasaaram Echcham","Avaavuntel Untaam Siridhu"],"en":["Fear is the base man's virtue; if that fail,","Intense desire some little may avail"],"s":"(The principle of) behaviour in the mean is chiefly fear; if not, hope of gain, to some extent","ch":108,"sec":2,"th":"wisdom"},
  {"n":1076,"ta":["அறைபறை அன்னர் கயவர்தாம் கேட்ட","மறைபிறர்க்கு உய்த்துரைக்க லான்"],"tr":["Araiparai Annar Kayavardhaam Ketta","Maraipirarkku Uyththuraikka Laan"],"en":["The base are like the beaten drum; for, when they hear","The sound the secret out in every neighbour's ear"],"s":"The base are like a drum that is beaten, for they unburden to others the secrets they have heard","ch":108,"sec":2,"th":"wisdom"},
  {"n":1077,"ta":["ஈர்ங்கை விதிரார் கயவர் கொடிறுடைக்கும்","கூன்கையர் அல்லா தவர்க்கு"],"tr":["Eerngai Vidhiraar Kayavar Kotirutaikkum","Koonkaiyar Allaa Thavarkku"],"en":["From off their moistened hands no clinging grain they shake,","Unless to those with clenched fist their jaws who break"],"s":"The mean will not  (even) shake off  (what sticks to) their hands  (soon after a meal) to any but those who would break their jaws with their clenched fists","ch":108,"sec":2,"th":"wisdom"},
  {"n":1078,"ta":["சொல்லப் பயன்படுவர் சான்றோர் கரும்புபோல்","கொல்லப் பயன்படும் கீழ்"],"tr":["Sollap Payanpatuvar Saandror Karumpupol","Kollap Payanpatum Keezh"],"en":["The good to those will profit yield fair words who use;","The base, like sugar-cane, will profit those who bruise"],"s":"The great bestow  (their alms) as soon as they are informed;  (but) the mean, like the sugar-cane, only when they are tortured to death","ch":108,"sec":2,"th":"wisdom"},
  {"n":1079,"ta":["உடுப்பதூஉம் உண்பதூஉம் காணின் பிறர்மேல்","வடுக்காண வற்றாகும் கீழ்"],"tr":["Utuppadhooum Unpadhooum Kaanin Pirarmel","Vatukkaana Vatraakum Keezh"],"en":["If neighbours clothed and fed he see, the base","Is mighty man some hidden fault to trace"],"s":"The base will bring an evil  (accusation) against others, as soon as he sees them  (enjoying) good food","ch":108,"sec":2,"th":"wisdom"},
  {"n":1080,"ta":["எற்றிற் குரியர் கயவரொன்று உற்றக்கால்","விற்றற்கு உரியர் விரைந்து"],"tr":["Etrir Kuriyar Kayavarondru Utrakkaal","Vitrarku Uriyar Viraindhu"],"en":["For what is base man fit, if griefs assail?","Himself to offer, there and then, for sale"],"s":"The base will hasten to sell themselves as soon as a calamity has befallen them. For what else are they fitted?","ch":108,"sec":2,"th":"wisdom"},
  {"n":1081,"ta":["அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை","மாதர்கொல் மாலும் என் நெஞ்சு"],"tr":["Anangukol Aaimayil Kollo Kananguzhai","Maadharkol Maalum En Nenju"],"en":["Goddess? or peafowl rare? She whose ears rich jewels wear,","Is she a maid of human kind? All wildered is my mind"],"s":"Is this jewelled female a celestial, a choice peahen, or a human being? My mind is perplexed","ch":109,"sec":3,"th":"love"},
  {"n":1082,"ta":["நோக்கினாள் நோக்கெதிர் நோக்குதல் தாக்கணங்கு","தானைக்கொண் டன்ன துடைத்து"],"tr":["Nokkinaal Nokkedhir Nokkudhal Thaakkanangu","Thaanaikkon Tanna Thutaiththu"],"en":["She of the beaming eyes, To my rash look her glance replies,","As if the matchless goddess' hand Led forth an armed band"],"s":"This female beauty returning my looks is like a celestial maiden coming with an army to contend against me","ch":109,"sec":3,"th":"love"},
  {"n":1083,"ta":["பண்டறியேன் கூற்றென் பதனை இனியறிந்தேன்","பெண்டகையால் பேரமர்க் கட்டு"],"tr":["Pantariyen Kootren Padhanai Iniyarindhen","Pentakaiyaal Peramark Kattu"],"en":["Death's form I formerly Knew not; but now 'tis plain to me;","He comes in lovely maiden's guise, With soul-subduing eyes"],"s":"I never knew before what is called Yama; I see it now; it is the eyes that carry on a great fight with  (the help of) female qualities","ch":109,"sec":3,"th":"love"},
  {"n":1084,"ta":["கண்டார் உயிருண்ணும் தோற்றத்தால் பெண்டகைப்","பேதைக்கு அமர்த்தன கண்"],"tr":["Kantaar Uyirunnum Thotraththaal Pentakaip","Pedhaikku Amarththana Kan"],"en":["In sweet simplicity, A woman's gracious form hath she;","But yet those eyes, that drink my life, Are with the form at strife"],"s":"These eyes that seem to kill those who look at them are as it were in hostilities with this feminine simplicity","ch":109,"sec":3,"th":"love"},
  {"n":1085,"ta":["கூற்றமோ கண்ணோ பிணையோ மடவரல்","நோக்கமிம் மூன்றும் உடைத்து"],"tr":["Kootramo Kanno Pinaiyo Matavaral","Nokkamim Moondrum Utaiththu"],"en":["The light that on me gleams, Is it death's dart? or eye's bright beams?","Or fawn's shy glance? All three appear In form of maiden here"],"s":"Is it Yama,  (a pair of) eyes or a hind?  Are not all these three in the looks of this maid?","ch":109,"sec":3,"th":"love"},
  {"n":1086,"ta":["கொடும்புருவம் கோடா மறைப்பின் நடுங்கஞர்","செய்யல மன்இவள் கண்"],"tr":["Kotumpuruvam Kotaa Maraippin Natungagnar","Seyyala Manival Kan"],"en":["If cruel eye-brow's bow, Unbent, would veil those glances now;","The shafts that wound this trembling heart Her eyes no more would dart"],"s":"Her eyes will cause  (me) no trembling sorrow, if they are properly hidden by her cruel arched eyebrows","ch":109,"sec":3,"th":"love"},
  {"n":1087,"ta":["கடாஅக் களிற்றின்மேற் கட்படாம் மாதர்","படாஅ முலைமேல் துகில்"],"tr":["Kataaak Kalitrinmer Katpataam Maadhar","Pataaa Mulaimel Thukil"],"en":["As veil o'er angry eyes Of raging elephant that lies,","The silken cincture's folds invest This maiden's panting breast"],"s":"The cloth that covers the firm bosom of this maiden is  (like) that which covers the eyes of a rutting elephant","ch":109,"sec":3,"th":"love"},
  {"n":1088,"ta":["ஒண்ணுதற் கோஒ உடைந்ததே ஞாட்பினுள்","நண்ணாரும் உட்குமென் பீடு"],"tr":["Onnudhar Koo Utaindhadhe Gnaatpinul","Nannaarum Utkumen Peetu"],"en":["Ah woe is me my might, That awed my foemen in the fight,","By lustre of that beaming brow Borne down, lies broken now"],"s":"On her bright brow alone is destroyed even that power of mine that used to terrify the most fearless","ch":109,"sec":3,"th":"love"},
  {"n":1089,"ta":["பிணையேர் மடநோக்கும் நாணும் உடையாட்கு","அணியெவனோ ஏதில தந்து"],"tr":["Pinaiyer Matanokkum Naanum Utaiyaatku","Aniyevano Edhila Thandhu"],"en":["Like tender fawn's her eye; Clothed on is she with modesty;","What added beauty can be lent; By alien ornament"],"s":"Of what use are other jewels to her who is adorned with modesty, and the meek looks of a hind?","ch":109,"sec":3,"th":"love"},
  {"n":1090,"ta":["உண்டார்கண் அல்லது அடுநறாக் காமம்போல்","கண்டார் மகிழ்செய்தல் இன்று"],"tr":["Untaarkan Alladhu Atunaraak Kaamampol","Kantaar Makizhseydhal Indru"],"en":["The palm-tree's fragrant wine, To those who taste yields joys divine;","But love hath rare felicity For those that only see"],"s":"Unlike boiled honey which yields delight only when it is drunk, love gives pleasure even when looked at","ch":109,"sec":3,"th":"love"},
  {"n":1091,"ta":["இருநோக்கு இவளுண்கண் உள்ளது ஒருநோக்கு","நோய்நோக்கொன் றந்நோய் மருந்து"],"tr":["Irunokku Ivalunkan Ulladhu Orunokku","Noinokkon Rannoi Marundhu"],"en":["A double witchery have glances of her liquid eye;","One glance is glance that brings me pain; the other heals again"],"s":"There are two looks in the dyed eyes of this  (fair one); one causes pain, and the other is the cure thereof","ch":110,"sec":3,"th":"love"},
  {"n":1092,"ta":["கண்களவு கொள்ளும் சிறுநோக்கம் காமத்தில்","செம்பாகம் அன்று பெரிது"],"tr":["Kankalavu Kollum Sirunokkam Kaamaththil","Sempaakam Andru Peridhu"],"en":["The furtive glance, that gleams one instant bright,","Is more than half of love's supreme delight"],"s":"A single stolen glance of her eyes is more than half the pleasure  (of sexual embrace)","ch":110,"sec":3,"th":"love"},
  {"n":1093,"ta":["நோக்கினாள் நோக்கி இறைஞ்சினாள் அஃதவள்","யாப்பினுள் அட்டிய நீர்"],"tr":["Nokkinaal Nokki Irainjinaal Aqdhaval","Yaappinul Attiya Neer"],"en":["She looked, and looking drooped her head:","On springing shoot of love 'its water shed"],"s":"She has looked  (at men) and stooped  (her head); and that  (sign) waters as it were  (the corn of) our love","ch":110,"sec":3,"th":"love"},
  {"n":1094,"ta":["யான்நோக்கும் காலை நிலன்நோக்கும் நோக்காக்கால்","தான்நோக்கி மெல்ல நகும்"],"tr":["Yaannokkum Kaalai Nilannokkum Nokkaakkaal","Thaannokki Mella Nakum"],"en":["I look on her: her eyes are on the ground the while:","I look away: she looks on me with timid smile"],"s":"When I look, she looks down; when I do not, she looks and smiles gently","ch":110,"sec":3,"th":"love"},
  {"n":1095,"ta":["குறிக்கொண்டு நோக்காமை அல்லால் ஒருகண்","சிறக்கணித்தாள் போல நகும்"],"tr":["Kurikkontu Nokkaamai Allaal Orukan","Sirakkaniththaal Pola Nakum"],"en":["She seemed to see me not; but yet the maid","Her love, by smiling side-long glance, betrayed"],"s":"She not only avoids a direct look at me, but looks as it were with a half-closed eye and smiles","ch":110,"sec":3,"th":"love"},
  {"n":1096,"ta":["உறாஅ தவர்போல் சொலினும் செறாஅர்சொல்","ஒல்லை உணரப் படும்"],"tr":["Uraaa Thavarpol Solinum Seraaarsol","Ollai Unarap Patum"],"en":["Though with their lips affection they disown,","Yet, when they hate us not, 'tis quickly known"],"s":"Though they may speak harshly as if they were strangers, the words of the friendly are soon understood","ch":110,"sec":3,"th":"love"},
  {"n":1097,"ta":["செறாஅச் சிறுசொல்லும் செற்றார்போல் நோக்கும்","உறாஅர்போன்று உற்றார் குறிப்பு"],"tr":["Seraaach Chirusollum Setraarpol Nokkum","Uraaarpondru Utraar Kurippu"],"en":["The slighting words that anger feign, while eyes their love reveal","Are signs of those that love, but would their love conceal"],"s":"Little words that are harsh and looks that are hateful are  (but) the expressions of lovers who wish to act like strangers","ch":110,"sec":3,"th":"love"},
  {"n":1098,"ta":["அசையியற்கு உண்டாண்டோர் ஏஎர்யான் நோக்கப்","பசையினள் பைய நகும்"],"tr":["Asaiyiyarku Untaantor Eeryaan Nokkap","Pasaiyinal Paiya Nakum"],"en":["I gaze, the tender maid relents the while;","And, oh the matchless grace of that soft smile"],"s":"When I look, the pitying maid looks in return and smiles gently; and that is a comforting sign for me","ch":110,"sec":3,"th":"love"},
  {"n":1099,"ta":["ஏதிலார் போலப் பொதுநோக்கு நோக்குதல்","காதலார் கண்ணே உள"],"tr":["Edhilaar Polap Podhunokku Nokkudhal","Kaadhalaar Kanne Ula"],"en":["The look indifferent, that would its love disguise,","Is only read aright by lovers' eyes"],"s":"Both the lovers are capable of looking at each other in an ordinary way, as if they were perfect strangers","ch":110,"sec":3,"th":"love"},
  {"n":1100,"ta":["கண்ணொடு கண்இணை நோக்கொக்கின் வாய்ச்சொற்கள்","என்ன பயனும் இல"],"tr":["Kannotu Kaninai Nokkokkin Vaaichchorkal","Enna Payanum Ila"],"en":["When eye to answering eye reveals the tale of love,","All words that lips can say must useless prove"],"s":"The words of the mouths are of no use whatever, when there is perfect agreement between the eyes  (of lovers)","ch":110,"sec":3,"th":"love"},
  {"n":1101,"ta":["கண்டுகேட்டு உண்டுயிர்த்து உற்றறியும் ஐம்புலனும்","ஒண்தொடி கண்ணே உள"],"tr":["Kantukettu Untuyirththu Utrariyum Aimpulanum","Ondhoti Kanne Ula"],"en":["All joys that senses five- sight, hearing, taste, smell, touch- can give,","In this resplendent armlets-bearing damsel live"],"s":"The  (simultaneous) enjoyment of the five senses of sight, hearing, taste, smell and touch can only be found with bright braceleted  (women)","ch":111,"sec":3,"th":"love"},
  {"n":1102,"ta":["பிணிக்கு மருந்து பிறமன் அணியிழை","தன்நோய்க்குத் தானே மருந்து"],"tr":["Pinikku Marundhu Piraman Aniyizhai","Thannoikkuth Thaane Marundhu"],"en":["Disease and medicine antagonists we surely see;","This maid, to pain she gives, herself is remedy"],"s":"The remedy for a disease is always something different  (from it); but for the disease caused by this jewelled maid, she is herself the cure","ch":111,"sec":3,"th":"love"},
  {"n":1103,"ta":["தாம்வீழ்வார் மென்றோள் துயிலின் இனிதுகொல்","தாமரைக் கண்ணான் உலகு"],"tr":["Thaamveezhvaar Mendrol Thuyilin Inidhukol","Thaamaraik Kannaan Ulaku"],"en":["Than rest in her soft arms to whom the soul is giv'n,","Is any sweeter joy in his, the Lotus-eyed-one's heaven"],"s":"Can the lotus-eyed Vishnu's heaven be indeed as sweet to those who delight to sleep in the delicate arms of their beloved?","ch":111,"sec":3,"th":"love"},
  {"n":1104,"ta":["நீங்கின் தெறூஉம் குறுகுங்கால் தண்ணென்னும்","தீயாண்டுப் பெற்றாள் இவள்?"],"tr":["Neengin Theruum Kurukungaal Thannennum","Theeyaantup Petraal Ival?"],"en":["Withdraw, it burns; approach, it soothes the pain;","Whence did the maid this wondrous fire obtain"],"s":"From whence has she got this fire that burns when I withdraw and cools when I approach?","ch":111,"sec":3,"th":"love"},
  {"n":1105,"ta":["வேட்ட பொழுதின் அவையவை போலுமே","தோட்டார் கதுப்பினாள் தோள்"],"tr":["Vetta Pozhudhin Avaiyavai Polume","Thottaar Kadhuppinaal Thol"],"en":["In her embrace, whose locks with flowery wreaths are bound,","Each varied form of joy the soul can wish is found"],"s":"Each varied form of joy the soul can wish is found","ch":111,"sec":3,"th":"love"},
  {"n":1106,"ta":["உறுதோறு உயிர்தளிர்ப்பத் தீண்டலால் பேதைக்கு","அமிழ்தின் இயன்றன தோள்"],"tr":["Urudhoru Uyirdhalirppath Theentalaal Pedhaikku","Amizhdhin Iyandrana Thol"],"en":["Ambrosia are the simple maiden's arms; when I attain","Their touch, my withered life puts forth its buds again"],"s":"The shoulders of this fair one are made of ambrosia, for they revive me with pleasure every time I embrace them","ch":111,"sec":3,"th":"love"},
  {"n":1107,"ta":["தம்மில் இருந்து தமதுபாத்து உண்டற்றால்","அம்மா அரிவை முயக்கு"],"tr":["Thammil Irundhu Thamadhupaaththu Untatraal","Ammaa Arivai Muyakku"],"en":["As when one eats from household store, with kindly grace","Sharing his meal: such is this golden maid's embrace"],"s":"The embraces of a gold-complexioned beautiful female are as pleasant as to dwell in one's own house and live by one's own  (earnings) after distributing  (a portion of it in charity)","ch":111,"sec":3,"th":"love"},
  {"n":1108,"ta":["வீழும் இருவர்க்கு இனிதே வளியிடை","போழப் படாஅ முயக்கு"],"tr":["Veezhum Iruvarkku Inidhe Valiyitai","Pozhap Pataaa Muyakku"],"en":["Sweet is the strict embrace of those whom fond affection binds,","Where no dissevering breath of discord entrance finds"],"s":"To ardent lovers sweet is the embrace that cannot be penetrated even by a breath of breeze","ch":111,"sec":3,"th":"love"},
  {"n":1109,"ta":["ஊடல் உணர்தல் புணர்தல் இவைகாமம்","கூடியார் பெற்ற பயன்"],"tr":["Ootal Unardhal Punardhal Ivaikaamam","Kootiyaar Petra Payan"],"en":["The jealous variance, the healing of the strife, reunion gained:","These are the fruits from wedded love obtained"],"s":"Love quarrel, reconciliation and intercourse - these are the advantages reaped by those who marry for lust","ch":111,"sec":3,"th":"love"},
  {"n":1110,"ta":["அறிதோறு அறியாமை கண்டற்றால் காமம்","செறிதோறும் சேயிழை மாட்டு"],"tr":["Aridhoru Ariyaamai Kantatraal Kaamam","Seridhorum Seyizhai Maattu"],"en":["The more men learn, the more their lack of learning they detect;","'Tis so when I approach the maid with gleaming jewels decked"],"s":"As  (one's) ignorance is discovered the more one learns, so does repeated intercourse with a welladorned female  (only create a desire for more)","ch":111,"sec":3,"th":"love"},
  {"n":1111,"ta":["நன்னீரை வாழி அனிச்சமே நின்னினும்","மென்னீரள் யாம்வீழ் பவள்"],"tr":["Nanneerai Vaazhi Anichchame Ninninum","Menneeral Yaamveezh Paval"],"en":["O flower of the sensitive plant! than thee","More tender's the maiden beloved by me"],"s":"May you flourish, O Anicham! you have a delicate nature But my beloved is more delicate than you","ch":112,"sec":3,"th":"love"},
  {"n":1112,"ta":["மலர்காணின் மையாத்தி நெஞ்சே இவள்கண்","பலர்காணும் பூவொக்கும் என்று"],"tr":["Malarkaanin Maiyaaththi Nenje Ivalkan","Palarkaanum Poovokkum Endru"],"en":["You deemed, as you saw the flowers, her eyes were as flowers, my soul,","That many may see; it was surely some folly that over you stole"],"s":"O my soul, fancying that flowers which are seen by many can resemble her eyes, you become confused at the sight of them","ch":112,"sec":3,"th":"love"},
  {"n":1113,"ta":["முறிமேனி முத்தம் முறுவல் வெறிநாற்றம்","வேலுண்கண் வேய்த்தோ ளவட்கு"],"tr":["Murimeni Muththam Muruval Verinaatram","Velunkan Veyththo Lavatku"],"en":["As tender shoot her frame; teeth, pearls; around her odours blend;","Darts are the eyes of her whose shoulders like the bambu bend"],"s":"The complexion of this bamboo-shouldered one is that of a shoot; her teeth, are pearls; her breath,","ch":112,"sec":3,"th":"love"},
  {"n":1114,"ta":["காணின் குவளை கவிழ்ந்து நிலன்நோக்கும்","மாணிழை கண்ணொவ்வேம் என்று"],"tr":["Kaanin Kuvalai Kavizhndhu Nilannokkum","Maanizhai Kannovvem Endru"],"en":["The lotus, seeing her, with head demiss, the ground would eye,","And say, 'With eyes of her, rich gems who wears, we cannot vie. '"],"s":"If the blue lotus could see, it would stoop and look at the ground saying, \"I can never resemble the eyes of this excellent jewelled one.\"","ch":112,"sec":3,"th":"love"},
  {"n":1115,"ta":["அனிச்சப்பூக் கால்களையாள் பெய்தாள் நுகப்பிற்கு","நல்ல படாஅ பறை"],"tr":["Anichchappook Kaalkalaiyaal Peydhaal Nukappirku","Nalla Pataaa Parai"],"en":["The flowers of the sensitive plant as a girdle around her she placed;","The stems she forgot to nip off; they 'll weigh down the delicate waist"],"s":"No merry drums will be beaten for the  (tender) waist of her who has adorned herself with the anicham without having removed its stem","ch":112,"sec":3,"th":"love"},
  {"n":1116,"ta":["மதியும் மடந்தை முகனும் அறியா","பதியின் கலங்கிய மீன்"],"tr":["Madhiyum Matandhai Mukanum Ariyaa","Padhiyin Kalangiya Meen"],"en":["The stars perplexed are rushing wildly from their spheres;","For like another moon this maiden's face appears"],"s":"The stars have become confused in their places not being able to distinguish between the moon and the maid's countenance","ch":112,"sec":3,"th":"love"},
  {"n":1117,"ta":["அறுவாய் நிறைந்த அவிர்மதிக்குப் க்குப் போல","மறுவுண்டோ மாதர் முகத்து"],"tr":["Aruvaai Niraindha Avirmadhikkup Pola","Maruvunto Maadhar Mukaththu"],"en":["In moon, that waxing waning shines, as sports appear,","Are any spots discerned in face of maiden here"],"s":"Could there be spots in the face of this maid like those in the bright full moon?","ch":112,"sec":3,"th":"love"},
  {"n":1118,"ta":["மாதர் முகம்போல் ஒளிவிட வல்லையேல்","காதலை வாழி மத஧"],"tr":["Maadhar Mukampol Olivita Vallaiyel","Kaadhalai Vaazhi Madhi"],"en":["Farewell, O moon! If that thine orb could shine","Bright as her face, thou shouldst be love of mine"],"s":"If you can indeed shine like the face of women, flourish, O moon, for then would you be worth loving?","ch":112,"sec":3,"th":"love"},
  {"n":1119,"ta":["மலரன்ன கண்ணாள் முகமொத்தி யாயின்","பலர்காணத் தோன்றல் மதி"],"tr":["Malaranna Kannaal Mukamoththi Yaayin","Palarkaanath Thondral Madhi"],"en":["If as her face, whose eyes are flowers, thou wouldst have charms for me,","Shine for my eyes alone, O moon, shine not for all to see"],"s":"O moon, if you wish to resemble the face of her whose eyes are like  (these) flowers, do not appear so as to be seen by all","ch":112,"sec":3,"th":"love"},
  {"n":1120,"ta":["அனிச்சமும் அன்னத்தின் தூவியும் மாதர்","அடிக்கு நெருஞ்சிப் பழம்"],"tr":["Anichchamum Annaththin Thooviyum Maadhar","Atikku Nerunjip Pazham"],"en":["The flower of the sensitive plant, and the down on the swan's white breast,","As the thorn are harsh, by the delicate feet of this maiden pressed"],"s":"The anicham and the feathers of the swan are to the feet of females, like the fruit of the  (thorny) Nerunji","ch":112,"sec":3,"th":"love"},
  {"n":1121,"ta":["பாலொடு தேன்கலந் தற்றே பணிமொழி","வாலெயிறு ஊறிய நீர்"],"tr":["Paalotu Thenkalan Thatre Panimozhi","Vaaleyiru Ooriya Neer"],"en":["The dew on her white teeth, whose voice is soft and low,","Is as when milk and honey mingled flow"],"s":"The water which oozes from the white teeth of this soft speeched damsel is like a mixture of milk and honey","ch":113,"sec":3,"th":"love"},
  {"n":1122,"ta":["உடம்பொடு உயிரிடை என்னமற் றன்ன","மடந்தையொடு எம்மிடை நட்பு"],"tr":["Utampotu Uyiritai Ennamar Ranna","Matandhaiyotu Emmitai Natpu"],"en":["Between this maid and me the friendship kind","Is as the bonds that soul and body bind"],"s":"The love between me and this damsel is like the union of body and soul","ch":113,"sec":3,"th":"love"},
  {"n":1123,"ta":["கருமணியிற் பாவாய்நீ போதாயாம் வீழும்","திருநுதற்கு இல்லை இடம்"],"tr":["Karumaniyir Paavaainee Podhaayaam Veezhum","Thirunudharku Illai Itam"],"en":["For her with beauteous brow, the maid I love, there place is none;","To give her image room, O pupil of mine eye, begone"],"s":"O you image in the pupil  (of my eye)! depart; there is no room for  (my) fair-browed beloved","ch":113,"sec":3,"th":"love"},
  {"n":1124,"ta":["வாழ்தல் உயிர்க்கன்னள் ஆயிழை சாதல்","அதற்கன்னள் நீங்கும் இடத்து"],"tr":["Vaazhdhal Uyirkkannal Aayizhai Saadhal","Adharkannal Neengum Itaththu"],"en":["Life is she to my very soul when she draws nigh;","Dissevered from the maid with jewels rare, I die"],"s":"My fair-jewelled one resembles the living soul  (when she is in union with me), the dying soul when she leaves me","ch":113,"sec":3,"th":"love"},
  {"n":1125,"ta":["உள்ளுவன் மன்யான் மறப்பின் மறப்பறியேன்","ஒள்ளமர்க் கண்ணாள் குணம்"],"tr":["Ulluvan Manyaan Marappin Marappariyen","Ollamark Kannaal Kunam"],"en":["I might recall, if I could once forget; but from my heart","Her charms fade not, whose eyes gleam like the warrior's dart"],"s":"If I had forgotten her who has bright battling eyes, I would have remembered  (thee); but I never forget her  (Thus says he to her maid)","ch":113,"sec":3,"th":"love"},
  {"n":1126,"ta":["கண்ணுள்ளின் போகார் இமைப்பின் பருகுவரா","நுண்ணியர்எம் காத லவர்"],"tr":["Kannullin Pokaar Imaippin Parukuvaraa","Nunniyarem Kaadha Lavar"],"en":["My loved one's subtle form departs not from my eyes;","I wink them not, lest I should pain him where he lies"],"s":"My lover would not depart from mine eyes; even if I wink, he would not suffer  (from pain); he is so ethereal","ch":113,"sec":3,"th":"love"},
  {"n":1127,"ta":["கண்ணுள்ளார் காத லவராகக் கண்ணும்","எழுதேம் கரப்பாக்கு அறிந்து"],"tr":["Kannullaar Kaadha Lavaraakak Kannum","Ezhudhem Karappaakku Arindhu"],"en":["My love doth ever in my eyes reside;","I stain them not, fearing his form to hide"],"s":"As my lover abides in my eyes, I will not even paint them, for he would  (then) have to conceal himself","ch":113,"sec":3,"th":"love"},
  {"n":1128,"ta":["நெஞ்சத்தார் காத லவராக வெய்துண்டல்","அஞ்சுதும் வேபாக் கறிந்து"],"tr":["Nenjaththaar Kaadha Lavaraaka Veydhuntal","Anjudhum Vepaak Karindhu"],"en":["Within my heart my lover dwells; from food I turn","That smacks of heat, lest he should feel it burn"],"s":"As my lover is in my heart, I am afraid of eating  (anything) hot, for I know it would pain him","ch":113,"sec":3,"th":"love"},
  {"n":1129,"ta":["இமைப்பின் கரப்பாக்கு அறிவல் அனைத்திற்கே","ஏதிலர் என்னும் இவ் வூர்"],"tr":["Imaippin Karappaakku Arival Anaiththirke","Edhilar Ennum Iv Voor"],"en":["I fear his form to hide, nor close my eyes:","'Her love estranged is gone! ' the village cries"],"s":"I will not wink, knowing that if I did, my lover would hide himself; and for this reason, this town says, he is unloving","ch":113,"sec":3,"th":"love"},
  {"n":1130,"ta":["உவந்துறைவர் உள்ளத்துள் என்றும் இகந்துறைவர்","ஏதிலர் என்னும் இவ் வூர்"],"tr":["Uvandhuraivar Ullaththul Endrum Ikandhuraivar","Edhilar Ennum Iv Voor"],"en":["Rejoicing in my very soul he ever lies;","'Her love estranged is gone far off! ' the village cries"],"s":"My lover dwells in my heart with perpetual delight; but the town says he is unloving and  (therefore) dwells afar","ch":113,"sec":3,"th":"love"},
  {"n":1131,"ta":["காமம் உழந்து வருந்தினார்க்கு ஏமம்","மடலல்லது இல்லை வலி"],"tr":["Kaamam Uzhandhu Varundhinaarkku Emam","Matalalladhu Illai Vali"],"en":["To those who 've proved love's joy, and now afflicted mourn,","Except the helpful 'horse of palm', no other strength remains"],"s":"To those who after enjoyment of sexual pleasure suffer  (for want of more), there is no help so efficient as the palmyra horse","ch":114,"sec":3,"th":"love"},
  {"n":1132,"ta":["நோனா உடம்பும் உயிரும் மடலேறும்","நாணினை நீக்கி நிறுத்து"],"tr":["Nonaa Utampum Uyirum Matalerum","Naaninai Neekki Niruththu"],"en":["My body and my soul, that can no more endure,","Will lay reserve aside, and mount the 'horse of palm'"],"s":"Having got rid of shame, the suffering body and soul save themselves on the palmyra horse","ch":114,"sec":3,"th":"love"},
  {"n":1133,"ta":["நாணொடு நல்லாண்மை பண்டுடையேன் இன்றுடையேன்","காமுற்றார் ஏறும் மடல்"],"tr":["Naanotu Nallaanmai Pantutaiyen Indrutaiyen","Kaamutraar Erum Matal"],"en":["I once retained reserve and seemly manliness;","To-day I nought possess but lovers' 'horse of palm'"],"s":"Modesty and manliness were once my own; now, my own is the palmyra horse that is ridden by the lustful","ch":114,"sec":3,"th":"love"},
  {"n":1134,"ta":["காமக் கடும்புனல் உய்க்கும் நாணொடு","நல்லாண்மை என்னும் புணை"],"tr":["Kaamak Katumpunal Uykkum Naanotu","Nallaanmai Ennum Punai"],"en":["Love's rushing tide will sweep away the raft","Of seemly manliness and shame combined"],"s":"The raft of modesty and manliness, is, alas, carried-off by the strong current of lust","ch":114,"sec":3,"th":"love"},
  {"n":1135,"ta":["தொடலைக் குறுந்தொடி தந்தாள் மடலொடு","மாலை உழக்கும் துயர்"],"tr":["Thotalaik Kurundhoti Thandhaal Matalotu","Maalai Uzhakkum Thuyar"],"en":["The maid that slender armlets wears, like flowers entwined,","Has brought me 'horse of palm, ' and pangs of eventide"],"s":"She with the small garland-like bracelets has given me the palmyra horse and the sorrow that is endured at night","ch":114,"sec":3,"th":"love"},
  {"n":1136,"ta":["மடலூர்தல் யாமத்தும் உள்ளுவேன் மன்ற","படல்ஒல்லா பேதைக்கென் கண்"],"tr":["Mataloordhal Yaamaththum Ulluven Mandra","Patalollaa Pedhaikken Kan"],"en":["Of climbing 'horse of palm' in midnight hour, I think;","My eyes know no repose for that same simple maid"],"s":"Mine eyes will not close in sleep on your mistress's account; even at midnight will I think of mounting the palmyra horse","ch":114,"sec":3,"th":"love"},
  {"n":1137,"ta":["கடலன்ன காமம் உழந்தும் மடலேறாப்","பெண்ணின் பெருந்தக்க தில்"],"tr":["Katalanna Kaamam Uzhandhum Mataleraap","Pennin Perundhakka Thil"],"en":["There's nought of greater worth than woman's long-enduring soul,","Who, vexed by love like ocean waves, climbs not the 'horse of palm'"],"s":"There is nothing so noble as the womanly nature that would not ride the palmyra horse, though plunged a sea of lust","ch":114,"sec":3,"th":"love"},
  {"n":1138,"ta":["நிறையரியர் மன்அளியர் என்னாது காமம்","மறையிறந்து மன்று படும்"],"tr":["Niraiyariyar Manaliyar Ennaadhu Kaamam","Maraiyirandhu Mandru Patum"],"en":["In virtue hard to move, yet very tender, too, are we;","Love deems not so, would rend the veil, and court publicity"],"s":"Even the Lust  (of women) transgresses its secrecy and appears in public, forgetting that they are too chaste and liberal  (to be overcome by it)","ch":114,"sec":3,"th":"love"},
  {"n":1139,"ta":["அறிகிலார் எல்லாரும் என்றேஎன் காமம்","மறுகின் மறுகும் மருண்டு"],"tr":["Arikilaar Ellaarum Endreen Kaamam","Marukin Marukum Maruntu"],"en":["'There's no one knows my heart, ' so says my love,","And thus, in public ways, perturbed will rove"],"s":"And thus, in public ways, perturbed will rove","ch":114,"sec":3,"th":"love"},
  {"n":1140,"ta":["யாம்கண்ணின் காண நகுப அறிவில்லார்","யாம்பட்ட தாம்படா ஆறு"],"tr":["Yaamkannin Kaana Nakupa Arivillaar","Yaampatta Thaampataa Aaru"],"en":["Before my eyes the foolish make a mock of me,","Because they ne'er endured the pangs I now must drie"],"s":"Even strangers laugh  (at us) so as to be seen by us, for they have not suffered","ch":114,"sec":3,"th":"love"},
  {"n":1141,"ta":["அலரெழ ஆருயிர் நிற்கும் அதனைப்","பலரறியார் பாக்கியத் தால்"],"tr":["Alarezha Aaruyir Na�rkum Adhanaip","Palarariyaar Paakkiyath Thaal"],"en":["By this same rumour's rise, my precious life stands fast;","Good fortune grant the many know this not"],"s":"My precious life is saved by the raise of rumour, and this, to my good luck no others are aware of","ch":115,"sec":3,"th":"love"},
  {"n":1142,"ta":["மலரன்ன கண்ணாள் அருமை அறியாது","அலரெமக்கு ஈந்ததிவ் வூர்"],"tr":["Malaranna Kannaal Arumai Ariyaadhu","Alaremakku Eendhadhiv Voor"],"en":["The village hath to us this rumour giv'n, that makes her mine;","Unweeting all the rareness of the maid with flower-like eyne"],"s":"Not knowing the value of her whose eyes are like flowers this town has got up a rumour about me","ch":115,"sec":3,"th":"love"},
  {"n":1143,"ta":["உறாஅதோ ஊரறிந்த கெளவை அதனைப்","பெறாஅது பெற்றன்ன நீர்த்து"],"tr":["Uraaadho Oorarindha Kelavai Adhanaip","Peraaadhu Petranna Neerththu"],"en":["The rumour spread within the town, is it not gain to me?","It is as though that were obtained that may not be"],"s":"Will I not get a rumour that is known to the  (whole) town? For what I have not got is as if I had got it  (already)","ch":115,"sec":3,"th":"love"},
  {"n":1144,"ta":["கவ்வையால் கவ்விது காமம் அதுவின்றேல்","தவ்வென்னும் தன்மை இழந்து"],"tr":["Kavvaiyaal Kavvidhu Kaamam Adhuvindrel","Thavvennum Thanmai Izhandhu"],"en":["The rumour rising makes my love to rise;","My love would lose its power and languish otherwise"],"s":"Rumour increases the violence of my passion; without it it would grow weak and waste away","ch":115,"sec":3,"th":"love"},
  {"n":1145,"ta":["களித்தொறும் கள்ளுண்டல் வேட்டற்றால் காமம்","வெளிப்படுந் தோறும் இனிது"],"tr":["Kaliththorum Kalluntal Vettatraal Kaamam","Velippatun Thorum Inidhu"],"en":["The more man drinks, the more he ever drunk would be;","The more my love's revealed, the sweeter 'tis to me"],"s":"As drinking liquor is delightful  (to one) whenever one is in mirth, so is lust delightful to me whenever it is the subject of rumour","ch":115,"sec":3,"th":"love"},
  {"n":1146,"ta":["கண்டது மன்னும் ஒருநாள் அலர்மன்னும்","திங்களைப் பாம்புகொண் டற்று"],"tr":["Kantadhu Mannum Orunaal Alarmannum","Thingalaip Paampukon Tatru"],"en":["I saw him but one single day: rumour spreads soon","As darkness, when the dragon seizes on the moon"],"s":"It was but a single day that I looked on  (my lover); but the rumour thereof has spread like the seizure of the moon by the serpent","ch":115,"sec":3,"th":"love"},
  {"n":1147,"ta":["ஊரவர் கெளவை எருவாக அன்னைசொல்","நீராக நீளும்இந் நோய்"],"tr":["Ooravar Kelavai Eruvaaka Annaisol","Neeraaka Neelumin Noi"],"en":["My anguish grows apace: the town's report","Manures it; my mother's word doth water it"],"s":"This malady  (of lust) is manured by the talk of women and watered by the  (harsh) words of my mother","ch":115,"sec":3,"th":"love"},
  {"n":1148,"ta":["நெய்யால் எரிநுதுப்பேம் என்றற்றால் கெளவையால்","காமம் நுதுப்பேம் எனல்"],"tr":["Neyyaal Erinudhuppem Endratraal Kelavaiyaal","Kaamam Nudhuppem Enal"],"en":["With butter-oil extinguish fire! 'Twill prove","Harder by scandal to extinguish love"],"s":"To say that one could extinguish passion by rumour is like extinguishing fire with ghee","ch":115,"sec":3,"th":"love"},
  {"n":1149,"ta":["அலர்நாண ஒல்வதோ அஞ்சலோம்பு என்றார்","பலர்நாண நீத்தக் கடை"],"tr":["Alarnaana Olvadho Anjalompu Endraar","Palarnaana Neeththak Katai"],"en":["When he who said 'Fear not! ' hath left me blamed,","While many shrink, can I from rumour hide ashamed"],"s":"When the departure of him who said \"fear not\" has put me to shame before others, why need I be ashamed of scandal","ch":115,"sec":3,"th":"love"},
  {"n":1150,"ta":["தாம்வேண்டின் நல்குவர் காதலர் யாம்வேண்டும்","கெளவை எடுக்கும்இவ் வூர்"],"tr":["Thaamventin Nalkuvar Kaadhalar Yaamventum","Kelavai Etukkumiv Voor"],"en":["If we desire, who loves will grant what we require;","This town sends forth the rumour we desire"],"s":"The rumour I desire is raised by the town  (itself); and my lover would if desired consent  (to my following him)","ch":115,"sec":3,"th":"love"},
  {"n":1151,"ta":["செல்லாமை உண்டேல் எனக்குரை மற்றுநின்","வல்வரவு வாழ்வார்க் குரை"],"tr":["Sellaamai Untel Enakkurai Matrunin","Valvaravu Vaazhvaark Kurai"],"en":["If you will say, 'I leave thee not, ' then tell me so;","Of quick return tell those that can survive this woe"],"s":"If it is not departure, tell me; but if it is your speedy return, tell it to those who would be alive then","ch":116,"sec":3,"th":"love"},
  {"n":1152,"ta":["இன்கண் உடைத்தவர் பார்வல் பிரிவஞ்சும்","புன்கண் உடைத்தால் புணர்வு"],"tr":["Inkan Utaiththavar Paarval Pirivanjum","Punkan Utaiththaal Punarvu"],"en":["It once was perfect joy to look upon his face;","But now the fear of parting saddens each embrace"],"s":"His very look was once pleasing; but  (now) even intercourse is painful through fear of separation","ch":116,"sec":3,"th":"love"},
  {"n":1153,"ta":["அரிதரோ தேற்றம் அறிவுடையார் கண்ணும்","பிரிவோ ரிடத்துண்மை யான்"],"tr":["Aridharo Thetram Arivutaiyaar Kannum","Pirivo Ritaththunmai Yaan"],"en":["To trust henceforth is hard, if ever he depart,","E'en he, who knows his promise and my breaking heart"],"s":"As even the lover who understands  (everything) may at times depart, confidence is hardly possible","ch":116,"sec":3,"th":"love"},
  {"n":1154,"ta":["அளித்தஞ்சல் என்றவர் நீப்பின் தெளித்தசொல்","தேறியார்க்கு உண்டோ தவறு"],"tr":["Aliththanjal Endravar Neeppin Theliththasol","Theriyaarkku Unto Thavaru"],"en":["If he depart, who fondly said, 'Fear not, ' what blame's incurred","By those who trusted to his reassuring word"],"s":"If he who bestowed his love and said \"fear not\" should depart, will it be the fault of those who believed in  (his) assuring words?","ch":116,"sec":3,"th":"love"},
  {"n":1155,"ta":["ஓம்பின் அமைந்தார் பிரிவோம்பல் மற்றவர்","நீங்கின் அரிதால் புணர்வு"],"tr":["Ompin Amaindhaar Pirivompal Matravar","Neengin Aridhaal Punarvu"],"en":["If you would guard my life, from going him restrain","Who fills my life! If he depart, hardly we meet again"],"s":"If you would save  (my life), delay the departure of my destined  (husband); for if he departs, intercourse will become impossible","ch":116,"sec":3,"th":"love"},
  {"n":1156,"ta":["பிரிவுரைக்கும் வன்கண்ணர் ஆயின் அரிதவர்","நல்குவர் என்னும் நசை"],"tr":["Pirivuraikkum Vankannar Aayin Aridhavar","Nalkuvar Ennum Nasai"],"en":["To cherish longing hope that he should ever gracious be,","Is hard, when he could stand, and of departure speak to me"],"s":"Is hard, when he could stand, and of departure speak to me","ch":116,"sec":3,"th":"love"},
  {"n":1157,"ta":["துறைவன் துறந்தமை தூற்றாகொல் முன்கை","இறைஇறவா நின்ற வளை"],"tr":["Thuraivan Thurandhamai Thootraakol Munkai","Iraiiravaa Nindra Valai"],"en":["The bracelet slipping from my wrist announced before","Departure of the Prince that rules the ocean shore"],"s":"Do not the rings that begin to slide down my fingers forebode the separation of my lord?","ch":116,"sec":3,"th":"love"},
  {"n":1158,"ta":["இன்னாது இனன்இல்ஊர் வாழ்தல் அதனினும்","இன்னாது இனியார்ப் பிரிவு"],"tr":["Innaadhu Inaniloor Vaazhdhal Adhaninum","Innaadhu Iniyaarp Pirivu"],"en":["'Tis sad to sojourn in the town where no kind kinsmen dwell;","'Tis sadder still to bid a friend beloved farewell"],"s":"Painful is it to live in a friendless town; but far more painful is it to part from one's lover","ch":116,"sec":3,"th":"love"},
  {"n":1159,"ta":["தொடிற்சுடின் அல்லது காமநோய் போல","விடிற்சுடல் ஆற்றுமோ தீ"],"tr":["Thotirsutin Alladhu Kaamanoi Pola","Vitirsutal Aatrumo Thee"],"en":["Fire burns the hands that touch; but smart of love","Will burn in hearts that far away remove"],"s":"Fire burns when touched; but, like the sickness of love, can it also burn when removed?","ch":116,"sec":3,"th":"love"},
  {"n":1160,"ta":["அரிதாற்றி அல்லல்நோய் நீக்கிப் பிரிவாற்றிப்","பின்இருந்து வாழ்வார் பலர்"],"tr":["Aridhaatri Allalnoi Neekkip Pirivaatrip","Pinirundhu Vaazhvaar Palar"],"en":["Sorrow's sadness meek sustaining, Driving sore distress away,","Separation uncomplaining Many bear the livelong day"],"s":"As if there were many indeed that can consent to the impossible, kill their pain, endure separation and yet continue to live afterwards","ch":116,"sec":3,"th":"love"},
  {"n":1161,"ta":["மறைப்பேன்மன் யானிஃதோ நோயை இறைப்பவர்க்கு","ஊற்றுநீர் போல மிகும்"],"tr":["Maraippenman Yaaniqdho Noyai Iraippavarkku","Ootruneer Pola Mikum"],"en":["I would my pain conceal, but see! it surging swells,","As streams to those that draw from ever-springing wells"],"s":"I would hide this pain from others; but it  (only) swells like a spring to those who drain it","ch":117,"sec":3,"th":"love"},
  {"n":1162,"ta":["கரத்தலும் ஆற்றேன்இந் நோயைநோய் செய்தார்க்கு","உரைத்தலும் நாணுத் தரும்"],"tr":["Karaththalum Aatrenin Noyainoi Seydhaarkku","Uraiththalum Naanuth Tharum"],"en":["I cannot hide this pain of mine, yet shame restrains","When I would tell it out to him who caused my pains"],"s":"I cannot conceal this pain, nor can I relate it without shame to him who has caused it","ch":117,"sec":3,"th":"love"},
  {"n":1163,"ta":["காமமும் நாணும் உயிர்காவாத் தூங்கும்என்","நோனா உடம்பின் அகத்து"],"tr":["Kaamamum Naanum Uyirkaavaath Thoongumen","Nonaa Utampin Akaththu"],"en":["My soul, like porter's pole, within my wearied frame,","Sustains a two-fold burthen poised, of love and shame"],"s":"(Both) lust and shame, with my soul for their shoulder pole balance themselves on a body that cannot bear them","ch":117,"sec":3,"th":"love"},
  {"n":1164,"ta":["காமக் கடல்மன்னும் உண்டே அதுநீந்தும்","ஏமப் புணைமன்னும் இல்"],"tr":["Kaamak Katalmannum Unte Adhuneendhum","Emap Punaimannum Il"],"en":["A sea of love, 'tis true, I see stretched out before,","But not the trusty bark that wafts to yonder shore"],"s":"There is indeed a flood of lust; but there is no raft of safety to cross it with","ch":117,"sec":3,"th":"love"},
  {"n":1165,"ta":["துப்பின் எவனாவர் மன்கொல் துயர்வரவு","நட்பினுள் ஆற்று பவர்"],"tr":["Thuppin Evanaavar Mankol Thuyarvaravu","Natpinul Aatru Pavar"],"en":["Who work us woe in friendship's trustful hour,","What will they prove when angry tempests lower"],"s":"What will they prove when angry tempests lower?","ch":117,"sec":3,"th":"love"},
  {"n":1166,"ta":["இன்பம் கடல்மற்றுக் காமம் அஃதடுங்கால்","துன்பம் அதனிற் பெரிது"],"tr":["Inpam Katalmatruk Kaamam Aqdhatungaal","Thunpam Adhanir Peridhu"],"en":["A happy love 's sea of joy; but mightier sorrows roll","From unpropitious love athwart the troubled soul"],"s":"The pleasure of lust is  (as great as) the sea; but the pain of lust is far greater","ch":117,"sec":3,"th":"love"},
  {"n":1167,"ta":["காமக் கடும்புனல் நீந்திக் கரைகாணேன்","யாமத்தும் யானே உளேன்"],"tr":["Kaamak Katumpunal Neendhik Karaikaanen","Yaamaththum Yaane Ulen"],"en":["I swim the cruel tide of love, and can no shore descry,","In watches of the night, too, 'mid the waters, only I"],"s":"I have swam across the terrible flood of lust, but have not seen its shore; even at midnight I am alone; still I live","ch":117,"sec":3,"th":"love"},
  {"n":1168,"ta":["மன்னுயிர் எல்லாம் துயிற்றி அளித்திரா","என்னல்லது இல்லை துணை"],"tr":["Mannuyir Ellaam Thuyitri Aliththiraa","Ennalladhu Illai Thunai"],"en":["All living souls in slumber soft she steeps;","But me alone kind night for her companing keeps"],"s":"The night which graciously lulls to sleep all living creatures, has me alone for her companion","ch":117,"sec":3,"th":"love"},
  {"n":1169,"ta":["கொடியார் கொடுமையின் தாம்கொடிய இந்நாள்","நெடிய கழியும் இரா"],"tr":["Kotiyaar Kotumaiyin Thaamkotiya Innaal","Netiya Kazhiyum Iraa"],"en":["More cruel than the cruelty of him, the cruel one,","In these sad times are lengthening hours of night I watch alone"],"s":"The long nights of these days are far more cruel than the heartless one who is torturing me","ch":117,"sec":3,"th":"love"},
  {"n":1170,"ta":["உள்ளம்போன்று உள்வழிச் செல்கிற்பின் வெள்ளநீர்","நீந்தல மன்னோஎன் கண்"],"tr":["Ullampondru Ulvazhich Chelkirpin Vellaneer","Neendhala Mannoen Kan"],"en":["When eye of mine would as my soul go forth to him,","It knows not how through floods of its own tears to swim"],"s":"Could mine eyes travel like my thoughts to the abode  (of my absent lord), they would not swim in this flood of tears","ch":117,"sec":3,"th":"love"},
  {"n":1171,"ta":["கண்தாம் கலுழ்வ தெவன்கொலோ தண்டாநோய்","தாம்காட்ட யாம்கண் டது"],"tr":["Kandhaam Kaluzhva Thevankolo Thantaanoi","Thaamkaatta Yaamkan Tadhu"],"en":["They showed me him, and then my endless pain","I saw: why then should weeping eyes complain"],"s":"As this incurable malady has been caused by my eyes which showed  (him) to me, why should they now weep for  (him)","ch":118,"sec":3,"th":"love"},
  {"n":1172,"ta":["தெரிந்துணரா நோக்கிய உண்கண் பரிந்துணராப்","பைதல் உழப்பது எவன்?"],"tr":["Therindhunaraa Nokkiya Unkan Parindhunaraap","Paidhal Uzhappadhu Evan?"],"en":["How glancing eyes, that rash unweeting looked that day,","With sorrow measureless are wasting now away"],"s":"The dyed eyes that  (then) looked without foresight, why should they now endure sorrow, without feeling sharply  (their own fault)","ch":118,"sec":3,"th":"love"},
  {"n":1173,"ta":["கதுமெனத் தாநோக்கித் தாமே கலுழும்","இதுநகத் தக்க துடைத்து"],"tr":["Kadhumenath Thaanokkith Thaame Kaluzhum","Ithunakath Thakka Thutaiththu"],"en":["The eyes that threw such eager glances round erewhile","Are weeping now. Such folly surely claims a smile"],"s":"They themselves looked eagerly  (on him) and now they weep. Is not this to be laughed at?","ch":118,"sec":3,"th":"love"},
  {"n":1174,"ta":["பெயலாற்றா நீருலந்த உண்கண் உயலாற்றா","உய்வில்நோய் என்கண் நிறுத்து"],"tr":["Peyalaatraa Neerulandha Unkan Uyalaatraa","Uyvilnoi Enkan Niruththu"],"en":["Those eyes have wept till all the fount of tears is dry,","That brought upon me pain that knows no remedy"],"s":"These painted eyes have caused me a lasting mortal disease; and now they can weep no more, the tears having dried up","ch":118,"sec":3,"th":"love"},
  {"n":1175,"ta":["படலாற்றா பைதல் உழக்கும் கடலாற்றாக்","காமநோய் செய்தஎன் கண்"],"tr":["Patalaatraa Paidhal Uzhakkum Katalaatraak","Kaamanoi Seydhaen Kan"],"en":["The eye that wrought me more than sea could hold of woes,","Is suffering pangs that banish all repose"],"s":"Mine eyes have caused me a lust that is greater than the sea and  (they themselves) endure the torture of sleeplessness","ch":118,"sec":3,"th":"love"},
  {"n":1176,"ta":["ஓஒ இனிதே எமக்கிந்நோய் செய்தகண்","தாஅம் இதற்பட் டது"],"tr":["Oo Inidhe Emakkinnoi Seydhakan","Thaaam Itharpat Tadhu"],"en":["Oho! how sweet a thing to see! the eye","That wrought this pain, in the same gulf doth lie"],"s":"The eyes that have given me this disease have themselves been seized with this  (suffering) Oh! I am much delighted","ch":118,"sec":3,"th":"love"},
  {"n":1177,"ta":["உழந்துழந் துள்நீர் அறுக விழைந்திழைந்து","வேண்டி அவர்க்கண்ட கண்"],"tr":["Uzhandhuzhan Thulneer Aruka Vizhaindhizhaindhu","Venti Avarkkanta Kan"],"en":["Aching, aching, let those exhaust their stream,","That melting, melting, that day gazed on him"],"s":"The eyes that became tender and gazed intently on him, may they suffer so much as to dry up the fountain of their tears","ch":118,"sec":3,"th":"love"},
  {"n":1178,"ta":["பேணாது பெட்டார் உளர்மன்னோ மற்றவர்க்","காணாது அமைவில கண்"],"tr":["Penaadhu Pettaar Ularmanno Matravark","Kaanaadhu Amaivila Kan"],"en":["Who loved me once, onloving now doth here remain;","Not seeing him, my eye no rest can gain"],"s":"He is indeed here who loved me with his lips but not with his heart but mine eyes suffer from not seeing him","ch":118,"sec":3,"th":"love"},
  {"n":1179,"ta":["வாராக்கால் துஞ்சா வரின்துஞ்சா ஆயிடை","ஆரஞர் உற்றன கண்"],"tr":["Vaaraakkaal Thunjaa Varindhunjaa Aayitai","Aaragnar Utrana Kan"],"en":["When he comes not, all slumber flies; no sleep when he is there;","Thus every way my eyes have troubles hard to bear"],"s":"When he is away they do not sleep; when he is present they do not sleep; in either case, mine eyes endure unbearable agony","ch":118,"sec":3,"th":"love"},
  {"n":1180,"ta":["மறைபெறல் ஊரார்க்கு அரிதன்றால் எம்போல்","அறைபறை கண்ணார் அகத்து"],"tr":["Maraiperal Ooraarkku Aridhandraal Empol","Araiparai Kannaar Akaththu"],"en":["It is not hard for all the town the knowledge to obtain,","When eyes, as mine, like beaten tambours, make the mystery plain"],"s":"It is not difficult for the people of this place to understand the secret of those whose eyes, like mine, are as it were beaten drums","ch":118,"sec":3,"th":"love"},
  {"n":1181,"ta":["நயந்தவர்க்கு நல்காமை நேர்ந்தேன் பசந்தவென்","பண்பியார்க்கு உரைக்கோ பிற"],"tr":["Nayandhavarkku Nalkaamai Nerndhen Pasandhaven","Panpiyaarkku Uraikko Pira"],"en":["I willed my lover absent should remain;","Of pining's sickly hue to whom shall I complain"],"s":"I who  (then) consented to the absence of my loving lord, to whom can I  (now) relate the fact of my having turned sallow","ch":119,"sec":3,"th":"love"},
  {"n":1182,"ta":["அவர்தந்தார் என்னும் தகையால் இவர்தந்தென்","மேனிமேல் ஊரும் பசப்பு"],"tr":["Avardhandhaar Ennum Thakaiyaal Ivardhandhen","Menimel Oorum Pasappu"],"en":["'He gave': this sickly hue thus proudly speaks,","Then climbs, and all my frame its chariot makes"],"s":"Sallowness, as if proud of having been caused by him, would now ride on my person","ch":119,"sec":3,"th":"love"},
  {"n":1183,"ta":["சாயலும் நாணும் அவர்கொண்டார் கைம்மாறா","நோயும் பசலையும் தந்து"],"tr":["Saayalum Naanum Avarkontaar Kaimmaaraa","Noyum Pasalaiyum Thandhu"],"en":["Of comeliness and shame he me bereft,","While pain and sickly hue, in recompense, he left"],"s":"He has taken  (away) my beauty and modesty, and given me instead disease and sallowness","ch":119,"sec":3,"th":"love"},
  {"n":1184,"ta":["உள்ளுவன் மன்யான் உரைப்பது அவர்திறமால்","கள்ளம் பிறவோ பசப்பு"],"tr":["Ulluvan Manyaan Uraippadhu Avardhiramaal","Kallam Piravo Pasappu"],"en":["I meditate his words, his worth is theme of all I say,","This sickly hue is false that would my trust betray"],"s":"I think  (of him); and what I speak about is but his excellence; still is there sallowness; and this is deceitful","ch":119,"sec":3,"th":"love"},
  {"n":1185,"ta":["உவக்காண்எம் காதலர் செல்வார் இவக்காண்என்","மேனி பசப்பூர் வது"],"tr":["Uvakkaanem Kaadhalar Selvaar Ivakkaanen","Meni Pasappoor Vadhu"],"en":["My lover there went forth to roam;","This pallor of my frame usurps his place at home"],"s":"Just as my lover departed then, did not sallowness spread here on my person?","ch":119,"sec":3,"th":"love"},
  {"n":1186,"ta":["விளக்கற்றம் பார்க்கும் இருளேபோல் கொண்கன்","முயக்கற்றம் பார்க்கும் பசப்பு"],"tr":["Vilakkatram Paarkkum Irulepol Konkan","Muyakkatram Paarkkum Pasappu"],"en":["As darkness waits till lamp expires, to fill the place,","This pallor waits till I enjoy no more my lord's embrace"],"s":"Just as darkness waits for the failing light; so does sallowness wait for the laxity of my husband's intercourse","ch":119,"sec":3,"th":"love"},
  {"n":1187,"ta":["புல்லிக் கிடந்தேன் புடைபெயர்ந்தேன் அவ்வளவில்","அள்ளிக்கொள் வற்றே பசப்பு"],"tr":["Pullik Kitandhen Putaipeyarndhen Avvalavil","Allikkol Vatre Pasappu"],"en":["I lay in his embrace, I turned unwittingly;","Forthwith this hue, as you might grasp it, came on me"],"s":"I who was in close embrace just turned aside and the moment I did so, sallowness came on me like something to be seized on","ch":119,"sec":3,"th":"love"},
  {"n":1188,"ta":["பசந்தாள் இவள்என்பது அல்லால் இவளைத்","துறந்தார் அவர்என்பார் இல்"],"tr":["Pasandhaal Ivalenpadhu Allaal Ivalaith","Thurandhaar Avarenpaar Il"],"en":["On me, because I pine, they cast a slur;","But no one says, 'He first deserted her. '"],"s":"Besides those who say \"she has turned sallow\" there are none who say \"he has forsaken her\"","ch":119,"sec":3,"th":"love"},
  {"n":1189,"ta":["பசக்கமன் பட்டாங்கென் மேனி நயப்பித்தார்","நன்னிலையர் ஆவர் எனின்"],"tr":["Pasakkaman Pattaangen Meni Nayappiththaar","Nannilaiyar Aavar Enin"],"en":["Well let my frame, as now, be sicklied o'er with pain,","If he who won my heart's consent, in good estate remain"],"s":"If he is clear of guilt who has conciliated me  (to his departure) let my body suffer its due and turn sallow","ch":119,"sec":3,"th":"love"},
  {"n":1190,"ta":["பசப்பெனப் பேர்பெறுதல் நன்றே நயப்பித்தார்","நல்காமை தூற்றார் எனின்"],"tr":["Pasappenap Perperudhal Nandre Nayappiththaar","Nalkaamai Thootraar Enin"],"en":["'Tis well, though men deride me for my sickly hue of pain;","If they from calling him unkind, who won my love, refrain"],"s":"It would be good to be said of me that I have turned sallow, if friends do not reproach with unkindness him who pleased me  (then)","ch":119,"sec":3,"th":"love"},
  {"n":1191,"ta":["தாம்வீழ்வார் தம்வீழப் பெற்றவர் பெற்றாரே","காமத்துக் காழில் கனி"],"tr":["Thaamveezhvaar Thamveezhap Petravar Petraare","Kaamaththuk Kaazhil Kani"],"en":["The bliss to be beloved by those they love who gains,","Of love the stoneless, luscious fruit obtains"],"s":"The women who are beloved by those whom they love, have they have not got the stone-less fruit of sexual delight?","ch":120,"sec":3,"th":"love"},
  {"n":1192,"ta":["வாழ்வார்க்கு வானம் பயந்தற்றால் வீழ்வார்க்கு","வீழ்வார் அள஧ க்கும் அளி"],"tr":["Vaazhvaarkku Vaanam Payandhatraal Veezhvaarkku","Veezhvaar Ala� Kkum Ali"],"en":["As heaven on living men showers blessings from above,","Is tender grace by lovers shown to those they love"],"s":"The bestowal of love by the beloved on those who love them is like the rain raining  (at the proper season) on those who live by it","ch":120,"sec":3,"th":"love"},
  {"n":1193,"ta":["வீழுநர் வீழப் படுவார்க்கு அமையுமே","வாழுநம் என்னும் செருக்கு"],"tr":["Veezhunar Veezhap Patuvaarkku Amaiyume","Vaazhunam Ennum Serukku"],"en":["Who love and are beloved to them alone","Belongs the boast, 'We've made life's very joys our own. '"],"s":"The pride that says \"we shall live\" suits only those who are loved by their beloved  (husbands)","ch":120,"sec":3,"th":"love"},
  {"n":1194,"ta":["வீழப் படுவார் கெழீஇயிலர் தாம்வீழ்வார்","வீழப் படாஅர் எனின்"],"tr":["Veezhap Patuvaar Kezheeiyilar Thaamveezhvaar","Veezhap Pataaar Enin"],"en":["Those well-beloved will luckless prove,","Unless beloved by those they love"],"s":"Even those who are esteemed  (by other women) are devoid of excellence, if they are not loved by their beloved","ch":120,"sec":3,"th":"love"},
  {"n":1195,"ta":["நாம்காதல் கொண்டார் நமக்கெவன் செய்பவோ","தாம்காதல் கொள்ளாக் கடை"],"tr":["Naamkaadhal Kontaar Namakkevan Seypavo","Thaamkaadhal Kollaak Katai"],"en":["From him I love to me what gain can be,","Unless, as I love him, he loveth me"],"s":"He who is beloved by me, what will he do to me, if I am not beloved by him?","ch":120,"sec":3,"th":"love"},
  {"n":1196,"ta":["ஒருதலையான் இன்னாது காமம்காப் போல","இருதலை யானும் இனிது"],"tr":["Orudhalaiyaan Innaadhu Kaamamkaap Pola","Irudhalai Yaanum Inidhu"],"en":["Love on one side is bad; like balanced load","By porter borne, love on both sides is good"],"s":"Lust, like the weight of the KAVADI, pains if it lies in one end only but pleases if it is in both","ch":120,"sec":3,"th":"love"},
  {"n":1197,"ta":["பருவரலும் பைதலும் காணான்கொல் காமன்","ஒருவர்கண் நின்றொழுகு வான்"],"tr":["Paruvaralum Paidhalum Kaanaankol Kaaman","Oruvarkan Nindrozhuku Vaan"],"en":["While Kaman rushes straight at me alone,","Is all my pain and wasting grief unknown"],"s":"Would not cupid who abides and contends in one party  (only) witness the pain and sorrow  (in that party)?","ch":120,"sec":3,"th":"love"},
  {"n":1198,"ta":["வீழ்வாரின் இன்சொல் பெறாஅது உலகத்து","வாழ்வாரின் வன்கணார் இல்"],"tr":["Veezhvaarin Insol Peraaadhu Ulakaththu","Vaazhvaarin Vankanaar Il"],"en":["Who hear from lover's lips no pleasant word from day to day,","Yet in the world live out their life,  no braver souls than they"],"s":"There is no one in the world so hard-hearted as those who can live without receiving  (even) a kind word from their beloved","ch":120,"sec":3,"th":"love"},
  {"n":1199,"ta":["நசைஇயார் நல்கார் எனினும் அவர்மாட்டு","இசையும் இனிய செவிக்கு"],"tr":["Nasaiiyaar Nalkaar Eninum Avarmaattu","Isaiyum Iniya Sevikku"],"en":["Though he my heart desires no grace accords to me,","Yet every accent of his voice is melody"],"s":"Though my beloved bestows no love on one, still are his words sweet to my ears","ch":120,"sec":3,"th":"love"},
  {"n":1200,"ta":["உறாஅர்க்கு உறுநோய் உரைப்பாய் கடலைச்","செறாஅஅய் வாழிய நெஞ்சு"],"tr":["Uraaarkku Urunoi Uraippaai Katalaich","Cheraaaai Vaazhiya Nenju"],"en":["Tell him thy pain that loves not thee?","Farewell, my soul, fill up the sea"],"s":"Live, O my soul, would you who relate your great sorrow to strangers, try rather to fill up your own sea  (of sorrow)","ch":120,"sec":3,"th":"love"},
  {"n":1201,"ta":["உள்ளினும் தீராப் பெருமகிழ் செய்தலால்","கள்ளினும் காமம் இனிது"],"tr":["Ullinum Theeraap Perumakizh Seydhalaal","Kallinum Kaamam Inidhu"],"en":["From thought of her unfailing gladness springs,","Sweeter than palm-rice wine the joy love brings"],"s":"Sexuality is sweeter than liquor, because when remembered, it creates a most rapturous delight","ch":121,"sec":3,"th":"love"},
  {"n":1202,"ta":["எனைத்தொனறு இனிதேகாண் காமம்தாம் வீழ்வார்","நினைப்ப வருவதொன்று ஏல்"],"tr":["Enaiththonaru Inidhekaan Kaamamdhaam Veezhvaar","Ninaippa Varuvadhondru El"],"en":["How great is love! Behold its sweetness past belief!","Think on the lover, and the spirit knows no grief"],"s":"Even to think of one's beloved gives one no pain Sexuality, in any degree, is always delightful","ch":121,"sec":3,"th":"love"},
  {"n":1203,"ta":["நினைப்பவர் போன்று நினையார்கொல் தும்மல்","சினைப்பது போன்று கெடும்"],"tr":["Ninaippavar Pondru Ninaiyaarkol Thummal","Sinaippadhu Pondru Ketum"],"en":["A fit of sneezing threatened, but it passed away;","He seemed to think of me, but do his fancies stray"],"s":"I feel as if I am going to sneeze but do not, and  (therefore) my beloved is about to think  (of me) but does not","ch":121,"sec":3,"th":"love"},
  {"n":1204,"ta":["யாமும் உளேங்கொல் அவர்நெஞ்சத்து எந்நெஞ்சத்து","ஓஒ உளரே அவர்"],"tr":["Yaamum Ulengol Avarnenjaththu Ennenjaththu","Oo Ulare Avar"],"en":["Have I a place within his heart!","From mine, alas! he never doth depart"],"s":"He continues to abide in my soul, do I likewise abide in his?","ch":121,"sec":3,"th":"love"},
  {"n":1205,"ta":["தம்நெஞ்சத்து எம்மைக் கடிகொண்டார் நாணார்கொல்","எம்நெஞ்சத்து ஓவா வரல்"],"tr":["Thamnenjaththu Emmaik Katikontaar Naanaarkol","Emnenjaththu Ovaa Varal"],"en":["Me from his heart he jealously excludes:","Hath he no shame who ceaseless on my heart intrudes"],"s":"He who has imprisoned me in his soul, is he ashamed to enter incessantly into mine","ch":121,"sec":3,"th":"love"},
  {"n":1206,"ta":["மற்றியான் என்னுளேன் மன்னோ அவரொடியான்","உற்றநாள் உள்ள உளேன்"],"tr":["Matriyaan Ennulen Manno Avaroti","Yaan Utranaal Ulla Ulen"],"en":["How live I yet? I live to ponder o'er","The days of bliss with him that are no more"],"s":"I live by remembering my  (former) intercourse with him; if it were not so, how could I live?","ch":121,"sec":3,"th":"love"},
  {"n":1207,"ta":["மறப்பின் எவனாவன் மற்கொல் மறப்பறியேன்","உள்ளினும் உள்ளம் சுடும்"],"tr":["Marappin Evanaavan Markol Marappariyen","Ullinum Ullam Sutum"],"en":["If I remembered not what were I then? And yet,","The fiery smart of what my spirit knows not to forget"],"s":"I have never forgotten  (the pleasure); even to think of it burns my soul; could I live, if I should ever forget it?","ch":121,"sec":3,"th":"love"},
  {"n":1208,"ta":["எனைத்து நினைப்பினும் காயார் அனைத்தன்றோ","காதலர் செய்யும் சிறப்பு"],"tr":["Enaiththu Ninaippinum Kaayaar Anaiththandro","Kaadhalar Seyyum Sirappu"],"en":["My frequent thought no wrath excites It is not so?","This honour doth my love on me bestow"],"s":"He will not be angry however much I may think of him; is it not so much the delight my beloved","ch":121,"sec":3,"th":"love"},
  {"n":1209,"ta":["விளியுமென் இன்னுயிர் வேறல்லம் என்பார்","அளியின்மை ஆற்ற நினைந்து"],"tr":["Viliyumen Innuyir Verallam Enpaar","Aliyinmai Aatra Ninaindhu"],"en":["Dear life departs, when his ungracious deeds I ponder o'er,","Who said erewhile, 'We're one for evermore'"],"s":"My precious life is wasting away by thinking too much on the cruelty of him who said we were not different","ch":121,"sec":3,"th":"love"},
  {"n":1210,"ta":["விடாஅது சென்றாரைக் கண்ணினால் காணப்","படாஅதி வாழி மதி"],"tr":["Vitaaadhu Sendraaraik Kanninaal Kaanap","Pataaadhi Vaazhi Madhi"],"en":["Set not; so may'st thou prosper, moon! that eyes may see","My love who went away, but ever bides with me"],"s":"May you live, O Moon! Do not set, that I mine see him who has departed without quitting my soul","ch":121,"sec":3,"th":"love"},
  {"n":1211,"ta":["காதலர் தூதொடு வந்த கனவினுக்கு","யாதுசெய் வேன்கொல் விருந்து"],"tr":["Kaadhalar Thoodhotu Vandha Kanavinukku","Yaadhusey Venkol Virundhu"],"en":["It came and brought to me, that nightly vision rare,","A message from my love,  what feast shall I prepare"],"s":"Where with shall I feast the dream which has brought me my dear one's messenger?","ch":122,"sec":3,"th":"love"},
  {"n":1212,"ta":["கயலுண்கண் யானிரப்பத் துஞ்சிற் கலந்தார்க்கு","உயலுண்மை சாற்றுவேன் மன்"],"tr":["Kayalunkan Yaanirappath Thunjir Kalandhaarkku","Uyalunmai Saatruven Man"],"en":["If my dark, carp-like eye will close in sleep, as I implore,","The tale of my long-suffering life I'll tell my loved one o'er"],"s":"If my fish-like painted eyes should, at my begging, close in sleep, I could fully relate my sufferings to my lord","ch":122,"sec":3,"th":"love"},
  {"n":1213,"ta":["நனவினால் நல்கா தவரைக் கனவினால்","காண்டலின் உண்டென் உயிர்"],"tr":["Nanavinaal Nalkaa Thavaraik Kanavinaal","Kaantalin Unten Uyir"],"en":["Him, who in waking hour no kindness shows,","In dreams I see; and so my lifetime goes"],"s":"My life lasts because in my dream I behold him who does not favour me in my waking hours","ch":122,"sec":3,"th":"love"},
  {"n":1214,"ta":["கனவினான் உண்டாகும் காமம் நனவினான்","நல்காரை நாடித் தரற்கு"],"tr":["Kanavinaan Untaakum Kaamam Nanavinaan","Nalkaarai Naatith Thararku"],"en":["Some pleasure I enjoy when him who loves not me","In waking hours, the vision searches out and makes me see"],"s":"There is pleasure in my dream, because in it I seek and obtain him who does not visit me in my wakefulness","ch":122,"sec":3,"th":"love"},
  {"n":1215,"ta":["நனவினால் கண்டதூஉம் ஆங்கே கனவுந்தான்","கண்ட பொழுதே இனிது"],"tr":["Nanavinaal Kantadhooum Aange Kanavundhaan","Kanta Pozhudhe Inidhu"],"en":["As what I then beheld in waking hour was sweet,","So pleasant dreams in hour of sleep my spirit greet"],"s":"I saw him in my waking hours, and then it was pleasant; I see him just now in my dream, and it is  (equally) pleasant","ch":122,"sec":3,"th":"love"},
  {"n":1216,"ta":["நனவென ஒன்றில்லை ஆயின் கனவினால்","காதலர் நீங்கலர் மன்"],"tr":["Nanavena Ondrillai Aayin Kanavinaal","Kaadhalar Neengalar Man"],"en":["And if there were no waking hour, my love","In dreams would never from my side remove"],"s":"Were there no such thing as wakefulness, my beloved  (who visited me) in my dream would not depart from me","ch":122,"sec":3,"th":"love"},
  {"n":1217,"ta":["நனவினால் நல்காக் கொடியார் கனவனால்","என்எம்மைப் பீழிப் பது"],"tr":["Nanavinaal Nalkaak Kotiyaar Kanavanaal","Enemmaip Peezhip Padhu"],"en":["The cruel one, in waking hour, who all ungracious seems,","Why should he thus torment my soul in nightly dreams"],"s":"The cruel one who would not favour me in my wakefulness, what right has he to torture me in my dreams?","ch":122,"sec":3,"th":"love"},
  {"n":1218,"ta":["துஞ்சுங்கால் தோள்மேலர் ஆகி விழிக்குங்கால்","நெஞ்சத்தர் ஆவர் விரைந்து"],"tr":["Thunjungaal Tholmelar Aaki Vizhikkungaal","Nenjaththar Aavar Viraindhu"],"en":["And when I sleep he holds my form embraced;","And when I wake to fill my heart makes haste"],"s":"When I am asleep he rests on my shoulders,  (but) when I awake he hastens into my soul","ch":122,"sec":3,"th":"love"},
  {"n":1219,"ta":["நனவினால் நல்காரை நோவர் கனவினால்","காதலர்க் காணா தவர்"],"tr":["Nanavinaal Nalkaarai Novar Kanavinaal","Kaadhalark Kaanaa Thavar"],"en":["In dreams who ne'er their lover's form perceive,","For those in waking hours who show no love will grieve"],"s":"They who have no dear ones to behold in their dreams blame him who visits me not in my waking hours","ch":122,"sec":3,"th":"love"},
  {"n":1220,"ta":["நனவினால் நம்நீத்தார் என்பர் கனவினால்","காணார்கொல் இவ்வூ ரவர்"],"tr":["Nanavinaal Namneeththaar Enpar Kanavinaal","Kaanaarkol Ivvoo Ravar"],"en":["They say, that he in waking hours has left me lone;","In dreams they surely see him not,  these people of the town;"],"s":"The women of this place say he has forsaken me in my wakefulness I think they have not seen him visit me in my dreams","ch":122,"sec":3,"th":"love"},
  {"n":1221,"ta":["மாலையோ அல்லை மணந்தார் உயிருண்ணும்","வேலைநீ வாழி பொழுது"],"tr":["Maalaiyo Allai Manandhaar Uyirunnum","Velainee Vaazhi Pozhudhu"],"en":["Thou art not evening, but a spear that doth devour","The souls of brides; farewell, thou evening hour"],"s":"Live, O you evening are you  (the former) evening? No, you are the season that slays  (married) women","ch":123,"sec":3,"th":"love"},
  {"n":1222,"ta":["புன்கண்ணை வாழி மருள்மாலை எம்கேள்போல்","வன்கண்ண தோநின் துணை"],"tr":["Punkannai Vaazhi Marulmaalai Emkelpol","Vankanna Thonin Thunai"],"en":["Thine eye is sad; Hail, doubtful hour of eventide!","Of cruel eye, as is my spouse, is too thy bride"],"s":"A long life to you, O dark evening! You are sightless Is your help-mate  (also) as hard-hearted as mine","ch":123,"sec":3,"th":"love"},
  {"n":1223,"ta":["பனிஅரும்பிப் பைதல்கொள் மாலை துனிஅரும்பித்","துன்பம் வளர வரும்"],"tr":["Paniarumpip Paidhalkol Maalai Thuniarumpith","Thunpam Valara Varum"],"en":["With buds of chilly dew wan evening's shade enclose;","My anguish buds space and all my sorrow grows"],"s":"The evening that  (once) came in with trembling and dimness  (now) brings me an aversion for life and increasing sorrow","ch":123,"sec":3,"th":"love"},
  {"n":1224,"ta":["காதலர் இல்வழி மாலை கொலைக்களத்து","ஏதிலர் போல வரும்"],"tr":["Kaadhalar Ilvazhi Maalai Kolaikkalaththu","Edhilar Pola Varum"],"en":["When absent is my love, the evening hour descends,","As when an alien host to field of battle wends"],"s":"In the absence of my lover, evening comes in like slayers on the field of slaughter","ch":123,"sec":3,"th":"love"},
  {"n":1225,"ta":["காலைக்குச் செய்தநன்று என்கொல் எவன்கொல்யான்","மாலைக்குச் செய்த பகை?"],"tr":["Kaalaikkuch Cheydhanandru Enkol Evankolyaan","Maalaikkuch Cheydha Pakai?"],"en":["O morn, how have I won thy grace? thou bring'st relief","O eve, why art thou foe! thou dost renew my grief"],"s":"O eve, why art thou foe! thou dost renew my grief","ch":123,"sec":3,"th":"love"},
  {"n":1226,"ta":["மாலைநோய் செய்தல் மணந்தார் அகலாத","காலை அறிந்த திலேன்"],"tr":["Maalainoi Seydhal Manandhaar Akalaadha","Kaalai Arindha Thilen"],"en":["The pangs that evening brings I never knew,","Till he, my wedded spouse, from me withdrew"],"s":"Previous to my husband's departure, I know not the painful nature of evening","ch":123,"sec":3,"th":"love"},
  {"n":1227,"ta":["காலை அரும்பிப் பகலெல்லாம் போதாகி","மாலை மலரும்இந் நோய்"],"tr":["Kaalai Arumpip Pakalellaam Podhaaki","Maalai Malarumin Noi"],"en":["My grief at morn a bud, all day an opening flower,","Full-blown expands in evening hour"],"s":"This malady buds forth in the morning, expands all day long and blossoms in the evening","ch":123,"sec":3,"th":"love"},
  {"n":1228,"ta":["அழல்போலும் மாலைக்குத் தூதாகி ஆயன்","குழல்போலும் கொல்லும் படை"],"tr":["Azhalpolum Maalaikkuth Thoodhaaki Aayan","Kuzhalpolum Kollum Patai"],"en":["The shepherd's pipe is like a murderous weapon, to my ear,","For it proclaims the hour of ev'ning's fiery anguish near"],"s":"The shepherd's flute now sounds as a fiery forerunner of night, and is become a weapon that slays  (me)","ch":123,"sec":3,"th":"love"},
  {"n":1229,"ta":["பதிமருண்டு பைதல் உழக்கும் மதிமருண்டு","மாலை படர்தரும் போழ்து"],"tr":["Padhimaruntu Paidhal Uzhakkum Madhimaruntu","Maalai Patardharum Pozhdhu"],"en":["If evening's shades, that darken all my soul, extend;","From this afflicted town will would of grief ascend"],"s":"When night comes on confusing  (everyone's) mind, the  (whole) town will lose its sense and be plunged in sorrow","ch":123,"sec":3,"th":"love"},
  {"n":1230,"ta":["பொருள்மாலை யாளரை உள்ளி மருள்மாலை","மாயும்என் மாயா உயிர்"],"tr":["Porulmaalai Yaalarai Ulli Marulmaalai","Maayumen Maayaa Uyir"],"en":["This darkening eve, my darkling soul must perish utterly;","Remembering him who seeks for wealth, but seeks not me"],"s":"My  (hitherto) unextinguished life is now lost in this bewildering night at the thought of him who has the nature of wealth","ch":123,"sec":3,"th":"love"},
  {"n":1231,"ta":["சிறுமை நமக்கொழியச் சேட்சென்றார் உள்ளி","நறுமலர் நாணின கண்"],"tr":["Sirumai Namakkozhiyach Chetchendraar Ulli","Narumalar Naanina Kan"],"en":["Thine eyes grown dim are now ashamed the fragrant flow'rs to see,","Thinking on him, who wand'ring far, leaves us in misery"],"s":"While we endure the unbearable sorrow, your eyes weep for him who is gone afar, and shun  (the sight of) fragrant flowers","ch":124,"sec":3,"th":"love"},
  {"n":1232,"ta":["நயந்தவர் நல்காமை சொல்லுவ போலும்","பசந்து பனிவாரும் கண்"],"tr":["Nayandhavar Nalkaamai Solluva Polum","Pasandhu Panivaarum Kan"],"en":["The eye, with sorrow wan, all wet with dew of tears,","As witness of the lover's lack of love appears"],"s":"The discoloured eyes that shed tears profusely seem to betray the unkindness of our beloved","ch":124,"sec":3,"th":"love"},
  {"n":1233,"ta":["தணந்தமை சால அறிவிப்ப போலும்","மணந்தநாள் வீங்கிய தோள்"],"tr":["Thanandhamai Saala Arivippa Polum","Manandhanaal Veengiya Thol"],"en":["These withered arms, desertion's pangs abundantly display,","That swelled with joy on that glad nuptial day"],"s":"The shoulders that swelled on the day of our union  (now) seem to announce our separation clearly  (to the public)","ch":124,"sec":3,"th":"love"},
  {"n":1234,"ta":["பணைநீங்கிப் பைந்தொடி சோரும் துணைநீங்கித்","தொல்கவின் வாடிய தோள்"],"tr":["Panaineengip Paindhoti Sorum Thunaineengith","Tholkavin Vaatiya Thol"],"en":["When lover went, then faded all their wonted charms,","And armlets' golden round slips off from these poor wasted arms"],"s":"In the absence of your consort, your shoulders having lost their former beauty and fulness, your bracelets of pure gold have become loose","ch":124,"sec":3,"th":"love"},
  {"n":1235,"ta":["கொடியார் கொடுமை உரைக்கும் தொடியொடு","தொல்கவின் வாடிய தோள்"],"tr":["Kotiyaar Kotumai Uraikkum Thotiyotu","Tholkavin Vaatiya Thol"],"en":["These wasted arms, the bracelet with their wonted beauty gone,","The cruelty declare of that most cruel one"],"s":"The  (loosened) bracelets, and the shoulders from which the old beauty has faded, relate the cruelty of the pitiless one","ch":124,"sec":3,"th":"love"},
  {"n":1236,"ta":["தொடியொடு தோள்நெகிழ நோவல் அவரைக்","கொடியர் எனக்கூறல் நொந்து"],"tr":["Thotiyotu Tholnekizha Noval Avaraik","Kotiyar Enakkooral Nondhu"],"en":["I grieve, 'tis pain to me to hear him cruel chid,","Because the armlet from my wasted arm has slid"],"s":"I am greatly pained to hear you call him a cruel man, just because your shoulders are reduced and your bracelets loosened","ch":124,"sec":3,"th":"love"},
  {"n":1237,"ta":["பாடு பெறுதியோ நெஞ்சே கொடியார்க்கென்","வாடுதோட் பூசல் உரைத்து"],"tr":["Paatu Perudhiyo Nenje Kotiyaarkken","Vaatudhot Poosal Uraiththu"],"en":["My heart! say ought of glory wilt thou gain,","If to that cruel one thou of thy wasted arms complain"],"s":"Can you O my soul! gain glory by relating to the  (so-called) cruel one the clamour of my fading shoulders?","ch":124,"sec":3,"th":"love"},
  {"n":1238,"ta":["முயங்கிய கைகளை ஊக்கப் பசந்தது","பைந்தொடிப் பேதை நுதல்"],"tr":["Muyangiya Kaikalai Ookkap Pasandhadhu","Paindhotip Pedhai Nudhal"],"en":["One day the fervent pressure of embracing arms I checked,","Grew wan the forehead of the maid with golden armlet decked"],"s":"When I once loosened the arms that were in embrace, the forehead of the gold-braceleted women turned sallow","ch":124,"sec":3,"th":"love"},
  {"n":1239,"ta":["முயக்கிடைத் தண்வளி போழப் பசப்புற்ற","பேதை பெருமழைக் கண்"],"tr":["Muyakkitaith Thanvali Pozhap Pasapputra","Pedhai Perumazhaik Kan"],"en":["As we embraced a breath of wind found entrance there;","The maid's large liquid eyes were dimmed with care"],"s":"When but a breath of breeze penetrated our embrace, her large cool eyes became sallow","ch":124,"sec":3,"th":"love"},
  {"n":1240,"ta":["கண்ணின் பசப்போ பருவரல் எய்தின்றே","ஒண்ணுதல் செய்தது கண்டு"],"tr":["Kannin Pasappo Paruvaral Eydhindre","Onnudhal Seydhadhu Kantu"],"en":["The dimness of her eye felt sorrow now,","Beholding what was done by that bright brow"],"s":"Was it at the sight of what the bright forehead had done that the sallowness of her eyes became sad?","ch":124,"sec":3,"th":"love"},
  {"n":1241,"ta":["நினைத்தொன்று சொல்லாயோ நெஞ்சே எனைத்தொன்றும்","எவ்வநோய் தீர்க்கும் மருந்து"],"tr":["Ninaiththondru Sollaayo Nenje Enaiththondrum","Evvanoi Theerkkum Marundhu"],"en":["My heart, canst thou not thinking of some med'cine tell,","Not any one, to drive away this grief incurable"],"s":"O my soul, will you not think and tell me some medicine be it what it may, that can cure this incurable malady?","ch":125,"sec":3,"th":"love"},
  {"n":1242,"ta":["காதல் அவரிலர் ஆகநீ நோவது","பேதைமை வாழியென் நெஞ்சு"],"tr":["Kaadhal Avarilar Aakanee Novadhu","Pedhaimai Vaazhiyen Nenju"],"en":["Since he loves not, thy smart","Is folly, fare thee well my heart"],"s":"Is folly, fare thee well my heart!","ch":125,"sec":3,"th":"love"},
  {"n":1243,"ta":["இருந்துள்ளி என்பரிதல் நெஞ்சே பரிந்துள்ளல்","பைதல்நோய் செய்தார்கண் இல்"],"tr":["Irundhulli Enparidhal Nenje Parindhullal","Paidhalnoi Seydhaarkan Il"],"en":["What comes of sitting here in pining thought, O heart? He knows","No pitying thought, the cause of all these wasting woes"],"s":"O my soul! why remain  (here) and suffer thinking  (of him)? There are no lewd thoughts  (of you) in him who has caused you this disease of sorrow","ch":125,"sec":3,"th":"love"},
  {"n":1244,"ta":["கண்ணும் கொளச்சேறி நெஞ்சே இவையென்னைத்","தின்னும் அவர்க்காணல் உற்று"],"tr":["Kannum Kolachcheri Nenje Ivaiyennaith","Thinnum Avarkkaanal Utru"],"en":["O rid me of these eyes, my heart; for they,","Longing to see him, wear my life away"],"s":"O my soul! take my eyes also with you,  (if not), these would eat me up  (in their desire) to see him","ch":125,"sec":3,"th":"love"},
  {"n":1245,"ta":["செற்றார் எனக்கை விடல்உண்டோ நெஞ்சேயாம்","உற்றால் உறாஅ தவர்"],"tr":["Setraar Enakkai Vitalunto Nenjeyaam","Utraal Uraaa Thavar"],"en":["O heart, as a foe, can I abandon utterly","Him who, though I long for him, longs not for me"],"s":"O my soul! can he who loves not though he is beloved, be forsaken saying he hates me  (now)?","ch":125,"sec":3,"th":"love"},
  {"n":1246,"ta":["கலந்துணர்த்தும் காதலர்க் கண்டாற் புலந்துணராய்","பொய்க்காய்வு காய்திஎன் நெஞ்சு"],"tr":["Kalandhunarththum Kaadhalark Kantaar Pulandhunaraai","Poikkaaivu Kaaidhien Nenju"],"en":["My heart, false is the fire that burns; thou canst not wrath maintain,","If thou thy love behold, embracing, soothing all thy pain"],"s":"O my soul! when you see the dear one who remove dislike by intercourse, you are displeased and continue to be so Nay, your displeasure is  (simply) false","ch":125,"sec":3,"th":"love"},
  {"n":1247,"ta":["காமம் விடுஒன்றோ நாண்விடு நன்னெஞ்சே","யானோ பொறேன்இவ் விரண்டு"],"tr":["Kaamam Vituondro Naanvitu Nannenje","Yaano Poreniv Virantu"],"en":["Or bid thy love, or bid thy shame depart;","For me, I cannot bear them both, my worthy heart"],"s":"O my good soul, give up either lust or honour, as for me I can endure neither","ch":125,"sec":3,"th":"love"},
  {"n":1248,"ta":["பரிந்தவர் நல்காரென்று ஏங்கிப் பிரிந்தவர்","பின்செல்வாய் பேதைஎன் நெஞ்சு"],"tr":["Parindhavar Nalkaarendru Engip Pirindhavar","Pinselvaai Pedhaien Nenju"],"en":["Thou art befooled, my heart, thou followest him who flees from thee;","And still thou yearning criest: 'He will nor pity show nor love to me. '"],"s":"You are a fool, O my soul! to go after my departed one, while you mourn that he is not kind enough to favour you","ch":125,"sec":3,"th":"love"},
  {"n":1249,"ta":["உள்ளத்தார் காத லவரால் உள்ளிநீ","யாருழைச் சேறியென் நெஞ்சு"],"tr":["Ullaththaar Kaadha Lavaraal Ullinee","Yaaruzhaich Cheriyen Nenju"],"en":["My heart! my lover lives within my mind;","Roaming, whom dost thou think to find"],"s":"O my soul! to whom would you repair, while the dear one is within yourself?","ch":125,"sec":3,"th":"love"},
  {"n":1250,"ta":["துன்னாத் துறந்தாரை நெஞ்சத்து உடையேமா","இன்னும் இழத்தும் கவின்"],"tr":["Thunnaath Thurandhaarai Nenjaththu Utaiyemaa","Innum Izhaththum Kavin"],"en":["If I should keep in mind the man who utterly renounces me,","My soul must suffer further loss of dignity"],"s":"If I retain in my heart him who has left me without befriending me, I shall lose even the  (inward) beauty that remains","ch":125,"sec":3,"th":"love"},
  {"n":1251,"ta":["காமக் கணிச்சி உடைக்கும் நிறையென்னும்","நாணுத்தாழ் வீழ்த்த கதவு"],"tr":["Kaamak Kanichchi Utaikkum Niraiyennum","Naanuththaazh Veezhththa Kadhavu"],"en":["Of womanly reserve love's axe breaks through the door,","Barred by the bolt of shame before"],"s":"The axe of lust can break the door of chastity which is bolted with the bolt of modesty","ch":126,"sec":3,"th":"love"},
  {"n":1252,"ta":["காமம் எனவொன்றோ கண்ணின்றென் நெஞ்சத்தை","யாமத்தும் ஆளும் தொழில்"],"tr":["Kaamam Enavondro Kannindren Nenjaththai","Yaamaththum Aalum Thozhil"],"en":["What men call love is the one thing of merciless power;","It gives my soul no rest, e'en in the midnight hour"],"s":"Even at midnight is my mind worried by lust, and this one thing, alas! is without mercy","ch":126,"sec":3,"th":"love"},
  {"n":1253,"ta":["மறைப்பேன்மன் காமத்தை யானோ குறிப்பின்றித்","தும்மல்போல் தோன்றி விடும்"],"tr":["Maraippenman Kaamaththai Yaano Kurippindrith","Thummalpol Thondri Vitum"],"en":["I would my love conceal, but like a sneeze","It shows itself, and gives no warning sign"],"s":"I would conceal my lust, but alas, it yields not to my will but breaks out like a sneeze","ch":126,"sec":3,"th":"love"},
  {"n":1254,"ta":["நிறையுடையேன் என்பேன்மன் யானோஎன் காமம்","மறையிறந்து மன்று படும்"],"tr":["Niraiyutaiyen Enpenman Yaanoen Kaamam","Maraiyirandhu Mandru Patum"],"en":["In womanly reserve I deemed myself beyond assail;","But love will come abroad, and casts away the veil"],"s":"I say I would be firm, but alas, my malady breaks out from its concealment and appears in public","ch":126,"sec":3,"th":"love"},
  {"n":1255,"ta":["செற்றார்பின் செல்லாப் பெருந்தகைமை காமநோய்","உற்றார் அறிவதொன்று அன்று"],"tr":["Setraarpin Sellaap Perundhakaimai Kaamanoi","Utraar Arivadhondru Andru"],"en":["The dignity that seeks not him who acts as foe,","Is the one thing that loving heart can never know"],"s":"The dignity that would not go after an absent lover is not known to those who are sticken by love","ch":126,"sec":3,"th":"love"},
  {"n":1256,"ta":["செற்றவர் பின்சேறல் வேண்டி அளித்தரோ","எற்றென்னை உற்ற துயர்"],"tr":["Setravar Pinseral Venti Aliththaro","Etrennai Utra Thuyar"],"en":["My grief how full of grace, I pray you see!","It seeks to follow him that hateth me"],"s":"The sorrow I have endured by desiring to go after my absent lover, in what way is it excellent?","ch":126,"sec":3,"th":"love"},
  {"n":1257,"ta":["நாணென ஒன்றோ அறியலம் காமத்தால்","பேணியார் பெட்ப செயின்"],"tr":["Naanena Ondro Ariyalam Kaamaththaal","Peniyaar Petpa Seyin"],"en":["No sense of shame my gladdened mind shall prove,","When he returns my longing heart to bless with love"],"s":"I know nothing like shame when my beloved does from love  (just) what is desired  (by me)","ch":126,"sec":3,"th":"love"},
  {"n":1258,"ta":["பன்மாயக் கள்வன் பணிமொழி அன்றோநம்","பெண்மை உடைக்கும் படை"],"tr":["Panmaayak Kalvan Panimozhi Andronam","Penmai Utaikkum Patai"],"en":["The words of that deceiver, versed in every wily art,","Are instruments that break through every guard of woman's heart"],"s":"Are not the enticing words of my trick-abounding roguish lover the weapon that breaks away my feminine firmness?","ch":126,"sec":3,"th":"love"},
  {"n":1259,"ta":["புலப்பல் எனச்சென்றேன் புல்லினேன் நெஞ்சம்","கலத்தல் உறுவது கண்டு"],"tr":["Pulappal Enachchendren Pullinen Nenjam","Kalaththal Uruvadhu Kantu"],"en":["'I 'll shun his greeting'; saying thus with pride away I went:","I held him in my arms, for straight I felt my heart relent"],"s":"I said I would feign dislike and so went  (away);  (but) I embraced him the moment I say my mind began to unite with him!","ch":126,"sec":3,"th":"love"},
  {"n":1260,"ta":["நிணந்தீயில் இட்டன்ன நெஞ்சினார்க்கு உண்டோ","புணர்ந்தூடி நிற்பேம் எனல்"],"tr":["Ninandheeyil Ittanna Nenjinaarkku Unto","Punarndhooti Nirpem Enal"],"en":["'We 'll stand aloof and then embrace': is this for them to say,","Whose hearts are as the fat that in the blaze dissolves away"],"s":"Is it possible for those whose hearts melt like fat in the fire to say they can feign a strong dislike and remain so?","ch":126,"sec":3,"th":"love"},
  {"n":1261,"ta":["வாளற்றுப் புற்கென்ற கண்ணும் அவர்சென்ற","நாளொற்றித் தேய்ந்த விரல்"],"tr":["Vaalatrup Purkendra Kannum Avarsendra","Naalotrith Theyndha Viral"],"en":["My eyes have lost their brightness, sight is dimmed; my fingers worn,","With nothing on the wall the days since I was left forlorn"],"s":"My finger has worn away by marking  (on the wall) the days he has been absent while my eyes have lost their lustre and begin to fail","ch":127,"sec":3,"th":"love"},
  {"n":1262,"ta":["இலங்கிழாய் இன்று மறப்பின்என் தோள்மேல்","கலங்கழியும் காரிகை நீத்து"],"tr":["Ilangizhaai Indru Marappinen Tholmel","Kalangazhiyum Kaarikai Neeththu"],"en":["O thou with gleaming jewels decked, could I forget for this one day,","Henceforth these bracelets from my arms will slip, my beauty worn away"],"s":"O you bright-jewelled maid, if I forget  (him) today, my shoulders will lose their beauty even in the other life and make my bracelets loose","ch":127,"sec":3,"th":"love"},
  {"n":1263,"ta":["உரன்நசைஇ உள்ளம் துணையாகச் சென்றார்","வரல்நசைஇ இன்னும் உளேன்"],"tr":["Urannasaii Ullam Thunaiyaakach Chendraar","Varalnasaii Innum Ulen"],"en":["On victory intent, His mind sole company he went;","And I yet life sustain And long to see his face again"],"s":"I still live by longing for the arrival of him who has gone out of love for victory and with valour as his guide","ch":127,"sec":3,"th":"love"},
  {"n":1264,"ta":["கூடிய காமம் பிரிந்தார் வரவுள்ளிக்","கோடுகொ டேறுமென் நெஞ்சு"],"tr":["Kootiya Kaamam Pirindhaar Varavullik","Kotuko Terumen Nenju"],"en":["'He comes again, who left my side, and I shall taste love's joy,","'-My heart with rapture swells, when thoughts like these my mind employ"],"s":"My heart is rid of its sorrow and swells with rapture to think of my absent lover returning with his love","ch":127,"sec":3,"th":"love"},
  {"n":1265,"ta":["காண்கமன் கொண்கனைக் கண்ணாரக் கண்டபின்","நீங்கும்என் மென்தோள் பசப்பு"],"tr":["Kaankaman Konkanaik Kannaarak Kantapin","Neengumen Mendhol Pasappu"],"en":["O let me see my spouse again and sate these longing eyes!","That instant from my wasted frame all pallor flies"],"s":"May I look on my lover till I am satisfied and thereafter will vanish the sallowness of my slender shoulders","ch":127,"sec":3,"th":"love"},
  {"n":1266,"ta":["வருகமன் கொண்கன் ஒருநாள் பருகுவன்","பைதல்நோய் எல்லாம் கெட"],"tr":["Varukaman Konkan Orunaal Parukuvan","Paidhalnoi Ellaam Keta"],"en":["O let my spouse but come again to me one day!","I'll drink that nectar: wasting grief shall flee away"],"s":"May my husband return some day; and then will I enjoy  (him) so as to destroy all this agonizing sorrow","ch":127,"sec":3,"th":"love"},
  {"n":1267,"ta":["புலப்பேன்கொல் புல்லுவேன் கொல்லோ கலப்பேன்கொல்","கண்அன்ன கேளிர் விரன்"],"tr":["Pulappenkol Pulluven Kollo Kalappenkol","Kananna Kelir Viran"],"en":["Shall I draw back, or yield myself, or shall both mingled be,","When he returns, my spouse, dear as these eyes to me"],"s":"On the return of him who is as dear as my eyes, am I displeased or am I to embrace  (him); or am I to do both?","ch":127,"sec":3,"th":"love"},
  {"n":1268,"ta":["வினைகலந்து வென்றீக வேந்தன் மனைகலந்து","மாலை அயர்கம் விருந்து"],"tr":["Vinaikalandhu Vendreeka Vendhan Manaikalandhu","Maalai Ayarkam Virundhu"],"en":["O would my king would fight, o'ercome, devide the spoil;","At home, to-night, the banquet spread should crown the toil"],"s":"Let the king fight and gain  (victories);  (but) let me be united to my wife and feast the evening","ch":127,"sec":3,"th":"love"},
  {"n":1269,"ta":["ஒருநாள் எழுநாள்போல் செல்லும்சேண் சென்றார்","வருநாள்வைத்து ஏங்கு பவர்க்கு"],"tr":["Orunaal Ezhunaalpol Sellumsen Sendraar","Varunaalvaiththu Engu Pavarkku"],"en":["One day will seem like seven to those who watch and yearn","For that glad day when wanderers from afar return"],"s":"To those who suffer waiting for the day of return of their distant lovers one day is as long as seven days","ch":127,"sec":3,"th":"love"},
  {"n":1270,"ta":["பெறின்என்னாம் பெற்றக்கால் என்னாம் உறினென்னாம்","உள்ளம் உடைந்துக்கக் கால்"],"tr":["Perinennaam Petrakkaal Ennaam Urinennaam","Ullam Utaindhukkak Kaal"],"en":["What's my return, the meeting hour, the wished-for greeting worth,","If she heart-broken lie, with all her life poured forth"],"s":"After  (my wife) has died of a broken heart, what good will there be if she is to receive me, has received me, or has even embraced me?","ch":127,"sec":3,"th":"love"},
  {"n":1271,"ta":["கரப்பினுங் கையிகந் தொல்லாநின் உண்கண்","உரைக்கல் உறுவதொன் றுண்டு"],"tr":["Karappinung Kaiyikan Thollaanin Unkan","Uraikkal Uruvadhon Runtu"],"en":["Thou hid'st it, yet thine eye, disdaining all restraint,","Something, I know not, what, would utter of complaint"],"s":"Though you would conceal  (your feelings), your painted eyes would not, for, transgressing  (their bounds), they tell  (me) something","ch":128,"sec":3,"th":"love"},
  {"n":1272,"ta":["கண்ணிறைந்த காரிகைக் காம்பேர்தோட் பேதைக்குப்","பெண்நிறைந்த நீர்மை பெரிது"],"tr":["Kanniraindha Kaarikaik Kaamperdhot Pedhaikkup","Penniraindha Neermai Peridhu"],"en":["The simple one whose beauty fills mine eye, whose shoulders curve","Like bambu stem, hath all a woman's modest sweet reserve"],"s":"Unusually great is the female simplicity of your maid whose beauty fills my eyes and whose shoulders resemble the bamboo","ch":128,"sec":3,"th":"love"},
  {"n":1273,"ta":["மணியில் திகழ்தரு நூல்போல் மடந்தை","அணியில் திகழ்வதொன்று உண்டு"],"tr":["Maniyil Thikazhdharu Noolpol Matandhai","Aniyil Thikazhvadhondru Untu"],"en":["As through the crystal beads is seen the thread on which they 're strung","So in her beauty gleams some thought cannot find a tongue"],"s":"There is something that is implied in the beauty of this woman, like the thread that is visible in a garland of gems","ch":128,"sec":3,"th":"love"},
  {"n":1274,"ta":["முகைமொக்குள் உள்ளது நாற்றம்போல் பேதை","நகைமொக்குள் உள்ளதொன் றுண்டு"],"tr":["Mukaimokkul Ulladhu Naatrampol Pedhai","Nakaimokkul Ulladhon Runtu"],"en":["As fragrance in the opening bud, some secret lies","Concealed in budding smile of this dear damsel's eyes"],"s":"There is something in the unmatured smile of this maid like the fragrance that is contained in an unblossomed bud","ch":128,"sec":3,"th":"love"},
  {"n":1275,"ta":["செறிதொடி செய்திறந்த கள்ளம் உறுதுயர்","தீர்க்கும் மருந்தொன்று உடைத்து"],"tr":["Seridhoti Seydhirandha Kallam Urudhuyar","Theerkkum Marundhondru Utaiththu"],"en":["The secret wiles of her with thronging armlets decked,","Are medicines by which my raising grief is checked"],"s":"The well-meant departure of her whose bangles are tight-fitting contains a remedy that can cure my great sorrow","ch":128,"sec":3,"th":"love"},
  {"n":1276,"ta":["பெரிதாற்றிப் பெட்பக் கலத்தல் அரிதாற்றி","அன்பின்மை சூழ்வ துடைத்து"],"tr":["Peridhaatrip Petpak Kalaththal Aridhaatri","Anpinmai Soozhva Thutaiththu"],"en":["While lovingly embracing me, his heart is only grieved:","It makes me think that I again shall live of love bereaved"],"s":"The embrace that fills me with comfort and gladness is capable of enduring  (my former) sorrow and meditating on his want of love","ch":128,"sec":3,"th":"love"},
  {"n":1277,"ta":["தண்ணந் துறைவன் தணந்தமை நம்மினும்","முன்னம் உணர்ந்த வளை"],"tr":["Thannan Thuraivan Thanandhamai Namminum","Munnam Unarndha Valai"],"en":["My severance from the lord of this cool shore,","My very armlets told me long before"],"s":"My bracelets have understood before me the  (mental) separation of him who rules the cool seashore","ch":128,"sec":3,"th":"love"},
  {"n":1278,"ta":["நெருநற்றுச் சென்றார்எம் காதலர் யாமும்","எழுநாளேம் மேனி பசந்து"],"tr":["Nerunatruch Chendraarem Kaadhalar Yaamum","Ezhunaalem Meni Pasandhu"],"en":["My loved one left me, was it yesterday?","Days seven my pallid body wastes away"],"s":"It was but yesterday my lover departed  (from me); and it is seven days since my complexion turned sallow","ch":128,"sec":3,"th":"love"},
  {"n":1279,"ta":["தொடிநோக்கி மென்தோளும் நோக்கி அடிநோக்கி","அஃதாண் டவள்செய் தது"],"tr":["Thotinokki Mendholum Nokki Atinokki","Aqdhaan Tavalsey Thadhu"],"en":["She viewed her tender arms, she viewed the armlets from them slid;","She viewed her feet: all this the lady did"],"s":"She looked at her bracelets, her tender shoulders, and her feet; this was what she did there  (significantly)","ch":128,"sec":3,"th":"love"},
  {"n":1280,"ta":["பெண்ணினால் பெண்மை உடைத்தென்ப கண்ணினால்","காமநோய் சொல்லி இரவு"],"tr":["Penninaal Penmai Utaiththenpa Kanninaal","Kaamanoi Solli Iravu"],"en":["To show by eye the pain of love, and for relief to pray,","Is womanhood's most womanly device, men say"],"s":"To express their love-sickness by their eyes and resort to begging bespeaks more than ordinary female excellence","ch":128,"sec":3,"th":"love"},
  {"n":1281,"ta":["உள்ளக் களித்தலும் காண மகிழ்தலும்","கள்ளுக்கில் காமத்திற் குண்டு"],"tr":["Ullak Kaliththalum Kaana Makizhdhalum","Kallukkil Kaamaththir Kuntu"],"en":["Gladness at the thought, rejoicing at the sight,","Not palm-tree wine, but love, yields such delight"],"s":"To please by thought and cheer by sight is peculiar, not to liquor but lust","ch":129,"sec":3,"th":"love"},
  {"n":1282,"ta":["தினைத்துணையும் ஊடாமை வேண்டும் பனைத்துணையும்","காமம் நிறைய வரின்"],"tr":["Thinaiththunaiyum Ootaamai Ventum Panaith","Thunaiyum Kaamam Niraiya Varin"],"en":["When as palmyra tall, fulness of perfect love we gain,","Distrust can find no place small as the millet grain"],"s":"If women have a lust that exceeds even the measure of the palmyra fruit, they will not desire  (to feign) dislike even as much as the millet","ch":129,"sec":3,"th":"love"},
  {"n":1283,"ta":["பேணாது பெட்பவே செய்யினும் கொண்கனைக்","காணா தமையல கண்"],"tr":["Penaadhu Petpave Seyyinum Konkanaik","Kaanaa Thamaiyala Kan"],"en":["Although his will his only law, he lightly value me,","My heart knows no repose unless my lord I see"],"s":"Though my eyes disregard me and do what is pleasing to my husband, still will they not be satisfied unless they see him","ch":129,"sec":3,"th":"love"},
  {"n":1284,"ta":["ஊடற்கண் சென்றேன்மன் தோழி அதுமறந்து","கூடற்கண் சென்றது என் னெஞ்சு"],"tr":["Ootarkan Sendrenman Thozhi Adhumarandhu","Kootarkan Sendradhu En Nenju"],"en":["My friend, I went prepared to show a cool disdain;","My heart, forgetting all, could not its love restrain"],"s":"My heart, forgetting all, could not its love restrain","ch":129,"sec":3,"th":"love"},
  {"n":1285,"ta":["எழுதுங்கால் கோல்காணாக் கண்ணேபோல் கொண்கன்","பழிகாணேன் கண்ட இடத்து"],"tr":["Ezhudhungaal Kolkaanaak Kannepol Konkan","Pazhikaanen Kanta Itaththu"],"en":["The eye sees not the rod that paints it; nor can","ISee any fault, when I behold my husband nigh"],"s":"Like the eyes which see not the pencil that paints it, I cannot see my husband's fault  (just) when I meet him","ch":129,"sec":3,"th":"love"},
  {"n":1286,"ta":["காணுங்கால் காணேன் தவறாய காணாக்கால்","காணேன் தவறல் லவை"],"tr":["Kaanungaal Kaanen Thavaraaya Kaanaakkaal","Kaanen Thavaral Lavai"],"en":["When him I see, to all his faults I 'm blind;","But when I see him not, nothing but faults I find"],"s":"When I see my husband, I do not see any faults; but when I do not see him, I do not see anything but faults","ch":129,"sec":3,"th":"love"},
  {"n":1287,"ta":["உய்த்தல் அறிந்து புனல்பாய் பவரேபோல்","பொய்த்தல் அறிந்தென் புலந்து"],"tr":["Uyththal Arindhu Punalpaai Pavarepol","Poiththal Arindhen Pulandhu"],"en":["As those of rescue sure, who plunge into the stream,","So did I anger feign, though it must falsehood seem"],"s":"Like those who leap into a stream which they know will carry them off, why should a wife feign dislike which she knows cannot hold out long?","ch":129,"sec":3,"th":"love"},
  {"n":1288,"ta":["இளித்தக்க இன்னா செயினும் களித்தார்க்குக்","கள்ளற்றே கள்வநின் மார்பு"],"tr":["Iliththakka Innaa Seyinum Kaliththaarkkuk","Kallatre Kalvanin Maarpu"],"en":["Though shameful ill it works, dear is the palm-tree wine","To drunkards; traitor, so to me that breast of thine"],"s":"O you rogue! your breast is to me what liquor is to those who rejoice in it, though it only gives them an unpleasant disgrace","ch":129,"sec":3,"th":"love"},
  {"n":1289,"ta":["மலரினும் மெல்லிது காமம் சிலர்அதன்","செவ்வி தலைப்படு வார்"],"tr":["Malarinum Mellidhu Kaamam Silaradhan","Sevvi Thalaippatu Vaar"],"en":["Love is tender as an opening flower In season due","To gain its perfect bliss is rapture known to few"],"s":"Sexual delight is more delicate than a flower, and few are those who understand its real nature","ch":129,"sec":3,"th":"love"},
  {"n":1290,"ta":["கண்ணின் துனித்தே கலங்கினாள் புல்லுதல்","என்னினும் தான்விதுப் புற்று"],"tr":["Kannin Thuniththe Kalanginaal Pulludhal","Enninum Thaanvidhup Putru"],"en":["Her eye, as I drew nigh one day, with anger shone:","By love o'erpowered, her tenderness surpassed my own"],"s":"She once feigned dislike in her eyes, but the warmth of her embrace exceeded my own","ch":129,"sec":3,"th":"love"},
  {"n":1291,"ta":["அவர்நெஞ்சு அவர்க்காதல் கண்டும் எவன்நெஞ்சே","நீஎமக்கு ஆகா தது"],"tr":["Avarnenju Avarkkaadhal Kantum Evannenje","Neeemakku Aakaa Thadhu"],"en":["You see his heart is his alone","O heart, why not be all my own"],"s":"O my soul! although you have seen how his soul stands by him, how is it you do not stand by me?","ch":130,"sec":3,"th":"love"},
  {"n":1292,"ta":["உறாஅ தவர்க்கண்ட கண்ணும் அவரைச்","செறாஅரெனச் சேறியென் நெஞ்சு"],"tr":["Uraaa Thavarkkanta Kannum Avaraich","Cheraaarenach Cheriyen Nenju"],"en":["'Tis plain, my heart, that he 's estranged from thee;","Why go to him as though he were not enemy"],"s":"O my soul! although you have known him who does not love me, still do you go to him, saying \"he will not be displeased.\"","ch":130,"sec":3,"th":"love"},
  {"n":1293,"ta":["கெட்டார்க்கு நட்டார்இல் என்பதோ நெஞ்சேநீ","பெட்டாங்கு அவர்பின் செலல்"],"tr":["Kettaarkku Nattaaril Enpadho Nenjenee","Pettaangu Avarpin Selal"],"en":["'The ruined have no friends, 'they say; and so, my heart,","To follow him, at thy desire, from me thou dost depart"],"s":"O my soul! do you follow him at pleasure under the belief that the ruined have no friends?","ch":130,"sec":3,"th":"love"},
  {"n":1294,"ta":["இனிஅன்ன நின்னொடு சூழ்வார்யார் நெஞ்சே","துனிசெய்து துவ்வாய்காண் மற்று"],"tr":["Inianna Ninnotu Soozhvaaryaar Nenje","Thuniseydhu Thuvvaaikaan Matru"],"en":["'See, thou first show offended pride, and then submit, ' I bade;","Henceforth such council who will share with thee my heart"],"s":"O my soul! you would not first seem sulky and then enjoy  (him); who then would in future consult you about such things?","ch":130,"sec":3,"th":"love"},
  {"n":1295,"ta":["பெறாஅமை அஞ்சும் பெறின்பிரிவு அஞ்சும்","அறாஅ இடும்பைத்தென் நெஞ்சு"],"tr":["Peraaamai Anjum Perinpirivu Anjum","Araaa Itumpaiththen Nenju"],"en":["I fear I shall not gain, I fear to lose him when I gain;","And thus my heart endures unceasing pain"],"s":"My soul fears when it is without him; it also fears when it is with him; it is subject to incessant sorrow","ch":130,"sec":3,"th":"love"},
  {"n":1296,"ta":["தனியே இருந்து நினைத்தக்கால் என்னைத்","தினிய இருந்ததென் நெஞ்சு"],"tr":["Thaniye Irundhu Ninaiththakkaal Ennaith","Thiniya Irundhadhen Nenju"],"en":["My heart consumes me when I ponder lone,","And all my lover's cruelty bemoan"],"s":"My mind has been  (here) in order to eat me up  (as it were) whenever I think of him in my solitude","ch":130,"sec":3,"th":"love"},
  {"n":1297,"ta":["நாணும் மறந்தேன் அவர்மறக் கல்லாஎன்","மாணா மடநெஞ்சிற் பட்டு"],"tr":["Naanum Marandhen Avarmarak Kallaaen","Maanaa Matanenjir Pattu"],"en":["Fall'n 'neath the sway of this ignoble foolish heart,","Which will not him forget, I have forgotten shame"],"s":"I have even forgotten my modesty, having been caught in my foolish mind which is not dignified enough to forget him","ch":130,"sec":3,"th":"love"},
  {"n":1298,"ta":["எள்ளின் இளிவாம்என்று எண்ணி அவர்திறம்","உள்ளும் உயிர்க்காதல் நெஞ்சு"],"tr":["Ellin Ilivaamendru Enni Avardhiram","Ullum Uyirkkaadhal Nenju"],"en":["If I contemn him, then disgrace awaits me evermore;","My soul that seeks to live his virtues numbers o'er"],"s":"My soul which clings to life thinks only of his  (own) gain in the belief that it would be disgraceful for it to despise him","ch":130,"sec":3,"th":"love"},
  {"n":1299,"ta":["துன்பத்திற்கு யாரே துணையாவார் தாமுடைய","நெஞ்சந் துணையல் வழி"],"tr":["Thunpaththirku Yaare Thunaiyaavaar Thaamutaiya","Nenjan Thunaiyal Vazhi"],"en":["And who will aid me in my hour of grief,","If my own heart comes not to my relief"],"s":"Who would help me out of one's distress, when one's own soul refuses help to one?","ch":130,"sec":3,"th":"love"},
  {"n":1300,"ta":["தஞ்சம் தமரல்லர் ஏதிலார் தாமுடைய","நெஞ்சம் தமரல் வழி"],"tr":["Thanjam Thamarallar Edhilaar Thaamutaiya","Nenjam Thamaral Vazhi"],"en":["A trifle is unfriendliness by aliens shown,","When our own heart itself is not our own"],"s":"It is hardly possible for strangers to behave like relations, when one's own soul acts like a stranger","ch":130,"sec":3,"th":"love"},
  {"n":1301,"ta":["புல்லா திராஅப் புலத்தை அவர்உறும்","அல்லல்நோய் காண்கம் சிறிது"],"tr":["Pullaa Thiraaap Pulaththai Avar","Urum Allalnoi Kaankam Siridhu"],"en":["Be still reserved, decline his profferred love;","A little while his sore distress we 'll prove"],"s":"Let us witness awhile his keen suffering; just feign dislike and embrace him not","ch":131,"sec":3,"th":"love"},
  {"n":1302,"ta":["உப்பமைந் தற்றால் புலவி அதுசிறிது","மிக்கற்றால் நீள விடல்"],"tr":["Uppamain Thatraal Pulavi Adhusiridhu","Mikkatraal Neela Vital"],"en":["A cool reserve is like the salt that seasons well the mess,","Too long maintained, 'tis like the salt's excess"],"s":"A little dislike is like salt in proportion; to prolong it a little is like salt a little too much","ch":131,"sec":3,"th":"love"},
  {"n":1303,"ta":["அலந்தாரை அல்லல்நோய் செய்தற்றால் தம்மைப்","புலந்தாரைப் புல்லா விடல்"],"tr":["Alandhaarai Allalnoi Seydhatraal Thammaip","Pulandhaaraip Pullaa Vital"],"en":["'Tis heaping griefs on those whose hearts are grieved;","To leave the grieving one without a fond embrace"],"s":"For men not to embrace those who have feigned dislike is like torturing those already in agony","ch":131,"sec":3,"th":"love"},
  {"n":1304,"ta":["ஊடி யவரை உணராமை வாடிய","வள்ளி முதலரிந் தற்று"],"tr":["Ooti Yavarai Unaraamai Vaatiya","Valli Mudhalarin Thatru"],"en":["To use no kind conciliating art when lover grieves,","Is cutting out the root of tender winding plant that droops"],"s":"Not to reconcile those who have feigned dislike is like cutting a faded creeper at its root","ch":131,"sec":3,"th":"love"},
  {"n":1305,"ta":["நலத்தகை நல்லவர்க்கு ஏஎர் புலத்தகை","பூஅன்ன கண்ணார் அகத்து"],"tr":["Nalaththakai Nallavarkku Eer Pulaththakai","Pooanna Kannaar Akaththu"],"en":["Even to men of good and worthy mind, the petulance","Of wives with flowery eyes lacks not a lovely grace"],"s":"An increased shyness in those whose eyes are like flowers is beautiful even to good and virtuous husbands","ch":131,"sec":3,"th":"love"},
  {"n":1306,"ta":["துனியும் புலவியும் இல்லாயின் காமம்","கனியும் கருக்காயும் அற்று"],"tr":["Thuniyum Pulaviyum Illaayin Kaamam","Kaniyum Karukkaayum Atru"],"en":["Love without hatred is ripened fruit;","Without some lesser strife, fruit immature"],"s":"Sexual pleasure, without prolonged and short-lived dislike, is like too ripe, and unripe fruit","ch":131,"sec":3,"th":"love"},
  {"n":1307,"ta":["ஊடலின் உண்டாங்கோர் துன்பம் புணர்வது","நீடுவ தன்று கொல் என்று"],"tr":["Ootalin Untaangor Thunpam Punarvadhu","Neetuva Thandru Kol Endru"],"en":["A lovers' quarrel brings its pain, when mind afraid","Asks doubtful, 'Will reunion sweet be long delayed? '"],"s":"The doubt as to whether intercourse would take place soon or not, creates a sorrow  (even) in feigned dislike","ch":131,"sec":3,"th":"love"},
  {"n":1308,"ta":["நோதல் எவன்மற்று நொந்தாரென்று அஃதறியும்","காதலர் இல்லா வழி"],"tr":["Nodhal Evanmatru Nondhaarendru Aqdhariyum","Kaadhalar Illaa Vazhi"],"en":["What good can grieving do, when none who love","Are there to know the grief thy soul endures"],"s":"What avails sorrow when I am without a wife who can understand the cause of my sorrow?","ch":131,"sec":3,"th":"love"},
  {"n":1309,"ta":["நீரும் நிழலது இனிதே புலவியும்","வீழுநர் கண்ணே இனிது"],"tr":["Neerum Nizhaladhu Inidhe Pulaviyum","Veezhunar Kanne Inidhu"],"en":["Water is pleasant in the cooling shade;","So coolness for a time with those we love"],"s":"Like water in the shade, dislike is delicious only in those who love","ch":131,"sec":3,"th":"love"},
  {"n":1310,"ta":["ஊடல் உணங்க விடுவாரோடு என்நெஞ்சம்","கூடுவேம் என்பது அவா"],"tr":["Ootal Unanga Vituvaarotu Ennenjam","Kootuvem Enpadhu Avaa"],"en":["Of her who leaves me thus in variance languishing,","To think within my heart with love is fond desire"],"s":"It is nothing but strong desire that makes her mind unite with me who can leave her to her own dislike","ch":131,"sec":3,"th":"love"},
  {"n":1311,"ta":["பெண்ணியலார் எல்லாரும் கண்ணின் பொதுஉண்பர்","நண்ணேன் பரத்தநின் மார்பு"],"tr":["Penniyalaar Ellaarum Kannin Podhuunpar","Nannen Paraththanin Maarpu"],"en":["From thy regard all womankind Enjoys an equal grace;","O thou of wandering fickle mind, I shrink from thine embrace"],"s":"You are given to prostitution; all those who are born as womankind enjoy you with their eyes in an ordinary way I will not embrace you","ch":132,"sec":3,"th":"love"},
  {"n":1312,"ta":["ஊடி இருந்தேமாத் தும்மினார் யாம்தம்மை","நீடுவாழ் கென்பாக் கறிந்து"],"tr":["Ooti Irundhemaath Thumminaar Yaamdhammai","Neetuvaazh Kenpaak Karindhu"],"en":["One day we silent sulked; he sneezed: The reason well I knew;","He thought that I, to speak well pleased, Would say, 'Long life to you! '"],"s":"When I continued to be sulky he sneezed and thought I would  (then) wish him a long life","ch":132,"sec":3,"th":"love"},
  {"n":1313,"ta":["கோட்டுப்பூச் சூடினும் காயும் ஒருத்தியைக்","காட்டிய சூடினீர் என்று"],"tr":["Kottup Pooch Chootinum Kaayum","Oruththiyaik Kaattiya Sootineer Endru"],"en":["I wreathed with flowers one day my brow, The angry tempest lowers;","She cries, 'Pray, for what woman now Do you put on your flowers? '"],"s":"Even if I were adorned with a garland of branch-flowers, she would say I did so to show it to another woman","ch":132,"sec":3,"th":"love"},
  {"n":1314,"ta":["யாரினும் காதலம் என்றேனா ஊடினாள்","யாரினும் யாரினும் என்று"],"tr":["Yaarinum Kaadhalam Endrenaa Ootinaal","Yaarinum Yaarinum Endru"],"en":["'I love you more than all beside, ' 'T was thus I gently spoke;","'What all, what all? ' she instant cried; And all her anger woke"],"s":"When I said I loved her more than any other woman, she said \"more than others, yes, more than others,\" and remained sulky","ch":132,"sec":3,"th":"love"},
  {"n":1315,"ta":["இம்மைப் பிறப்பில் பிரியலம் என்றேனாக்","கண்நிறை நீர்கொண் டனள்"],"tr":["Immaip Pirappil Piriyalam Endrenaak","Kannirai Neerkon Tanal"],"en":["'While here I live, I leave you not, ' I said to calm her fears","She cried, 'There, then, I read your thought'; And straight dissolved in tears"],"s":"When I said I would never part from her in this life her eyes were filled with tears","ch":132,"sec":3,"th":"love"},
  {"n":1316,"ta":["உள்ளினேன் என்றேன்மற் றென்மறந்தீர் என்றென்னைப்","புல்லாள் புலத்தக் கனள்"],"tr":["Ullinen Endrenmar Renmarandheer Endrennaip","Pullaal Pulaththak Kanal"],"en":["'Each day I called to mind your charms, ' 'O, then, you had forgot,","'She cried, and then her opened arms, Forthwith embraced me not"],"s":"When I said I had remembered her, she said I had forgotten her and relaxing her embrace, began to feign dislike","ch":132,"sec":3,"th":"love"},
  {"n":1317,"ta":["வழுத்தினாள் தும்மினேன் ஆக அழித்தழுதாள்","யாருள்ளித் தும்மினீர் என்று"],"tr":["Vazhuththinaal Thumminen Aaka Azhiththazhudhaal","Yaarullith Thummineer Endru"],"en":["She hailed me when I sneezed one day; But straight with anger seized,","She cried; 'Who was the woman, pray, Thinking of whom you sneezed? '"],"s":"When I sneezed she blessed me, but at once changed  (her mind) and wept, asking, \"At the thought of whom did you sneeze?\"","ch":132,"sec":3,"th":"love"},
  {"n":1318,"ta":["தும்முச் செறுப்ப அழுதாள் நுமர்உள்ளல்","எம்மை மறைத்திரோ என்று"],"tr":["Thummuch Cheruppa Azhudhaal Numarullal","Emmai Maraiththiro Endru"],"en":["And so next time I checked my sneeze; She forthwith wept and cried,","(That woman difficult to please), 'Your thoughts from me you hide'"],"s":"When I suppressed my sneezing, she wept saying, \"I suppose you  (did so) to hide from me your own people's remembrance of you\"","ch":132,"sec":3,"th":"love"},
  {"n":1319,"ta":["தன்னை உணர்த்தினும் காயும் பிறர்க்கும்நீர்","இந்நீரர் ஆகுதிர் என்று"],"tr":["Thannai Unarththinum Kaayum Pirarkkumneer","Inneerar Aakudhir Endru"],"en":["I then began to soothe and coax, To calm her jealous mind;","'I see', quoth she, 'to other folks How you are wondrous kind"],"s":"'I see', quoth she, 'to other folks How you are wondrous kind' Even when I try to remove her dislike, she is displeased and says, \"This is the way you behave","ch":132,"sec":3,"th":"love"},
  {"n":1320,"ta":["நினைத்திருந்து நோக்கினும் காயும் அனைத்துநீர்","யாருள்ளி நோக்கினீர் என்று"],"tr":["Ninaiththirundhu Nokkinum Kaayum Anaiththuneer","Yaarulli Nokkineer Endru"],"en":["I silent sat, but thought the more, And gazed on her Then she","Cried out, 'While thus you eye me o'er, Tell me whose form you see'"],"s":"Even when I look on her contemplating  (her beauty), she is displeased and says, \"With whose thought have you  (thus) looked on my person?\"","ch":132,"sec":3,"th":"love"},
  {"n":1321,"ta":["இல்லை தவறவர்க்கு ஆயினும் ஊடுதல்","வல்லது அவர்அள஧க்கு மாறு"],"tr":["Illai Thavaravarkku Aayinum Ootudhal","Valladhu Avaralikku Maaru"],"en":["Although there be no fault in him, the sweetness of his love","Hath power in me a fretful jealousy to move"],"s":"Although my husband is free from defects, the way in which he embraces me is such as to make me feign dislike","ch":133,"sec":3,"th":"love"},
  {"n":1322,"ta":["ஊடலின் தோன்றும் சிறுதுனி நல்லளி","வாடினும் பாடு பெறும்"],"tr":["Ootalin Thondrum Sirudhuni Nallali","Vaatinum Paatu Perum"],"en":["My 'anger feigned' gives but a little pain;","And when affection droops, it makes it bloom again"],"s":"His love will increase though it may  (at first seem to) fade through the short-lived distress caused by  (my) dislike","ch":133,"sec":3,"th":"love"},
  {"n":1323,"ta":["புலத்தலின் புத்தேள்நாடு உண்டோ நிலத்தொடு","நீரியைந் தன்னார் அகத்து"],"tr":["Pulaththalin Puththelnaatu Unto Nilaththotu","Neeriyain Thannaar Akaththu"],"en":["Is there a bliss in any world more utterly divine,","Than 'coyness' gives, when hearts as earth and water join"],"s":"Is there a celestial land that can please like the feigned dislike of those whose union resembles that of earth and water?","ch":133,"sec":3,"th":"love"},
  {"n":1324,"ta":["புல்லி விடாஅப் புலவியுள் தோன்றுமென்","உள்ளம் உடைக்கும் படை"],"tr":["Pulli Vitaaap Pulaviyul Thondrumen","Ullam Utaikkum Patai"],"en":["'Within the anger feigned' that close love's tie doth bind,","A weapon lurks, which quite breaks down my mind"],"s":"In prolonged dislike after an embrace there is a weapon that can break my heart","ch":133,"sec":3,"th":"love"},
  {"n":1325,"ta":["தவறிலர் ஆயினும் தாம்வீழ்வார் மென்றோள்","அகறலின் ஆங்கொன் றுடைத்து"],"tr":["Thavarilar Aayinum Thaamveezhvaar Mendrol","Akaralin Aangon Rutaiththu"],"en":["Though free from fault, from loved one's tender arms","To be estranged a while hath its own special charms"],"s":"Though free from defects, men feel pleased when they cannot embrace the delicate shoulders of those whom they love","ch":133,"sec":3,"th":"love"},
  {"n":1326,"ta":["உணலினும் உண்டது அறல்இனிது காமம்","புணர்தலின் ஊடல் இனிது"],"tr":["Unalinum Untadhu Aralinidhu Kaamam","Punardhalin Ootal Inidhu"],"en":["'Tis sweeter to digest your food than 'tis to eat;","In love, than union's self is anger feigned more sweet"],"s":"To digest what has been eaten is more delightful than to eat more; likewise love is more delightful in dislike than intercourse","ch":133,"sec":3,"th":"love"},
  {"n":1327,"ta":["ஊடலில் தோற்றவர் வென்றார் அதுமன்னும்","கூடலிற் காணப் படும்"],"tr":["Ootalil Thotravar Vendraar Adhumannum","Kootalir Kaanap Patum"],"en":["In lovers' quarrels, 'tis the one that first gives way,","That in re-union's joy is seen to win the day"],"s":"Those are conquerors whose dislike has been defeated and that is proved by the love  (which","ch":133,"sec":3,"th":"love"},
  {"n":1328,"ta":["ஊடிப் பெறுகுவம் கொல்லோ நுதல்வெயர்ப்பக்","கூடலில் தோன்றிய உப்பு"],"tr":["Ootip Perukuvam Kollo Nudhalveyarppak","Kootalil Thondriya Uppu"],"en":["And shall we ever more the sweetness know of that embrace","With dewy brow; to which 'feigned anger' lent its piquant grace"],"s":"Will I enjoy once more through her dislike, the pleasure of that love that makes her forehead perspire?","ch":133,"sec":3,"th":"love"},
  {"n":1329,"ta":["ஊடுக மன்னோ ஒளியிழை யாமிரப்ப","நீடுக மன்னோ இரா"],"tr":["Ootuka Manno Oliyizhai Yaamirappa","Neetuka Manno Iraa"],"en":["Let her, whose jewels brightly shine, aversion feign","That I may still plead on, O night, prolong thy reign"],"s":"May the bright-jewelled one feign dislike, and may the night be prolonged for me to implore her!","ch":133,"sec":3,"th":"love"},
  {"n":1330,"ta":["ஊடுதல் காமத்திற்கு இன்பம் அதற்கின்பம்","கூடி முயங்கப் பெறின்"],"tr":["Ootudhal Kaamaththirku Inpam Adharkinpam","Kooti Muyangap Perin"],"en":["A 'feigned aversion' coy to pleasure gives a zest;","The pleasure's crowned when breast is clasped to breast"],"s":"Dislike adds delight to love; and a hearty embrace  (thereafter) will add delight to dislike","ch":133,"sec":3,"th":"love"}
];

